INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39238, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの生き物がいて、みんな元気に生きていることを「生物多様性」と言います。", "primary_collocate": null, "pronunciation": "せいぶつたようせい", "ipa": "seːbɯtsɯ tajoːseː", "syllable_count": 9, "sentences": [{"text": "森を守ることは、生物多様性を守ることにつながる。", "target_word": "生物多様性", "complexity_tier": "T3", "furigana": "森[もり]を守[まも]ることは、生物多様性[せいぶつたようせい]を守[まも]ることにつながる。", "sentence_source": "generated"}, {"text": "この島は生物多様性が豊かで、めずらしい鳥も多い。", "target_word": "生物多様性", "complexity_tier": "T3", "furigana": "この島[しま]は生物多様性[せいぶつたようせい]が豊[ゆた]かで、めずらしい鳥[とり]も多[おお]い。", "sentence_source": "generated"}, {"text": "温暖化は、生物多様性に大きな影響をあたえている。", "target_word": "生物多様性", "complexity_tier": "T3", "furigana": "温暖化[おんだんか]は、生物多様性[せいぶつたようせい]に大[おお]きな影響[えいきょう]をあたえている。", "sentence_source": "generated"}, {"text": "先生は、生物多様性とは何かを黒板に書いて説明した。", "target_word": "生物多様性", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生物多様性[せいぶつたようせい]とは何[なに]かを黒板[こくばん]に書[か]いて説明[せつめい]した。", "sentence_source": "generated"}, {"text": "開発で森が減ると、生物多様性が失われてしまう。", "target_word": "生物多様性", "complexity_tier": "T3", "furigana": "開発[かいはつ]で森[もり]が減[へ]ると、生物多様性[せいぶつたようせい]が失[うしな]われてしまう。", "sentence_source": "generated"}, {"text": "川にいろいろな魚がいることは、生物多様性の例だ。", "target_word": "生物多様性", "complexity_tier": "T3", "furigana": "川[かわ]にいろいろな魚[さかな]がいることは、生物多様性[せいぶつたようせい]の例[れい]だ。", "sentence_source": "generated"}, {"text": "私たちの町は、生物多様性を守るために田んぼの水路を残した。", "target_word": "生物多様性", "complexity_tier": "T3", "furigana": "私[わたし]たちの町[まち]は、生物多様性[せいぶつたようせい]を守[まも]るために田[た]んぼの水路[すいろ]を残[のこ]した。", "sentence_source": "generated"}, {"text": "海のごみが増えて、生物多様性が心配されている。", "target_word": "生物多様性", "complexity_tier": "T3", "furigana": "海[うみ]のごみが増[ふ]えて、生物多様性[せいぶつたようせい]が心配[しんぱい]されている。", "sentence_source": "generated"}, {"text": "生物多様性が高い湿地には、多くの虫や草が見られる。", "target_word": "生物多様性", "complexity_tier": "T3", "furigana": "生物多様性[せいぶつたようせい]が高[たか]い湿地[しっち]には、多[おお]くの虫[むし]や草[くさ]が見[み]られる。", "sentence_source": "generated"}, {"text": "子どもたちは、生物多様性について調べて発表した。", "target_word": "生物多様性", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、生物多様性[せいぶつたようせい]について調[しら]べて発表[はっぴょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生物多様性", "label": "基本形"}], "register": "標準", "sense_fingerprint": "生物多様性=ある地域に多くの種類の生き物がいて、それぞれが生きている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39238, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生物多様性", "is_correct": true, "explanation": "「森を守ることは、生物多様性を守ることにつながる」と意味が通る。正しい。"}, {"text": "大そうじ", "is_correct": false, "explanation": "「大そうじを守る」は意味が通らず、文の流れに合わない。"}, {"text": "ボタン", "is_correct": false, "explanation": "「ボタンを守ることにつながる」は意味が通らず、森の文脈と合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖を守ることにつながる」は意味が通らず、文の論理に合わない。"}], "explanations": {"生物多様性": "「森を守ることは、生物多様性を守ることにつながる」と意味が通る。正しい。", "大そうじ": "「大そうじを守る」は意味が通らず、文の流れに合わない。", "ボタン": "「ボタンを守ることにつながる」は意味が通らず、森の文脈と合わない。", "砂糖": "「砂糖を守ることにつながる」は意味が通らず、文の論理に合わない。"}, "sentence_index": 0, "correct_answer": "生物多様性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この池には生物多様性が三つ見つかった。", "explanation": "ここは〈種〉の意味。生物多様性は種の豊かさを表す言葉で、〜つ・〜種類と数える対象ではない。"}, {"text": "海には生物多様性が多くすんでいる。", "explanation": "ここは〈生き物〉の意味。生物多様性は種類の豊かさという概念なので、すむ主体にはならない。"}, {"text": "この会社は社員の出身地が生物多様性に富んでいる。", "explanation": "ここは〈人の多様さ〉の意味。生物多様性は生き物の種類の豊かさを指し、人の出身には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39238, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生物多様性", "is_correct": true, "explanation": "「生物多様性を守るために田んぼの水路を残した」と意味が通る。正しい。"}, {"text": "給食", "is_correct": false, "explanation": "「給食を守るために」は意味が通らず、田んぼの水路の文脈と合わない。"}, {"text": "新聞", "is_correct": false, "explanation": "「新聞を守るために」は不自然で、水路を残す目的として成り立たない。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題を守るために」は意味が通らず、文の論理に合わない。"}], "explanations": {"生物多様性": "「生物多様性を守るために田んぼの水路を残した」と意味が通る。正しい。", "給食": "「給食を守るために」は意味が通らず、田んぼの水路の文脈と合わない。", "新聞": "「新聞を守るために」は不自然で、水路を残す目的として成り立たない。", "宿題": "「宿題を守るために」は意味が通らず、文の論理に合わない。"}, "sentence_index": 6, "correct_answer": "生物多様性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は生物多様性が豊かで、季節ごとに商品がよく変わる。", "explanation": "ここは〈品ぞろえ〉の意味。生物多様性は生き物の種類の豊かさを指し、店の商品の豊富さには使わない。"}, {"text": "この花は生物多様性が豊かで、絵の具の見本になる。", "explanation": "ここは〈色〉の意味。色の豊かさを表す語で、生き物の種類の豊かさを指す生物多様性とは合わない。"}, {"text": "この会議は生物多様性のある考えが出て、話し合いが進んだ。", "explanation": "ここは〈発想の幅〉の意味。生物多様性は生き物の種類の豊かさを指すので、発想の豊かさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39238, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の人たちは生物多様性に守るため、活動に参加している。", "corrected_sentence": "町の人たちは生物多様性を守るため、活動に参加している。", "error_description": "助詞の誤り。「守る」の目的語は「を」。「に」にすると「生物多様性に守る」となり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39238, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は生物多様性で守る活動を始めた。", "corrected_sentence": "町は生物多様性を守る活動を始めた。", "error_description": "助詞の誤り。「守る」の目的語は「を」。「で」は手段や場所を表し、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39242, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「毎月の小遣い」で、〈毎月〉が名詞を修飾する形として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「毎月が小遣い」は〈毎月〉を主語にするが、名詞を修飾する形として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「毎月を小遣い」は目的語の形で、名詞を修飾する文脈に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「毎月に小遣い」は時点を示す形で、〈毎月の〉の修飾の形にならない。"}], "correct_answer": "の", "explanations": {"の": "「毎月の小遣い」で、〈毎月〉が名詞を修飾する形として正しい。", "が": "「毎月が小遣い」は〈毎月〉を主語にするが、名詞を修飾する形として成り立たない。", "を": "「毎月を小遣い」は目的語の形で、名詞を修飾する文脈に合わない。", "に": "「毎月に小遣い」は時点を示す形で、〈毎月の〉の修飾の形にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "時点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
