INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39242, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「毎月の＋名詞」の形で、どの月にも繰り返し決まってあるもの・起こることを表す言葉です。", "primary_collocate": null, "pronunciation": "まいつき", "ipa": "maitsɯki", "syllable_count": 4, "sentences": [{"text": "毎月の家賃は、月末までに払わなければならない。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)の家賃(やちん)は、月末(げつまつ)までに払(はら)わなければならない。", "sentence_source": "generated"}, {"text": "毎月の小遣いは、五千円と決まっている。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)の小遣(こづか)いは、五千円(ごせんえん)と決(き)まっている。", "sentence_source": "generated"}, {"text": "毎月の目標を決めると、勉強を続けやすくなる。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)の目標(もくひょう)を決(き)めると、勉強(べんきょう)を続(つづ)けやすくなる。", "sentence_source": "generated"}, {"text": "毎月の電気代が高いので、節電を始めた。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)の電気代(でんきだい)が高(たか)いので、節電(せつでん)を始(はじ)めた。", "sentence_source": "generated"}, {"text": "毎月の第一日曜日に、町内で掃除をする。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)の第一(だいいち)日曜日(にちようび)に、町内(ちょうない)で掃除(そうじ)をする。", "sentence_source": "generated"}, {"text": "毎月の会議で、チームの成果が報告される。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)の会議(かいぎ)で、チームの成果(せいか)が報告(ほうこく)される。", "sentence_source": "generated"}, {"text": "毎月の貯金が少しずつ増えて、旅行の費用がたまった。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)の貯金(ちょきん)が少(すこ)しずつ増(ふ)えて、旅行(りょこう)の費用(ひよう)がたまった。", "sentence_source": "generated"}, {"text": "毎月の給料日には、家族で外食するのが楽しみだ。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)の給料日(きゅうりょうび)には、家族(かぞく)で外食(がいしょく)するのが楽(たの)しみだ。", "sentence_source": "generated"}, {"text": "毎月の雑誌代だけでも、一年にすると大きな金額になる。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)の雑誌代(ざっしだい)だけでも、一年(いちねん)にすると大(おお)きな金額(きんがく)になる。", "sentence_source": "generated"}, {"text": "毎月の天気を記録して、グラフにまとめた。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)の天気(てんき)を記録(きろく)して、グラフにまとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "毎月", "label": "基本形"}, {"form": "毎月の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "どの月も例外なく、という意味で名詞を修飾する毎月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24002b6-c864-4b47-b0ab-4d78dc52710d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39242, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毎月", "is_correct": true, "explanation": "月ごとに決まって払う家賃を表し、「毎月の家賃」として文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は家賃を払うものではないので、「雨の家賃」と文が成り立たない。"}, {"text": "猫", "is_correct": false, "explanation": "猫は家賃を払う対象ではないので、「猫の家賃」と合わない。"}, {"text": "海", "is_correct": false, "explanation": "海は家賃と結びつかないので、この文には入らない。"}], "explanations": {"毎月": "月ごとに決まって払う家賃を表し、「毎月の家賃」として文に合う。", "雨": "雨は家賃を払うものではないので、「雨の家賃」と文が成り立たない。", "猫": "猫は家賃を払う対象ではないので、「猫の家賃」と合わない。", "海": "海は家賃と結びつかないので、この文には入らない。"}, "sentence_index": 0, "correct_answer": "毎月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎月の元日には、家族で神社へお参りする。", "explanation": "ここは〈毎年〉の話。元日は一年に一度なので、〈毎月〉ではなく〈毎年〉を使う。"}, {"text": "毎月の入学式は、今年の春に一度だけ行われた。", "explanation": "ここは〈毎年〉の話。入学式は一年に一度なので、〈毎月〉ではなく〈毎年〉を使う。"}, {"text": "毎月の夏休みは、母と一緒に海へ行った。", "explanation": "ここは〈毎年〉の話。夏休みは一年に一度なので、〈毎月〉ではなく〈毎年〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39242, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毎月", "is_correct": true, "explanation": "月ごとに増える貯金を表し、「毎月の貯金」として文に合う。"}, {"text": "犬", "is_correct": false, "explanation": "犬は貯金をしないので、「犬の貯金」と文が成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "花は貯金と結びつかないので、この文には入らない。"}, {"text": "石", "is_correct": false, "explanation": "石は貯金と結びつかないので、「石の貯金」と合わない。"}], "explanations": {"毎月": "月ごとに増える貯金を表し、「毎月の貯金」として文に合う。", "犬": "犬は貯金をしないので、「犬の貯金」と文が成り立たない。", "花": "花は貯金と結びつかないので、この文には入らない。", "石": "石は貯金と結びつかないので、「石の貯金」と合わない。"}, "sentence_index": 6, "correct_answer": "毎月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎月の大晦日は、年に一度の家族の行事だ。", "explanation": "ここは〈毎年〉の話。大晦日は一年に一度なので、〈毎月〉ではなく〈毎年〉を使う。"}, {"text": "毎月の誕生日に、一生に一度のケーキを食べた。", "explanation": "ここは〈毎年〉の話。誕生日は一年に一度なので、〈毎月〉ではなく〈毎年〉を使う。"}, {"text": "毎月の初雪が、今年も山を白くした。", "explanation": "ここは〈毎年〉の話。初雪は一年に一度なので、〈毎月〉ではなく〈毎年〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39242, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎月に貯金で、旅行の費用をためた。", "corrected_sentence": "毎月の貯金で、旅行の費用をためた。", "error_description": "〈毎月〉は名詞を修飾するので「毎月の」と「の」で続ける。「毎月に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39242, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎月を給料で、旅行の費用がたまった。", "corrected_sentence": "毎月の給料で、旅行の費用がたまった。", "error_description": "「毎月」は名詞を修飾するので「毎月の」と「の」で続ける。「毎月を」の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
