INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39243, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "毎月（まいつき）とは、月に一度、またはそれぞれの月ごとに繰り返されることを表す言葉です。", "primary_collocate": null, "pronunciation": "まいつき", "ipa": "maitsɯki", "syllable_count": 4, "sentences": [{"text": "毎月、第一日曜日に町の公園で掃除をする。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)、第一(だいいち)日曜日(にちようび)に町(まち)の公園(こうえん)で掃除(そうじ)をする。", "sentence_source": "generated"}, {"text": "私は毎月、図書館で五冊の本を借りている。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "私(わたし)は毎月(まいつき)、図書館(としょかん)で五冊(ごさつ)の本(ほん)を借(か)りている。", "sentence_source": "generated"}, {"text": "毎月、同じ日に美容院へ行くことにしている。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)、同(おな)じ日(ひ)に美容院(びよういん)へ行(い)くことにしている。", "sentence_source": "generated"}, {"text": "姉は毎月、母に手紙を書いて送っている。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "姉(あね)は毎月(まいつき)、母(はは)に手紙(てがみ)を書(か)いて送(おく)っている。", "sentence_source": "generated"}, {"text": "この雑誌は毎月、十日に発売される。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "この雑誌(ざっし)は毎月(まいつき)、十日(とおか)に発売(はつばい)される。", "sentence_source": "generated"}, {"text": "毎月、少しずつお金をためて、新しいカメラを買った。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)、少(すこ)しずつお金(かね)をためて、新(あたら)しいカメラを買(か)った。", "sentence_source": "generated"}, {"text": "毎月、体重をはかって、ノートに書いている。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "毎月(まいつき)、体重(たいじゅう)をはかって、ノートに書(か)いている。", "sentence_source": "generated"}, {"text": "友達とは毎月、一度は会って食事をする。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "友達(ともだち)とは毎月(まいつき)、一度(いちど)は会(あ)って食事(しょくじ)をする。", "sentence_source": "generated"}, {"text": "病院で、毎月、血圧の検査を受けている。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "病院(びょういん)で、毎月(まいつき)、血圧(けつあつ)の検査(けんさ)を受(う)けている。", "sentence_source": "generated"}, {"text": "祖父は毎月、山の写真を撮りに出かける。", "target_word": "毎月", "complexity_tier": "T3", "furigana": "祖父(そふ)は毎月(まいつき)、山(やま)の写真(しゃしん)を撮(と)りに出(で)かける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "毎月", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "月に一度など、月ごとに繰り返す行動の頻度を表す毎月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24002b6-c864-4b47-b0ab-4d78dc52710d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39243, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毎月", "is_correct": true, "explanation": "月ごとに繰り返す行動を表し、「毎月、第一日曜日に」の副詞として文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は掃除を決める時の副詞にならず、「雨、第一日曜日に」と文が成り立たない。"}, {"text": "猫", "is_correct": false, "explanation": "猫は掃除の時期を示さないので、この文の副詞にならない。"}, {"text": "海", "is_correct": false, "explanation": "海は掃除の時期を示さないので、「海、第一日曜日に」と合わない。"}], "explanations": {"毎月": "月ごとに繰り返す行動を表し、「毎月、第一日曜日に」の副詞として文に合う。", "雨": "雨は掃除を決める時の副詞にならず、「雨、第一日曜日に」と文が成り立たない。", "猫": "猫は掃除の時期を示さないので、この文の副詞にならない。", "海": "海は掃除の時期を示さないので、「海、第一日曜日に」と合わない。"}, "sentence_index": 0, "correct_answer": "毎月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉は毎月、年末の大掃除を手伝う。", "explanation": "ここは〈毎年〉の話。年末の大掃除は一年に一度なので、〈毎月〉ではなく〈毎年〉を使う。"}, {"text": "姉は毎月、一年に一度の旅行を楽しむ。", "explanation": "ここは〈毎年〉の話。一年に一度の旅行は〈毎年〉で表すので、〈毎月〉とは合わない。"}, {"text": "姉は毎月、朝ごはんの後に歯をみがく。", "explanation": "ここは〈毎日〉の話。歯みがきは毎日するので、〈毎月〉ではなく〈毎日〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39243, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毎月", "is_correct": true, "explanation": "月ごとに繰り返す体重測定を表し、「毎月、体重をはかって」に合う。"}, {"text": "花", "is_correct": false, "explanation": "花は体重をはからないので、「花、体重をはかって」と合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は体重をはからないので、この文に入らない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は体重をはからないので、文の副詞として成り立たない。"}], "explanations": {"毎月": "月ごとに繰り返す体重測定を表し、「毎月、体重をはかって」に合う。", "花": "花は体重をはからないので、「花、体重をはかって」と合わない。", "石": "石は体重をはからないので、この文に入らない。", "雲": "雲は体重をはからないので、文の副詞として成り立たない。"}, "sentence_index": 6, "correct_answer": "毎月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は毎月、朝ごはんに味噌汁を飲んでいる。", "explanation": "ここは〈毎日〉の話。朝ごはんの味噌汁は毎日飲むので、〈毎月〉ではなく〈毎日〉を使う。"}, {"text": "祖父は毎月、年に一回だけ山を登る。", "explanation": "ここは〈毎年〉の話。年に一回だけ山に登るのは〈毎年〉で表すので、〈毎月〉とは合わない。"}, {"text": "祖父は毎月、新年の初日の出を見に行く。", "explanation": "ここは〈毎年〉の話。初日の出は年に一度なので、〈毎月〉ではなく〈毎年〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39243, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は毎月に、市場で野菜を買っている。", "corrected_sentence": "母は毎月、市場で野菜を買っている。", "error_description": "副詞の〈毎月〉の後には「、」を置く。「毎月に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39243, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は毎月を山へ写真を撮りに行く。", "corrected_sentence": "祖父は毎月、山へ写真を撮りに行く。", "error_description": "副詞の〈毎月〉の後には「、」を置く。「毎月を」の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39244, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ボランティア」に続けて「している」の目的語を示す格助詞で、ここでは正解。"}, {"text": "に", "is_correct": false, "explanation": "「ボランティアにしている」は不自然。「に」は方向や相手を示すため「する」には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「ボランティアでしている」は場所や手段の「で」になり、「している」につながらない。"}, {"text": "が", "is_correct": false, "explanation": "「ボランティアがしている」は主語になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「ボランティア」に続けて「している」の目的語を示す格助詞で、ここでは正解。", "に": "「ボランティアにしている」は不自然。「に」は方向や相手を示すため「する」には合わない。", "で": "「ボランティアでしている」は場所や手段の「で」になり、「している」につながらない。", "が": "「ボランティアがしている」は主語になり、文が成り立たない。"}, "error_tags": {"に": "方向・相手", "で": "場所・手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39244, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ボランティア」に続けて「集める」の対象を示す格助詞で、ここでは正解。"}, {"text": "や", "is_correct": false, "explanation": "「や」は名詞を並べる用法で、「集める」の対象にはならず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ボランティアに集める」は方向や相手を示す「に」で、集める対象を示す文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「ボランティアと集める」は共同や並列の「と」で、集める対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「ボランティア」に続けて「集める」の対象を示す格助詞で、ここでは正解。", "や": "「や」は名詞を並べる用法で、「集める」の対象にはならず文が成り立たない。", "に": "「ボランティアに集める」は方向や相手を示す「に」で、集める対象を示す文には合わない。", "と": "「ボランティアと集める」は共同や並列の「と」で、集める対象を示せない。"}, "error_tags": {"や": "並列", "に": "方向・相手", "と": "共同・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39244, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人がお金をもらわずに、みんなのためになることをすることです。", "primary_collocate": null, "pronunciation": "ぼらんてぃあ", "ipa": "boɾantia", "syllable_count": 5, "sentences": [{"text": "休みの日に、ごみを拾うボランティアをした。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]に、ごみを拾[ひろ]うボランティアをした。", "sentence_source": "generated"}, {"text": "姉は老人ホームでボランティアをしている。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "姉[あね]は老人[ろうじん]ホームでボランティアをしている。", "sentence_source": "generated"}, {"text": "ボランティアは、お金をもらわないで人を助ける活動だ。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "ボランティアは、お金[かね]をもらわないで人[ひと]を助[たす]ける活動[かつどう]だ。", "sentence_source": "generated"}, {"text": "祭りの日は、ボランティアの人たちが道を案内した。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]は、ボランティアの人[ひと]たちが道[みち]を案内[あんない]した。", "sentence_source": "generated"}, {"text": "大雨のあと、多くの学生がボランティアに来た。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のあと、多[おお]くの学生[がくせい]がボランティアに来[き]た。", "sentence_source": "generated"}, {"text": "私は子どもたちに本を読むボランティアに参加している。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "私[わたし]は子[こ]どもたちに本[ほん]を読[よ]むボランティアに参加[さんか]している。", "sentence_source": "generated"}, {"text": "彼はお金がなくても、ボランティアを続けている。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "彼[かれ]はお金[かね]がなくても、ボランティアを続[つづ]けている。", "sentence_source": "generated"}, {"text": "町のボランティアを集めるポスターを見た。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "町[まち]のボランティアを集[あつ]めるポスターを見[み]た。", "sentence_source": "generated"}, {"text": "ボランティアなので、給料は出ない。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "ボランティアなので、給料[きゅうりょう]は出[で]ない。", "sentence_source": "generated"}, {"text": "学校のボランティアで、駅前の花に水をやった。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "学校[がっこう]のボランティアで、駅前[えきまえ]の花[はな]に水[みず]をやった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ボランティア", "label": "基本形"}, {"form": "ボランティアを", "label": "を格"}], "register": "neutral", "sense_fingerprint": "お金をもらわずに人のために何かをすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba24b57-71af-43be-bb65-9109da6c8bd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39244, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ボランティア", "is_correct": true, "explanation": "ごみ拾いという無償の社会活動を表す正解。"}, {"text": "料理", "is_correct": false, "explanation": "「ごみを拾う料理」とは言えず、ごみ拾いの活動を表せないためここには入らない。"}, {"text": "貯金", "is_correct": false, "explanation": "「ごみを拾う貯金」は成り立たず、活動名としてここには入らない。"}, {"text": "手紙", "is_correct": false, "explanation": "「ごみを拾う手紙」は成り立たず、活動を表す語としてここには入らない。"}], "explanations": {"ボランティア": "ごみ拾いという無償の社会活動を表す正解。", "料理": "「ごみを拾う料理」とは言えず、ごみ拾いの活動を表せないためここには入らない。", "貯金": "「ごみを拾う貯金」は成り立たず、活動名としてここには入らない。", "手紙": "「ごみを拾う手紙」は成り立たず、活動を表す語としてここには入らない。"}, "sentence_index": 0, "correct_answer": "ボランティア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その会社は新しい工場に設備費をボランティアした。", "explanation": "ここは〈出資〉（資金を出す）の意味。ボランティアは時間や労力を使う活動を指すので、資金を出す行為には使わない。"}, {"text": "父は毎年、地元の学校に現金をボランティアしている。", "explanation": "ここは〈寄付〉の意味。ボランティアは時間や労力を無償で使う活動なので、現金を渡すことには使わない。"}, {"text": "図書館に古い本をボランティアした。", "explanation": "ここは〈寄贈〉（物を贈る）の意味。ボランティアは物ではなく活動を指すので、本を贈る行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39244, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ボランティア", "is_correct": true, "explanation": "お金をもらわずに続ける無償の活動を指す正解。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を続けている」とは言えず、続けられる活動の語としてここには入らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫を続けている」は成り立たず、ここには入らない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓を続けている」は成り立たず、ここには入らない。"}], "explanations": {"ボランティア": "お金をもらわずに続ける無償の活動を指す正解。", "天気": "「天気を続けている」とは言えず、続けられる活動の語としてここには入らない。", "冷蔵庫": "「冷蔵庫を続けている」は成り立たず、ここには入らない。", "窓": "「窓を続けている」は成り立たず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "ボランティア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店は地元の野菜をボランティアしている。", "explanation": "ここは〈販売〉（商品を売る）の意味。ボランティアは活動を指すので、商品を売ることには使わない。"}, {"text": "父は古い時計をボランティアした。", "explanation": "ここは〈修理〉（物を直す）の意味。ボランティアは人のための活動を指し、物を直す行為には使わない。"}, {"text": "会社は社員を海外にボランティアした。", "explanation": "ここは〈派遣〉（人を送る）の意味。ボランティアは人を送ることではなく、活動そのものを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39244, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は毎週、公園の掃除でボランティアにしている。", "corrected_sentence": "祖父は毎週、公園の掃除でボランティアをしている。", "error_description": "「する」の目的語は「を」で示す。「ボランティアに」は誤りで、正しくは「ボランティアを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39244, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は週末に、施設でボランティアがしている。", "corrected_sentence": "兄は週末に、施設でボランティアをしている。", "error_description": "「する」の目的語は「を」で示す。「が」は主語を示す助詞なので、ここでは誤り。正しくは「ボランティアを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39245, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ボランティアのために」の「の」。名詞につく「の」で、目的を示す「ために」につながる正解。"}, {"text": "が", "is_correct": false, "explanation": "「ボランティアがために」は成り立たず、主語の「が」は文に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「ボランティアでために」は場所や手段の「で」で、「ために」に続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「ボランティアへために」は方向の「へ」で、目的を示す「ために」に合わない。"}], "correct_answer": "の", "explanations": {"の": "「ボランティアのために」の「の」。名詞につく「の」で、目的を示す「ために」につながる正解。", "が": "「ボランティアがために」は成り立たず、主語の「が」は文に合わない。", "で": "「ボランティアでために」は場所や手段の「で」で、「ために」に続かない。", "へ": "「ボランティアへために」は方向の「へ」で、目的を示す「ために」に合わない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39245, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ボランティアで雪かきをしている」の手段や立場を示す「で」で、ここでは正解。"}, {"text": "に", "is_correct": false, "explanation": "「ボランティアに雪かき」は方向や相手を示す「に」で、雪かきの手段にはならない。"}, {"text": "を", "is_correct": false, "explanation": "「ボランティアを雪かきをしている」は「を」が二つ重なり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「ボランティアへ雪かき」は雪かきの対象・手段にならず不自然。"}], "correct_answer": "で", "explanations": {"で": "「ボランティアで雪かきをしている」の手段や立場を示す「で」で、ここでは正解。", "に": "「ボランティアに雪かき」は方向や相手を示す「に」で、雪かきの手段にはならない。", "を": "「ボランティアを雪かきをしている」は「を」が二つ重なり、文が成り立たない。", "へ": "「へ」は方向を示し、「ボランティアへ雪かき」は雪かきの対象・手段にならず不自然。"}, "error_tags": {"に": "方向・相手", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39245, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分の時間や力を使って、お金をもらわずに社会や地域のために行う活動のことです。", "primary_collocate": null, "pronunciation": "ぼらんてぃあ", "ipa": "boɾantia", "syllable_count": 5, "sentences": [{"text": "地域のボランティアに参加して、公園をきれいにした。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "地域[ちいき]のボランティアに参加[さんか]して、公園[こうえん]をきれいにした。", "sentence_source": "generated"}, {"text": "彼は毎週末、ボランティアのために時間を使っている。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "彼[かれ]は毎週末[まいしゅうまつ]、ボランティアのために時間[じかん]を使[つか]っている。", "sentence_source": "generated"}, {"text": "災害の現場で、ボランティアとして泥をかき出した。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "災害[さいがい]の現場[げんば]で、ボランティアとして泥[どろ]をかき出[だ]した。", "sentence_source": "generated"}, {"text": "ボランティアは、自分から進んでする活動だ。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "ボランティアは、自分[じぶん]から進[すす]んでする活動[かつどう]だ。", "sentence_source": "generated"}, {"text": "大学生のとき、海外でボランティアを経験した。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "大学生[だいがくせい]のとき、海外[かいがい]でボランティアを経験[けいけん]した。", "sentence_source": "generated"}, {"text": "母は町のボランティアで、お年寄りの買い物を手伝う。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "母[はは]は町[まち]のボランティアで、お年寄[としよ]りの買[か]い物[もの]を手伝[てつだ]う。", "sentence_source": "generated"}, {"text": "この活動はボランティアなので、参加費もいらない。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "この活動[かつどう]はボランティアなので、参加費[さんかひ]もいらない。", "sentence_source": "generated"}, {"text": "力仕事が得意な父は、ボランティアで雪かきをしている。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "力仕事[ちからしごと]が得意[とくい]な父[ちち]は、ボランティアで雪[ゆき]かきをしている。", "sentence_source": "generated"}, {"text": "ボランティアを通して、地域の人と知り合えた。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "ボランティアを通[とお]して、地域[ちいき]の人[ひと]と知[し]り合[あ]えた。", "sentence_source": "generated"}, {"text": "英語を使ったボランティアで、旅行者に道を教えた。", "target_word": "ボランティア", "complexity_tier": "T3", "furigana": "英語[えいご]を使[つか]ったボランティアで、旅行者[りょこうしゃ]に道[みち]を教[おし]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ボランティア", "label": "基本形"}, {"form": "ボランティアに", "label": "に格"}], "register": "neutral", "sense_fingerprint": "自分の時間や力で社会や地域のために行う無償の活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: かき出し (Zipf 1.45)']::text[], '6ba24b57-71af-43be-bb65-9109da6c8bd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39245, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ボランティア", "is_correct": true, "explanation": "「参加する」の対象になる無償の社会活動を表す正解。"}, {"text": "天気", "is_correct": false, "explanation": "「天気に参加する」は成り立たず、ここには入らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫に参加する」は成り立たず、ここには入らない。"}, {"text": "目薬", "is_correct": false, "explanation": "「目薬に参加する」は成り立たず、ここには入らない。"}], "explanations": {"ボランティア": "「参加する」の対象になる無償の社会活動を表す正解。", "天気": "「天気に参加する」は成り立たず、ここには入らない。", "冷蔵庫": "「冷蔵庫に参加する」は成り立たず、ここには入らない。", "目薬": "「目薬に参加する」は成り立たず、ここには入らない。"}, "sentence_index": 0, "correct_answer": "ボランティア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市民は毎年、税金をボランティアしている。", "explanation": "ここは〈納税〉（税金を納める）の意味。ボランティアは自分の意思で行う活動を指すので、義務である税金の納付には使わない。"}, {"text": "父は毎年、地元の施設に現金をボランティアしている。", "explanation": "ここは〈寄付〉の意味。ボランティアは金銭ではなく労力や時間を使う活動なので、現金には使わない。"}, {"text": "その会社は新工場に三億円をボランティアした。", "explanation": "ここは〈出資〉の意味。ボランティアは資金を出す行為を指さないので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39245, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ボランティア", "is_correct": true, "explanation": "お金をもらわない活動だから参加費がいらないという文脈に合う正解。"}, {"text": "雪", "is_correct": false, "explanation": "「雪なので、参加費もいらない」は意味が通らず、ここには入らない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "「洗濯機なので、参加費もいらない」は成り立たず、ここには入らない。"}, {"text": "電池", "is_correct": false, "explanation": "「電池なので、参加費もいらない」は成り立たず、ここには入らない。"}], "explanations": {"ボランティア": "お金をもらわない活動だから参加費がいらないという文脈に合う正解。", "雪": "「雪なので、参加費もいらない」は意味が通らず、ここには入らない。", "洗濯機": "「洗濯機なので、参加費もいらない」は成り立たず、ここには入らない。", "電池": "「電池なので、参加費もいらない」は成り立たず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "ボランティア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その店は地元の米をボランティアしている。", "explanation": "ここは〈販売〉（商品を売る）の意味。ボランティアは活動を指すので、商品を売ることには使わない。"}, {"text": "母は壊れた椅子をボランティアした。", "explanation": "ここは〈修理〉（物を直す）の意味。ボランティアは人のための活動で、物を直す行為には使わない。"}, {"text": "大使館は職員を現地にボランティアした。", "explanation": "ここは〈派遣〉（人を送る）の意味。ボランティアは人を送る行為ではなく、活動そのものを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39245, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生は毎週土曜日、河原の清掃のボランティアを参加している。", "corrected_sentence": "学生は毎週土曜日、河原の清掃のボランティアに参加している。", "error_description": "「参加する」の相手は「に」で示す。「ボランティアを参加」は誤りで、正しくは「ボランティアに参加」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39245, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は町の集会所で、子どもに読み聞かせのボランティアへしている。", "corrected_sentence": "母は町の集会所で、子どもに読み聞かせのボランティアをしている。", "error_description": "「する」の目的語は「を」で示す。「へ」は方向を表す助詞で、ここでは誤り。正しくは「ボランティアを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39246, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「森に入る」で、入る先を示す助詞として自然。"}, {"text": "を", "is_correct": false, "explanation": "「森を入る」は入るの対象にできず、日本語として不自然。"}, {"text": "が", "is_correct": false, "explanation": "「森が入ると」は森を主語にする形で、入る人の動作を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「森の入ると」は連体修飾として続かず、文の連結が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「森に入る」で、入る先を示す助詞として自然。", "を": "「森を入る」は入るの対象にできず、日本語として不自然。", "が": "「森が入ると」は森を主語にする形で、入る人の動作を表せない。", "の": "「森の入ると」は連体修飾として続かず、文の連結が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39246, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「森が広がる」で、森が主語になって広がる動作を表す自然な形。"}, {"text": "を", "is_correct": false, "explanation": "「森を広がる」は広がるが目的語を取れず、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「森と広がる」は並列を示すが、文の意味が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞で、「森より広がる」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「森が広がる」で、森が主語になって広がる動作を表す自然な形。", "を": "「森を広がる」は広がるが目的語を取れず、成り立たない。", "と": "「森と広がる」は並列を示すが、文の意味が成り立たない。", "より": "比較を示す助詞で、「森より広がる」は意味が通らない。"}, "error_tags": {"と": "並列", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39246, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの木が集まっているところ。", "primary_collocate": null, "pronunciation": "もり", "ipa": "mori", "syllable_count": 2, "sentences": [{"text": "子どもの頃、近所の森で虫を捕まえて遊んだ。", "target_word": "森", "complexity_tier": "T3", "furigana": "子[こ]どもの頃[ころ]、近所[きんじょ]の森[もり]で虫[むし]を捕[つか]まえて遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "森に入ると、土と葉の匂いがした。", "target_word": "森", "complexity_tier": "T3", "furigana": "森[もり]に入[はい]ると、土[つち]と葉[は]の匂[にお]いがした。", "sentence_source": "generated"}, {"text": "森の小道を歩くと、足もとで落ち葉が音を立てた。", "target_word": "森", "complexity_tier": "T3", "furigana": "森[もり]の小道[こみち]を歩[ある]くと、足[あし]もとで落[お]ち葉[ば]が音[おと]を立[た]てた。", "sentence_source": "generated"}, {"text": "大きな森に囲まれた村には、店が一軒しかない。", "target_word": "森", "complexity_tier": "T3", "furigana": "大[おお]きな森[もり]に囲[かこ]まれた村[むら]には、店[みせ]が一軒[いっけん]しかない。", "sentence_source": "generated"}, {"text": "森の奥から、フクロウの鳴き声が聞こえてくる。", "target_word": "森", "complexity_tier": "T3", "furigana": "森[もり]の奥[おく]から、フクロウの鳴[な]き声[ごえ]が聞[き]こえてくる。", "sentence_source": "generated"}, {"text": "雨のあとの森は、苔が濃い緑色に光っている。", "target_word": "森", "complexity_tier": "T3", "furigana": "雨[あめ]のあとの森[もり]は、苔[こけ]が濃[こ]い緑色[みどりいろ]に光[ひか]っている。", "sentence_source": "generated"}, {"text": "学校の裏の森は、昔から入ってはいけない場所だと言われている。", "target_word": "森", "complexity_tier": "T3", "furigana": "学校[がっこう]の裏[うら]の森[もり]は、昔[むかし]から入[はい]ってはいけない場所[ばしょ]だと言[い]われている。", "sentence_source": "generated"}, {"text": "森が広がるほど、川の水もきれいになる。", "target_word": "森", "complexity_tier": "T3", "furigana": "森[もり]が広[ひろ]がるほど、川[かわ]の水[みず]もきれいになる。", "sentence_source": "generated"}, {"text": "地図を見ると、この町の東側はほとんど森だ。", "target_word": "森", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ると、この町[まち]の東側[ひがしがわ]はほとんど森[もり]だ。", "sentence_source": "generated"}, {"text": "森の中でキャンプをして、星空を眺めた。", "target_word": "森", "complexity_tier": "T3", "furigana": "森[もり]の中[なか]でキャンプをして、星空[ほしぞら]を眺[なが]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "森", "label": "基本形"}], "register": "普通体の日常語", "sense_fingerprint": "たくさんの木が集まっている場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 足もと (Zipf 2.29)']::text[], '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39246, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "森", "is_correct": true, "explanation": "「近所の森で虫を捕まえて遊んだ」で、木が集まる場所として文脈に合う正解。"}, {"text": "電話", "is_correct": false, "explanation": "電話は虫を捕まえる場所にならず、「近所の電話で虫を捕まえて」は意味が通らない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は虫を捕まえる場所にならず、この文脈では成り立たない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機は虫捕りの場所にならず、「近所の洗濯機で」は不自然。"}], "explanations": {"森": "「近所の森で虫を捕まえて遊んだ」で、木が集まる場所として文脈に合う正解。", "電話": "電話は虫を捕まえる場所にならず、「近所の電話で虫を捕まえて」は意味が通らない。", "紙": "紙は虫を捕まえる場所にならず、この文脈では成り立たない。", "洗濯機": "洗濯機は虫捕りの場所にならず、「近所の洗濯機で」は不自然。"}, "sentence_index": 0, "correct_answer": "森"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家の前の森が、一輪だけ白く咲いている。", "explanation": "ここは〈花〉の意味。一輪だけ白く咲くのは花で、木が集まる森が咲くとは言わない。"}, {"text": "夏の森で、子どもたちが貝を拾っている。", "explanation": "ここは〈海〉の意味。貝を拾うのは海辺で、森では成り立たない。"}, {"text": "森に、睡蓮の花が浮かんでいる。", "explanation": "ここは〈池〉の意味。睡蓮が浮かぶのは池で、森とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39246, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "森", "is_correct": true, "explanation": "「学校の裏の森は入ってはいけない場所」で、木が集まる場所として文脈に合う正解。"}, {"text": "空", "is_correct": false, "explanation": "空は入る場所として扱えず、「入ってはいけない場所」と結びつかない。"}, {"text": "霧", "is_correct": false, "explanation": "霧は入ってはいけない場所として言われるものではなく、文として不自然。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱は入る場所にならず、「学校の裏の電柱は入ってはいけない場所」は意味が通らない。"}], "explanations": {"森": "「学校の裏の森は入ってはいけない場所」で、木が集まる場所として文脈に合う正解。", "空": "空は入る場所として扱えず、「入ってはいけない場所」と結びつかない。", "霧": "霧は入ってはいけない場所として言われるものではなく、文として不自然。", "電柱": "電柱は入る場所にならず、「学校の裏の電柱は入ってはいけない場所」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "森"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "高い空に、ちぎれた森がゆっくり流れている。", "explanation": "ここは〈雲〉の意味。ちぎれて流れるのは雲で、森には使わない。"}, {"text": "谷の奥で、森が白く落ちている。", "explanation": "ここは〈滝〉の意味。白く落ちるのは水の流れで、森とは合わない。"}, {"text": "夕方の森に、波が打ち寄せている。", "explanation": "ここは〈砂浜〉（海辺の陸地）の意味。波が打ち寄せるのは海辺で、森とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39246, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏休み、友達と近くの森に虫を捕まえて遊んだ。", "corrected_sentence": "夏休み、友達と近くの森で虫を捕まえて遊んだ。", "error_description": "「森」に続く助詞が「に」になっている。遊ぶ場所を示すには「で」が必要で、「森で虫を捕まえて遊んだ」が自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39246, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の東側の森を、夜になると鹿が現れる。", "corrected_sentence": "町の東側の森では、夜になると鹿が現れる。", "error_description": "「森」に続く助詞が「を」になっている。場面を示すには「では」が必要で、「森では、夜になると鹿が現れる」が自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39247, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「深い森を歩いた」の目的語を示す助詞で、歩く場所として自然。"}, {"text": "が", "is_correct": false, "explanation": "「森が歩いた」は森を動作主にする形になり、歩いた人の動作を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「深い森の歩いた」は連体修飾として続かず、動詞の目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「森と歩いた」は同伴の意味になり、深い森を歩く場所の文にはならない。"}], "correct_answer": "を", "explanations": {"を": "「深い森を歩いた」の目的語を示す助詞で、歩く場所として自然。", "が": "「森が歩いた」は森を動作主にする形になり、歩いた人の動作を表せない。", "の": "「深い森の歩いた」は連体修飾として続かず、動詞の目的語にならない。", "と": "「森と歩いた」は同伴の意味になり、深い森を歩く場所の文にはならない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "同伴"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39247, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「森に立っている」で、杉が立つ場所を示す助詞として自然。"}, {"text": "へ", "is_correct": false, "explanation": "「森へ立っている」は方向を示すが、立っている場所を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「森から立っている」は場所の関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞で、「森より立っている」は文の関係が通らない。"}], "correct_answer": "に", "explanations": {"に": "「森に立っている」で、杉が立つ場所を示す助詞として自然。", "へ": "「森へ立っている」は方向を示すが、立っている場所を示せない。", "から": "起点を示す助詞で、「森から立っている」は場所の関係が成り立たない。", "より": "比較を示す助詞で、「森より立っている」は文の関係が通らない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39247, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "多くの木が生い茂っている場所。森林。", "primary_collocate": null, "pronunciation": "もり", "ipa": "mori", "syllable_count": 2, "sentences": [{"text": "森の奥深くに佇む、その赤いドアの小さな家は、かつて祖母が一人で暮らしていた場所だ。", "target_word": "森", "complexity_tier": "T4", "furigana": "森[もり]の奥深[おくぶか]くに佇[たたず]む、その赤[あか]いドアの小[ちい]さな家[いえ]は、かつて祖母[そぼ]が一人[ひとり]で暮[く]らしていた場所[ばしょ]だ。", "sentence_source": "mined"}, {"text": "夏休みに、家族で深い森を歩いた。", "target_word": "森", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、家族[かぞく]で深[ふか]い森[もり]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "森の中は涼しくて、鳥の声がよく聞こえた。", "target_word": "森", "complexity_tier": "T3", "furigana": "森[もり]の中[なか]は涼[すず]しくて、鳥[とり]の声[こえ]がよく聞[き]こえた。", "sentence_source": "generated"}, {"text": "町の北には広い森があり、多くの動物が暮らしている。", "target_word": "森", "complexity_tier": "T3", "furigana": "町[まち]の北[きた]には広[ひろ]い森[もり]があり、多[おお]くの動物[どうぶつ]が暮[く]らしている。", "sentence_source": "generated"}, {"text": "森を抜けると、小さな湖が見えてきた。", "target_word": "森", "complexity_tier": "T3", "furigana": "森[もり]を抜[ぬ]けると、小[ちい]さな湖[みずうみ]が見[み]えてきた。", "sentence_source": "generated"}, {"text": "森の木が切られて、住む場所を失った鳥もいる。", "target_word": "森", "complexity_tier": "T3", "furigana": "森[もり]の木[き]が切[き]られて、住[す]む場所[ばしょ]を失[うしな]った鳥[とり]もいる。", "sentence_source": "generated"}, {"text": "霧の朝、森は静まり返っていた。", "target_word": "森", "complexity_tier": "T3", "furigana": "霧[きり]の朝[あさ]、森[もり]は静[しず]まり返[かえ]っていた。", "sentence_source": "generated"}, {"text": "この森には樹齢千年の杉が立っている。", "target_word": "森", "complexity_tier": "T3", "furigana": "この森[もり]には樹齢[じゅれい]千年[せんねん]の杉[すぎ]が立[た]っている。", "sentence_source": "generated"}, {"text": "森で道に迷って、暗くなる前に川沿いを下った。", "target_word": "森", "complexity_tier": "T3", "furigana": "森[もり]で道[みち]に迷[まよ]って、暗[くら]くなる前[まえ]に川沿[かわぞ]いを下[くだ]った。", "sentence_source": "generated"}, {"text": "秋になると、森は赤や黄色に染まる。", "target_word": "森", "complexity_tier": "T3", "furigana": "秋[あき]になると、森[もり]は赤[あか]や黄色[きいろ]に染[そ]まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "森", "label": "基本形"}], "register": "普通体の日常語", "sense_fingerprint": "木が多く茂った広い場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 静まり返っ (Zipf 2.4)']::text[], '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39247, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "森", "is_correct": true, "explanation": "「森の奥深くに佇む家」で、木の茂る場所として文脈に合う正解。"}, {"text": "雑誌", "is_correct": false, "explanation": "雑誌は場所ではないので、「雑誌の奥深くに佇む家」は文として不自然。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は場所ではなく、「眠気の奥深くに佇む家」は意味が通らない。"}, {"text": "鞄", "is_correct": false, "explanation": "鞄は持ち物で、家が佇む場所として使えず、文が成り立たない。"}], "explanations": {"森": "「森の奥深くに佇む家」で、木の茂る場所として文脈に合う正解。", "雑誌": "雑誌は場所ではないので、「雑誌の奥深くに佇む家」は文として不自然。", "眠気": "眠気は場所ではなく、「眠気の奥深くに佇む家」は意味が通らない。", "鞄": "鞄は持ち物で、家が佇む場所として使えず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "森"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭に森を一本植えたら、夏に木陰ができた。", "explanation": "ここは〈木〉（一本の木）の意味。森は木が集まった場所なので、一本だけ植えるという言い方には合わない。"}, {"text": "夏の森に、稲が並んでいる。", "explanation": "ここは〈田〉の意味。稲が列になって並ぶのは田で、木が茂る森には合わない。"}, {"text": "森の大根が一列に並んでいる。", "explanation": "ここは〈畑〉の意味。大根が一列に並んで育つのは畑で、木が茂る森とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39247, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "森", "is_correct": true, "explanation": "霧の中で静まり返る場所として、森は文脈に合う正解。"}, {"text": "財布", "is_correct": false, "explanation": "財布は静まり返る対象にならず、「財布は静まり返っていた」は不自然。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は静まり返るという様子に結びつかず、文が成り立たない。"}, {"text": "味噌汁", "is_correct": false, "explanation": "味噌汁は静まり返るという状態にならず、文として意味が通らない。"}], "explanations": {"森": "霧の中で静まり返る場所として、森は文脈に合う正解。", "財布": "財布は静まり返る対象にならず、「財布は静まり返っていた」は不自然。", "椅子": "椅子は静まり返るという様子に結びつかず、文が成り立たない。", "味噌汁": "味噌汁は静まり返るという状態にならず、文として意味が通らない。"}, "sentence_index": 6, "correct_answer": "森"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "森に漁船が並んで、夕日が映っている。", "explanation": "ここは〈港〉の意味。漁船が並んで停泊するのは港で、木が茂る森とは合わない。"}, {"text": "高い空に、白い森がぽかりと浮かんでいる。", "explanation": "ここは〈雲〉の意味。空に浮かぶのは雲で、木が茂る森は地面に広がるものなので合わない。"}, {"text": "山の上から森が勢いよく流れ落ちる。", "explanation": "ここは〈滝〉の意味。流れ落ちるのは水で、森とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39247, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末に、家族で近くの森が歩いた。", "corrected_sentence": "週末に、家族で近くの森を歩いた。", "error_description": "「森」に続く助詞が「が」になっている。歩く対象を示す「を」が正しく、「森を歩いた」が自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39247, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔、この森へ狼が住んでいた。", "corrected_sentence": "昔、この森に狼が住んでいた。", "error_description": "「森」に続く助詞が「へ」になっている。住む場所を示すには「に」が必要で、「森に住んでいた」が自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39248, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「住処になっています」は、ある状態へ変わったことを表す「に」で自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「住処をなっています」とは続かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。「住処でなっています」では変化の意味が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「住処へなっています」では変化の相手にならない。"}], "correct_answer": "に", "explanations": {"に": "正解。「住処になっています」は、ある状態へ変わったことを表す「に」で自然に続く。", "を": "「を」は目的語を示す。「住処をなっています」とは続かない。", "で": "「で」は場所や手段を示す。「住処でなっています」では変化の意味が成り立たない。", "へ": "「へ」は方向を示す。「住処へなっています」では変化の相手にならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39248, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39248, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生きものが住んでいる場所のことです。", "primary_collocate": null, "pronunciation": "すみか", "ipa": "sɯmika", "syllable_count": 3, "sentences": [{"text": "森はたくさんの動物の住処です。", "target_word": "住処", "complexity_tier": "T3", "furigana": "森(もり)はたくさんの動物(どうぶつ)の住処(すみか)です。", "sentence_source": "generated"}, {"text": "川の近くは、カワセミの住処になっています。", "target_word": "住処", "complexity_tier": "T3", "furigana": "川(かわ)の近(ちか)くは、カワセミの住処(すみか)になっています。", "sentence_source": "generated"}, {"text": "木を切りすぎて、鳥は住処を失いました。", "target_word": "住処", "complexity_tier": "T3", "furigana": "木(き)を切(き)りすぎて、鳥(とり)は住処(すみか)を失(うしな)いました。", "sentence_source": "generated"}, {"text": "クマは冬になると、穴の中の住処で眠ります。", "target_word": "住処", "complexity_tier": "T3", "furigana": "クマは冬(ふゆ)になると、穴(あな)の中(なか)の住処(すみか)で眠(ねむ)ります。", "sentence_source": "generated"}, {"text": "海の中には、魚たちの住処がたくさんあります。", "target_word": "住処", "complexity_tier": "T3", "furigana": "海(うみ)の中(なか)には、魚(さかな)たちの住処(すみか)がたくさんあります。", "sentence_source": "generated"}, {"text": "人間が森を開発したので、動物たちは新しい住処を探しています。", "target_word": "住処", "complexity_tier": "T3", "furigana": "人間(にんげん)が森(もり)を開発(かいはつ)したので、動物(どうぶつ)たちは新(あたら)しい住処(すみか)を探(さが)しています。", "sentence_source": "generated"}, {"text": "この池は、めずらしいカエルの住処として守られています。", "target_word": "住処", "complexity_tier": "T3", "furigana": "この池(いけ)は、めずらしいカエルの住処(すみか)として守(まも)られています。", "sentence_source": "generated"}, {"text": "地球は私たち人間の住処でもあります。", "target_word": "住処", "complexity_tier": "T3", "furigana": "地球(ちきゅう)は私(わたし)たち人間(にんげん)の住処(すみか)でもあります。", "sentence_source": "generated"}, {"text": "虫の住処になるように、庭に石を置きました。", "target_word": "住処", "complexity_tier": "T3", "furigana": "虫(むし)の住処(すみか)になるように、庭(にわ)に石(いし)を置(お)きました。", "sentence_source": "generated"}, {"text": "サンゴ礁は、小さな魚にとって安全な住処です。", "target_word": "住処", "complexity_tier": "T3", "furigana": "サンゴ礁(しょう)は、小(ちい)さな魚(さかな)にとって安全(あんぜん)な住処(すみか)です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "住処", "label": "基本形"}, {"form": "住処に", "label": "に格"}, {"form": "住処を", "label": "を格"}], "register": "標準（丁寧体）", "sense_fingerprint": "動物や虫などの生きものが暮らしている場所（森・池・海など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7187a5e-8c4c-4216-b62d-4b95debbe3a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39248, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住処", "is_correct": true, "explanation": "正解。動物が暮らす場所を指し、「森は動物の住処です」で意味が通る。"}, {"text": "池", "is_correct": false, "explanation": "池は水をたたえた場所。「森は動物の池です」では森と池が同じものになり、文が成り立たない。"}, {"text": "巣箱", "is_correct": false, "explanation": "鳥などのために作る箱で、森全体を指せない。「森は動物の巣箱です」は不自然。"}, {"text": "花畑", "is_correct": false, "explanation": "花を植えた畑のこと。森を花畑と言うと動物の暮らしの話と合わない。"}], "explanations": {"住処": "正解。動物が暮らす場所を指し、「森は動物の住処です」で意味が通る。", "池": "池は水をたたえた場所。「森は動物の池です」では森と池が同じものになり、文が成り立たない。", "巣箱": "鳥などのために作る箱で、森全体を指せない。「森は動物の巣箱です」は不自然。", "花畑": "花を植えた畑のこと。森を花畑と言うと動物の暮らしの話と合わない。"}, "sentence_index": 0, "correct_answer": "住処"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "引っ越したので、年賀状に新しい住処を書きました。", "explanation": "ここは〈住所〉の意味。住処は生きものが暮らす場所を指すので、郵便の宛先には使わない。"}, {"text": "会社は海外に新しい住処を作り、営業の拠点にしました。", "explanation": "ここは〈事務所〉の意味。住処は生きものの住みかで、会社の仕事場には使わない。"}, {"text": "荷物を減らして、棚の住処を空けました。", "explanation": "ここは〈置き場所〉の意味。住処は生きものが暮らす場所なので、棚のすき間には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39248, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住処", "is_correct": true, "explanation": "正解。カエルの暮らす場所を指し、「カエルの住処として守られています」と自然に続く。"}, {"text": "名前", "is_correct": false, "explanation": "呼び名のこと。「カエルの名前として守られています」では意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、「カエルの季節」とは言わない。"}, {"text": "教室", "is_correct": false, "explanation": "学ぶ部屋のこと。「カエルの教室として守られています」では生きものの住む場所の意味にならない。"}], "explanations": {"住処": "正解。カエルの暮らす場所を指し、「カエルの住処として守られています」と自然に続く。", "名前": "呼び名のこと。「カエルの名前として守られています」では意味が通らない。", "季節": "時期を表す語で、「カエルの季節」とは言わない。", "教室": "学ぶ部屋のこと。「カエルの教室として守られています」では生きものの住む場所の意味にならない。"}, "sentence_index": 6, "correct_answer": "住処"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行先で、予約しておいた住処に泊まりました。", "explanation": "ここは〈宿〉の意味。住処は生きものが住む場所で、旅行の一時的な宿には使わない。"}, {"text": "工房の住処で、毎日陶器を作っています。", "explanation": "ここは〈作業場〉の意味。住処は生きものの暮らす場所で、仕事をする工房には使えない。"}, {"text": "転校した彼は、クラスの中に自分の住処をなかなか見つけられなかった。", "explanation": "ここは〈居場所〉（自分がいてよい場所）の意味。人の居場所は〈居場所〉で表し、生きものが暮らす場所を指す「住処」の意味とは異なる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39248, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬の間、ヘビは岩の割れ目の住処を過ごします。", "corrected_sentence": "冬の間、ヘビは岩の割れ目の住処で過ごします。", "error_description": "「過ごす」の場所を示すのは「で」。「住処を」は目的語の形で、場所を表す「で」に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39248, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強い台風で、カエルの住処を流されてしまいました。", "corrected_sentence": "強い台風で、カエルの住処が流されてしまいました。", "error_description": "「流される」（受け身）の主語は「が」。「住処を」は目的語の形で誤りで、「住処が流される」と直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39249, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「住処にしていた」の「に」は、そのものを何にするかを表し、自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「住処がしていた」では主語と動詞が結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。「住処でしていた」では意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「住処をしていた」は「する」の目的語として不自然。"}], "correct_answer": "に", "explanations": {"に": "正解。「住処にしていた」の「に」は、そのものを何にするかを表し、自然に続く。", "が": "「が」は主語を示す。「住処がしていた」では主語と動詞が結びつかない。", "で": "「で」は場所や手段を示す。「住処でしていた」では意味が通らない。", "を": "「を」は目的語を示す。「住処をしていた」は「する」の目的語として不自然。"}, "error_tags": {"が": "主語", "で": "場所・手段", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39249, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「住処を守る」の「を」は守る対象を示し、文の意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「住処が守るために」では守る主体が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示す。「住処に守る」では守る対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「住処へ守る」では守るという動作と結びつかない。"}], "correct_answer": "を", "explanations": {"を": "正解。「住処を守る」の「を」は守る対象を示し、文の意味に合う。", "が": "「が」は主語を示す。「住処が守るために」では守る主体が合わない。", "に": "「に」は相手や場所を示す。「住処に守る」では守る対象にならない。", "へ": "「へ」は方向を示す。「住処へ守る」では守るという動作と結びつかない。"}, "error_tags": {"が": "主語", "に": "相手・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39249, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生物が生活の拠点とする場所。巣や隠れ家など。", "primary_collocate": null, "pronunciation": "すみか", "ipa": "sɯmika", "syllable_count": 3, "sentences": [{"text": "キツネは山の斜面に穴を掘って住処を作ります。", "target_word": "住処", "complexity_tier": "T3", "furigana": "キツネは山(やま)の斜面(しゃめん)に穴(あな)を掘(ほ)って住処(すみか)を作(つく)ります。", "sentence_source": "generated"}, {"text": "犯人は古い倉庫を住処にしていたそうです。", "target_word": "住処", "complexity_tier": "T3", "furigana": "犯人(はんにん)は古(ふる)い倉庫(そうこ)を住処(すみか)にしていたそうです。", "sentence_source": "generated"}, {"text": "ツバメは毎年同じ軒下を住処にして、巣を作ります。", "target_word": "住処", "complexity_tier": "T3", "furigana": "ツバメは毎年(まいとし)同(おな)じ軒下(のきした)を住処(すみか)にして、巣(す)を作(つく)ります。", "sentence_source": "generated"}, {"text": "雨がやむと、アリは地面の下の住処から出てきました。", "target_word": "住処", "complexity_tier": "T3", "furigana": "雨(あめ)がやむと、アリは地面(じめん)の下(した)の住処(すみか)から出(で)てきました。", "sentence_source": "generated"}, {"text": "洞窟はコウモリの住処で、昼間は静かです。", "target_word": "住処", "complexity_tier": "T3", "furigana": "洞窟(どうくつ)はコウモリの住処(すみか)で、昼間(ひるま)は静(しず)かです。", "sentence_source": "generated"}, {"text": "野良猫が空き家を住処にしているので、近所の人は心配しています。", "target_word": "住処", "complexity_tier": "T3", "furigana": "野良猫(のらねこ)が空(あ)き家(や)を住処(すみか)にしているので、近所(きんじょ)の人(ひと)は心配(しんぱい)しています。", "sentence_source": "generated"}, {"text": "川の岸に、ビーバーが木で作った住処があります。", "target_word": "住処", "complexity_tier": "T3", "furigana": "川(かわ)の岸(きし)に、ビーバーが木(き)で作(つく)った住処(すみか)があります。", "sentence_source": "generated"}, {"text": "鳥の住処を守るために、春の間は木を切りません。", "target_word": "住処", "complexity_tier": "T3", "furigana": "鳥(とり)の住処(すみか)を守(まも)るために、春(はる)の間(あいだ)は木(き)を切(き)りません。", "sentence_source": "generated"}, {"text": "ヤドカリは貝がらを背負って、それを住処にしています。", "target_word": "住処", "complexity_tier": "T3", "furigana": "ヤドカリは貝(かい)がらを背負(せお)って、それを住処(すみか)にしています。", "sentence_source": "generated"}, {"text": "スズメバチの住処に近づくと危ないので、注意してください。", "target_word": "住処", "complexity_tier": "T3", "furigana": "スズメバチの住処(すみか)に近(ちか)づくと危(あぶ)ないので、注意(ちゅうい)してください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "住処", "label": "基本形"}, {"form": "住処に", "label": "に格"}, {"form": "住処を", "label": "を格"}], "register": "標準（丁寧体）", "sense_fingerprint": "生物が巣や隠れ家として生活の拠点にしている場所（住処にする・住処を作る）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7187a5e-8c4c-4216-b62d-4b95debbe3a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39249, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住処", "is_correct": true, "explanation": "正解。穴を掘って作るのは生活の拠点で、「住処を作ります」と自然に続く。"}, {"text": "食事", "is_correct": false, "explanation": "料理のこと。「穴を掘って食事を作ります」では文の場面に合わない。"}, {"text": "歌", "is_correct": false, "explanation": "作品のこと。穴を掘る行為とつながらず、「歌を作ります」と続けても場面に合わない。"}, {"text": "教室", "is_correct": false, "explanation": "学ぶ部屋のこと。穴を掘って作るものではなく、文の意味が通らない。"}], "explanations": {"住処": "正解。穴を掘って作るのは生活の拠点で、「住処を作ります」と自然に続く。", "食事": "料理のこと。「穴を掘って食事を作ります」では文の場面に合わない。", "歌": "作品のこと。穴を掘る行為とつながらず、「歌を作ります」と続けても場面に合わない。", "教室": "学ぶ部屋のこと。穴を掘って作るものではなく、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "住処"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は、駅前の大きな住処で行われました。", "explanation": "ここは〈会議室〉の意味。住処は生きものが暮らす場所で、会議を開く部屋には使わない。"}, {"text": "社会人になってから、同じ会社の住処で働いています。", "explanation": "ここは〈職場〉の意味。住処は生きものが巣や隠れ家として暮らす場所で、勤め先には使えない。"}, {"text": "車は、毎晩住処に止めています。", "explanation": "ここは〈車庫〉の意味。住処は生きものが生活する拠点で、車を止める場所には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39249, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住処", "is_correct": true, "explanation": "正解。ビーバーが木で作るのは暮らす場所で、「木で作った住処があります」と自然に続く。"}, {"text": "手紙", "is_correct": false, "explanation": "書くもの。木で作る手紙は文の場面に合わない。"}, {"text": "病気", "is_correct": false, "explanation": "人や動物がかかるもの。作ったものを指せず、文が成り立たない。"}, {"text": "宿題", "is_correct": false, "explanation": "学校でするもの。木で作ったものとしては意味が通らない。"}], "explanations": {"住処": "正解。ビーバーが木で作るのは暮らす場所で、「木で作った住処があります」と自然に続く。", "手紙": "書くもの。木で作る手紙は文の場面に合わない。", "病気": "人や動物がかかるもの。作ったものを指せず、文が成り立たない。", "宿題": "学校でするもの。木で作ったものとしては意味が通らない。"}, "sentence_index": 6, "correct_answer": "住処"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "買ってきた食材を、すぐに住処に入れました。", "explanation": "ここは〈冷蔵庫〉の意味。住処は生きものが暮らす場所で、食材を入れる設備には使わない。"}, {"text": "店の住処に、新しい商品を並べました。", "explanation": "ここは〈陳列棚〉の意味。住処は生きものの暮らす場所で、商品を並べる棚には使わない。"}, {"text": "お菓子は、住処で買いました。", "explanation": "ここは〈売店〉の意味。住処は生きものが暮らす場所で、買い物をする店には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39249, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "アリは地面の下に住処で作って、暮らしています。", "corrected_sentence": "アリは地面の下に住処を作って、暮らしています。", "error_description": "「作る」の目的語を示すのは「を」。「住処で作る」の「で」は誤りで、「住処を作る」と直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39249, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ビーバーは、川の岸の住処を冬を越します。", "corrected_sentence": "ビーバーは、川の岸の住処で冬を越します。", "error_description": "「越す」の場所を示すのは「で」。「住処を」は目的語の形で誤りで、「住処で」と直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39250, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減らす", "is_correct": true, "explanation": "「増やす」の対義語で、数や量を少なくする意味。"}, {"text": "集める", "is_correct": false, "explanation": "一か所に寄せる語で、「増やす」の対義語ではない。"}, {"text": "広げる", "is_correct": false, "explanation": "範囲や規模を大きくする語で、対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる語で、対義語ではない。"}], "correct_answer": "減らす", "explanations": {"減らす": "「増やす」の対義語で、数や量を少なくする意味。", "集める": "一か所に寄せる語で、「増やす」の対義語ではない。", "広げる": "範囲や規模を大きくする語で、対義語ではない。", "運ぶ": "物を移動させる語で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39250, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「本数を」の「を」で、増やす対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「本数に増やして」では増やす対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」は、増やす対象には使えない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す「より」は、増やす対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「本数を」の「を」で、増やす対象を示す。", "に": "「本数に増やして」では増やす対象を示せない。", "で": "手段を示す「で」は、増やす対象には使えない。", "より": "比較の基準を示す「より」は、増やす対象を表せない。"}, "error_tags": {"に": "方向・結果", "で": "手段", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減らす", "is_correct": true, "explanation": "「増やす」の対義語で、数や量を少なくする意味。"}, {"text": "届ける", "is_correct": false, "explanation": "物を相手に送り届ける語で、対義語ではない。"}, {"text": "伸ばす", "is_correct": false, "explanation": "長さや範囲を広げる語で、対義語ではない。"}, {"text": "固める", "is_correct": false, "explanation": "硬くする、まとめる意味の語で、対義語ではない。"}], "correct_answer": "減らす", "explanations": {"減らす": "「増やす」の対義語で、数や量を少なくする意味。", "届ける": "物を相手に送り届ける語で、対義語ではない。", "伸ばす": "長さや範囲を広げる語で、対義語ではない。", "固める": "硬くする、まとめる意味の語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39250, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを、もっとたくさんにする。", "primary_collocate": null, "pronunciation": "ふやす", "ipa": "ɸɯjasɯ", "syllable_count": 3, "sentences": [{"text": "友だちを増やすために、新しいクラブに入りました。", "target_word": "増やす", "complexity_tier": "T3", "furigana": "友(とも)だちを増(ふ)やすために、新(あたら)しいクラブに入(はい)りました。", "sentence_source": "generated"}, {"text": "野菜を食べる量を増やしたら、体の調子がよくなりました。", "target_word": "増やした", "complexity_tier": "T3", "furigana": "野菜(やさい)を食(た)べる量(りょう)を増(ふ)やしたら、体(からだ)の調子(ちょうし)がよくなりました。", "sentence_source": "generated"}, {"text": "母は庭の花を増やしたくて、種をたくさん買いました。", "target_word": "増やし", "complexity_tier": "T3", "furigana": "母(はは)は庭(にわ)の花(はな)を増(ふ)やしたくて、種(たね)をたくさん買(か)いました。", "sentence_source": "generated"}, {"text": "本が多くて入らないので、本棚を増やしました。", "target_word": "増やし", "complexity_tier": "T3", "furigana": "本(ほん)が多(おお)くて入(はい)らないので、本棚(ほんだな)を増(ふ)やしました。", "sentence_source": "generated"}, {"text": "夏は忙しいので、お店は店員を増やします。", "target_word": "増やし", "complexity_tier": "T3", "furigana": "夏(なつ)は忙(いそが)しいので、お店(みせ)は店員(てんいん)を増(ふ)やします。", "sentence_source": "generated"}, {"text": "英語の勉強時間を増やしましたが、まだ上手に話せません。", "target_word": "増やし", "complexity_tier": "T3", "furigana": "英語(えいご)の勉強時間(べんきょうじかん)を増(ふ)やしましたが、まだ上手(じょうず)に話(はな)せません。", "sentence_source": "generated"}, {"text": "町は、公園を増やす計画を発表しました。", "target_word": "増やす", "complexity_tier": "T3", "furigana": "町(まち)は、公園(こうえん)を増(ふ)やす計画(けいかく)を発表(はっぴょう)しました。", "sentence_source": "generated"}, {"text": "朝は電車が混むので、本数を増やしてほしいと、みんなが言っています。", "target_word": "増やして", "complexity_tier": "T3", "furigana": "朝(あさ)は電車(でんしゃ)が混(こ)むので、本数(ほんすう)を増(ふ)やしてほしいと、みんなが言(い)っています。", "sentence_source": "generated"}, {"text": "趣味を増やすと、毎日がもっと楽しくなります。", "target_word": "増やす", "complexity_tier": "T3", "furigana": "趣味(しゅみ)を増(ふ)やすと、毎日(まいにち)がもっと楽(たの)しくなります。", "sentence_source": "generated"}, {"text": "寒くなったので、毛布を一枚増やして寝ました。", "target_word": "増やして", "complexity_tier": "T3", "furigana": "寒(さむ)くなったので、毛布(もうふ)を一枚(いちまい)増(ふ)やして寝(ね)ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "増やす", "label": "辞書形"}, {"form": "増やし", "label": "連用形"}, {"form": "増やした", "label": "タ形"}, {"form": "増やして", "label": "テ形"}, {"form": "増やさない", "label": "ナイ形"}, {"form": "増やせば", "label": "仮定形"}, {"form": "増やそう", "label": "意志形"}], "register": "標準（丁寧体）", "sense_fingerprint": "人・物・時間などを今よりたくさんにする（友だち・本棚・店員などを増やす）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7187a5e-8c4c-4216-b62d-4b95debbe3a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39250, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "増やす", "is_correct": true, "explanation": "「増やすために」で目的を表し、友だちを増やすことを示すので文脈に合う。"}, {"text": "増える", "is_correct": false, "explanation": "自動詞なので「友だちを」と続かず、「増えるために」は成り立たない。"}, {"text": "減る", "is_correct": false, "explanation": "自動詞で「友だちを」を取れない。「減るために」も文に合わない。"}, {"text": "減らす", "is_correct": false, "explanation": "「友だちを減らすために」は文法上は続くが、クラブに入る目的として意味が逆になり文脈に合わない。"}], "explanations": {"増やす": "「増やすために」で目的を表し、友だちを増やすことを示すので文脈に合う。", "増える": "自動詞なので「友だちを」と続かず、「増えるために」は成り立たない。", "減る": "自動詞で「友だちを」を取れない。「減るために」も文に合わない。", "減らす": "「友だちを減らすために」は文法上は続くが、クラブに入る目的として意味が逆になり文脈に合わない。"}, "sentence_index": 0, "correct_answer": "増やす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "社員の意識を増やす研修を行った。", "explanation": "ここは〈高める〉の意味。増やすは数や量を多くする語で、意識の度合いを上げる意味には合わない。"}, {"text": "店は来月から値段を増やすことにした。", "explanation": "ここは〈上げる〉の意味。増やすは数量を多くする語で、価格を引き上げることには使わない。"}, {"text": "先生は生徒の理解を増やす授業をした。", "explanation": "ここは〈深める〉の意味。増やすは数を多くする語で、理解の深さを表す場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39250, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "増やす", "is_correct": true, "explanation": "「公園を増やす計画」の形で、名詞「計画」を修飾する。"}, {"text": "増やそう", "is_correct": false, "explanation": "意志形は名詞を直接修飾できず、「増やそう計画」は成り立たない。"}, {"text": "増やせ", "is_correct": false, "explanation": "命令形は名詞を修飾できず、文に合わない。"}, {"text": "増やして", "is_correct": false, "explanation": "テ形は名詞に続かず、文が成り立たない。"}], "explanations": {"増やす": "「公園を増やす計画」の形で、名詞「計画」を修飾する。", "増やそう": "意志形は名詞を直接修飾できず、「増やそう計画」は成り立たない。", "増やせ": "命令形は名詞を修飾できず、文に合わない。", "増やして": "テ形は名詞に続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "増やす"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は毎晩、友人の気持ちを増やすために手紙を書いている。", "explanation": "ここは〈込める〉の意味。増やすは数や量を多くする語で、気持ちの込め方を表す場合には使わない。"}, {"text": "彼女は感性を増やすために、毎日詩を読んでいる。", "explanation": "ここは〈磨く〉の意味。増やすは数量を増やす語で、感性を磨き高める意味には合わない。"}, {"text": "職人は毎日、腕を増やすために練習している。", "explanation": "ここは〈鍛える〉の意味。増やすは数を多くする語で、技術や体を鍛える意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39250, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店は客を増えるために、毎日セールを行っています。", "corrected_sentence": "店は客を増やすために、毎日セールを行っています。", "error_description": "「増えるために」は自動詞「増える」で、「客を」を取れないため誤り。正しくは他動詞「増やす」で「客を増やすために」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "増やした", "is_correct": true, "explanation": "「増やしたら」の形で、過去の動作を条件として表す。"}, {"text": "増やす", "is_correct": false, "explanation": "辞書形では「増やすたら」となり「たら」に続かない。"}, {"text": "増やさない", "is_correct": false, "explanation": "ナイ形では「増やさないたら」となり文が成り立たない。"}, {"text": "増やせば", "is_correct": false, "explanation": "仮定形と「たら」が重なり、文が成り立たない。"}], "correct_form": "増やした", "base_form": "増やす", "form_label": "タ形", "sentence_index": 1, "explanations": {"増やした": "「増やしたら」の形で、過去の動作を条件として表す。", "増やす": "辞書形では「増やすたら」となり「たら」に続かない。", "増やさない": "ナイ形では「増やさないたら」となり文が成り立たない。", "増やせば": "仮定形と「たら」が重なり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39250, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場は部品の数が増やすために、新しい機械を入れた。", "corrected_sentence": "工場は部品の数を増やすために、新しい機械を入れた。", "error_description": "「部品の数が」の「が」は誤り。増やすの目的語には「を」が必要で、正しくは「数を増やす」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "増やして", "is_correct": true, "explanation": "「増やしてほしい」のテ形で、依頼の内容を表す。"}, {"text": "増やし", "is_correct": false, "explanation": "連用形は「ほしい」に直接続かず、文が成り立たない。"}, {"text": "増やそう", "is_correct": false, "explanation": "意志形は「ほしい」に続かず、文に合わない。"}, {"text": "増やせ", "is_correct": false, "explanation": "命令形は「ほしい」に続かず、文に合わない。"}], "correct_form": "増やして", "base_form": "増やす", "form_label": "テ形", "sentence_index": 7, "explanations": {"増やして": "「増やしてほしい」のテ形で、依頼の内容を表す。", "増やし": "連用形は「ほしい」に直接続かず、文が成り立たない。", "増やそう": "意志形は「ほしい」に続かず、文に合わない。", "増やせ": "命令形は「ほしい」に続かず、文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39251, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減らす", "is_correct": true, "explanation": "「増やす」の対義語で、数や量を少なくする意味。"}, {"text": "集める", "is_correct": false, "explanation": "一か所に寄せる語で、対義語ではない。"}, {"text": "掘る", "is_correct": false, "explanation": "地面に穴をあける語で、対義語ではない。"}, {"text": "並べる", "is_correct": false, "explanation": "順序よく置く語で、対義語ではない。"}], "correct_answer": "減らす", "explanations": {"減らす": "「増やす」の対義語で、数や量を少なくする意味。", "集める": "一か所に寄せる語で、対義語ではない。", "掘る": "地面に穴をあける語で、対義語ではない。", "並べる": "順序よく置く語で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39251, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減らす", "is_correct": true, "explanation": "「増やす」の対義語で、数や量を少なくする意味。"}, {"text": "届ける", "is_correct": false, "explanation": "物を相手に送り届ける語で、対義語ではない。"}, {"text": "伸ばす", "is_correct": false, "explanation": "長さや範囲を広げる語で、対義語ではない。"}, {"text": "固める", "is_correct": false, "explanation": "硬くする、まとめる意味の語で、対義語ではない。"}], "correct_answer": "減らす", "explanations": {"減らす": "「増やす」の対義語で、数や量を少なくする意味。", "届ける": "物を相手に送り届ける語で、対義語ではない。", "伸ばす": "長さや範囲を広げる語で、対義語ではない。", "固める": "硬くする、まとめる意味の語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39251, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "数量や程度を大きくする。", "primary_collocate": null, "pronunciation": "ふやす", "ipa": "ɸɯjasɯ", "syllable_count": 3, "sentences": [{"text": "毎月の貯金を一万円に増やすことにしました。", "target_word": "増やす", "complexity_tier": "T3", "furigana": "毎月(まいつき)の貯金(ちょきん)を一万円(いちまんえん)に増(ふ)やすことにしました。", "sentence_source": "generated"}, {"text": "筋力をつけたいので、トレーニングの回数を増やしています。", "target_word": "増やし", "complexity_tier": "T3", "furigana": "筋力(きんりょく)をつけたいので、トレーニングの回数(かいすう)を増(ふ)やしています。", "sentence_source": "generated"}, {"text": "会社は利益を増やすために、新しい商品を作りました。", "target_word": "増やす", "complexity_tier": "T3", "furigana": "会社(かいしゃ)は利益(りえき)を増(ふ)やすために、新(あたら)しい商品(しょうひん)を作(つく)りました。", "sentence_source": "generated"}, {"text": "医者は、薬の量を増やさないように注意しました。", "target_word": "増やさ", "complexity_tier": "T3", "furigana": "医者(いしゃ)は、薬(くすり)の量(りょう)を増(ふ)やさないように注意(ちゅうい)しました。", "sentence_source": "generated"}, {"text": "農家は米の収穫量を増やそうとして、毎日畑を手入れしました。", "target_word": "増やそう", "complexity_tier": "T3", "furigana": "農家(のうか)は米(こめ)の収穫量(しゅうかくりょう)を増(ふ)やそうとして、毎日(まいにち)畑(はたけ)を手入(てい)れしました。", "sentence_source": "generated"}, {"text": "収入を増やすために、週末も働いています。", "target_word": "増やす", "complexity_tier": "T3", "furigana": "収入(しゅうにゅう)を増(ふ)やすために、週末(しゅうまつ)も働(はたら)いています。", "sentence_source": "generated"}, {"text": "去年より生徒の数を増やしたため、教室が足りなくなりました。", "target_word": "増やした", "complexity_tier": "T3", "furigana": "去年(きょねん)より生徒(せいと)の数(かず)を増(ふ)やしたため、教室(きょうしつ)が足(た)りなくなりました。", "sentence_source": "generated"}, {"text": "彼は疲れていたので、睡眠時間を八時間に増やしました。", "target_word": "増やし", "complexity_tier": "T3", "furigana": "彼(かれ)は疲(つか)れていたので、睡眠時間(すいみんじかん)を八時間(はちじかん)に増(ふ)やしました。", "sentence_source": "generated"}, {"text": "工場は注文が多いので、生産量を二倍に増やす予定です。", "target_word": "増やす", "complexity_tier": "T3", "furigana": "工場(こうじょう)は注文(ちゅうもん)が多(おお)いので、生産量(せいさんりょう)を二倍(にばい)に増(ふ)やす予定(よてい)です。", "sentence_source": "generated"}, {"text": "塩の量を増やしすぎて、スープがからくなりました。", "target_word": "増やし", "complexity_tier": "T3", "furigana": "塩(しお)の量(りょう)を増(ふ)やしすぎて、スープがからくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "増やす", "label": "辞書形"}, {"form": "増やし", "label": "連用形"}, {"form": "増やした", "label": "タ形"}, {"form": "増やして", "label": "テ形"}, {"form": "増やさない", "label": "ナイ形"}, {"form": "増やせば", "label": "仮定形"}, {"form": "増やそう", "label": "意志形"}], "register": "標準（丁寧体）", "sense_fingerprint": "貯金・収入・回数・生産量など、数量や程度の数字を大きくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7187a5e-8c4c-4216-b62d-4b95debbe3a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39251, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "増やす", "is_correct": true, "explanation": "「貯金を一万円に増やすこと」の形で、目的の動作として自然。"}, {"text": "増える", "is_correct": false, "explanation": "自動詞で「貯金を」と続かず、「増えること」は文に合わない。"}, {"text": "減る", "is_correct": false, "explanation": "自動詞で「貯金を」を取れず、文が成り立たない。"}, {"text": "増やそう", "is_correct": false, "explanation": "意志形は「増やそうこと」の形にならず、文に合わない。"}], "explanations": {"増やす": "「貯金を一万円に増やすこと」の形で、目的の動作として自然。", "増える": "自動詞で「貯金を」と続かず、「増えること」は文に合わない。", "減る": "自動詞で「貯金を」を取れず、文が成り立たない。", "増やそう": "意志形は「増やそうこと」の形にならず、文に合わない。"}, "sentence_index": 0, "correct_answer": "増やす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は毎晩、友人の気持ちを増やすために手紙を書いている。", "explanation": "ここは〈込める〉の意味。増やすは数量や程度を大きくする語で、気持ちの込め方を表す場合には使わない。"}, {"text": "会社は、製品の品質を増やすための検査を続けた。", "explanation": "ここは〈高める〉の意味。増やすは数量を増やす語で、品質の水準を上げる意味には合わない。"}, {"text": "先生は、生徒の理解を増やすための工夫をした。", "explanation": "ここは〈深める〉の意味。増やすは数を多くする語で、理解の深さを表す場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39251, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "増やした", "is_correct": true, "explanation": "「増やしたため」の形で、原因を表す。"}, {"text": "増やせ", "is_correct": false, "explanation": "命令形は「ため」に続かず、文に合わない。"}, {"text": "増やして", "is_correct": false, "explanation": "テ形は「ため」に続かず、文が成り立たない。"}, {"text": "増やさ", "is_correct": false, "explanation": "未然形は「ため」に直接続かず、文が成り立たない。"}], "explanations": {"増やした": "「増やしたため」の形で、原因を表す。", "増やせ": "命令形は「ため」に続かず、文に合わない。", "増やして": "テ形は「ため」に続かず、文が成り立たない。", "増やさ": "未然形は「ため」に直接続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "増やした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は旅行をして、視野を増やした。", "explanation": "ここは〈広げる〉の意味。増やすは数量や程度を大きくする語で、視野の範囲を広げる意味には合わない。"}, {"text": "彼女は毎朝、感性を増やすために詩を読んでいる。", "explanation": "ここは〈磨く〉の意味。増やすは数を増やす語で、感性を磨く意味には合わない。"}, {"text": "選手は毎日、足腰を増やすための練習をしている。", "explanation": "ここは〈鍛える〉の意味。増やすは数量を多くする語で、体を強くする意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39251, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店は売り場の面積を増えるために、新しい棚を置いた。", "corrected_sentence": "店は売り場の面積を増やすために、新しい棚を置いた。", "error_description": "「増えるために」は自動詞で「面積を」を取れない。他動詞「増やす」を使い「面積を増やすために」とする必要がある。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "増やし", "is_correct": true, "explanation": "連用形で「増やしています」の形を作る。"}, {"text": "増やす", "is_correct": false, "explanation": "辞書形では「増やすています」となり文が成り立たない。"}, {"text": "増やさない", "is_correct": false, "explanation": "ナイ形は「ています」に続かず、文に合わない。"}, {"text": "増やせば", "is_correct": false, "explanation": "仮定形は「ています」に続かず、文に合わない。"}], "correct_form": "増やし", "base_form": "増やす", "form_label": "連用形", "sentence_index": 1, "explanations": {"増やし": "連用形で「増やしています」の形を作る。", "増やす": "辞書形では「増やすています」となり文が成り立たない。", "増やさない": "ナイ形は「ています」に続かず、文に合わない。", "増やせば": "仮定形は「ています」に続かず、文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39251, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店は利益の額が増やすために、値段を見直した。", "corrected_sentence": "店は利益の額を増やすために、値段を見直した。", "error_description": "「利益の額が」の「が」は誤り。増やすの目的語には「を」が必要で、正しくは「額を増やす」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "増やし", "is_correct": true, "explanation": "連用形で「増やしました」の形を作る。"}, {"text": "増やそう", "is_correct": false, "explanation": "意志形は「ました」に続かず、文に合わない。"}, {"text": "増やさ", "is_correct": false, "explanation": "未然形は「ました」に続かず、文が成り立たない。"}, {"text": "増やした", "is_correct": false, "explanation": "タ形に「ました」が続くと「増やしたました」となり不自然。"}], "correct_form": "増やし", "base_form": "増やす", "form_label": "連用形", "sentence_index": 7, "explanations": {"増やし": "連用形で「増やしました」の形を作る。", "増やそう": "意志形は「ました」に続かず、文に合わない。", "増やさ": "未然形は「ました」に続かず、文が成り立たない。", "増やした": "タ形に「ました」が続くと「増やしたました」となり不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39254, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「村には年寄りが多い」の主語にあたり、「多い」と合う。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「多い」は目的語を取らない形容詞なので、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すが、「年寄りと多い」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞修飾に使うので、「年寄りの多くて」は文の述語にならず、不自然。"}], "correct_answer": "が", "explanations": {"が": "「村には年寄りが多い」の主語にあたり、「多い」と合う。正しい。", "を": "「多い」は目的語を取らない形容詞なので、「を」は合わない。", "と": "「と」は並列を表すが、「年寄りと多い」は文として成り立たない。", "の": "「の」は名詞修飾に使うので、「年寄りの多くて」は文の述語にならず、不自然。"}, "error_tags": {"を": "目的語", "と": "並列", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39254, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39254, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "とても年をとった人のことです。", "primary_collocate": null, "pronunciation": "としより", "ipa": "toɕijoɾi", "syllable_count": 4, "sentences": [{"text": "電車で、年寄りに席をゆずった。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "電車[でんしゃ]で、年寄[としよ]りに席[せき]をゆずった。", "sentence_source": "generated"}, {"text": "村には年寄りが多くて、若い人は少ない。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "村[むら]には年寄[としよ]りが多[おお]くて、若[わか]い人[ひと]は少[すく]ない。", "sentence_source": "generated"}, {"text": "祖父は元気な年寄りで、毎朝さんぽをする。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "祖父[そふ]は元気[げんき]な年寄[としよ]りで、毎朝[まいあさ]さんぽをする。", "sentence_source": "generated"}, {"text": "年寄りの話を聞くと、昔のことがよくわかる。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "年寄[としよ]りの話[はなし]を聞[き]くと、昔[むかし]のことがよくわかる。", "sentence_source": "generated"}, {"text": "重い荷物を持った年寄りを、みんなで手伝った。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を持[も]った年寄[としよ]りを、みんなで手伝[てつだ]った。", "sentence_source": "generated"}, {"text": "雪の日は道がすべるので、年寄りは外に出ないほうがいい。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は道[みち]がすべるので、年寄[としよ]りは外[そと]に出[で]ないほうがいい。", "sentence_source": "generated"}, {"text": "公園では、年寄りたちがゲートボールをしていた。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "公園[こうえん]では、年寄[としよ]りたちがゲートボールをしていた。", "sentence_source": "generated"}, {"text": "その年寄りは、七十年前の戦争のことをよく覚えていた。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "その年寄[としよ]りは、七十年前[ななじゅうねんまえ]の戦争[せんそう]のことをよく覚[おぼ]えていた。", "sentence_source": "generated"}, {"text": "年寄りだからといって、何もできないわけではない。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "年寄[としよ]りだからといって、何[なに]もできないわけではない。", "sentence_source": "generated"}, {"text": "おまつりでは、年寄りも子どもも一緒におどった。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "おまつりでは、年寄[としよ]りも子[こ]どもも一緒[いっしょ]におどった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年寄り", "label": "基本形"}, {"form": "年寄りたち", "label": "複数形"}], "register": "日常（口語）", "sense_fingerprint": "年寄り=年を重ねたお年寄り個人。日常会話で、年をとった人をさす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: おどっ (Zipf 1.84)']::text[], '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39254, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年寄り", "is_correct": true, "explanation": "「電車で、年寄りに席をゆずった」と人に席をゆずる文になる。正しい。"}, {"text": "荷物", "is_correct": false, "explanation": "「荷物に席をゆずった」は意味が通らず、席をゆずる相手にならない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓に席をゆずった」は成り立たず、文の意味が通らない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書に席をゆずった」は不自然で、席をゆずる相手として合わない。"}], "explanations": {"年寄り": "「電車で、年寄りに席をゆずった」と人に席をゆずる文になる。正しい。", "荷物": "「荷物に席をゆずった」は意味が通らず、席をゆずる相手にならない。", "窓": "「窓に席をゆずった」は成り立たず、文の意味が通らない。", "教科書": "「教科書に席をゆずった」は不自然で、席をゆずる相手として合わない。"}, "sentence_index": 0, "correct_answer": "年寄り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その子は年寄りで、公園でボールを追いかけていた。", "explanation": "ここは〈幼児〉の意味。年寄りは年をとった人を指すので、幼い子には使わない。"}, {"text": "生まれたばかりの年寄りが、大きな声で泣いている。", "explanation": "ここは〈赤ちゃん〉の意味。年寄りは年を重ねた人を指す語なので、新生児には使わない。"}, {"text": "大学生の年寄りが、来年就職する。", "explanation": "ここは〈若者〉の意味。年寄りは年をとった人を指すので、大学生には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39254, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年寄り", "is_correct": true, "explanation": "「公園では、年寄りたちがゲートボールをしていた」と人が主語になる。正しい。"}, {"text": "自転車", "is_correct": false, "explanation": "「自転車がゲートボールをしていた」は意味が通らず、主語として合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "「屋根がゲートボールをしていた」は成り立たず、文の主語にならない。"}, {"text": "花瓶", "is_correct": false, "explanation": "「花瓶がゲートボールをしていた」は不自然で、主語として合わない。"}], "explanations": {"年寄り": "「公園では、年寄りたちがゲートボールをしていた」と人が主語になる。正しい。", "自転車": "「自転車がゲートボールをしていた」は意味が通らず、主語として合わない。", "屋根": "「屋根がゲートボールをしていた」は成り立たず、文の主語にならない。", "花瓶": "「花瓶がゲートボールをしていた」は不自然で、主語として合わない。"}, "sentence_index": 6, "correct_answer": "年寄り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの庭の年寄りは、毎年大きな実をつける。", "explanation": "ここは〈老木〉の意味。年寄りは人を指す語で、木の古さには老木を使う。"}, {"text": "この建物は年寄りなので、地震に強い。", "explanation": "ここは〈古くなったもの〉の意味。年寄りは人を指す語なので、建物の古さには使わない。"}, {"text": "この車は年寄りで、よく走る。", "explanation": "ここは〈旧型〉の意味。年寄りは人を指す語なので、車の古さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39254, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電車で年寄りを席をゆずった人がいた。", "corrected_sentence": "電車で年寄りに席をゆずった人がいた。", "error_description": "助詞の誤り。「ゆずる」の相手は「に」で表す。「を」にすると「年寄りを席をゆずる」となり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39254, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公園では、年寄りたちを体操をしていた。", "corrected_sentence": "公園では、年寄りたちが体操をしていた。", "error_description": "助詞の誤り。「している」の主語は「が」。「を」は目的語を表すので、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39255, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「年寄りを狙った詐欺」で狙う対象を表す。正しい。"}, {"text": "に", "is_correct": false, "explanation": "「年寄りに狙った」は対象の示し方が合わず、文として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「年寄りで狙った」は場所や手段の意味にならず、文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「年寄りへ狙った」は方向の意味になり、「狙う」の対象として合わない。"}], "correct_answer": "を", "explanations": {"を": "「年寄りを狙った詐欺」で狙う対象を表す。正しい。", "に": "「年寄りに狙った」は対象の示し方が合わず、文として不自然。", "で": "「年寄りで狙った」は場所や手段の意味にならず、文が通らない。", "へ": "「年寄りへ狙った」は方向の意味になり、「狙う」の対象として合わない。"}, "error_tags": {"に": "対象・方向", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39255, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「年寄りと若者が交流できる」の並列を表す。正しい。"}, {"text": "が", "is_correct": false, "explanation": "「年寄りが若者が交流」と二つの主語が並ぶ形は成り立たず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「年寄りから若者が交流」は並列の意味にならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「若者が交流できる」の前に置くと文が成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「年寄りと若者が交流できる」の並列を表す。正しい。", "が": "「年寄りが若者が交流」と二つの主語が並ぶ形は成り立たず、不自然。", "から": "「から」は起点を表すので、「年寄りから若者が交流」は並列の意味にならない。", "を": "「を」は目的語を示すので、「若者が交流できる」の前に置くと文が成り立たない。"}, "error_tags": {"が": "主語", "から": "起点", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39255, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "年齢が高い人のこと。高齢者。", "primary_collocate": null, "pronunciation": "としより", "ipa": "toɕijoɾi", "syllable_count": 4, "sentences": [{"text": "市は、年寄りが安心して暮らせる町づくりを進めている。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "市[し]は、年寄[としよ]りが安心[あんしん]して暮[く]らせる町[まち]づくりを進[すす]めている。", "sentence_source": "generated"}, {"text": "年寄りを狙った詐欺が増えているので注意が必要だ。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "年寄[としよ]りを狙[ねら]った詐欺[さぎ]が増[ふ]えているので注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "年寄りの一人暮らしが増え、近所の見守りが大切になった。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "年寄[としよ]りの一人暮[ひとりぐ]らしが増[ふ]え、近所[きんじょ]の見守[みまも]りが大切[たいせつ]になった。", "sentence_source": "generated"}, {"text": "バスの運賃は、年寄りには割引がある。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "バスの運賃[うんちん]は、年寄[としよ]りには割引[わりびき]がある。", "sentence_source": "generated"}, {"text": "年寄りに配慮して、病院の入り口に段差をなくした。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "年寄[としよ]りに配慮[はいりょ]して、病院[びょういん]の入[い]り口[ぐち]に段差[だんさ]をなくした。", "sentence_source": "generated"}, {"text": "年寄りの健康を守るため、無料の体操教室が開かれている。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "年寄[としよ]りの健康[けんこう]を守[まも]るため、無料[むりょう]の体操教室[たいそうきょうしつ]が開[ひら]かれている。", "sentence_source": "generated"}, {"text": "災害のとき、年寄りは避難に時間がかかる。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、年寄[としよ]りは避難[ひなん]に時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "年寄りと若者が交流できる集まりを、町内会が開いた。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "年寄[としよ]りと若者[わかもの]が交流[こうりゅう]できる集[あつ]まりを、町内会[ちょうないかい]が開[ひら]いた。", "sentence_source": "generated"}, {"text": "日本は年寄りの割合が高い国だと言われている。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "日本[にほん]は年寄[としよ]りの割合[わりあい]が高[たか]い国[くに]だと言[い]われている。", "sentence_source": "generated"}, {"text": "年寄りの意見も取り入れて、公園の設計を決めた。", "target_word": "年寄り", "complexity_tier": "T3", "furigana": "年寄[としよ]りの意見[いけん]も取[と]り入[い]れて、公園[こうえん]の設計[せっけい]を決[き]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年寄り", "label": "基本形"}, {"form": "年寄りたち", "label": "複数形"}], "register": "標準（社会・福祉の文脈）", "sense_fingerprint": "年寄り=高齢者という社会的な集団・層。福祉や政策の話題で使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39255, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年寄り", "is_correct": true, "explanation": "「年寄りが安心して暮らせる町づくり」と人が主語になり、文として自然。正しい。"}, {"text": "道路", "is_correct": false, "explanation": "「道路が安心して暮らせる」は意味が通らず、暮らす主体にならない。"}, {"text": "公園", "is_correct": false, "explanation": "「公園が安心して暮らせる」は成り立たず、文の主語として合わない。"}, {"text": "自動車", "is_correct": false, "explanation": "「自動車が安心して暮らせる」は意味が通らず、文の主語として合わない。"}], "explanations": {"年寄り": "「年寄りが安心して暮らせる町づくり」と人が主語になり、文として自然。正しい。", "道路": "「道路が安心して暮らせる」は意味が通らず、暮らす主体にならない。", "公園": "「公園が安心して暮らせる」は成り立たず、文の主語として合わない。", "自動車": "「自動車が安心して暮らせる」は意味が通らず、文の主語として合わない。"}, "sentence_index": 0, "correct_answer": "年寄り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "生まれたばかりの年寄りを、みんなで祝った。", "explanation": "ここは〈赤ちゃん〉の意味。年寄りは年を重ねた人の集団を指すので、生まれたばかりの子には使わない。"}, {"text": "この車は年寄りで、燃費がとてもいい。", "explanation": "ここは〈旧型〉の意味。年寄りは人の集団を指す語なので、車には使わない。"}, {"text": "大学生の年寄りが、サークルの新入生を歓迎した。", "explanation": "ここは〈若者〉の意味。年寄りは高齢の人の集団を指すので、大学生には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39255, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年寄り", "is_correct": true, "explanation": "「災害のとき、年寄りは避難に時間がかかる」と人が主語になり、文として自然。正しい。"}, {"text": "地図", "is_correct": false, "explanation": "「地図は避難に時間がかかる」は意味が通らず、避難する主体にならない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書は避難に時間がかかる」は意味が通らず、文の主語として合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "「花瓶は避難に時間がかかる」は不自然で、避難する主体として成り立たない。"}], "explanations": {"年寄り": "「災害のとき、年寄りは避難に時間がかかる」と人が主語になり、文として自然。正しい。", "地図": "「地図は避難に時間がかかる」は意味が通らず、避難する主体にならない。", "教科書": "「教科書は避難に時間がかかる」は意味が通らず、文の主語として合わない。", "花瓶": "「花瓶は避難に時間がかかる」は不自然で、避難する主体として成り立たない。"}, "sentence_index": 6, "correct_answer": "年寄り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この古い木は年寄りで、大きな実をつける。", "explanation": "ここは〈老樹〉の意味。年寄りは人の集団を指す語で、木の古さには使わない。"}, {"text": "この建物は年寄りなので、地震に強い。", "explanation": "ここは〈老朽化〉の意味。年寄りは人の集団を指す語なので、建物には使わない。"}, {"text": "この製品は年寄りで、長く使える。", "explanation": "ここは〈耐久〉の意味。年寄りは人を指す語なので、製品の丈夫さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39255, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年寄りに守るため、市は見守り活動を始めた。", "corrected_sentence": "年寄りを守るため、市は見守り活動を始めた。", "error_description": "助詞の誤り。「守る」の目的語は「を」。「に」にすると「年寄りに守る」となり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39255, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "災害のとき、年寄りを避難の手助けが必要だ。", "corrected_sentence": "災害のとき、年寄りは避難の手助けが必要だ。", "error_description": "助詞の誤り。主題を示す「は」が正しい。「を」は目的語で、「必要だ」の主語にはならないため不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
