INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39256, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39256, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "年齢や立場がちがう人たちも、みんなが入っていること。", "primary_collocate": null, "pronunciation": "はばひろい", "ipa": "habaçiɾoi", "syllable_count": 5, "sentences": [{"text": "このゲームは、子どもから大人まで幅広い年齢の人が楽しめます。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "このゲームは、子[こ]どもから大人[おとな]まで幅広[はばひろ]い年齢[ねんれい]の人[ひと]が楽[たの]しめます。", "sentence_source": "generated"}, {"text": "料理教室には、学生や会社員など、幅広い立場の人が来ています。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "料理教室[りょうりきょうしつ]には、学生[がくせい]や会社員[かいしゃいん]など、幅広[はばひろ]い立場[たちば]の人[ひと]が来[き]ています。", "sentence_source": "generated"}, {"text": "この歌手のファンは幅広い年代にわたり、十代から七十代までいます。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "この歌手のファンは幅広[はばひろ]い年代にわたり、十代から七十代までいます。", "sentence_source": "generated"}, {"text": "公園のお祭りには、幅広い世代の人が集まりました。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "公園[こうえん]のお祭[まつ]りには、幅広[はばひろ]い世代[せだい]の人[ひと]が集[あつ]まりました。", "sentence_source": "generated"}, {"text": "私たちのクラブは、年齢に関係なく幅広い人を歓迎しています。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "私[わたし]たちのクラブは、年齢[ねんれい]に関係[かんけい]なく幅広[はばひろ]い人[ひと]を歓迎[かんげい]しています。", "sentence_source": "generated"}, {"text": "この本は幅広い読者に読まれているので、書店でいつも目立つ場所にあります。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "この本[ほん]は幅広[はばひろ]い読者[どくしゃ]に読[よ]まれているので、書店[しょてん]でいつも目立[めだ]つ場所[ばしょ]にあります。", "sentence_source": "generated"}, {"text": "町の会議には、先生や店の人など、幅広い立場の人が参加しました。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "町[まち]の会議[かいぎ]には、先生[せんせい]や店[みせ]の人[ひと]など、幅広[はばひろ]い立場[たちば]の人[ひと]が参加[さんか]しました。", "sentence_source": "generated"}, {"text": "その映画は幅広い年代に人気があったため、長い間上映されました。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "その映画[えいが]は幅広[はばひろ]い年代[ねんだい]に人気[にんき]があったため、長[なが]い間[あいだ]上映[じょうえい]されました。", "sentence_source": "generated"}, {"text": "幅広い人に使ってもらえるように、案内板は大きな字で書かれています。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "幅広[はばひろ]い人[ひと]に使[つか]ってもらえるように、案内板[あんないばん]は大[おお]きな字[じ]で書[か]かれています。", "sentence_source": "generated"}, {"text": "私の友達は幅広い年代にわたっていて、年上の人も年下の人もいます。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "私の友達は幅広[はばひろ]い年代にわたっていて、年上の人も年下の人もいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幅広い", "label": "終止形・連体形"}, {"form": "幅広く", "label": "連用形"}, {"form": "幅広かった", "label": "過去形"}, {"form": "幅広くない", "label": "否定形"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "年齢や立場のちがう、いろいろな人が含まれている様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39256, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幅広い", "is_correct": true, "explanation": "「子どもから大人まで」と合い、年齢の範囲が広いことを表す。正解。"}, {"text": "狭い", "is_correct": false, "explanation": "範囲が狭いという意味になり、「子どもから大人まで」という広い範囲の説明と矛盾する。"}, {"text": "細かい", "is_correct": false, "explanation": "「細かい年齢」は区分の細かさを表し、年齢の範囲の広さは表せない。"}, {"text": "高い", "is_correct": false, "explanation": "「高い年齢」は年齢が上の方であることを表し、子どもから大人までの幅とは合わない。"}], "explanations": {"幅広い": "「子どもから大人まで」と合い、年齢の範囲が広いことを表す。正解。", "狭い": "範囲が狭いという意味になり、「子どもから大人まで」という広い範囲の説明と矛盾する。", "細かい": "「細かい年齢」は区分の細かさを表し、年齢の範囲の広さは表せない。", "高い": "「高い年齢」は年齢が上の方であることを表し、子どもから大人までの幅とは合わない。"}, "sentence_index": 0, "correct_answer": "幅広い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は幅広いので、大きなベッドを置けます。", "explanation": "部屋の広さには〈広い〉を使う。〈幅広い〉は種類や範囲の広さに使うので、面積の説明には合わない。"}, {"text": "この寺の門は幅広いので、大きな車が通れます。", "explanation": "ここは〈幅が広い〉の意味。門の横幅には〈広い〉を使うので、人や物の範囲を表す語義とは違う。"}, {"text": "彼は幅広い汗をかいて、ベンチに座り込みました。", "explanation": "汗の量は〈大量の〉などで表す。〈幅広い〉は範囲の広さに使うので、量の多さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39256, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幅広い", "is_correct": true, "explanation": "「先生や店の人など」という多様な立場の範囲を表す。正解。"}, {"text": "遠い", "is_correct": false, "explanation": "「遠い立場」は距離の遠さを表し、参加者の立場の範囲を表せない。"}, {"text": "浅い", "is_correct": false, "explanation": "「浅い」は深さの反対で、立場の範囲を表せないので文が合わない。"}, {"text": "細い", "is_correct": false, "explanation": "「細い立場」は立場の範囲を表せず、「先生や店の人など」という説明と合わない。"}], "explanations": {"幅広い": "「先生や店の人など」という多様な立場の範囲を表す。正解。", "遠い": "「遠い立場」は距離の遠さを表し、参加者の立場の範囲を表せない。", "浅い": "「浅い」は深さの反対で、立場の範囲を表せないので文が合わない。", "細い": "「細い立場」は立場の範囲を表せず、「先生や店の人など」という説明と合わない。"}, "sentence_index": 6, "correct_answer": "幅広い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このペンの芯は幅広いので、細かい字が書けません。", "explanation": "芯の太さには〈太い〉を使う。〈幅広い〉は範囲の広さに使うので、太さの説明には合わない。"}, {"text": "この本は幅広いので、ページ数がとても多いです。", "explanation": "本の厚みには〈厚い〉を使う。〈幅広い〉は範囲の広さを表すので、厚さの説明には合わない。"}, {"text": "この井戸は幅広いので、底がよく見えません。", "explanation": "井戸の深さには〈深い〉を使う。〈幅広い〉は範囲の広さを表すので、深さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39256, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "若い社員から経験のあるベテランまで、幅広いな年齢の人が働いています。", "corrected_sentence": "若い社員から経験のあるベテランまで、幅広い年齢の人が働いています。", "error_description": "い形容詞「幅広い」に「な」は付かない。名詞「年齢」を修飾するには「幅広い年齢」と続ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "幅広い", "is_correct": true, "explanation": "名詞「立場」を修飾する連体形で、文の形として正しい。"}, {"text": "幅広く", "is_correct": false, "explanation": "連用形なので、名詞「立場」を直接修飾できない。"}, {"text": "幅広ければ", "is_correct": false, "explanation": "仮定形なので、名詞「立場」を修飾できず、「来ています」に続かない。"}, {"text": "幅広くて", "is_correct": false, "explanation": "て形なので、名詞「立場」を直接修飾できない。「幅広くて立場の人」は文として成り立たない。"}], "correct_form": "幅広い", "base_form": "幅広い", "form_label": "連体形", "sentence_index": 1, "explanations": {"幅広い": "名詞「立場」を修飾する連体形で、文の形として正しい。", "幅広く": "連用形なので、名詞「立場」を直接修飾できない。", "幅広ければ": "仮定形なので、名詞「立場」を修飾できず、「来ています」に続かない。", "幅広くて": "て形なので、名詞「立場」を直接修飾できない。「幅広くて立場の人」は文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39256, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公民館では、体操から料理まで幅広くの講座が開かれています。", "corrected_sentence": "公民館では、体操から料理まで幅広い講座が開かれています。", "error_description": "連用形の「幅広く」は名詞「講座」を修飾できず、「の」も続かない。「幅広い講座」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "幅広い", "is_correct": true, "explanation": "名詞「年代」を修飾する連体形で、文の形として正しい。正解。"}, {"text": "幅広かったら", "is_correct": false, "explanation": "仮定形の過去なので、名詞「年代」を修飾できず、「人気があったため」の文に続かない。"}, {"text": "幅広さ", "is_correct": false, "explanation": "名詞形なので、名詞「年代」を直接修飾できない。「幅広さ年代」は文として成り立たない。"}, {"text": "幅広そう", "is_correct": false, "explanation": "様子の推定の形で、名詞を直接修飾するには「幅広そうな」が必要。「幅広そう年代」は成り立たない。"}], "correct_form": "幅広い", "base_form": "幅広い", "form_label": "連体形", "sentence_index": 7, "explanations": {"幅広い": "名詞「年代」を修飾する連体形で、文の形として正しい。正解。", "幅広かったら": "仮定形の過去なので、名詞「年代」を修飾できず、「人気があったため」の文に続かない。", "幅広さ": "名詞形なので、名詞「年代」を直接修飾できない。「幅広さ年代」は文として成り立たない。", "幅広そう": "様子の推定の形で、名詞を直接修飾するには「幅広そうな」が必要。「幅広そう年代」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
