INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39257, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "対象となる人や物の範囲が広いこと。種類や年齢などに差が大きく、多くのものが含まれる様子。", "primary_collocate": null, "pronunciation": "はばひろい", "ipa": "habaçiɾoi", "syllable_count": 5, "sentences": [{"text": "この店には、安いものから高いものまで幅広い商品があります。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "この店[みせ]には、安[やす]いものから高[たか]いものまで幅広[はばひろ]い商品[しょうひん]があります。", "sentence_source": "generated"}, {"text": "彼女は本が好きで、歴史から科学まで幅広い知識を持っています。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は本[ほん]が好[す]きで、歴史[れきし]から科学[かがく]まで幅広[はばひろ]い知識[ちしき]を持[も]っています。", "sentence_source": "generated"}, {"text": "大学では、幅広い分野を学ぶことができます。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "大学[だいがく]では、幅広[はばひろ]い分野[ぶんや]を学[まな]ぶことができます。", "sentence_source": "generated"}, {"text": "この薬は幅広い病気に効くので、多くの家庭にあります。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "この薬[くすり]は幅広[はばひろ]い病気[びょうき]に効[き]くので、多[おお]くの家庭[かてい]にあります。", "sentence_source": "generated"}, {"text": "先生の興味は幅広い分野におよび、音楽にも料理にも詳しいです。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "先生の興味は幅広[はばひろ]い分野におよび、音楽にも料理にも詳しいです。", "sentence_source": "generated"}, {"text": "会社は幅広い種類の仕事を用意して、新しい社員を探しています。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は幅広[はばひろ]い種類[しゅるい]の仕事[しごと]を用意[ようい]して、新[あたら]しい社員[しゃいん]を探[さが]しています。", "sentence_source": "generated"}, {"text": "図書館には、子ども向けから専門書まで幅広い本がそろっています。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "図書館[としょかん]には、子[こ]ども向[む]けから専門書[せんもんしょ]まで幅広[はばひろ]い本[ほん]がそろっています。", "sentence_source": "generated"}, {"text": "幅広い経験があるので、どんな質問にも答えられます。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "幅広[はばひろ]い経験[けいけん]があるので、どんな質問[しつもん]にも答[こた]えられます。", "sentence_source": "generated"}, {"text": "このアプリは幅広い使い方ができて、便利です。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "このアプリは幅広[はばひろ]い使[つか]い方[かた]ができて、便利[べんり]です。", "sentence_source": "generated"}, {"text": "彼は仕事で世界の国々を回り、幅広い文化を知りました。", "target_word": "幅広い", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事[しごと]で世界[せかい]の国々[くにぐに]を回[まわ]り、幅広[はばひろ]い文化[ぶんか]を知[し]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幅広い", "label": "終止形・連体形"}, {"form": "幅広く", "label": "連用形"}, {"form": "幅広かった", "label": "過去形"}, {"form": "幅広くない", "label": "否定形"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "種類や分野などの範囲が広く、多くのものが含まれる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39257, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幅広い", "is_correct": true, "explanation": "「安いものから高いものまで」と合い、品ぞろえの範囲が広いことを表す。正解。"}, {"text": "狭い", "is_correct": false, "explanation": "範囲が狭いという意味になり、「安いものから高いものまで」という広がりと矛盾する。"}, {"text": "細かい", "is_correct": false, "explanation": "「細かい商品」は品ぞろえの細かさを表し、品ぞろえの幅の広さは表せない。"}, {"text": "深い", "is_correct": false, "explanation": "「深い商品」は内容の深さを表し、品ぞろえの幅の広さには合わない。"}], "explanations": {"幅広い": "「安いものから高いものまで」と合い、品ぞろえの範囲が広いことを表す。正解。", "狭い": "範囲が狭いという意味になり、「安いものから高いものまで」という広がりと矛盾する。", "細かい": "「細かい商品」は品ぞろえの細かさを表し、品ぞろえの幅の広さは表せない。", "深い": "「深い商品」は内容の深さを表し、品ぞろえの幅の広さには合わない。"}, "sentence_index": 0, "correct_answer": "幅広い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この倉庫は幅広いので、大きな机が三台入ります。", "explanation": "場所の面積には〈広い〉を使う。〈幅広い〉は種類や範囲の広さに使うので、面積の説明には合わない。"}, {"text": "その会議は幅広い時間続き、みんな疲れました。", "explanation": "時間の長さには〈長い〉を使う。〈幅広い〉は範囲の広さに使うので、時間の長さには合わない。"}, {"text": "彼は幅広い足音で、部屋に近づいてきました。", "explanation": "足音の大きさには〈大きな〉などを使う。〈幅広い〉は範囲の広さを表すので、音の大きさには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39257, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幅広い", "is_correct": true, "explanation": "「子ども向けから専門書まで」という範囲の広さを表す。正解。"}, {"text": "浅い", "is_correct": false, "explanation": "「浅い本」は内容の浅さを表し、本の種類の範囲には合わない。"}, {"text": "軽い", "is_correct": false, "explanation": "「軽い本」は重さの軽さを表し、「子ども向けから専門書まで」の範囲とは合わない。"}, {"text": "低い", "is_correct": false, "explanation": "高さの反対を表す語で、本の範囲を表せないので文が合わない。"}], "explanations": {"幅広い": "「子ども向けから専門書まで」という範囲の広さを表す。正解。", "浅い": "「浅い本」は内容の浅さを表し、本の種類の範囲には合わない。", "軽い": "「軽い本」は重さの軽さを表し、「子ども向けから専門書まで」の範囲とは合わない。", "低い": "高さの反対を表す語で、本の範囲を表せないので文が合わない。"}, "sentence_index": 6, "correct_answer": "幅広い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宿題が幅広い量で、一晩では終わりません。", "explanation": "量の多さには〈大量の〉などを使う。〈幅広い〉は範囲の広さに使うので、量の説明には合わない。"}, {"text": "この谷には幅広い川が流れていて、橋を渡るのに苦労します。", "explanation": "ここは〈幅が広い〉の意味。川の横幅を表すので、対象の範囲が広いことを表す語義とは違う。"}, {"text": "このビルの持ち主は幅広い笑顔で、いつも大きく笑います。", "explanation": "笑顔の表情には〈明るい〉〈にこやかな〉を使う。〈幅広い〉は範囲の広さを表すので、表情の説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39257, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このサイトには、料理から旅行まで幅広いで話題が載っています。", "corrected_sentence": "このサイトには、料理から旅行まで幅広い話題が載っています。", "error_description": "形容詞「幅広い」に「で」が続いている。名詞「話題」を修飾するには連体形の「幅広い」をそのまま置く。「幅広いで」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "幅広い", "is_correct": true, "explanation": "名詞「知識」を修飾する連体形で、文の形として正しい。"}, {"text": "幅広く", "is_correct": false, "explanation": "連用形なので、名詞「知識」を直接修飾できない。"}, {"text": "幅広ければ", "is_correct": false, "explanation": "仮定形なので、名詞「知識」を修飾できず、「持っています」に続かない。"}, {"text": "幅広くて", "is_correct": false, "explanation": "て形なので、名詞「知識」を直接修飾できない。「幅広くて知識」は文として成り立たない。"}], "correct_form": "幅広い", "base_form": "幅広い", "form_label": "連体形", "sentence_index": 1, "explanations": {"幅広い": "名詞「知識」を修飾する連体形で、文の形として正しい。", "幅広く": "連用形なので、名詞「知識」を直接修飾できない。", "幅広ければ": "仮定形なので、名詞「知識」を修飾できず、「持っています」に続かない。", "幅広くて": "て形なので、名詞「知識」を直接修飾できない。「幅広くて知識」は文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39257, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この動物園には、小さな動物から大きな動物まで幅広いの種類の動物がいます。", "corrected_sentence": "この動物園には、小さな動物から大きな動物まで幅広い種類の動物がいます。", "error_description": "「幅広い」の直後に「の」を付けると、「種類」を修飾する形が成り立たない。「幅広い種類」と続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "幅広い", "is_correct": true, "explanation": "名詞「経験」を修飾する連体形で、文の形として正しい。正解。"}, {"text": "幅広かったら", "is_correct": false, "explanation": "仮定形の過去なので、名詞「経験」を修飾できず、「あるので」の文に続かない。"}, {"text": "幅広さ", "is_correct": false, "explanation": "名詞形なので、名詞「経験」を直接修飾できない。「幅広さ経験」は文として成り立たない。"}, {"text": "幅広そう", "is_correct": false, "explanation": "様子の推定の形で、名詞を直接修飾するには「幅広そうな」が必要。「幅広そう経験」は成り立たない。"}], "correct_form": "幅広い", "base_form": "幅広い", "form_label": "連体形", "sentence_index": 7, "explanations": {"幅広い": "名詞「経験」を修飾する連体形で、文の形として正しい。正解。", "幅広かったら": "仮定形の過去なので、名詞「経験」を修飾できず、「あるので」の文に続かない。", "幅広さ": "名詞形なので、名詞「経験」を直接修飾できない。「幅広さ経験」は文として成り立たない。", "幅広そう": "様子の推定の形で、名詞を直接修飾するには「幅広そうな」が必要。「幅広そう経験」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
