INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39258, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを作ったり、直したりするために、体や手を動かしてすること。", "primary_collocate": null, "pronunciation": "さぎょう", "ipa": "saɡʲoː", "syllable_count": 3, "sentences": [{"text": "今日の作業は、午後五時までに終わらせます。", "target_word": "作業", "complexity_tier": "T3", "furigana": "今日[きょう]の作業[さぎょう]は、午後[ごご]五時[ごじ]までに終[お]わらせます。", "sentence_source": "generated"}, {"text": "暗くなってきたので、外での作業は明日にしましょう。", "target_word": "作業", "complexity_tier": "T3", "furigana": "暗[くら]くなってきたので、外[そと]での作業[さぎょう]は明日[あした]にしましょう。", "sentence_source": "generated"}, {"text": "工場では、みんなが帽子をかぶって作業をしています。", "target_word": "作業", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、みんなが帽子[ぼうし]をかぶって作業[さぎょう]をしています。", "sentence_source": "generated"}, {"text": "細かい作業が続いたので、目がとても疲れました。", "target_word": "作業", "complexity_tier": "T3", "furigana": "細[こま]かい作業[さぎょう]が続[つづ]いたので、目[め]がとても疲[つか]れました。", "sentence_source": "generated"}, {"text": "作業が遅れたのは、雨で道具が使えなかったからです。", "target_word": "作業", "complexity_tier": "T3", "furigana": "作業[さぎょう]が遅[おく]れたのは、雨[あめ]で道具[どうぐ]が使[つか]えなかったからです。", "sentence_source": "generated"}, {"text": "机の上を片づけてから、作業を始めてください。", "target_word": "作業", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]を片[かた]づけてから、作業[さぎょう]を始[はじ]めてください。", "sentence_source": "generated"}, {"text": "父は庭で、朝から草をぬく作業をしています。", "target_word": "作業", "complexity_tier": "T3", "furigana": "父[ちち]は庭[にわ]で、朝[あさ]から草[くさ]をぬく作業[さぎょう]をしています。", "sentence_source": "generated"}, {"text": "この作業は一人では大変なので、友達に手伝ってもらいました。", "target_word": "作業", "complexity_tier": "T3", "furigana": "この作業[さぎょう]は一人[ひとり]では大変[たいへん]なので、友達[ともだち]に手伝[てつだ]ってもらいました。", "sentence_source": "generated"}, {"text": "作業するときは、危ないので機械にさわらないでください。", "target_word": "作業", "complexity_tier": "T3", "furigana": "作業[さぎょう]するときは、危[あぶ]ないので機械[きかい]にさわらないでください。", "sentence_source": "generated"}, {"text": "難しい作業ではないですが、時間がかかります。", "target_word": "作業", "complexity_tier": "T3", "furigana": "難[むずか]しい作業[さぎょう]ではないですが、時間[じかん]がかかります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作業", "label": "基本形"}, {"form": "作業する", "label": "サ変動詞（辞書形）"}, {"form": "作業した", "label": "過去形"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "物を作る・直すために手や体を動かして行う仕事の動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39258, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作業", "is_correct": true, "explanation": "手や体を動かして行う仕事を指すので、「今日の〜は、午後五時までに終わらせます」と合い、空欄に入る。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態を表す語で、終わらせる対象にはならないので入らない。"}, {"text": "景色", "is_correct": false, "explanation": "眺める対象を表す語で、「終わらせる」という文の主語には合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体の熱の状態を表す語で、一日の予定として終わらせるものではない。"}], "explanations": {"作業": "手や体を動かして行う仕事を指すので、「今日の〜は、午後五時までに終わらせます」と合い、空欄に入る。", "天気": "空の状態を表す語で、終わらせる対象にはならないので入らない。", "景色": "眺める対象を表す語で、「終わらせる」という文の主語には合わない。", "体温": "体の熱の状態を表す語で、一日の予定として終わらせるものではない。"}, "sentence_index": 0, "correct_answer": "作業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は、近くの公園を一時間作業するのが楽しみです。", "explanation": "ここは〈散歩〉の意味。作業は目的のある手仕事を指すので、気楽に歩く楽しみには合わない。"}, {"text": "毎晩、友達と電話で一時間作業しました。", "explanation": "ここは〈おしゃべり〉の意味。作業は手や体を動かして物を作ったり直したりすることで、電話で話す行為には使わない。"}, {"text": "毎朝、ピアノを三十分作業しています。", "explanation": "ここは〈練習〉の意味。作業は手や体を動かして物を作ったり直したりすることで、同じ技を繰り返して磨く練習には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39258, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作業", "is_correct": true, "explanation": "草をぬくという手を動かす仕事を指すので、「草をぬく〜をしています」と合い、空欄に入る。"}, {"text": "散歩", "is_correct": false, "explanation": "気晴らしに歩くことで、草をぬく行為とは結びつかないので入らない。"}, {"text": "読書", "is_correct": false, "explanation": "本を読むことで、草をぬくという動作を修飾する語としては成り立たない。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作ることで、草をぬく動作とは組み合わない。"}], "explanations": {"作業": "草をぬくという手を動かす仕事を指すので、「草をぬく〜をしています」と合い、空欄に入る。", "散歩": "気晴らしに歩くことで、草をぬく行為とは結びつかないので入らない。", "読書": "本を読むことで、草をぬくという動作を修飾する語としては成り立たない。", "料理": "食べ物を作ることで、草をぬく動作とは組み合わない。"}, "sentence_index": 6, "correct_answer": "作業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カラオケで好きな曲を大声で作業しました。", "explanation": "ここは〈歌う〉の意味。作業は手や体を動かして物を作ったり直したりすることで、声を出して曲を歌う行為には使わない。"}, {"text": "毎朝、五キロの作業をしてから出勤します。", "explanation": "ここは〈運動〉の意味。作業は手を使う仕事なので、体を鍛えるための距離の運動には合わない。"}, {"text": "寝る前に、小説を一時間作業しました。", "explanation": "ここは〈読書〉の意味。作業は物を作ったり直したりすることで、本を読んで楽しむ行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39258, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い荷物の作業に手伝ってください。", "corrected_sentence": "重い荷物の作業を手伝ってください。", "error_description": "「手伝う」は手伝う対象を「を」で示す。「作業に」は「作業を」の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39258, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業を始まった後、みんなで昼ご飯を食べました。", "corrected_sentence": "作業を始めた後、みんなで昼ご飯を食べました。", "error_description": "「始める」は他の動作を起こす他動詞なので「始めた」。「始まった」は自動詞で、誤った形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39260, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「植林のおかげで」と名詞「植林」を「おかげ」につなぐ「の」で、原因を示す。"}, {"text": "を", "is_correct": false, "explanation": "「植林を」だと目的語になり、「おかげで」と続かないので不自然。"}, {"text": "で", "is_correct": false, "explanation": "「植林で」は手段の意味になり、「おかげで」と重なって意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「植林に」は対象や方向を表し、「おかげで」の前には来ないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「植林のおかげで」と名詞「植林」を「おかげ」につなぐ「の」で、原因を示す。", "を": "「植林を」だと目的語になり、「おかげで」と続かないので不自然。", "で": "「植林で」は手段の意味になり、「おかげで」と重なって意味が通らない。", "に": "「植林に」は対象や方向を表し、「おかげで」の前には来ないので合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "に": "対象・方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39260, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39260, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "木を新しく植えることです。", "primary_collocate": null, "pronunciation": "しょくりん", "ipa": "ɕokɯɾiɴ", "syllable_count": 4, "sentences": [{"text": "春になると、町の人たちが山で植林をする。", "target_word": "植林", "complexity_tier": "T3", "furigana": "春[はる]になると、町[まち]の人[ひと]たちが山[やま]で植林[しょくりん]をする。", "sentence_source": "generated"}, {"text": "植林のおかげで、はげ山に緑が戻ってきた。", "target_word": "植林", "complexity_tier": "T3", "furigana": "植林[しょくりん]のおかげで、はげ山[やま]に緑[みどり]が戻[もど]ってきた。", "sentence_source": "generated"}, {"text": "学校の行事で、生徒は植林に参加した。", "target_word": "植林", "complexity_tier": "T3", "furigana": "学校[がっこう]の行事[ぎょうじ]で、生徒[せいと]は植林[しょくりん]に参加[さんか]した。", "sentence_source": "generated"}, {"text": "植林をした場所には、小さな苗木が並んでいる。", "target_word": "植林", "complexity_tier": "T3", "furigana": "植林[しょくりん]をした場所[ばしょ]には、小[ちい]さな苗木[なえぎ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "この川の近くでは、毎年植林が行われる。", "target_word": "植林", "complexity_tier": "T3", "furigana": "この川[かわ]の近[ちか]くでは、毎年[まいとし]植林[しょくりん]が行[おこな]われる。", "sentence_source": "generated"}, {"text": "父は休みの日に、植林の手伝いに出かけた。", "target_word": "植林", "complexity_tier": "T3", "furigana": "父[ちち]は休[やす]みの日[ひ]に、植林[しょくりん]の手伝[てつだ]いに出[で]かけた。", "sentence_source": "generated"}, {"text": "植林は大変な仕事だが、やりがいがある。", "target_word": "植林", "complexity_tier": "T3", "furigana": "植林[しょくりん]は大変[たいへん]な仕事[しごと]だが、やりがいがある。", "sentence_source": "generated"}, {"text": "森が焼けたので、新しく植林することになった。", "target_word": "植林", "complexity_tier": "T3", "furigana": "森[もり]が焼[や]けたので、新[あたら]しく植林[しょくりん]することになった。", "sentence_source": "generated"}, {"text": "植林から十年たって、木は大きく育った。", "target_word": "植林", "complexity_tier": "T3", "furigana": "植林[しょくりん]から十年[じゅうねん]たって、木[き]は大[おお]きく育[そだ]った。", "sentence_source": "generated"}, {"text": "子どものころ、海のそばで植林を体験した。", "target_word": "植林", "complexity_tier": "T3", "furigana": "子[こ]どものころ、海[うみ]のそばで植林[しょくりん]を体験[たいけん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "植林", "label": "基本形"}, {"form": "植林する", "label": "する動詞形"}], "register": "中立", "sense_fingerprint": "山や野原に木を新しく植える作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39260, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植林", "is_correct": true, "explanation": "「植林をする」は山で木を植える活動を指し、文の内容に合う。"}, {"text": "接客", "is_correct": false, "explanation": "「接客」は客への応対を指し、山での作業としては合わない。"}, {"text": "納品", "is_correct": false, "explanation": "「納品」は商品を届けることで、山での作業には合わない。"}, {"text": "製粉", "is_correct": false, "explanation": "「製粉」は穀物を粉にすることで、山で行う作業としては合わない。"}], "explanations": {"植林": "「植林をする」は山で木を植える活動を指し、文の内容に合う。", "接客": "「接客」は客への応対を指し、山での作業としては合わない。", "納品": "「納品」は商品を届けることで、山での作業には合わない。", "製粉": "「製粉」は穀物を粉にすることで、山で行う作業としては合わない。"}, "sentence_index": 0, "correct_answer": "植林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山の斜面では、植林で古い木を次々に倒していった。", "explanation": "ここは〈伐採〉の意味。「植林」は木を植える作業で、木を倒す作業には使わないので合わない。"}, {"text": "夏の畑では、植林で雑草を一日中抜いた。", "explanation": "ここは〈除草〉の意味。「植林」は木を植える作業で、雑草を抜くことには使わないので合わない。"}, {"text": "週末の公園で、植林を使って落ち葉を集めた。", "explanation": "ここは〈清掃〉の意味。「植林」は木を植える行為で、落ち葉を集める作業には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39260, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植林", "is_correct": true, "explanation": "「植林は大変な仕事だが、やりがいがある」の主語として、木を植える作業を指し、文に合う。"}, {"text": "星空", "is_correct": false, "explanation": "「星空」は空の眺めで、仕事を指さないので「大変な仕事」とは合わない。"}, {"text": "苗木", "is_correct": false, "explanation": "「苗木」は植える木の苗で、仕事そのものを指さないので合わない。"}, {"text": "木陰", "is_correct": false, "explanation": "「木陰」は木の陰の部分で、仕事を指さないので合わない。"}], "explanations": {"植林": "「植林は大変な仕事だが、やりがいがある」の主語として、木を植える作業を指し、文に合う。", "星空": "「星空」は空の眺めで、仕事を指さないので「大変な仕事」とは合わない。", "苗木": "「苗木」は植える木の苗で、仕事そのものを指さないので合わない。", "木陰": "「木陰」は木の陰の部分で、仕事を指さないので合わない。"}, "sentence_index": 6, "correct_answer": "植林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鉱山では、植林で大きな岩を砕く作業が続いた。", "explanation": "ここは〈採掘〉の意味。「植林」は木を植えることで、岩を砕いて掘り出す作業は指さないので合わない。"}, {"text": "雨漏りを直すため、業者に植林で屋根を修理してもらった。", "explanation": "ここは〈修理〉の意味。「植林」は木を植える作業で、屋根を直す作業には使わないので合わない。"}, {"text": "早朝、植林は港から船を出した。", "explanation": "ここは〈漁業〉の意味。「植林」は木を植える活動で、船を出して漁に行く人や活動を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39260, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "森を取り戻すため、町は植林を力を入れた。", "corrected_sentence": "森を取り戻すため、町は植林に力を入れた。", "error_description": "「力を入れる」は「〜に力を入れる」の形を取るので、「植林」の後は「に」が正しい。「を」にすると目的語が二つ並んで文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39260, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年も、村の人が協力して植林を食べた。", "corrected_sentence": "今年も、村の人が協力して植林を行った。", "error_description": "「植林」は行うものなので「行った」が正しい。「食べた」は植林と結びつかず、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39261, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「植林に力を入れる」の形で、植林に力を注ぐという意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「植林を」だと目的語になり、「力を入れている」と結びつかない。"}, {"text": "が", "is_correct": false, "explanation": "「植林が」だと主語になり、「力を入れている」の対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "「植林から」は起点を表し、「力を入れる」とは組み合わない。"}], "correct_answer": "に", "explanations": {"に": "「植林に力を入れる」の形で、植林に力を注ぐという意味になる。", "を": "「植林を」だと目的語になり、「力を入れている」と結びつかない。", "が": "「植林が」だと主語になり、「力を入れている」の対象にならない。", "から": "「植林から」は起点を表し、「力を入れる」とは組み合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39261, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「植林に使う」は植林のための用途を表し、苗木の代金の説明として意味が通る。"}, {"text": "が", "is_correct": false, "explanation": "「植林が使う」では植林が主語になり、苗木の代金の説明にならない。"}, {"text": "を", "is_correct": false, "explanation": "「植林を使う」は目的語にしてしまい、「使う苗木」とつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「植林へ使う」は方向を表し、用途を示さないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「植林に使う」は植林のための用途を表し、苗木の代金の説明として意味が通る。", "が": "「植林が使う」では植林が主語になり、苗木の代金の説明にならない。", "を": "「植林を使う」は目的語にしてしまい、「使う苗木」とつながらない。", "へ": "「植林へ使う」は方向を表し、用途を示さないので合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39261, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "森林や緑地を増やすために、苗木を地面に植えること。", "primary_collocate": null, "pronunciation": "しょくりん", "ipa": "ɕokɯɾiɴ", "syllable_count": 4, "sentences": [{"text": "森を増やすため、会社は山で植林を続けている。", "target_word": "植林", "complexity_tier": "T3", "furigana": "森[もり]を増[ふ]やすため、会社[かいしゃ]は山[やま]で植林[しょくりん]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "砂漠化を防ぐために、各国が植林に力を入れている。", "target_word": "植林", "complexity_tier": "T3", "furigana": "砂漠化[さばくか]を防[ふせ]ぐために、各国[かっこく]が植林[しょくりん]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "植林には、苗木を選ぶところから時間がかかる。", "target_word": "植林", "complexity_tier": "T3", "furigana": "植林[しょくりん]には、苗木[なえぎ]を選[えら]ぶところから時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "市は緑地を広げる計画として、公園の植林を進める。", "target_word": "植林", "complexity_tier": "T3", "furigana": "市[し]は緑地[りょくち]を広[ひろ]げる計画[けいかく]として、公園[こうえん]の植林[しょくりん]を進[すす]める。", "sentence_source": "generated"}, {"text": "地元の高校生が、ボランティアで植林を行った。", "target_word": "植林", "complexity_tier": "T3", "furigana": "地元[じもと]の高校生[こうこうせい]が、ボランティアで植林[しょくりん]を行[おこな]った。", "sentence_source": "generated"}, {"text": "木を切ったあとは、植林をしなければ森は元に戻らない。", "target_word": "植林", "complexity_tier": "T3", "furigana": "木[き]を切[き]ったあとは、植林[しょくりん]をしなければ森[もり]は元[もと]に戻[もど]らない。", "sentence_source": "generated"}, {"text": "雨で土が流れないように、斜面に植林した。", "target_word": "植林", "complexity_tier": "T3", "furigana": "雨[あめ]で土[つち]が流[なが]れないように、斜面[しゃめん]に植林[しょくりん]した。", "sentence_source": "generated"}, {"text": "寄付は、植林に使う苗木の代金になる。", "target_word": "植林", "complexity_tier": "T3", "furigana": "寄付[きふ]は、植林[しょくりん]に使[つか]う苗木[なえぎ]の代金[だいきん]になる。", "sentence_source": "generated"}, {"text": "この団体は、海外でも植林を支援している。", "target_word": "植林", "complexity_tier": "T3", "furigana": "この団体[だんたい]は、海外[かいがい]でも植林[しょくりん]を支援[しえん]している。", "sentence_source": "generated"}, {"text": "植林のあとは、水やりや草取りが欠かせない。", "target_word": "植林", "complexity_tier": "T3", "furigana": "植林[しょくりん]のあとは、水[みず]やりや草取[くさと]りが欠[か]かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "植林", "label": "基本形"}, {"form": "植林する", "label": "する動詞形"}], "register": "中立", "sense_fingerprint": "森や緑を増やす目的で苗木を計画的に植えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39261, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植林", "is_correct": true, "explanation": "「植林を続けている」は山で木を植える作業を続ける意味になり、会社の取り組みとして合う。"}, {"text": "接客", "is_correct": false, "explanation": "「接客」は客への応対で、山で続ける作業としては合わない。"}, {"text": "製本", "is_correct": false, "explanation": "「製本」は本を綴じる作業で、山では行わないので合わない。"}, {"text": "納品", "is_correct": false, "explanation": "「納品」は商品を届けることで、山で続ける作業としては合わない。"}], "explanations": {"植林": "「植林を続けている」は山で木を植える作業を続ける意味になり、会社の取り組みとして合う。", "接客": "「接客」は客への応対で、山で続ける作業としては合わない。", "製本": "「製本」は本を綴じる作業で、山では行わないので合わない。", "納品": "「納品」は商品を届けることで、山で続ける作業としては合わない。"}, "sentence_index": 0, "correct_answer": "植林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の木の枝を植林して、形を整えた。", "explanation": "ここは〈剪定〉の意味。「植林」は木を植えることで、枝を切って形を整える作業には合わない。"}, {"text": "乾いた畑に、植林で水を引いた。", "explanation": "ここは〈灌漑〉の意味。「植林」は木を植える作業で、水路を通して水を引く行為には使わないので合わない。"}, {"text": "夜の公園は、植林が見回りをしている。", "explanation": "ここは〈警備〉の意味。「植林」は木を植える活動で、見回りをする人や仕事を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39261, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植林", "is_correct": true, "explanation": "斜面に木を植えて土を守る作業を指し、「土が流れないように」の目的に合う。"}, {"text": "読書", "is_correct": false, "explanation": "「読書」は本を読む活動で、斜面での土砂対策とは合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「洗濯」は衣類を洗う作業で、斜面の土対策には合わない。"}, {"text": "作曲", "is_correct": false, "explanation": "「作曲」は曲を作る作業で、土砂を防ぐ行為ではないので合わない。"}], "explanations": {"植林": "斜面に木を植えて土を守る作業を指し、「土が流れないように」の目的に合う。", "読書": "「読書」は本を読む活動で、斜面での土砂対策とは合わない。", "洗濯": "「洗濯」は衣類を洗う作業で、斜面の土対策には合わない。", "作曲": "「作曲」は曲を作る作業で、土砂を防ぐ行為ではないので合わない。"}, "sentence_index": 6, "correct_answer": "植林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、母は服を植林してから出かける。", "explanation": "ここは〈洗濯〉の意味。「植林」は木を植える作業で、服を洗う作業には使わないので合わない。"}, {"text": "ホールでは、植林が三曲目を情感たっぷりに奏でた。", "explanation": "ここは〈演奏者〉の意味。「植林」は木を植える活動で、楽器を奏でる人を指さないので合わない。"}, {"text": "雨の中、植林は手紙を届けた。", "explanation": "ここは〈配達〉の意味。「植林」は木を植える活動で、手紙を届ける仕事には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39261, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "砂漠化を防ぐため、政府は植林が進めている。", "corrected_sentence": "砂漠化を防ぐため、政府は植林を進めている。", "error_description": "「進める」は目的語を取る他動詞なので、「植林」の後は「を」が正しい。「が」にすると進める対象がなくなり、文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39261, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は山を守るため、植林を泳いだ。", "corrected_sentence": "会社は山を守るため、植林を進めた。", "error_description": "「植林」と結びつく動詞は「進める」が正しい。「泳いだ」は植林と結びつかず、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39262, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疎遠", "is_correct": true, "explanation": "正解。「親しい」の対義語で、関係が遠くよそよそしい状態を表す。"}, {"text": "丁寧", "is_correct": false, "explanation": "礼儀正しく念入りな様子を表し、親しさの反対の意味ではない。"}, {"text": "新鮮", "is_correct": false, "explanation": "新しくいきいきした様子を表し、人間関係の対義語ではない。"}, {"text": "大切", "is_correct": false, "explanation": "大事だという意味で、親しさと反対の関係にはない。"}], "correct_answer": "疎遠", "explanations": {"疎遠": "正解。「親しい」の対義語で、関係が遠くよそよそしい状態を表す。", "丁寧": "礼儀正しく念入りな様子を表し、親しさの反対の意味ではない。", "新鮮": "新しくいきいきした様子を表し、人間関係の対義語ではない。", "大切": "大事だという意味で、親しさと反対の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39262, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39262, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "「したしい」は、ともだちのように、なかがいいことです。", "primary_collocate": null, "pronunciation": "したしい", "ipa": "ɕitaɕiː", "syllable_count": 4, "sentences": [{"text": "小学校のころから親しい友だちと、今も毎週会っている。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "小学校[しょうがっこう]のころから親[した]しい友[とも]だちと、今[いま]も毎週[まいしゅう]会[あ]っている。", "sentence_source": "generated"}, {"text": "彼とは親しい仲なので、何でも相談できる。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "彼[かれ]とは親[した]しい仲[なか]なので、何[なん]でも相談[そうだん]できる。", "sentence_source": "generated"}, {"text": "親しい人には、本当の気持ちを話しやすい。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "親[した]しい人[ひと]には、本当[ほんとう]の気持[きも]ちを話[はな]しやすい。", "sentence_source": "generated"}, {"text": "隣の席の子と親しくなって、いっしょに帰るようになった。", "target_word": "親しく", "complexity_tier": "T3", "furigana": "隣[となり]の席[せき]の子[こ]と親[した]しくなって、いっしょに帰[かえ]るようになった。", "sentence_source": "generated"}, {"text": "親しい友だちの誕生日に、手作りのカードをおくった。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "親[した]しい友[とも]だちの誕生日[たんじょうび]に、手作[てづく]りのカードをおくった。", "sentence_source": "generated"}, {"text": "先生とは親しく話せるので、質問がしやすい。", "target_word": "親しく", "complexity_tier": "T3", "furigana": "先生[せんせい]とは親[した]しく話[はな]せるので、質問[しつもん]がしやすい。", "sentence_source": "generated"}, {"text": "親しくない人に急にあだ名で呼ばれて、びっくりした。", "target_word": "親しくない", "complexity_tier": "T3", "furigana": "親[した]しくない人[ひと]に急[きゅう]にあだ名[な]で呼[よ]ばれて、びっくりした。", "sentence_source": "generated"}, {"text": "旅行先で親しくなった人と、今も手紙を書いている。", "target_word": "親しく", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]で親[した]しくなった人[ひと]と、今[いま]も手紙[てがみ]を書[か]いている。", "sentence_source": "generated"}, {"text": "親しい友だちだけを、家のパーティーに呼んだ。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "親[した]しい友[とも]だちだけを、家[いえ]のパーティーに呼[よ]んだ。", "sentence_source": "generated"}, {"text": "二人は親しそうに笑いながら、公園を歩いていた。", "target_word": "親しそう", "complexity_tier": "T3", "furigana": "二人[ふたり]は親[した]しそうに笑[わら]いながら、公園[こうえん]を歩[ある]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "親しい", "label": "終止形"}, {"form": "親しく", "label": "連用形"}, {"form": "親しくない", "label": "否定形"}, {"form": "親しかった", "label": "過去形"}, {"form": "親しくて", "label": "て形"}, {"form": "親しければ", "label": "仮定形"}], "register": "日常", "sense_fingerprint": "親しい=友だちのように気軽に話せるほど仲がよい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39262, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "親しい", "is_correct": true, "explanation": "正解。「小学校のころから親しい友だち」は、今も毎週会う仲の良さと合う。"}, {"text": "新しい", "is_correct": false, "explanation": "「新しい友だち」は付き合いの始まりを表し、「小学校のころから」と矛盾する。"}, {"text": "珍しい", "is_correct": false, "explanation": "「珍しい友だち」は人として変わっている、まれだという意味になり、文脈に合わない。"}, {"text": "遠い", "is_correct": false, "explanation": "距離が遠いという意味になり、毎週会う流れと合わない。"}], "explanations": {"親しい": "正解。「小学校のころから親しい友だち」は、今も毎週会う仲の良さと合う。", "新しい": "「新しい友だち」は付き合いの始まりを表し、「小学校のころから」と矛盾する。", "珍しい": "「珍しい友だち」は人として変わっている、まれだという意味になり、文脈に合わない。", "遠い": "距離が遠いという意味になり、毎週会う流れと合わない。"}, "sentence_index": 0, "correct_answer": "親しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅から家が親しいので、雨の日も歩いて帰れる。", "explanation": "ここは〈近い〉（距離が近い）の意味。親しいは人との心の距離に使うので、家と駅の関係には合わない。"}, {"text": "この問題は親しいので、すぐ解けた。", "explanation": "親しいは人と人の関係に使うので、問題の易しさには使えない。"}, {"text": "海で親しい魚を釣って、家族に見せた。", "explanation": "親しいは人との関係に使うので、魚の珍しさには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39262, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "親しくない", "is_correct": true, "explanation": "正解。知らない・親しくない人に急にあだ名で呼ばれて驚く文脈に合う。"}, {"text": "眠くない", "is_correct": false, "explanation": "眠気の否定を表し、人を修飾すると意味が通らない。"}, {"text": "おいしくない", "is_correct": false, "explanation": "味の否定を表し、人を修飾すると意味が通らない。"}, {"text": "寒くない", "is_correct": false, "explanation": "気温の否定を表し、人を修飾すると意味が通らない。"}], "explanations": {"親しくない": "正解。知らない・親しくない人に急にあだ名で呼ばれて驚く文脈に合う。", "眠くない": "眠気の否定を表し、人を修飾すると意味が通らない。", "おいしくない": "味の否定を表し、人を修飾すると意味が通らない。", "寒くない": "気温の否定を表し、人を修飾すると意味が通らない。"}, "sentence_index": 6, "correct_answer": "親しくない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どものころの親しい思い出を、今も大切にしている。", "explanation": "ここは〈懐かしい〉の意味。親しいは人との関係に使うので、思い出の感じ方には合わない。"}, {"text": "親しい問題について、みんなで話し合った。", "explanation": "ここは〈身近〉の意味。親しいは人と人の関係に使うので、問題の身近さには合わない。"}, {"text": "親しい冬に、ストーブをつけた。", "explanation": "親しいは人との関係に使うので、季節の寒さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39262, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大学時代からの親しく友人と、今も年に数回食事をする。", "corrected_sentence": "大学時代からの親しい友人と、今も年に数回食事をする。", "error_description": "誤: 親しく（連用形）／正: 親しい（連体形）。名詞「友人」を修飾するので連体形が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "親しい", "is_correct": true, "explanation": "正解。連体形で、名詞「仲」を直接修飾している。"}, {"text": "親しく", "is_correct": false, "explanation": "連用形は動詞や形容詞を修飾する形で、名詞「仲」の前には使えない。"}, {"text": "親しければ", "is_correct": false, "explanation": "仮定形で、名詞「仲」を直接修飾できない。"}, {"text": "親しくて", "is_correct": false, "explanation": "て形で、名詞「仲」を直接修飾できない。"}], "correct_form": "親しい", "base_form": "親しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"親しい": "正解。連体形で、名詞「仲」を直接修飾している。", "親しく": "連用形は動詞や形容詞を修飾する形で、名詞「仲」の前には使えない。", "親しければ": "仮定形で、名詞「仲」を直接修飾できない。", "親しくて": "て形で、名詞「仲」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39262, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "留学先で親しいなった友人と、今もメールを交わしている。", "corrected_sentence": "留学先で親しくなった友人と、今もメールを交わしている。", "error_description": "誤: 親しい（終止形）＋なった／正: 親しく（連用形）＋なった。形容詞が「なる」につくときは「〜く」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "親しく", "is_correct": true, "explanation": "正解。連用形で、「親しくなった」のように「なる」につながっている。"}, {"text": "親しくない", "is_correct": false, "explanation": "否定形で、「なった」の前に置くと文が成り立たない。"}, {"text": "親しかった", "is_correct": false, "explanation": "過去形で、「なった」の前には使えない。「親しかったなった」は文として成り立たない。"}, {"text": "親しかろう", "is_correct": false, "explanation": "推量形で、「なった」の文の形と合わない。"}], "correct_form": "親しく", "base_form": "親しい", "form_label": "連用形", "sentence_index": 7, "explanations": {"親しく": "正解。連用形で、「親しくなった」のように「なる」につながっている。", "親しくない": "否定形で、「なった」の前に置くと文が成り立たない。", "親しかった": "過去形で、「なった」の前には使えない。「親しかったなった」は文として成り立たない。", "親しかろう": "推量形で、「なった」の文の形と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39263, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疎遠", "is_correct": true, "explanation": "正解。「親しい」の対義語で、関係が遠くよそよそしい状態を表す。"}, {"text": "丁寧", "is_correct": false, "explanation": "念入りな様子を表し、関係の遠近の反対語ではない。"}, {"text": "新鮮", "is_correct": false, "explanation": "新しくいきいきした様子を表し、関係の対義語ではない。"}, {"text": "大切", "is_correct": false, "explanation": "大事だという意味で、親しさと反対の関係にはない。"}], "correct_answer": "疎遠", "explanations": {"疎遠": "正解。「親しい」の対義語で、関係が遠くよそよそしい状態を表す。", "丁寧": "念入りな様子を表し、関係の遠近の反対語ではない。", "新鮮": "新しくいきいきした様子を表し、関係の対義語ではない。", "大切": "大事だという意味で、親しさと反対の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39263, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疎遠", "is_correct": true, "explanation": "正解。「親しい」の対義語で、関係が遠くよそよそしい状態を表す。"}, {"text": "静か", "is_correct": false, "explanation": "物音が少ない様子を表し、関係の遠近の反対語ではない。"}, {"text": "豊か", "is_correct": false, "explanation": "たくさんある様子を表し、人間関係の対義語ではない。"}, {"text": "確か", "is_correct": false, "explanation": "確実だという意味で、親しさの反対の意味ではない。"}], "correct_answer": "疎遠", "explanations": {"疎遠": "正解。「親しい」の対義語で、関係が遠くよそよそしい状態を表す。", "静か": "物音が少ない様子を表し、関係の遠近の反対語ではない。", "豊か": "たくさんある様子を表し、人間関係の対義語ではない。", "確か": "確実だという意味で、親しさの反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39263, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "人と人の関係が近く、心が通じ合っている様子。仲が良い。", "primary_collocate": null, "pronunciation": "したしい", "ipa": "ɕitaɕiː", "syllable_count": 4, "sentences": [{"text": "二つの国は長年、親しい関係を保っている。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]は長年[ながねん]、親[した]しい関係[かんけい]を保[たも]っている。", "sentence_source": "generated"}, {"text": "親しい間柄でも、礼儀は忘れないようにしたい。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "親[した]しい間柄[あいだがら]でも、礼儀[れいぎ]は忘[わす]れないようにしたい。", "sentence_source": "generated"}, {"text": "彼は社長と親しいので、会社の情報が早く入る。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "彼[かれ]は社長[しゃちょう]と親[した]しいので、会社[かいしゃ]の情報[じょうほう]が早[はや]く入[はい]る。", "sentence_source": "generated"}, {"text": "親しい取引先を招いて、小さな会を開いた。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "親[した]しい取引先[とりひきさき]を招[まね]いて、小[ちい]さな会[かい]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "親しくなるにつれて、二人は互いの悩みも話すようになった。", "target_word": "親しく", "complexity_tier": "T3", "furigana": "親[した]しくなるにつれて、二人[ふたり]は互[たが]いの悩[なや]みも話[はな]すようになった。", "sentence_source": "generated"}, {"text": "隣人と親しい関係を築くと、災害のときに助け合える。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "隣人[りんじん]と親[した]しい関係[かんけい]を築[きず]くと、災害[さいがい]のときに助[たす]け合[あ]える。", "sentence_source": "generated"}, {"text": "親しい仲だからこそ、はっきり意見を言うこともある。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "親[した]しい仲[なか]だからこそ、はっきり意見[いけん]を言[い]うこともある。", "sentence_source": "generated"}, {"text": "作家は、親しい友人にだけ新作を見せていた。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "作家[さっか]は、親[した]しい友人[ゆうじん]にだけ新作[しんさく]を見[み]せていた。", "sentence_source": "generated"}, {"text": "彼女は誰とでもすぐ親しくなれる、明るい人だ。", "target_word": "親しく", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は誰[だれ]とでもすぐ親[した]しくなれる、明[あか]るい人[ひと]だ。", "sentence_source": "generated"}, {"text": "長年の付き合いで、取引先の社長とも親しい間柄だ。", "target_word": "親しい", "complexity_tier": "T3", "furigana": "長年[ながねん]の付[つ]き合[あ]いで、取引先[とりひきさき]の社長[しゃちょう]とも親[した]しい間柄[あいだがら]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "親しい", "label": "終止形"}, {"form": "親しく", "label": "連用形"}, {"form": "親しくない", "label": "否定形"}, {"form": "親しかった", "label": "過去形"}, {"form": "親しくて", "label": "て形"}, {"form": "親しければ", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "親しい=人や国などの関係が近く、互いに心が通じている", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39263, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "親しい", "is_correct": true, "explanation": "正解。国どうしの関係が近く、互いに通じ合っている様子を表す。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す語で、「関係」を修飾すると意味が通らない。"}, {"text": "苦い", "is_correct": false, "explanation": "味の形容で、国の関係を表すことはできない。"}, {"text": "鋭い", "is_correct": false, "explanation": "鋭さや察しの良さを表し、長年の関係を保つという文脈に合わない。"}], "explanations": {"親しい": "正解。国どうしの関係が近く、互いに通じ合っている様子を表す。", "眠い": "眠気を表す語で、「関係」を修飾すると意味が通らない。", "苦い": "味の形容で、国の関係を表すことはできない。", "鋭い": "鋭さや察しの良さを表し、長年の関係を保つという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "親しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅から会社までは親しいので、歩いて通える。", "explanation": "ここは〈近い〉（距離が近い）の意味。親しいは人どうしの関係の近さに使い、場所の距離には合わない。"}, {"text": "展示会で親しい絵画を見た。", "explanation": "親しいは人どうしの関係に使うので、絵画の珍しさには使えない。"}, {"text": "冬の朝は親しいので、なかなか布団から出られない。", "explanation": "親しいは人との関係に使うので、気温の寒さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39263, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "親しい", "is_correct": true, "explanation": "正解。「親しい仲だからこそ、はっきり意見を言う」という文脈で、関係の近さを表す。"}, {"text": "暑い", "is_correct": false, "explanation": "気温を表す語で、「仲」を修飾すると意味が通らない。"}, {"text": "辛い", "is_correct": false, "explanation": "味や苦しさを表し、人間関係の近さを言う文脈に合わない。"}, {"text": "高い", "is_correct": false, "explanation": "値段や位置を表し、「仲」を修飾すると不自然になる。"}], "explanations": {"親しい": "正解。「親しい仲だからこそ、はっきり意見を言う」という文脈で、関係の近さを表す。", "暑い": "気温を表す語で、「仲」を修飾すると意味が通らない。", "辛い": "味や苦しさを表し、人間関係の近さを言う文脈に合わない。", "高い": "値段や位置を表し、「仲」を修飾すると不自然になる。"}, "sentence_index": 6, "correct_answer": "親しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に親しい夢を見て、目が覚めた。", "explanation": "親しいは人との関係に使うので、夢の内容には使えない。"}, {"text": "親しい庭のある家に住みたい。", "explanation": "親しいは人間関係に使うので、庭の広さには合わない。"}, {"text": "押し入れで親しい写真を見つけた。", "explanation": "ここは〈懐かしい〉の意味。親しいは人との関係に使うので、写真の感じ方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39263, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同じ部の先輩とは親しく仲なので、仕事の相談がしやすい。", "corrected_sentence": "同じ部の先輩とは親しい仲なので、仕事の相談がしやすい。", "error_description": "誤: 親しく（連用形）／正: 親しい（連体形）。名詞「仲」を修飾するので連体形が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "親しい", "is_correct": true, "explanation": "正解。連体形で、名詞「間柄」を直接修飾している。"}, {"text": "親しく", "is_correct": false, "explanation": "連用形で、名詞「間柄」の前には使えない。"}, {"text": "親しくて", "is_correct": false, "explanation": "て形で、名詞「間柄」を直接修飾できない。"}, {"text": "親しければ", "is_correct": false, "explanation": "仮定形で、名詞「間柄」を直接修飾できない。"}], "correct_form": "親しい", "base_form": "親しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"親しい": "正解。連体形で、名詞「間柄」を直接修飾している。", "親しく": "連用形で、名詞「間柄」の前には使えない。", "親しくて": "て形で、名詞「間柄」を直接修飾できない。", "親しければ": "仮定形で、名詞「間柄」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39263, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同じ寮の仲間と、だんだん親しいなった。", "corrected_sentence": "同じ寮の仲間と、だんだん親しくなった。", "error_description": "誤: 親しい（終止形）＋なった／正: 親しく（連用形）＋なった。形容詞が「なる」につくときは「〜く」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "親しい", "is_correct": true, "explanation": "正解。連体形で、名詞「友人」を直接修飾している。"}, {"text": "親しさ", "is_correct": false, "explanation": "名詞で、形容詞の連体形として「友人」を修飾することはできない。"}, {"text": "親しみ", "is_correct": false, "explanation": "名詞で、「友人」を直接修飾する形ではない。"}, {"text": "親しかろう", "is_correct": false, "explanation": "推量形で「〜だろう」の意味になり、断定の文と合わない。"}], "correct_form": "親しい", "base_form": "親しい", "form_label": "連体形", "sentence_index": 7, "explanations": {"親しい": "正解。連体形で、名詞「友人」を直接修飾している。", "親しさ": "名詞で、形容詞の連体形として「友人」を修飾することはできない。", "親しみ": "名詞で、「友人」を直接修飾する形ではない。", "親しかろう": "推量形で「〜だろう」の意味になり、断定の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39264, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「学習の時間」の「の」で、名詞「学習」と「時間」をつなぐ。正解。"}, {"text": "が", "is_correct": false, "explanation": "「学習が時間」は主語の関係が成り立たず、文が合わない。"}, {"text": "を", "is_correct": false, "explanation": "「学習を時間」は目的語にならず、名詞をつなげられない。"}, {"text": "で", "is_correct": false, "explanation": "「学習で時間」は手段や場所の関係になり、意味が合わない。"}], "correct_answer": "の", "explanations": {"の": "「学習の時間」の「の」で、名詞「学習」と「時間」をつなぐ。正解。", "が": "「学習が時間」は主語の関係が成り立たず、文が合わない。", "を": "「学習を時間」は目的語にならず、名詞をつなげられない。", "で": "「学習で時間」は手段や場所の関係になり、意味が合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
