INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39264, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "べんきょうやしらべものをすること。", "primary_collocate": null, "pronunciation": "がくしゅう", "ipa": "ɡakɯɕɯː", "syllable_count": 4, "sentences": [{"text": "毎日三十分、英語を学習しています。", "target_word": "学習", "complexity_tier": "T3", "furigana": "毎日[まいにち]三十分[さんじゅっぷん]、英語[えいご]を学習[がくしゅう]しています。", "sentence_source": "generated"}, {"text": "子どもたちは、学習の時間にしずかに本を読んでいます。", "target_word": "学習", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、学習[がくしゅう]の時間[じかん]にしずかに本[ほん]を読[よ]んでいます。", "sentence_source": "generated"}, {"text": "新しい方法で学習したら、漢字がすぐにおぼえられました。", "target_word": "学習", "complexity_tier": "T3", "furigana": "新[あたら]しい方法[ほうほう]で学習[がくしゅう]したら、漢字[かんじ]がすぐにおぼえられました。", "sentence_source": "generated"}, {"text": "学習のあとで、先生にしつもんをしました。", "target_word": "学習", "complexity_tier": "T3", "furigana": "学習[がくしゅう]のあとで、先生[せんせい]にしつもんをしました。", "sentence_source": "generated"}, {"text": "この教室は、学習するのにとてもしずかでいい場所です。", "target_word": "学習", "complexity_tier": "T3", "furigana": "この教室[きょうしつ]は、学習[がくしゅう]するのにとてもしずかでいい場所[ばしょ]です。", "sentence_source": "generated"}, {"text": "試験が近いので、今週は学習の時間をふやしました。", "target_word": "学習", "complexity_tier": "T3", "furigana": "試験[しけん]が近[ちか]いので、今週[こんしゅう]は学習[がくしゅう]の時間[じかん]をふやしました。", "sentence_source": "generated"}, {"text": "学習の計画を立てて、少しずつ進めています。", "target_word": "学習", "complexity_tier": "T3", "furigana": "学習[がくしゅう]の計画[けいかく]を立[た]てて、少[すこ]しずつ進[すす]めています。", "sentence_source": "generated"}, {"text": "図書館で資料を調べながら学習しました。", "target_word": "学習", "complexity_tier": "T3", "furigana": "図書館[としょかん]で資料[しりょう]を調[しら]べながら学習[がくしゅう]しました。", "sentence_source": "generated"}, {"text": "兄は理科の学習が好きで、実験をよくします。", "target_word": "学習", "complexity_tier": "T3", "furigana": "兄[あに]は理科[りか]の学習[がくしゅう]が好[す]きで、実験[じっけん]をよくします。", "sentence_source": "generated"}, {"text": "学習ノートに、毎日学んだことを書いています。", "target_word": "学習", "complexity_tier": "T3", "furigana": "学習[がくしゅう]ノートに、毎日[まいにち]学[まな]んだことを書[か]いています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "学習する", "label": "基本形"}, {"form": "学習した", "label": "過去形"}, {"form": "学習して", "label": "て形"}, {"form": "学習しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "勉強したり調べたりして知識や技能を身につけること。「学習する」の形で動詞にもなる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: ふやし (Zipf 2.23)']::text[], '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39264, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学習", "is_correct": true, "explanation": "「英語を学習しています」として、勉強する行為を表す。正解。"}, {"text": "注文", "is_correct": false, "explanation": "「英語を注文」は勉強の意味にならず、文が合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "「英語を掃除」は意味が通らず、勉強を表せない。"}, {"text": "出発", "is_correct": false, "explanation": "「英語を出発」は意味が通らず、勉強を表せない。"}], "explanations": {"学習": "「英語を学習しています」として、勉強する行為を表す。正解。", "注文": "「英語を注文」は勉強の意味にならず、文が合わない。", "掃除": "「英語を掃除」は意味が通らず、勉強を表せない。", "出発": "「英語を出発」は意味が通らず、勉強を表せない。"}, "sentence_index": 0, "correct_answer": "学習"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は学習を大きな箱に入れて、倉庫へ運びました。", "explanation": "〈学習〉は学ぶ行為を表すので、箱に入れて運べる物としては使えない。"}, {"text": "友達の服を毎朝学習して、ほめていました。", "explanation": "服を選んだり見て判断したりするのは〈観察〉か〈評価〉を使う。〈学習〉は知識や技能を身につけることを指すので、服の評価には合わない。"}, {"text": "彼は新しい薬を学習して、論文にまとめました。", "explanation": "対象を調べて明らかにする場合は〈研究〉を使う。〈学習〉は知識を身につけることを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39264, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学習", "is_correct": true, "explanation": "「学習の計画」として、学ぶための計画を表す。正解。"}, {"text": "体温", "is_correct": false, "explanation": "「体温の計画」は意味が通らず、文が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の計画」は意味が通らず、勉強の計画を表せない。"}, {"text": "爆発", "is_correct": false, "explanation": "「爆発の計画」は意味が通らず、文が合わない。"}], "explanations": {"学習": "「学習の計画」として、学ぶための計画を表す。正解。", "体温": "「体温の計画」は意味が通らず、文が合わない。", "天気": "「天気の計画」は意味が通らず、勉強の計画を表せない。", "爆発": "「爆発の計画」は意味が通らず、文が合わない。"}, "sentence_index": 6, "correct_answer": "学習"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の虫を毎朝学習して、ノートに記録しました。", "explanation": "対象を見て調べる行為は〈観察〉を使う。〈学習〉は知識や技能を身につけることで、観察の意味では合わない。"}, {"text": "子どもの頃から切手を毎日学習して、今も集めています。", "explanation": "集める行為は〈収集〉を使う。〈学習〉は知識を身につけることで、物を集める意味には合わない。"}, {"text": "ベテランの先生は、新人を学習しています。", "explanation": "人を教え導くのは〈指導〉を使う。〈学習〉は学ぶ側の行為なので、先生が相手に対して使うのは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39264, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎晩一時間、数学を学習でいます。", "corrected_sentence": "毎晩一時間、数学を学習しています。", "error_description": "サ変動詞「する」の活用の誤り。「学習＋しています」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39264, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みに、日本の歴史を毎日学習を見ました。", "corrected_sentence": "夏休みに、日本の歴史を毎日学習しました。", "error_description": "「学習」に続けるのは「する」の活用である。「学習を見ました」は動詞が違い、意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
