INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39266, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "「予定より早く」は予定と比べての早さを表し、文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「予定を早く」は予定を目的語にするので、早く来た様子とつながらない。"}, {"text": "が", "is_correct": false, "explanation": "「予定が早く」は予定を主語にしてしまい、先生が早く来た意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「予定へ早く」は方向を表すが、比べる基準を示す文の意味に合わない。"}], "correct_answer": "より", "explanations": {"より": "「予定より早く」は予定と比べての早さを表し、文の意味に合う。", "を": "「予定を早く」は予定を目的語にするので、早く来た様子とつながらない。", "が": "「予定が早く」は予定を主語にしてしまい、先生が早く来た意味にならない。", "へ": "「予定へ早く」は方向を表すが、比べる基準を示す文の意味に合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39266, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これからすることや、これから起こることを、あらかじめ考えておくことです。", "primary_collocate": null, "pronunciation": "よてい", "ipa": "joteː", "syllable_count": 3, "sentences": [{"text": "明日の予定は、まだ何も決まっていない。", "target_word": "予定", "complexity_tier": "T3", "furigana": "明日[あした]の予定[よてい]は、まだ何[なに]も決[き]まっていない。", "sentence_source": "generated"}, {"text": "今週末は友だちと会う予定だ。", "target_word": "予定", "complexity_tier": "T3", "furigana": "今週末[こんしゅうまつ]は友[とも]だちと会[あ]う予定[よてい]だ。", "sentence_source": "generated"}, {"text": "予定が変わったので、すぐに連絡します。", "target_word": "予定", "complexity_tier": "T3", "furigana": "予定[よてい]が変[か]わったので、すぐに連絡[れんらく]します。", "sentence_source": "generated"}, {"text": "旅行の予定を、家族みんなで相談した。", "target_word": "予定", "complexity_tier": "T3", "furigana": "旅行[りょこう]の予定[よてい]を、家族[かぞく]みんなで相談[そうだん]した。", "sentence_source": "generated"}, {"text": "雨が降ったため、運動会は予定どおりに終わらなかった。", "target_word": "予定", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったため、運動会[うんどうかい]は予定[よてい]どおりに終[お]わらなかった。", "sentence_source": "generated"}, {"text": "来月、引っ越しをする予定です。", "target_word": "予定", "complexity_tier": "T3", "furigana": "来月[らいげつ]、引[ひ]っ越[こ]しをする予定[よてい]です。", "sentence_source": "generated"}, {"text": "今日は予定がないから、ゆっくり本を読もう。", "target_word": "予定", "complexity_tier": "T3", "furigana": "今日[きょう]は予定[よてい]がないから、ゆっくり本[ほん]を読[よ]もう。", "sentence_source": "generated"}, {"text": "先生は予定より早く教室に来た。", "target_word": "予定", "complexity_tier": "T3", "furigana": "先生[せんせい]は予定[よてい]より早[はや]く教室[きょうしつ]に来[き]た。", "sentence_source": "generated"}, {"text": "予定を手帳に書いておけば、忘れない。", "target_word": "予定", "complexity_tier": "T3", "furigana": "予定[よてい]を手帳[てちょう]に書[か]いておけば、忘[わす]れない。", "sentence_source": "generated"}, {"text": "彼は夏に留学する予定で、英語を勉強している。", "target_word": "予定", "complexity_tier": "T3", "furigana": "彼[かれ]は夏[なつ]に留学[りゅうがく]する予定[よてい]で、英語[えいご]を勉強[べんきょう]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "予定", "label": "基本形"}, {"form": "予定する", "label": "する動詞形"}], "register": "中立", "sense_fingerprint": "これからすることを前もって考えておくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39266, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "予定", "is_correct": true, "explanation": "「明日の予定」はこれから行う計画の意味になり、まだ何も決まっていないという文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「明日の天気」は決めて計画するものではなく、「まだ何も決まっていない」という文の主語にならない。"}, {"text": "味", "is_correct": false, "explanation": "「明日の味」は意味が通らず、空欄に入ると文が成り立たない。"}, {"text": "悩み", "is_correct": false, "explanation": "「明日の悩み」は決まっているかどうかを問う対象にならず、「まだ何も決まっていない」と続かない。"}], "explanations": {"予定": "「明日の予定」はこれから行う計画の意味になり、まだ何も決まっていないという文に合う。", "天気": "「明日の天気」は決めて計画するものではなく、「まだ何も決まっていない」という文の主語にならない。", "味": "「明日の味」は意味が通らず、空欄に入ると文が成り立たない。", "悩み": "「明日の悩み」は決まっているかどうかを問う対象にならず、「まだ何も決まっていない」と続かない。"}, "sentence_index": 0, "correct_answer": "予定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合結果の予定を、ファンみんなで立てた。", "explanation": "ここは〈予想〉の意味。試合の結果は予定して決めるものではないので、見通しを表すには予想を使う。"}, {"text": "スマホの予定の電池を、かばんに入れた。", "explanation": "ここは〈予備〉の意味。いざという時の替えの電池は予備と言い、予定とは言わないので合わない。"}, {"text": "明日の天気の予定を、テレビで確認した。", "explanation": "ここは〈予報〉の意味。天気の見通しは予報と言い、予定を使うと不自然で意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39266, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "予定", "is_correct": true, "explanation": "「今日は予定がない」は特に決まった用事や計画がないことを表し、ゆっくり本を読むという文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「今日は天気がない」は天気の有無を言う表現として成り立たず、本を読む理由にもならない。"}, {"text": "歌", "is_correct": false, "explanation": "「今日は歌がない」は文として意味が通らず、空欄に入らない。"}, {"text": "色", "is_correct": false, "explanation": "「今日は色がない」は色の有無を述べる表現で、予定の不在を表す文に合わない。"}], "explanations": {"予定": "「今日は予定がない」は特に決まった用事や計画がないことを表し、ゆっくり本を読むという文に合う。", "天気": "「今日は天気がない」は天気の有無を言う表現として成り立たず、本を読む理由にもならない。", "歌": "「今日は歌がない」は文として意味が通らず、空欄に入らない。", "色": "「今日は色がない」は色の有無を述べる表現で、予定の不在を表す文に合わない。"}, "sentence_index": 6, "correct_answer": "予定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の旅館の予定を取った。", "explanation": "ここは〈予約〉の意味。部屋を押さえる行為は予約と言い、予定は取るものではないので合わない。"}, {"text": "なぜか嫌な予定がする。", "explanation": "ここは〈予感〉の意味。ぼんやりした不安の気配は予感と言い、予定を「する」と言うのは合わない。"}, {"text": "風邪の予定に、うがいをする。", "explanation": "ここは〈予防〉の意味。病気を防ぐための行為は予防で表し、計画の意味の予定は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39266, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週、美術館へ行く予定ます。", "corrected_sentence": "来週、美術館へ行く予定です。", "error_description": "「予定」は名詞なので、丁寧に言い切るときは「です」で続ける。「ます」は動詞につく形なので、名詞の「予定」には続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
