INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39267, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「予定を変更します」は予定を目的語にして、変える対象を示すので文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「予定が変更」は予定を主語にしてしまい、変える対象を示せないので不自然。"}, {"text": "の", "is_correct": false, "explanation": "「予定の変更します」は名詞の後に「します」が続けられず、「予定の変更をします」が必要なので文として不完全。"}, {"text": "で", "is_correct": false, "explanation": "「予定で変更」は手段や場所を表し、変更される対象を結べないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「予定を変更します」は予定を目的語にして、変える対象を示すので文に合う。", "が": "「予定が変更」は予定を主語にしてしまい、変える対象を示せないので不自然。", "の": "「予定の変更します」は名詞の後に「します」が続けられず、「予定の変更をします」が必要なので文として不完全。", "で": "「予定で変更」は手段や場所を表し、変更される対象を結べないので合わない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39267, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "将来行われることや、ある状態になることを前もって考えたり計画したりすること。また、その内容。", "primary_collocate": null, "pronunciation": "よてい", "ipa": "joteː", "syllable_count": 3, "sentences": [{"text": "会議の予定は、メールでお知らせします。", "target_word": "予定", "complexity_tier": "T3", "furigana": "会議[かいぎ]の予定[よてい]は、メールでお知[し]らせします。", "sentence_source": "generated"}, {"text": "工事は来月終わる予定だったが、少し遅れている。", "target_word": "予定", "complexity_tier": "T3", "furigana": "工事[こうじ]は来月[らいげつ]終[お]わる予定[よてい]だったが、少[すこ]し遅[おく]れている。", "sentence_source": "generated"}, {"text": "来週の予定を確認してから、出張の日を決めた。", "target_word": "予定", "complexity_tier": "T3", "furigana": "来週[らいしゅう]の予定[よてい]を確認[かくにん]してから、出張[しゅっちょう]の日[ひ]を決[き]めた。", "sentence_source": "generated"}, {"text": "新しい店は、四月に開店する予定です。", "target_word": "予定", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]は、四月[しがつ]に開店[かいてん]する予定[よてい]です。", "sentence_source": "generated"}, {"text": "予定には、午前の打ち合わせと午後の会議が入っている。", "target_word": "予定", "complexity_tier": "T3", "furigana": "予定[よてい]には、午前[ごぜん]の打[う]ち合[あ]わせと午後[ごご]の会議[かいぎ]が入[はい]っている。", "sentence_source": "generated"}, {"text": "電車が遅れたせいで、予定が大きく狂った。", "target_word": "予定", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が遅[おく]れたせいで、予定[よてい]が大[おお]きく狂[くる]った。", "sentence_source": "generated"}, {"text": "社長の今月の予定は、すでにいっぱいだ。", "target_word": "予定", "complexity_tier": "T3", "furigana": "社長[しゃちょう]の今月[こんげつ]の予定[よてい]は、すでにいっぱいだ。", "sentence_source": "generated"}, {"text": "台風が近づいているため、予定を変更します。", "target_word": "予定", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいているため、予定[よてい]を変更[へんこう]します。", "sentence_source": "generated"}, {"text": "発表の予定を聞いて、準備を始めた。", "target_word": "予定", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の予定[よてい]を聞[き]いて、準備[じゅんび]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "工場は秋に完成する予定で、工事が進んでいる。", "target_word": "予定", "complexity_tier": "T3", "furigana": "工場[こうじょう]は秋[あき]に完成[かんせい]する予定[よてい]で、工事[こうじ]が進[すす]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "予定", "label": "基本形"}, {"form": "予定する", "label": "する動詞形"}], "register": "中立", "sense_fingerprint": "将来の行事や状態を計画すること、またその計画の中身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39267, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "予定", "is_correct": true, "explanation": "「会議の予定」は会議の日程や内容を指し、メールで知らせる対象として文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「会議の天気」は会議の日程や内容を指さず、メールで知らせる対象にならない。"}, {"text": "味", "is_correct": false, "explanation": "「会議の味」は会議を表す語句として成り立たず、お知らせする内容にならない。"}, {"text": "色", "is_correct": false, "explanation": "「会議の色」は会議の何を指すのか不明で、メールで知らせる内容として成り立たない。"}], "explanations": {"予定": "「会議の予定」は会議の日程や内容を指し、メールで知らせる対象として文に合う。", "天気": "「会議の天気」は会議の日程や内容を指さず、メールで知らせる対象にならない。", "味": "「会議の味」は会議を表す語句として成り立たず、お知らせする内容にならない。", "色": "「会議の色」は会議の何を指すのか不明で、メールで知らせる内容として成り立たない。"}, "sentence_index": 0, "correct_answer": "予定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の予定が、ぴたりと当たった。", "explanation": "ここは〈予言〉の意味。未来を言い当てる内容は予言と言い、予定が当たるとは言わないので合わない。"}, {"text": "予定のタイヤを、車に積んだ。", "explanation": "ここは〈予備〉の意味。いざという時に備えて持つ替えのタイヤは予備と言い、予定とは言わない。"}, {"text": "地震の予定に、家具を固定した。", "explanation": "ここは〈予防〉の意味。被害を防ぐための行為は予防で表し、計画の意味の予定は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39267, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "予定", "is_correct": true, "explanation": "「社長の今月の予定」は社長の行動計画を指し、「すでにいっぱいだ」という状態に合う。"}, {"text": "名刺", "is_correct": false, "explanation": "「名刺」は社長の今月の行動計画を指さず、「すでにいっぱいだ」という状態に合わない。"}, {"text": "傘", "is_correct": false, "explanation": "「社長の今月の傘」は計画を指さず、「すでにいっぱいだ」という状態に合わない。"}, {"text": "靴", "is_correct": false, "explanation": "靴は社長の行動計画を指さず、「すでにいっぱいだ」という状態を表せない。"}], "explanations": {"予定": "「社長の今月の予定」は社長の行動計画を指し、「すでにいっぱいだ」という状態に合う。", "名刺": "「名刺」は社長の今月の行動計画を指さず、「すでにいっぱいだ」という状態に合わない。", "傘": "「社長の今月の傘」は計画を指さず、「すでにいっぱいだ」という状態に合わない。", "靴": "靴は社長の行動計画を指さず、「すでにいっぱいだ」という状態を表せない。"}, "sentence_index": 6, "correct_answer": "予定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台風の予定が出た。", "explanation": "ここは〈予報〉の意味。台風の見通しを伝える情報は予報と言い、予定とは言わないので合わない。"}, {"text": "席の予定を取った。", "explanation": "ここは〈予約〉の意味。席を押さえる行為は予約と言い、予定は取るものではないので合わない。"}, {"text": "大きな地震が来る予定がした。", "explanation": "ここは〈予感〉の意味。ぼんやりした不安の気配は予感と言い、予定が「する」ものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
