INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39268, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「クラスの話し合い」と、名詞をつなぐ「の」。"}, {"text": "を", "is_correct": false, "explanation": "「クラスを話し合いは」は文法的に成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「クラスに話し合いは」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「クラスへ話し合いは」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「クラスの話し合い」と、名詞をつなぐ「の」。", "を": "「クラスを話し合いは」は文法的に成り立たない。", "に": "「クラスに話し合いは」は成り立たない。", "へ": "「クラスへ話し合いは」は成り立たない。"}, "error_tags": {"を": "object_marker", "に": "target_marker", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "追随", "is_correct": true, "explanation": "人の後に従う意味で、自分たちが中心の「主導」の反対。"}, {"text": "先導", "is_correct": false, "explanation": "先に立って導く意味で、類義語。"}, {"text": "主催", "is_correct": false, "explanation": "中心となって催す意味で、反対語ではない。"}, {"text": "実行", "is_correct": false, "explanation": "行う意味で、反対語ではない。"}], "correct_answer": "追随", "explanations": {"追随": "人の後に従う意味で、自分たちが中心の「主導」の反対。", "先導": "先に立って導く意味で、類義語。", "主催": "中心となって催す意味で、反対語ではない。", "実行": "行う意味で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
