INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39268, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを中心にして、自分たちで進めていくこと。", "primary_collocate": null, "pronunciation": "しゅどう", "ipa": "ɕɯdoː", "syllable_count": 3, "sentences": [{"text": "私たちが主導して進める。", "target_word": "主導", "complexity_tier": "T2", "furigana": "私[わたし]たちが主導[しゅどう]して進[すす]める。", "sentence_source": "generated"}, {"text": "クラスの話し合いは田中さんが主導した。", "target_word": "主導", "complexity_tier": "T3", "furigana": "クラスの話[はな]し合[あ]いは田中[たなか]さんが主導[しゅどう]した。", "sentence_source": "generated"}, {"text": "生徒が主導して、祭りを開いた。", "target_word": "主導", "complexity_tier": "T3", "furigana": "生徒[せいと]が主導[しゅどう]して、祭[まつ]りを開[ひら]いた。", "sentence_source": "generated"}, {"text": "自分たちで主導して、発表を準備した。", "target_word": "主導", "complexity_tier": "T3", "furigana": "自分[じぶん]たちで主導[しゅどう]して、発表[はっぴょう]を準備[じゅんび]した。", "sentence_source": "generated"}, {"text": "先生ではなく、子どもの主導で遊んだ。", "target_word": "主導", "complexity_tier": "T3", "furigana": "先生[せんせい]ではなく、子[こ]どもの主導[しゅどう]で遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "だれが主導するのか、まだ決まっていない。", "target_word": "主導", "complexity_tier": "T3", "furigana": "だれが主導[しゅどう]するのか、まだ決[き]まっていない。", "sentence_source": "generated"}, {"text": "この活動は地域の人が主導している。", "target_word": "主導", "complexity_tier": "T3", "furigana": "この活動[かつどう]は地域[ちいき]の人[ひと]が主導[しゅどう]している。", "sentence_source": "generated"}, {"text": "主導した人は、最後まで責任を持つべきだ。", "target_word": "主導", "complexity_tier": "T4", "furigana": "主導[しゅどう]した人[ひと]は、最後[さいご]まで責任[せきにん]を持[も]つべきだ。", "sentence_source": "generated"}, {"text": "彼の主導がなければ、成功しなかっただろう。", "target_word": "主導", "complexity_tier": "T4", "furigana": "彼[かれ]の主導[しゅどう]がなければ、成功[せいこう]しなかっただろう。", "sentence_source": "generated"}, {"text": "彼女は何でも自分が主導したがる。", "target_word": "主導", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は何[なん]でも自分[じぶん]が主導[しゅどう]したがる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主導する", "label": "活用"}, {"form": "主導した", "label": "活用"}, {"form": "主導権", "label": "派生"}, {"form": "主導者", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自分たちが中心で進めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39268, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主導", "is_correct": true, "explanation": "見出し語「しゅどう」そのもの。"}, {"text": "受動", "is_correct": false, "explanation": "「じゅどう」で、一音違いの別語。"}, {"text": "書道", "is_correct": false, "explanation": "「しょどう」で、一音違いの別語。"}, {"text": "主要", "is_correct": false, "explanation": "「しゅよう」で、一音違いの別語。"}, {"text": "種痘", "is_correct": false, "explanation": "「しゅとう」で、一音違いの別語。"}], "explanations": {"主導": "見出し語「しゅどう」そのもの。", "受動": "「じゅどう」で、一音違いの別語。", "書道": "「しょどう」で、一音違いの別語。", "主要": "「しゅよう」で、一音違いの別語。", "種痘": "「しゅとう」で、一音違いの別語。"}, "sentence_index": null, "correct_answer": "主導"}, "level_3": {"options": [{"text": "主導", "is_correct": true, "explanation": "自分たちが中心になって進めるという意味に合う。"}, {"text": "見学", "is_correct": false, "explanation": "形は合うが、「見学して進める」では意味が合わない。"}, {"text": "入浴", "is_correct": false, "explanation": "形は合うが、「入浴して進める」では意味が合わない。"}, {"text": "欠席", "is_correct": false, "explanation": "形は合うが、「欠席して進める」では意味が合わない。"}], "explanations": {"主導": "自分たちが中心になって進めるという意味に合う。", "見学": "形は合うが、「見学して進める」では意味が合わない。", "入浴": "形は合うが、「入浴して進める」では意味が合わない。", "欠席": "形は合うが、「欠席して進める」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "主導"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生に全部決めてもらって、私たちが主導して準備した。", "explanation": "全部決めてもらうのは自分たちが中心ではなく、「主導」と矛盾する。"}, {"text": "バスが遅れたので、主導して学校に着いた。", "explanation": "遅れた結果と「主導」は関係がなく、意味が合わない。"}, {"text": "彼の主導を聞いて、みんなが笑った。", "explanation": "「主導」は話や冗談の意味ではなく、聞くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
