INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39269, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「人がいない」の存在の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「人をいない」は文法的に成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「人でいない」は存在文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「人へいない」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「人がいない」の存在の主語を示す「が」。", "を": "「人をいない」は文法的に成り立たない。", "で": "「人でいない」は存在文として成り立たない。", "へ": "「人へいない」は成り立たない。"}, "error_tags": {"を": "object_marker", "で": "means", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "従属", "is_correct": true, "explanation": "他に従う意味で、中心となる「主導」の反対。"}, {"text": "主催", "is_correct": false, "explanation": "中心となって催す意味で、反対語ではない。"}, {"text": "率先", "is_correct": false, "explanation": "先に立って行う意味で、反対語ではない。"}, {"text": "指導", "is_correct": false, "explanation": "教え導く意味で、反対語ではない。"}], "correct_answer": "従属", "explanations": {"従属": "他に従う意味で、中心となる「主導」の反対。", "主催": "中心となって催す意味で、反対語ではない。", "率先": "先に立って行う意味で、反対語ではない。", "指導": "教え導く意味で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39269, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある物事を、中心となって引っ張っていく立場や役割。または、そのような立場で物事を動かすこと。", "primary_collocate": null, "pronunciation": "しゅどう", "ipa": "ɕɯdoː", "syllable_count": 3, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "主導", "complexity_tier": "T6", "furigana": "さらに、こうした非伝統的[ひでんとうてき]な金融[きんゆう]政策[せいさく]がインフレ期待[きたい]のアンカーとして機能[きのう]し得[う]る一方[いっぽう]で、過剰[かじょう]な流動性[りゅうどうせい]が実体[じったい]経済[けいざい]における物価[ぶっか]上昇[じょうしょう]圧力[あつりょく]と相乗[そうじょう]効果[こうか]を生[う]み、予期[よき]せぬスタグフレーションや財政[ざいせい]主導[しゅどう]のシナリオへと帰結[きけつ]するリスクを常[つね]に内包[ないほう]していることを、我々[われわれ]は冷徹[れいてつ]に認識[にんしき]する責務[せきむ]を負[お]っている。", "sentence_source": "mined"}, {"text": "国が計画を主導する。", "target_word": "主導", "complexity_tier": "T2", "furigana": "国[くに]が計画[けいかく]を主導[しゅどう]する。", "sentence_source": "generated"}, {"text": "彼が会議を主導した。", "target_word": "主導", "complexity_tier": "T2", "furigana": "彼[かれ]が会議[かいぎ]を主導[しゅどう]した。", "sentence_source": "generated"}, {"text": "新しい研究は大学が主導している。", "target_word": "主導", "complexity_tier": "T3", "furigana": "新[あたら]しい研究[けんきゅう]は大学[だいがく]が主導[しゅどう]している。", "sentence_source": "generated"}, {"text": "市民の主導で公園が作られた。", "target_word": "主導", "complexity_tier": "T4", "furigana": "市民[しみん]の主導[しゅどう]で公園[こうえん]が作[つく]られた。", "sentence_source": "generated"}, {"text": "彼女は改革を主導する立場にある。", "target_word": "主導", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は改革[かいかく]を主導[しゅどう]する立場[たちば]にある。", "sentence_source": "generated"}, {"text": "この事業は民間の主導で進められた。", "target_word": "主導", "complexity_tier": "T4", "furigana": "この事業[じぎょう]は民間[みんかん]の主導[しゅどう]で進[すす]められた。", "sentence_source": "generated"}, {"text": "主導する人がいないと、話がまとまらない。", "target_word": "主導", "complexity_tier": "T4", "furigana": "主導[しゅどう]する人[ひと]がいないと、話[はなし]がまとまらない。", "sentence_source": "generated"}, {"text": "日本が主導して、新しい協定がつくられた。", "target_word": "主導", "complexity_tier": "T4", "furigana": "日本[にほん]が主導[しゅどう]して、新[あたら]しい協定[きょうてい]がつくられた。", "sentence_source": "generated"}, {"text": "首相の主導により、法律が改正された。", "target_word": "主導", "complexity_tier": "T4", "furigana": "首相[しゅしょう]の主導[しゅどう]により、法律[ほうりつ]が改正[かいせい]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主導する", "label": "活用"}, {"form": "主導した", "label": "活用"}, {"form": "主導権", "label": "派生"}, {"form": "主導的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 中心となって物事を引っ張ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: スタグフレーション (Zipf 1.93)']::text[], '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39269, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主導", "is_correct": true, "explanation": "見出し語「しゅどう」そのもの。"}, {"text": "受動", "is_correct": false, "explanation": "「じゅどう」で、「しゅ」が「じゅ」に変わる一音違いの別語。"}, {"text": "書道", "is_correct": false, "explanation": "「しょどう」で、「しゅ」が「しょ」に変わる一音違いの別語。"}, {"text": "主要", "is_correct": false, "explanation": "「しゅよう」で、「ど」が「よ」に変わる一音違いの別語。"}, {"text": "種痘", "is_correct": false, "explanation": "「しゅとう」で、「ど」が「と」に変わる一音違いの別語。"}], "explanations": {"主導": "見出し語「しゅどう」そのもの。", "受動": "「じゅどう」で、「しゅ」が「じゅ」に変わる一音違いの別語。", "書道": "「しょどう」で、「しゅ」が「しょ」に変わる一音違いの別語。", "主要": "「しゅよう」で、「ど」が「よ」に変わる一音違いの別語。", "種痘": "「しゅとう」で、「ど」が「と」に変わる一音違いの別語。"}, "sentence_index": null, "correct_answer": "主導"}, "level_3": {"options": [{"text": "主導", "is_correct": true, "explanation": "「財政主導のシナリオ」で、財政が中心となる意味に合う。"}, {"text": "開催", "is_correct": false, "explanation": "形は合うが、「財政開催のシナリオ」では意味が合わない。"}, {"text": "郵送", "is_correct": false, "explanation": "形は合うが、「財政郵送のシナリオ」では意味が合わない。"}, {"text": "登山", "is_correct": false, "explanation": "形は合うが、「財政登山のシナリオ」では意味が合わない。"}], "explanations": {"主導": "「財政主導のシナリオ」で、財政が中心となる意味に合う。", "開催": "形は合うが、「財政開催のシナリオ」では意味が合わない。", "郵送": "形は合うが、「財政郵送のシナリオ」では意味が合わない。", "登山": "形は合うが、「財政登山のシナリオ」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "主導"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は昼ごはんに主導を食べた。", "explanation": "「主導」は食べ物ではなく、中心となって引っ張ることを表す語。"}, {"text": "リーダーが全員に任せきりで、プロジェクトを強く主導している。", "explanation": "任せきりでは中心になって引っ張ることにならず、「主導」と矛盾する。"}, {"text": "彼女は先生の指示に従うだけで、行事を主導した。", "explanation": "指示に従うだけでは「主導」ではなく、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39269, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主導", "is_correct": true, "explanation": "見出し語「しゅどう」そのもの。"}, {"text": "趣向", "is_correct": false, "explanation": "「しゅこう」で、「ど」が「こ」に変わる一音違いの別語。"}, {"text": "酒造", "is_correct": false, "explanation": "「しゅぞう」で、「ど」が「ぞ」に変わる一音違いの別語。"}, {"text": "手法", "is_correct": false, "explanation": "「しゅほう」で、「ど」が「ほ」に変わる一音違いの別語。"}], "explanations": {"主導": "見出し語「しゅどう」そのもの。", "趣向": "「しゅこう」で、「ど」が「こ」に変わる一音違いの別語。", "酒造": "「しゅぞう」で、「ど」が「ぞ」に変わる一音違いの別語。", "手法": "「しゅほう」で、「ど」が「ほ」に変わる一音違いの別語。"}, "sentence_index": null, "correct_answer": "主導"}, "level_3": {"options": [{"text": "主導", "is_correct": true, "explanation": "民間が中心となって事業を進めたという意味に合う。"}, {"text": "欠席", "is_correct": false, "explanation": "形は合うが、「民間の欠席で進められた」では意味が合わない。"}, {"text": "入浴", "is_correct": false, "explanation": "形は合うが、「民間の入浴で進められた」では意味が合わない。"}, {"text": "反省", "is_correct": false, "explanation": "形は合うが、「民間の反省で進められた」では意味が合わない。"}], "explanations": {"主導": "民間が中心となって事業を進めたという意味に合う。", "欠席": "形は合うが、「民間の欠席で進められた」では意味が合わない。", "入浴": "形は合うが、「民間の入浴で進められた」では意味が合わない。", "反省": "形は合うが、「民間の反省で進められた」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "主導"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が降ったので、遠足は主導になった。", "explanation": "「主導」は中止の意味ではなく、遠足が主導になるのは意味が合わない。"}, {"text": "他国に任せきりで、わが国は交渉を主導した。", "explanation": "任せきりでは中心になって引っ張ることにならず、「主導」と矛盾する。"}, {"text": "毎日主導を飲むと体にいい。", "explanation": "「主導」は飲み物ではなく、物事を引っ張る立場や役割を表す語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED