INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39269, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼が会議を主導にした。", "corrected_sentence": "彼が会議を主導した。", "error_description": "「主導する」の過去形は「主導した」で、「主導にした」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39270, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "が", "is_correct": false, "explanation": "主語を示す「が」になり、「緑化には」の文の形と合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」になり、「かかる」の文の主題と合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は「は」と続けると文として成立しない。"}, {"text": "に", "is_correct": true, "explanation": "正解。「緑化には」の「に」で、主題を示している。"}], "correct_answer": "に", "explanations": {"が": "主語を示す「が」になり、「緑化には」の文の形と合わない。", "を": "目的語を示す「を」になり、「かかる」の文の主題と合わない。", "の": "「の」は「は」と続けると文として成立しない。", "に": "正解。「緑化には」の「に」で、主題を示している。"}, "error_tags": {"が": "主語", "を": "対象", "の": "連体修飾", "に": "主題"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "砂漠化", "is_correct": true, "explanation": "正解。木や草を増やす緑化の反対で、土地が荒れて砂漠になる過程を指す。"}, {"text": "美化", "is_correct": false, "explanation": "美しくすることで、緑を失う過程の反対語ではない。"}, {"text": "清掃", "is_correct": false, "explanation": "きれいにする行為で、緑化の対義語ではない。"}, {"text": "舗装", "is_correct": false, "explanation": "道路を固める工事で、緑を減らす意味の反対語ではない。"}], "correct_answer": "砂漠化", "explanations": {"砂漠化": "正解。木や草を増やす緑化の反対で、土地が荒れて砂漠になる過程を指す。", "美化": "美しくすることで、緑を失う過程の反対語ではない。", "清掃": "きれいにする行為で、緑化の対義語ではない。", "舗装": "道路を固める工事で、緑を減らす意味の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39270, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「緑化の第一歩」の「の」で、名詞どうしを結んでいる。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、「緑化と第一歩」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「緑化から第一歩」は不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「緑化より第一歩」は意味が合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「緑化の第一歩」の「の」で、名詞どうしを結んでいる。", "と": "並列や相手を示すが、「緑化と第一歩」では意味が通らない。", "から": "起点を示すが、「緑化から第一歩」は不自然になる。", "より": "比較を示すが、「緑化より第一歩」は意味が合わない。"}, "error_tags": {"と": "並列・相手", "から": "起点", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "砂漠化", "is_correct": true, "explanation": "正解。緑化の反対で、緑が失われ土地が砂漠になる過程を指す。"}, {"text": "建築", "is_correct": false, "explanation": "建物を造ることで、緑を失う過程の反対語ではない。"}, {"text": "製造", "is_correct": false, "explanation": "物を作ることで、緑化の対義語ではない。"}, {"text": "設置", "is_correct": false, "explanation": "備え付けることで、緑を減らす意味の反対語ではない。"}], "correct_answer": "砂漠化", "explanations": {"砂漠化": "正解。緑化の反対で、緑が失われ土地が砂漠になる過程を指す。", "建築": "建物を造ることで、緑を失う過程の反対語ではない。", "製造": "物を作ることで、緑化の対義語ではない。", "設置": "備え付けることで、緑を減らす意味の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39270, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "木や草を植えて、町や山を緑（みどり）でいっぱいにすること。", "primary_collocate": null, "pronunciation": "りょっか", "ipa": "ɾʲokka", "syllable_count": 3, "sentences": [{"text": "市は駅前の道に木を植えて、緑化を進めている。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "市[し]は駅前[えきまえ]の道[みち]に木[き]を植[う]えて、緑化[りょっか]を進[すす]めている。", "sentence_source": "generated"}, {"text": "はげ山の緑化には、何十年もかかる。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "はげ山[やま]の緑化[りょっか]には、何十年[なんじゅうねん]もかかる。", "sentence_source": "generated"}, {"text": "学校の運動場のまわりを緑化するために、生徒が苗を植えた。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "学校[がっこう]の運動場[うんどうじょう]のまわりを緑化[りょっか]するために、生徒[せいと]が苗[なえ]を植[う]えた。", "sentence_source": "generated"}, {"text": "砂漠の緑化に取り組む団体が、苗木を送っている。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "砂漠[さばく]の緑化[りょっか]に取[と]り組[く]む団体[だんたい]が、苗木[なえぎ]を送[おく]っている。", "sentence_source": "generated"}, {"text": "町の緑化が進み、夏でも散歩が楽しくなった。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "町[まち]の緑化[りょっか]が進[すす]み、夏[なつ]でも散歩[さんぽ]が楽[たの]しくなった。", "sentence_source": "generated"}, {"text": "山火事のあとの緑化計画に、地域の人が参加した。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "山火事[やまかじ]のあとの緑化[りょっか]計画[けいかく]に、地域[ちいき]の人[ひと]が参加[さんか]した。", "sentence_source": "generated"}, {"text": "緑化のおかげで、ごみだらけだった川原がきれいな公園に変わった。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "緑化[りょっか]のおかげで、ごみだらけだった川原[かわら]がきれいな公園[こうえん]に変[か]わった。", "sentence_source": "generated"}, {"text": "緑化の第一歩として、まず空き地に草の種をまいた。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "緑化[りょっか]の第一歩[だいいっぽ]として、まず空[あ]き地[ち]に草[くさ]の種[たね]をまいた。", "sentence_source": "generated"}, {"text": "先生は緑化の大切さを、子どもたちに話した。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "先生[せんせい]は緑化[りょっか]の大切[たいせつ]さを、子[こ]どもたちに話[はな]した。", "sentence_source": "generated"}, {"text": "緑化にはお金がかかるが、町の人たちは協力してくれた。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "緑化[りょっか]にはお金[かね]がかかるが、町[まち]の人[ひと]たちは協力[きょうりょく]してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緑化", "label": "基本形"}, {"form": "緑化する", "label": "サ変動詞形"}, {"form": "緑化した", "label": "過去形"}], "register": "標準", "sense_fingerprint": "緑化=木や草を植えて、町・山・荒れ地を緑でいっぱいにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39270, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緑化", "is_correct": true, "explanation": "正解。木を植えて町を緑にする取り組みを指し、「進めている」と合う。"}, {"text": "散歩", "is_correct": false, "explanation": "歩く行為を表し、「進めている」の対象にはならない。"}, {"text": "遠足", "is_correct": false, "explanation": "学校の行事を表し、道に木を植える文脈と合わない。"}, {"text": "夕食", "is_correct": false, "explanation": "食事を表し、「進めている」の対象として不自然になる。"}], "explanations": {"緑化": "正解。木を植えて町を緑にする取り組みを指し、「進めている」と合う。", "散歩": "歩く行為を表し、「進めている」の対象にはならない。", "遠足": "学校の行事を表し、道に木を植える文脈と合わない。", "夕食": "食事を表し、「進めている」の対象として不自然になる。"}, "sentence_index": 0, "correct_answer": "緑化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏になって、山の緑化が濃くなった。", "explanation": "緑化は町や山を緑にする取り組みで、山の色の濃さを言う語ではない。"}, {"text": "鉢植えの植物を毎朝緑化している。", "explanation": "緑化は場所を緑にする取り組みで、鉢植えの世話には使わない。"}, {"text": "畑で野菜を緑化して、毎年収穫している。", "explanation": "緑化は地面を緑で覆う取り組みで、野菜の栽培には言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39270, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緑化", "is_correct": true, "explanation": "正解。緑化によって川原が公園になったという文脈に合う。"}, {"text": "卒業", "is_correct": false, "explanation": "学校を終える意味で、川原を公園に変える文脈と合わない。"}, {"text": "誕生日", "is_correct": false, "explanation": "日付や祝いを表し、川原の変化の原因にはならない。"}, {"text": "読書", "is_correct": false, "explanation": "本を読む行為で、川原の変化の原因として不自然になる。"}], "explanations": {"緑化": "正解。緑化によって川原が公園になったという文脈に合う。", "卒業": "学校を終える意味で、川原を公園に変える文脈と合わない。", "誕生日": "日付や祝いを表し、川原の変化の原因にはならない。", "読書": "本を読む行為で、川原の変化の原因として不自然になる。"}, "sentence_index": 6, "correct_answer": "緑化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい机を緑化して、教室に運んだ。", "explanation": "緑化は町や山を植物で緑にする取り組みで、机を対象にすることはできない。"}, {"text": "緑化して、部屋の床をきれいにした。", "explanation": "緑化は植物で地面を覆う取り組みで、床の掃除には使わない。"}, {"text": "庭に緑化を張って、子どもが遊べるようにした。", "explanation": "緑化は取り組みを指す語で、庭に張る草地の材料にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39270, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の空き地に花を植えて、緑化に広げている。", "corrected_sentence": "町の空き地に花を植えて、緑化を広げている。", "error_description": "誤: 緑化に（助詞「に」）／正: 緑化を（助詞「を」）。「広げる」の目的語なので「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39270, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は屋上の緑化に取り返すため、補助金を出すことにした。", "corrected_sentence": "市は屋上の緑化に取り組むため、補助金を出すことにした。", "error_description": "誤: 取り返す（「取り戻す」の意味で、緑化には結びつかない）／正: 取り組む（「緑化に取り組む」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39271, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「駐車場を緑化して」の「を」で、緑化する対象を示している。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す「に」になり、「駐車場に緑化して」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、緑化の対象を示す文に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、緑化の対象を示す文に合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「駐車場を緑化して」の「を」で、緑化する対象を示している。", "に": "位置や相手を示す「に」になり、「駐車場に緑化して」は不自然。", "へ": "方向を示す「へ」は、緑化の対象を示す文に合わない。", "から": "起点を示す「から」は、緑化の対象を示す文に合わない。"}, "error_tags": {"を": "対象", "に": "位置・相手", "へ": "方向", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "砂漠化", "is_correct": true, "explanation": "正解。緑化の反対で、緑が失われ土地が荒れていく過程を指す。"}, {"text": "舗装", "is_correct": false, "explanation": "道路を固める工事で、緑化の対義語ではない。"}, {"text": "撤去", "is_correct": false, "explanation": "取り除く行為で、緑を減らす意味の反対語ではない。"}, {"text": "施工", "is_correct": false, "explanation": "工事を行うことで、緑化の対義語ではない。"}], "correct_answer": "砂漠化", "explanations": {"砂漠化": "正解。緑化の反対で、緑が失われ土地が荒れていく過程を指す。", "舗装": "道路を固める工事で、緑化の対義語ではない。", "撤去": "取り除く行為で、緑を減らす意味の反対語ではない。", "施工": "工事を行うことで、緑化の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39271, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「緑化には」の「に」で、主題を示している。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す「と」では、「屋上の緑化と、重さに耐える」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は「は」と続けると文として成立しない。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す「を」になり、「緑化を、重さに耐える」は不自然になる。"}], "correct_answer": "に", "explanations": {"に": "正解。「緑化には」の「に」で、主題を示している。", "と": "並列を示す「と」では、「屋上の緑化と、重さに耐える」は意味が通らない。", "の": "「の」は「は」と続けると文として成立しない。", "を": "対象を示す「を」になり、「緑化を、重さに耐える」は不自然になる。"}, "error_tags": {"と": "並列", "の": "連体修飾", "を": "対象", "に": "主題"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "砂漠化", "is_correct": true, "explanation": "正解。緑化の反対で、緑が失われ土地が砂漠になる過程を指す。"}, {"text": "建築", "is_correct": false, "explanation": "建物を造ることで、緑化の対義語ではない。"}, {"text": "設置", "is_correct": false, "explanation": "備え付けることで、緑を減らす意味の反対語ではない。"}, {"text": "改修", "is_correct": false, "explanation": "直して使えるようにすることで、緑化の対義語ではない。"}], "correct_answer": "砂漠化", "explanations": {"砂漠化": "正解。緑化の反対で、緑が失われ土地が砂漠になる過程を指す。", "建築": "建物を造ることで、緑化の対義語ではない。", "設置": "備え付けることで、緑を減らす意味の反対語ではない。", "改修": "直して使えるようにすることで、緑化の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39271, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "植物を植えたり育てたりして、地面を緑色で覆うこと。環境改善や景観向上のために行われる。", "primary_collocate": null, "pronunciation": "りょっか", "ipa": "ɾʲokka", "syllable_count": 3, "sentences": [{"text": "ビルの屋上を緑化すると、夏の室内の温度が下がる。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "ビルの屋上[おくじょう]を緑化[りょっか]すると、夏[なつ]の室内[しつない]の温度[おんど]が下[さ]がる。", "sentence_source": "generated"}, {"text": "公共の駐車場を緑化して、景観を良くする計画だ。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "公共[こうきょう]の駐車場[ちゅうしゃじょう]を緑化[りょっか]して、景観[けいかん]を良[よ]くする計画[けいかく]だ。", "sentence_source": "generated"}, {"text": "都市の緑化は、空気をきれいにする効果もある。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "都市[とし]の緑化[りょっか]は、空気[くうき]をきれいにする効果[こうか]もある。", "sentence_source": "generated"}, {"text": "壁面の緑化には、つる植物がよく使われる。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "壁面[へきめん]の緑化[りょっか]には、つる植物[しょくぶつ]がよく使[つか]われる。", "sentence_source": "generated"}, {"text": "会社は工場の敷地を緑化し、周辺の景色に調和させた。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は工場[こうじょう]の敷地[しきち]を緑化[りょっか]し、周辺[しゅうへん]の景色[けしき]に調和[ちょうわ]させた。", "sentence_source": "generated"}, {"text": "緑化によって、ヒートアイランド現象をやわらげたい。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "緑化[りょっか]によって、ヒートアイランド現象[げんしょう]をやわらげたい。", "sentence_source": "generated"}, {"text": "道路のわきを緑化した結果、街並みが明るくなった。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "道路[どうろ]のわきを緑化[りょっか]した結果[けっか]、街並[まちな]みが明[あか]るくなった。", "sentence_source": "generated"}, {"text": "屋上の緑化には、重さに耐える建物の構造が必要だ。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "屋上[おくじょう]の緑化[りょっか]には、重[おも]さに耐[た]える建物[たてもの]の構造[こうぞう]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "市は、緑化を条件に新しいビルの建築を許可した。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "市[し]は、緑化[りょっか]を条件[じょうけん]に新[あたら]しいビルの建築[けんちく]を許可[きょか]した。", "sentence_source": "generated"}, {"text": "線路沿いを緑化して、騒音と見た目の両方を改善した。", "target_word": "緑化", "complexity_tier": "T3", "furigana": "線路沿[せんろぞ]いを緑化[りょっか]して、騒音[そうおん]と見[み]た目[め]の両方[りょうほう]を改善[かいぜん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緑化", "label": "基本形"}, {"form": "緑化する", "label": "サ変動詞形"}, {"form": "緑化した", "label": "過去形"}], "register": "やや硬め（都市計画・環境）", "sense_fingerprint": "緑化=屋上・壁面・敷地などを植物で覆い、環境や景観を良くする取り組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39271, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緑化", "is_correct": true, "explanation": "正解。屋上を緑で覆うと室内の温度が下がるという文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "歩く行為で、屋上を対象にすると温度が下がる理由にならない。"}, {"text": "読書", "is_correct": false, "explanation": "本を読む行為で、室内の温度を下げる理由として成り立たない。"}, {"text": "配達", "is_correct": false, "explanation": "物を届ける行為で、屋上の温度変化の原因にならない。"}], "explanations": {"緑化": "正解。屋上を緑で覆うと室内の温度が下がるという文脈に合う。", "散歩": "歩く行為で、屋上を対象にすると温度が下がる理由にならない。", "読書": "本を読む行為で、室内の温度を下げる理由として成り立たない。", "配達": "物を届ける行為で、屋上の温度変化の原因にならない。"}, "sentence_index": 0, "correct_answer": "緑化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "緑化を家の前に並べて、道を華やかにした。", "explanation": "緑化は屋上や壁面を植物で覆う取り組みで、家の前に並べる植木を指すことはできない。"}, {"text": "壁の緑化が濃くなり、夏は涼しく感じる。", "explanation": "緑化は植物で覆う取り組みで、壁の色の濃さには使えない。"}, {"text": "夏に肌が緑化して、少し赤くなった。", "explanation": "緑化は植物で覆う取り組みで、肌の変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39271, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緑化", "is_correct": true, "explanation": "正解。道路のわきを緑化した結果、街並みが明るくなったという文脈に合う。"}, {"text": "誕生日", "is_correct": false, "explanation": "祝いの日を表し、街並みが明るくなる原因にならない。"}, {"text": "手紙", "is_correct": false, "explanation": "書いた文章を表し、道路の景観を変える行為として成り立たない。"}, {"text": "遠足", "is_correct": false, "explanation": "学校の行事で、道路のわきを変える行為として不自然になる。"}], "explanations": {"緑化": "正解。道路のわきを緑化した結果、街並みが明るくなったという文脈に合う。", "誕生日": "祝いの日を表し、街並みが明るくなる原因にならない。", "手紙": "書いた文章を表し、道路の景観を変える行為として成り立たない。", "遠足": "学校の行事で、道路のわきを変える行為として不自然になる。"}, "sentence_index": 6, "correct_answer": "緑化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "緑化して、木の机を白く塗った。", "explanation": "緑化は植物で覆う取り組みで、家具の塗り替えには使わない。"}, {"text": "緑化をつけて、暗い部屋を明るくした。", "explanation": "緑化は植物で覆う取り組みで、照明には使わない。"}, {"text": "新しい電線を緑化した。", "explanation": "緑化は植物で覆う取り組みで、電線の作業には言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39271, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "マンションの屋上を緑化に、見晴らしを良くしたい。", "corrected_sentence": "マンションの屋上を緑化して、見晴らしを良くしたい。", "error_description": "誤: 緑化に（「緑化」は名詞で、「に」だけでは述語にならない）／正: 緑化して（「緑化する」の連用形）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39271, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場の屋上を緑化されて、騒音が減った。", "corrected_sentence": "工場の屋上が緑化されて、騒音が減った。", "error_description": "誤: 屋上を（助詞「を」）／正: 屋上が（助詞「が」）。受け身の主語は「が」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39272, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「編成が新しくなる」の主語は「が」で示すので、正しく続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、「新しくなる」は対象を取らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、「新しくなる」の主語にはできない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は一緒にする相手を示すので、「新しくなる」の主語としては成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「編成が新しくなる」の主語は「が」で示すので、正しく続く。", "を": "「を」は動作の対象を示すが、「新しくなる」は対象を取らないので合わない。", "の": "「の」は名詞どうしをつなぐ助詞で、「新しくなる」の主語にはできない。", "と": "「と」は一緒にする相手を示すので、「新しくなる」の主語としては成り立たない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "共同", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39272, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39272, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の組み合わせを変えて、新しいものに作り直すこと。", "primary_collocate": null, "pronunciation": "へんせい", "ipa": "heŋseː", "syllable_count": 4, "sentences": [{"text": "試合に負けたので、監督はチームの編成を変えました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けたので、監督[かんとく]はチームの編成[へんせい]を変[か]えました。", "sentence_source": "generated"}, {"text": "来月から、会社の班の編成が新しくなります。", "target_word": "編成", "complexity_tier": "T3", "furigana": "来月[らいげつ]から、会社[かいしゃ]の班[はん]の編成[へんせい]が新[あたら]しくなります。", "sentence_source": "generated"}, {"text": "時間割の編成を考え直して、授業の数を減らしました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "時間割[じかんわり]の編成[へんせい]を考[かんが]え直[なお]して、授業[じゅぎょう]の数[かず]を減[へ]らしました。", "sentence_source": "generated"}, {"text": "新しい編成になってから、クラスの雰囲気が明るくなりました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "新[あたら]しい編成[へんせい]になってから、クラスの雰囲気[ふんいき]が明[あか]るくなりました。", "sentence_source": "generated"}, {"text": "番組の編成を見直したので、夜のニュースが長くなりました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "番組[ばんぐみ]の編成[へんせい]を見直[みなお]したので、夜[よる]のニュースが長[なが]くなりました。", "sentence_source": "generated"}, {"text": "人数が減ったため、グループを編成し直しました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "人数[にんずう]が減[へ]ったため、グループを編成[へんせい]し直[なお]しました。", "sentence_source": "generated"}, {"text": "部隊の編成は、春に大きく変わりました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "部隊[ぶたい]の編成[へんせい]は、春[はる]に大[おお]きく変[か]わりました。", "sentence_source": "generated"}, {"text": "先生は生徒の意見を聞いて、班の編成を決めました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の意見[いけん]を聞[き]いて、班[はん]の編成[へんせい]を決[き]めました。", "sentence_source": "generated"}, {"text": "オーケストラの編成を小さくして、小さな部屋でも演奏できるようにしました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "オーケストラの編成[へんせい]を小[ちい]さくして、小[ちい]さな部屋[へや]でも演奏[えんそう]できるようにしました。", "sentence_source": "generated"}, {"text": "新しい編成で試合に出ることになりました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "新[あたら]しい編成[へんせい]で試合[しあい]に出[で]ることになりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "編成", "label": "基本形"}, {"form": "編成する", "label": "サ変動詞（辞書形）"}, {"form": "編成し直す", "label": "複合動詞（辞書形）"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "メンバーや項目の組み合わせを変えて、新しい形に組み直すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39272, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "編成", "is_correct": true, "explanation": "メンバーの組み合わせを変えることを指すので、「チームの〜を変えました」と合い、空欄に入る。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、チームのものとして変える対象にはならない。"}, {"text": "季節", "is_correct": false, "explanation": "一年の時期を表す語で、チームの一部として変えることはできない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語で、チームの組み合わせを変える文には入らない。"}], "explanations": {"編成": "メンバーの組み合わせを変えることを指すので、「チームの〜を変えました」と合い、空欄に入る。", "天気": "空模様を表す語で、チームのものとして変える対象にはならない。", "季節": "一年の時期を表す語で、チームの一部として変えることはできない。", "体重": "体の重さを表す語で、チームの組み合わせを変える文には入らない。"}, "sentence_index": 0, "correct_answer": "編成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い時計を、ねじを外して編成しました。", "explanation": "ここは〈分解〉の意味。編成は人やチーム、番組などを組み直すことで、ねじを外して機械をばらす行為には使わない。"}, {"text": "この映像は、編成で長さを短くしました。", "explanation": "ここは〈編集〉の意味。映像の長さを切ったり並べたりすることで、メンバーの組み合わせを変える編成とは意味が違う。"}, {"text": "レジで、買った品物の代金を編成しました。", "explanation": "ここは〈計算〉の意味。編成は人や要素を組み直すことで、代金を数えて足す計算には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39272, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "編成", "is_correct": true, "explanation": "部隊の組み合わせを指すので、「部隊の〜は、春に大きく変わりました」と合い、空欄に入る。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の性質を表す語で、部隊の組み合わせを述べる文には入らない。"}, {"text": "値段", "is_correct": false, "explanation": "売買の価格を表す語で、部隊には当てはまらないので入らない。"}, {"text": "香り", "is_correct": false, "explanation": "においを表す語で、部隊の構成が春に変わるという文には合わない。"}], "explanations": {"編成": "部隊の組み合わせを指すので、「部隊の〜は、春に大きく変わりました」と合い、空欄に入る。", "味": "食べ物の性質を表す語で、部隊の組み合わせを述べる文には入らない。", "値段": "売買の価格を表す語で、部隊には当てはまらないので入らない。", "香り": "においを表す語で、部隊の構成が春に変わるという文には合わない。"}, "sentence_index": 6, "correct_answer": "編成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家具を、説明書を見て編成しました。", "explanation": "ここは〈組み立て〉の意味。部品をつないで形にすることで、人や要素の組み合わせを変える編成とは意味が違う。"}, {"text": "プレゼントを、きれいな紙で編成しました。", "explanation": "ここは〈包装〉の意味。物を紙で包むことで、メンバーや項目の組み合わせを変える編成とは全く違う。"}, {"text": "夕食の料理は、野菜を一つずつ切って編成しました。", "explanation": "ここは〈調理〉の意味。食材を切って料理を作ることで、要素を組み直す編成は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39272, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋になると、班の編成が変えました。", "corrected_sentence": "秋になると、班の編成を変えました。", "error_description": "「変える」は変える対象を「を」で示す。「班の編成が」は「班の編成を」の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39272, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい編成を、夏の大会に出ることになりました。", "corrected_sentence": "新しい編成で、夏の大会に出ることになりました。", "error_description": "「編成で」は手段や形態を示す「で」。「編成を」は「編成で」の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39273, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に作り直す」は結果の状態を「に」で示すので、「新しい編成に作り直す」と正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「作り直す」の結果を表すことはできない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は一緒にするものを示すので、結果の状態を述べる文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、「作り直す」の対象を直接示せない。"}], "correct_answer": "に", "explanations": {"に": "「〜に作り直す」は結果の状態を「に」で示すので、「新しい編成に作り直す」と正しく続く。", "が": "「が」は主語を示すが、「作り直す」の結果を表すことはできない。", "と": "「と」は一緒にするものを示すので、結果の状態を述べる文には合わない。", "の": "「の」は名詞どうしをつなぐ助詞で、「作り直す」の対象を直接示せない。"}, "error_tags": {"が": "主語", "と": "共同", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39273, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「役所の編成」は名詞を「の」でつなぐ連体修飾で、自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "「役所が編成」は名詞どうしを主語と述語のように続けることになり、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「役所に編成」は名詞どうしを結ぶ形にならず、文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「役所を編成」は目的語の形だが、続く「が変わった」と合わず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「役所の編成」は名詞を「の」でつなぐ連体修飾で、自然な文になる。", "が": "「役所が編成」は名詞どうしを主語と述語のように続けることになり、不自然。", "に": "「役所に編成」は名詞どうしを結ぶ形にならず、文として成り立たない。", "を": "「役所を編成」は目的語の形だが、続く「が変わった」と合わず、文が成り立たない。"}, "error_tags": {"が": "主語", "に": "位置", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39273, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の要素や部分を組み合わせて、全体の構造や組織を新しく作り直すこと。特に、社会や組織の仕組みを変えることを指す。", "primary_collocate": null, "pronunciation": "へんせい", "ipa": "heŋseː", "syllable_count": 4, "sentences": [{"text": "戦争のあと、国の政治の仕組みが新しく編成されました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "戦争[せんそう]のあと、国[くに]の政治[せいじ]の仕組[しく]みが新[あたら]しく編成[へんせい]されました。", "sentence_source": "generated"}, {"text": "会社は古い組織を、部門ごとの新しい編成に作り直しました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は古[ふる]い組織[そしき]を、部門[ぶもん]ごとの新[あたら]しい編成[へんせい]に作[つく]り直[なお]しました。", "sentence_source": "generated"}, {"text": "市は人口が減ったため、地域の編成を見直すことを決めました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "市[し]は人口[じんこう]が減[へ]ったため、地域[ちいき]の編成[へんせい]を見直[みなお]すことを決[き]めました。", "sentence_source": "generated"}, {"text": "社会の編成が変わると、人々の暮らしも大きく変わります。", "target_word": "編成", "complexity_tier": "T3", "furigana": "社会[しゃかい]の編成[へんせい]が変[か]わると、人々[ひとびと]の暮[く]らしも大[おお]きく変[か]わります。", "sentence_source": "generated"}, {"text": "大きな会社は、時代に合わせて組織の編成を変えていきます。", "target_word": "編成", "complexity_tier": "T3", "furigana": "大[おお]きな会社[かいしゃ]は、時代[じだい]に合[あ]わせて組織[そしき]の編成[へんせい]を変[か]えていきます。", "sentence_source": "generated"}, {"text": "新しい編成になって、課の数が十から六に減りました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "新[あたら]しい編成[へんせい]になって、課[か]の数[かず]が十[じゅう]から六[ろく]に減[へ]りました。", "sentence_source": "generated"}, {"text": "古い身分制度をなくし、社会全体の編成をやり直しました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "古[ふる]い身分制度[みぶんせいど]をなくし、社会全体[しゃかいぜんたい]の編成[へんせい]をやり直[なお]しました。", "sentence_source": "generated"}, {"text": "役所の編成が変わったので、手続きの窓口も変わりました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "役所[やくしょ]の編成[へんせい]が変[か]わったので、手続[てつづ]きの窓口[まどぐち]も変[か]わりました。", "sentence_source": "generated"}, {"text": "国の編成を変えるには、長い時間と多くの話し合いが必要です。", "target_word": "編成", "complexity_tier": "T3", "furigana": "国[くに]の編成[へんせい]を変[か]えるには、長[なが]い時間[じかん]と多[おお]くの話[はな]し合[あ]いが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "組織の編成を新しくしたことで、仕事の流れがわかりやすくなりました。", "target_word": "編成", "complexity_tier": "T3", "furigana": "組織[そしき]の編成[へんせい]を新[あたら]しくしたことで、仕事[しごと]の流[なが]れがわかりやすくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "編成", "label": "基本形"}, {"form": "編成する", "label": "サ変動詞（辞書形）"}, {"form": "編成された", "label": "受身の過去形"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "社会や組織の仕組み全体を新しく作り直すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39273, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "編成", "is_correct": true, "explanation": "国や社会の仕組みを組み直すことを指すので、「新しく〜されました」と合い、空欄に入る。"}, {"text": "消費", "is_correct": false, "explanation": "物やお金を使い切ることを表す語で、仕組みを組み直す文では成り立たない。"}, {"text": "合計", "is_correct": false, "explanation": "数を足すことを表す語で、政治の仕組みに対して「新しく合計される」とはならない。"}, {"text": "変色", "is_correct": false, "explanation": "色が変わることを表す語で、国の仕組みの変化を述べる文には入らない。"}], "explanations": {"編成": "国や社会の仕組みを組み直すことを指すので、「新しく〜されました」と合い、空欄に入る。", "消費": "物やお金を使い切ることを表す語で、仕組みを組み直す文では成り立たない。", "合計": "数を足すことを表す語で、政治の仕組みに対して「新しく合計される」とはならない。", "変色": "色が変わることを表す語で、国の仕組みの変化を述べる文には入らない。"}, "sentence_index": 0, "correct_answer": "編成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の編成で、窓をふいて床をきれいにしました。", "explanation": "ここは〈掃除〉の意味。汚れを落とす作業で、社会や組織の仕組みを組み直す編成とは意味が違う。"}, {"text": "布を、赤い染料で編成しました。", "explanation": "ここは〈染色〉の意味。布に色をつけることで、仕組みを組み直す編成とは全く違う。"}, {"text": "毎朝、十分間の編成をしました。", "explanation": "ここは〈体操〉の意味。体を動かす運動で、組織や仕組みを組み直す編成とは意味が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39273, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "編成", "is_correct": true, "explanation": "社会全体の仕組みの組み立てを指すので、「社会全体の〜をやり直しました」と合い、空欄に入る。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、社会の仕組みを組み直す対象にはならない。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作ることを表す語で、社会全体に対してやり直す対象にはならない。"}, {"text": "写真", "is_correct": false, "explanation": "画像を表す語で、社会の仕組みをやり直すという文には入らない。"}], "explanations": {"編成": "社会全体の仕組みの組み立てを指すので、「社会全体の〜をやり直しました」と合い、空欄に入る。", "天気": "空模様を表す語で、社会の仕組みを組み直す対象にはならない。", "料理": "食べ物を作ることを表す語で、社会全体に対してやり直す対象にはならない。", "写真": "画像を表す語で、社会の仕組みをやり直すという文には入らない。"}, "sentence_index": 6, "correct_answer": "編成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その本を、英語から日本語に編成しました。", "explanation": "ここは〈翻訳〉の意味。言語を別の言語に置き換えることで、組織の仕組みを組み直す編成とは意味が違う。"}, {"text": "庭では、トマトを編成しています。", "explanation": "ここは〈栽培〉の意味。植物を育てることで、社会や組織の仕組みを組み直す編成とは全く違う。"}, {"text": "先生は、答案を一枚ずつ編成しました。", "explanation": "ここは〈採点〉の意味。答案に点数をつける行為で、組織の仕組みを組み直す編成は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39273, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "役所の編成を変わったので、受付の時間も変わりました。", "corrected_sentence": "役所の編成が変わったので、受付の時間も変わりました。", "error_description": "「変わる」は主語に「が」を取る自動詞。「編成を」は「編成が」の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39273, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、区の編成が見直すことを決めました。", "corrected_sentence": "市は、区の編成を見直すことを決めました。", "error_description": "「見直す」は対象を「を」で示す他動詞。「区の編成が」は「区の編成を」の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39274, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「その土地固有の食べ物」の「の」で、「固有」と「食べ物」をつなぐ。正解。"}, {"text": "が", "is_correct": false, "explanation": "「固有が食べ物」は成り立たず、名詞を修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「固有を食べ物」は目的語にならず、名詞をつなげられない。"}, {"text": "で", "is_correct": false, "explanation": "「固有で食べ物」は名詞を修飾できず、文が合わない。"}], "correct_answer": "の", "explanations": {"の": "「その土地固有の食べ物」の「の」で、「固有」と「食べ物」をつなぐ。正解。", "が": "「固有が食べ物」は成り立たず、名詞を修飾できない。", "を": "「固有を食べ物」は目的語にならず、名詞をつなげられない。", "で": "「固有で食べ物」は名詞を修飾できず、文が合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "場所・手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共通", "is_correct": true, "explanation": "〈固有〉が一つの場所だけのものを表すのに対し、〈共通〉は多くのものに共通することを表す。対義語。"}, {"text": "特別", "is_correct": false, "explanation": "〈固有〉と似た意味を持つ近い語で、対義語ではない。"}, {"text": "独自", "is_correct": false, "explanation": "他と違う自分たちの特色を表す語で、〈固有〉の反対の意味ではない。"}, {"text": "個人的", "is_correct": false, "explanation": "個人に関わることを表す語で、場所に限る〈固有〉の反対にはならない。"}], "correct_answer": "共通", "explanations": {"共通": "〈固有〉が一つの場所だけのものを表すのに対し、〈共通〉は多くのものに共通することを表す。対義語。", "特別": "〈固有〉と似た意味を持つ近い語で、対義語ではない。", "独自": "他と違う自分たちの特色を表す語で、〈固有〉の反対の意味ではない。", "個人的": "個人に関わることを表す語で、場所に限る〈固有〉の反対にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39274, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ここにしかいない固有の魚」の「の」で、「固有」と「魚」をつなぐ。正解。"}, {"text": "と", "is_correct": false, "explanation": "「固有と魚」は並列の関係になり、「固有」が「魚」を修飾しない。"}, {"text": "から", "is_correct": false, "explanation": "「固有から魚」は起点を表し、名詞を修飾する関係にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「固有へ魚」は方向を表し、名詞をつなげられない。"}], "correct_answer": "の", "explanations": {"の": "「ここにしかいない固有の魚」の「の」で、「固有」と「魚」をつなぐ。正解。", "と": "「固有と魚」は並列の関係になり、「固有」が「魚」を修飾しない。", "から": "「固有から魚」は起点を表し、名詞を修飾する関係にならない。", "へ": "「固有へ魚」は方向を表し、名詞をつなげられない。"}, "error_tags": {"と": "並列", "から": "起点", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共通", "is_correct": true, "explanation": "〈固有〉が一つの場所だけのものを表すのに対し、〈共通〉は多くの場所にあるものを表す。対義語。"}, {"text": "特定", "is_correct": false, "explanation": "ある対象を決める意味の語で、〈固有〉の反対の意味ではない。"}, {"text": "専用", "is_correct": false, "explanation": "特定の人や目的だけに使う語で、〈固有〉の対義語ではない。"}, {"text": "独創的", "is_correct": false, "explanation": "独自性の高さを表す語で、〈固有〉の対義語ではない。"}], "correct_answer": "共通", "explanations": {"共通": "〈固有〉が一つの場所だけのものを表すのに対し、〈共通〉は多くの場所にあるものを表す。対義語。", "特定": "ある対象を決める意味の語で、〈固有〉の反対の意味ではない。", "専用": "特定の人や目的だけに使う語で、〈固有〉の対義語ではない。", "独創的": "独自性の高さを表す語で、〈固有〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39274, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その場所にだけある、特別なもののこと。", "primary_collocate": null, "pronunciation": "こゆう", "ipa": "kojɯː", "syllable_count": 3, "sentences": [{"text": "この島には、ほかの場所にはない固有の文化があります。", "target_word": "固有", "complexity_tier": "T3", "furigana": "この島[しま]には、ほかの場所[ばしょ]にはない固有[こゆう]の文化[ぶんか]があります。", "sentence_source": "generated"}, {"text": "京都には、その土地固有の食べ物がたくさんあります。", "target_word": "固有", "complexity_tier": "T3", "furigana": "京都[きょうと]には、その土地[とち]固有[こゆう]の食[た]べ物[もの]がたくさんあります。", "sentence_source": "generated"}, {"text": "旅行では、その町固有のお菓子を買うのが楽しみです。", "target_word": "固有", "complexity_tier": "T3", "furigana": "旅行[りょこう]では、その町[まち]固有[こゆう]のお菓子[かし]を買[か]うのが楽[たの]しみです。", "sentence_source": "generated"}, {"text": "山の村には、村固有のお祭りが今も残っています。", "target_word": "固有", "complexity_tier": "T3", "furigana": "山[やま]の村[むら]には、村[むら]固有[こゆう]のお祭[まつ]りが今[いま]も残[のこ]っています。", "sentence_source": "generated"}, {"text": "祖母は、この地方固有の言葉を子どもたちに教えています。", "target_word": "固有", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、この地方[ちほう]固有[こゆう]の言葉[ことば]を子[こ]どもたちに教[おし]えています。", "sentence_source": "generated"}, {"text": "固有のものを大切にしないと、町の特色がなくなってしまいます。", "target_word": "固有", "complexity_tier": "T3", "furigana": "固有[こゆう]のものを大切[たいせつ]にしないと、町[まち]の特色[とくしょく]がなくなってしまいます。", "sentence_source": "generated"}, {"text": "沖縄固有の楽器を、博物館で見ました。", "target_word": "固有", "complexity_tier": "T3", "furigana": "沖縄[おきなわ]固有[こゆう]の楽器[がっき]を、博物館[はくぶつかん]で見[み]ました。", "sentence_source": "generated"}, {"text": "この湖には、ここにしかいない固有の魚がすんでいます。", "target_word": "固有", "complexity_tier": "T3", "furigana": "この湖[みずうみ]には、ここにしかいない固有[こゆう]の魚[さかな]がすんでいます。", "sentence_source": "generated"}, {"text": "どの国にも、その国固有の習慣があります。", "target_word": "固有", "complexity_tier": "T3", "furigana": "どの国[くに]にも、その国[くに]固有[こゆう]の習慣[しゅうかん]があります。", "sentence_source": "generated"}, {"text": "外国から来た友だちに、わたしの町固有の料理を作りました。", "target_word": "固有", "complexity_tier": "T3", "furigana": "外国[がいこく]から来[き]た友[とも]だちに、わたしの町[まち]固有[こゆう]の料理[りょうり]を作[つく]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "固有の", "label": "連体形"}, {"form": "固有で", "label": "で形"}, {"form": "固有である", "label": "である形"}, {"form": "固有ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "ある土地や場所だけにあって、ほかにはない特別なもの。「その土地固有のもの」のように使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39274, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固有", "is_correct": true, "explanation": "「ほかの場所にはない固有の文化」として、その場所だけにある特別なものを表す。正解。"}, {"text": "大量", "is_correct": false, "explanation": "量を表す語で、「ほかの場所にはない文化」の特色を表せない。"}, {"text": "週末", "is_correct": false, "explanation": "時期を表す語で、場所だけにあるという文化の意味と合わない。"}, {"text": "平日", "is_correct": false, "explanation": "時期を表す語で、場所に限られた文化を示せない。"}], "explanations": {"固有": "「ほかの場所にはない固有の文化」として、その場所だけにある特別なものを表す。正解。", "大量": "量を表す語で、「ほかの場所にはない文化」の特色を表せない。", "週末": "時期を表す語で、場所だけにあるという文化の意味と合わない。", "平日": "時期を表す語で、場所に限られた文化を示せない。"}, "sentence_index": 0, "correct_answer": "固有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は全国どこでも同じ固有の料金を決めていて、地域ごとの差はありません。", "explanation": "〈固有〉はその場所だけにあることを表すので、全国どこでも同じという文と矛盾する。"}, {"text": "この教科書は全国で固有に使われています。", "explanation": "〈固有〉は限られた地域にあるものに使う。全国で広く使うものには〈全国的〉などを使うので合わない。"}, {"text": "彼女は全国どこの店でも買える固有の服を着て、いつも明るく話します。", "explanation": "〈固有〉はその場所だけにあるものに使うので、全国どこでも買えるという文と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39274, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "固有", "is_correct": true, "explanation": "「沖縄固有の楽器」として、その土地だけにある特色を表す。正解。"}, {"text": "中古", "is_correct": false, "explanation": "「沖縄中古の楽器」は意味が通らず、土地に結びつく言葉ではない。"}, {"text": "最新", "is_correct": false, "explanation": "新しさを表す語で、土地だけにあるという意味にならない。"}, {"text": "年末", "is_correct": false, "explanation": "時期を表す語で、楽器の説明にならない。"}], "explanations": {"固有": "「沖縄固有の楽器」として、その土地だけにある特色を表す。正解。", "中古": "「沖縄中古の楽器」は意味が通らず、土地に結びつく言葉ではない。", "最新": "新しさを表す語で、土地だけにあるという意味にならない。", "年末": "時期を表す語で、楽器の説明にならない。"}, "sentence_index": 6, "correct_answer": "固有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、全国の支店で同じ固有の看板を出しています。", "explanation": "〈固有〉はその場所だけにあるものに使うので、全国の支店で同じという文と矛盾する。"}, {"text": "この料理は、全国どこの地方でも食べられる固有の料理です。", "explanation": "〈固有〉はその場所だけにあるものに使うので、全国どこでも食べられるという文と矛盾する。"}, {"text": "会議は、全国の会場で同じ固有の時間に始まるので、遅れないでください。", "explanation": "〈固有〉はその場所だけにあるものに使うので、全国の会場で同じという文と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39274, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この村固有を織物は、昔から残っています。", "corrected_sentence": "この村固有の織物は、昔から残っています。", "error_description": "「固有」の後には連体修飾の「の」が必要。「を」は目的語の助詞なので、名詞「織物」を修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39274, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地方固有で行事が、毎年秋に行われます。", "corrected_sentence": "この地方固有の行事が、毎年秋に行われます。", "error_description": "「固有」が名詞を修飾するには「固有の」が必要。「固有で」は名詞「行事」に続けられない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39275, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "普遍", "is_correct": true, "explanation": "「どこにでもある」ことを表し、「ある地域だけに特有」の固有と対になる。"}, {"text": "確実", "is_correct": false, "explanation": "確かであることを表し、固有の対義語にはならない。"}, {"text": "手軽", "is_correct": false, "explanation": "手間がかからないことを表し、土地の特性を表す固有とは対にならない。"}, {"text": "公正", "is_correct": false, "explanation": "かたよりなく正しいことを表し、固有とは対義の関係にない。"}], "correct_answer": "普遍", "explanations": {"普遍": "「どこにでもある」ことを表し、「ある地域だけに特有」の固有と対になる。", "確実": "確かであることを表し、固有の対義語にはならない。", "手軽": "手間がかからないことを表し、土地の特性を表す固有とは対にならない。", "公正": "かたよりなく正しいことを表し、固有とは対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39275, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "普遍", "is_correct": true, "explanation": "「どこにでもある」ことを表し、「ある土地だけに特有」の固有と対になる。"}, {"text": "清潔", "is_correct": false, "explanation": "衛生的であることを表し、固有の対義語にはならない。"}, {"text": "健康", "is_correct": false, "explanation": "体や状態がよいことを表し、固有とは対義の関係にない。"}, {"text": "豪華", "is_correct": false, "explanation": "ぜいたくで華やかなことを表し、固有とは関係がない。"}], "correct_answer": "普遍", "explanations": {"普遍": "「どこにでもある」ことを表し、「ある土地だけに特有」の固有と対になる。", "清潔": "衛生的であることを表し、固有の対義語にはならない。", "健康": "体や状態がよいことを表し、固有とは対義の関係にない。", "豪華": "ぜいたくで華やかなことを表し、固有とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39275, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ある土地や地域だけに特有であること。", "primary_collocate": null, "pronunciation": "こゆう", "ipa": "kojɯː", "syllable_count": 3, "sentences": [{"text": "この花は、山の北側だけに見られる、この地域に固有の植物です。", "target_word": "固有", "complexity_tier": "T3", "furigana": "この花[はな]は、山[やま]の北側[きたがわ]だけに見[み]られる、この地域[ちいき]に固有[こゆう]の植物[しょくぶつ]です。", "sentence_source": "generated"}, {"text": "その病気は熱帯の地域に固有で、日本ではほとんど見られません。", "target_word": "固有", "complexity_tier": "T3", "furigana": "その病気[びょうき]は熱帯[ねったい]の地域[ちいき]に固有[こゆう]で、日本[にほん]ではほとんど見[み]られません。", "sentence_source": "generated"}, {"text": "この方言は、この地方に固有であり、ほかの県では通じません。", "target_word": "固有", "complexity_tier": "T3", "furigana": "この方言[ほうげん]は、この地方[ちほう]に固有[こゆう]であり、ほかの県[けん]では通[つう]じません。", "sentence_source": "generated"}, {"text": "島に固有の生き物を守るため、島への持ちこみが禁止されました。", "target_word": "固有", "complexity_tier": "T3", "furigana": "島[しま]に固有[こゆう]の生[い]き物[もの]を守[まも]るため、島[しま]への持[も]ちこみが禁止[きんし]されました。", "sentence_source": "generated"}, {"text": "この祭りは、この谷に固有のもので、ほかの町にはありません。", "target_word": "固有", "complexity_tier": "T3", "furigana": "この祭[まつ]りは、この谷[たに]に固有[こゆう]のもので、ほかの町[まち]にはありません。", "sentence_source": "generated"}, {"text": "北の地方に固有の気候が、おいしい野菜を育てます。", "target_word": "固有", "complexity_tier": "T3", "furigana": "北[きた]の地方[ちほう]に固有[こゆう]の気候[きこう]が、おいしい野菜[やさい]を育[そだ]てます。", "sentence_source": "generated"}, {"text": "この問題は、この町に固有ではなく、日本中で起きています。", "target_word": "固有", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、この町[まち]に固有[こゆう]ではなく、日本中[にほんじゅう]で起[お]きています。", "sentence_source": "generated"}, {"text": "その鳥は、この島に固有の鳥なので、ほかの国では見られません。", "target_word": "固有", "complexity_tier": "T3", "furigana": "その鳥[とり]は、この島[しま]に固有[こゆう]の鳥[とり]なので、ほかの国[くに]では見[み]られません。", "sentence_source": "generated"}, {"text": "地域に固有の料理を調べて、レポートにまとめました。", "target_word": "固有", "complexity_tier": "T3", "furigana": "地域[ちいき]に固有[こゆう]の料理[りょうり]を調[しら]べて、レポートにまとめました。", "sentence_source": "generated"}, {"text": "文化は、それぞれの土地に固有であり、どれが上とは言えません。", "target_word": "固有", "complexity_tier": "T3", "furigana": "文化[ぶんか]は、それぞれの土地[とち]に固有[こゆう]であり、どれが上[うえ]とは言[い]えません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "固有の", "label": "連体形"}, {"form": "固有で", "label": "で形"}, {"form": "固有である", "label": "である形"}, {"form": "固有ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "ある土地や地域にだけ見られる性質であること。「地域に固有の」「〜に固有だ」の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: 持ちこみ (Zipf 1.75)']::text[], '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39275, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固有", "is_correct": true, "explanation": "「その地域だけに特有」の意味で、「〜に固有の植物」と植物を修飾する形で入る。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫で壊れにくいという意味。土地の特性を表す文脈に合わず、「地域に頑丈の植物」は意味が通らない。"}, {"text": "確実", "is_correct": false, "explanation": "確かであることを表す。植物が特定の地域にだけ見られるという文の内容には入らない。"}, {"text": "手軽", "is_correct": false, "explanation": "簡単で手間がかからない意味。植物の分布を示す文脈には合わず、「手軽の植物」は不自然。"}], "explanations": {"固有": "「その地域だけに特有」の意味で、「〜に固有の植物」と植物を修飾する形で入る。", "頑丈": "丈夫で壊れにくいという意味。土地の特性を表す文脈に合わず、「地域に頑丈の植物」は意味が通らない。", "確実": "確かであることを表す。植物が特定の地域にだけ見られるという文の内容には入らない。", "手軽": "簡単で手間がかからない意味。植物の分布を示す文脈には合わず、「手軽の植物」は不自然。"}, "sentence_index": 0, "correct_answer": "固有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この券は数が固有で、一人三枚までしか買えません。", "explanation": "ここは〈限られた〉の意味。固有は土地や地域に特有であることを表し、数が限られていることを表すわけではないので合わない。"}, {"text": "この駐車場は、社長固有で、ほかの人は使えません。", "explanation": "ここは〈専用〉の意味。固有は性質や特徴を表すもので、利用する人を限って使わせる意味では合わない。"}, {"text": "このクーポンは、会員に固有で、一般の客は使えません。", "explanation": "ここは〈限定〉の意味。固有は土地や集団が本来もつ性質を表し、対象を限って提供する意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39275, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "固有", "is_correct": true, "explanation": "「この町だけに特有」の意味で、「固有ではなく」と否定して使う。"}, {"text": "清潔", "is_correct": false, "explanation": "衛生的であるという意味。町だけの問題かどうかを言う文脈には合わない。"}, {"text": "健康", "is_correct": false, "explanation": "体や状態がよいという意味。「この町に健康ではなく」は意味が通らない。"}, {"text": "豪華", "is_correct": false, "explanation": "ぜいたくで華やかという意味。問題の広がりを言う文には入らない。"}], "explanations": {"固有": "「この町だけに特有」の意味で、「固有ではなく」と否定して使う。", "清潔": "衛生的であるという意味。町だけの問題かどうかを言う文脈には合わない。", "健康": "体や状態がよいという意味。「この町に健康ではなく」は意味が通らない。", "豪華": "ぜいたくで華やかという意味。問題の広がりを言う文には入らない。"}, "sentence_index": 6, "correct_answer": "固有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この時計は、父の固有の持ち物です。", "explanation": "ここは〈所有〉の意味。固有は本来の性質を表し、持ち主を示す意味ではないので合わない。"}, {"text": "この料金は固有で、季節によって変わりません。", "explanation": "ここは〈固定〉の意味。固有は土地に特有の性質を表し、変わらないことを表すわけではないので合わない。"}, {"text": "この部屋の固有面積は三十平米です。", "explanation": "ここは〈専有〉の意味。固有は本来の性質や特徴を表すもので、一人が占める面積を指す専有の意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39275, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この鳥は、この島に固有を鳥で、ほかの国では見られません。", "corrected_sentence": "この鳥は、この島に固有の鳥で、ほかの国では見られません。", "error_description": "「固有」は形状詞なので、名詞の前では「の」を付ける（固有の鳥）。「を」は付かないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "固有で", "is_correct": true, "explanation": "文中の「固有で、」そのもの。「で」で文を続けている。"}, {"text": "固有の", "is_correct": false, "explanation": "連体形で、名詞の前に置く形。「固有で、」と文を続ける形ではない。"}, {"text": "固有だ", "is_correct": false, "explanation": "文末で言い切る形。「だ、」と続けると文が切れてしまい、「で、」の位置には合わない。"}, {"text": "固有に", "is_correct": false, "explanation": "副詞の形で、動詞や形容詞を修飾する。「固有に、」と文を続けることはできない。"}], "correct_form": "固有で", "base_form": "固有", "form_label": "で形", "sentence_index": 1, "explanations": {"固有で": "文中の「固有で、」そのもの。「で」で文を続けている。", "固有の": "連体形で、名詞の前に置く形。「固有で、」と文を続ける形ではない。", "固有だ": "文末で言い切る形。「だ、」と続けると文が切れてしまい、「で、」の位置には合わない。", "固有に": "副詞の形で、動詞や形容詞を修飾する。「固有に、」と文を続けることはできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39275, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この虫は、この島に固有だ、ほかの島では見られません。", "corrected_sentence": "この虫は、この島に固有で、ほかの島では見られません。", "error_description": "「固有」を続ける形は「で」。「だ」は文末で言い切る形なので、後ろに続けられない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "固有の", "is_correct": true, "explanation": "文中の「固有の鳥」そのもの。名詞「鳥」を修飾する連体形。"}, {"text": "固有ならば", "is_correct": false, "explanation": "仮定形なので、名詞「鳥」を修飾できず、「見られません」の文に続かない。"}, {"text": "固有さ", "is_correct": false, "explanation": "名詞形なので、名詞「鳥」を直接修飾できない。「固有さ鳥」は文として成り立たない。"}, {"text": "固有だったら", "is_correct": false, "explanation": "仮定形の過去なので、名詞「鳥」を修飾できず、「見られません」の文に続かない。"}], "correct_form": "固有の", "base_form": "固有", "form_label": "連体形", "sentence_index": 7, "explanations": {"固有の": "文中の「固有の鳥」そのもの。名詞「鳥」を修飾する連体形。", "固有ならば": "仮定形なので、名詞「鳥」を修飾できず、「見られません」の文に続かない。", "固有さ": "名詞形なので、名詞「鳥」を直接修飾できない。「固有さ鳥」は文として成り立たない。", "固有だったら": "仮定形の過去なので、名詞「鳥」を修飾できず、「見られません」の文に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39276, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「続く」の主語を示す。「断絶が続き」で、断絶が続くことを表す。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は目的語を取らない動詞なので、「を」は入らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「断絶と続く」とはならず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や原因を示すが、「続く」の主語には「が」が必要なので入らない。"}], "correct_answer": "が", "explanations": {"が": "「続く」の主語を示す。「断絶が続き」で、断絶が続くことを表す。", "を": "「続く」は目的語を取らない動詞なので、「を」は入らない。", "と": "「と」は並列や相手を示すが、「断絶と続く」とはならず文が成り立たない。", "で": "「で」は手段や原因を示すが、「続く」の主語には「が」が必要なので入らない。"}, "error_tags": {"を": "自動詞の目的語", "と": "並列・相手", "で": "手段・原因"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39276, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「断絶がある」の主語を示す。断絶が存在するという文の形に合う。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「世代と断絶がある」は文がつながらない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここは存在を述べる文なので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので「を」は入らない。"}], "correct_answer": "が", "explanations": {"が": "「断絶がある」の主語を示す。断絶が存在するという文の形に合う。", "と": "「と」は並列や相手を示すが、「世代と断絶がある」は文がつながらない。", "より": "「より」は比較を示すが、ここは存在を述べる文なので合わない。", "を": "「ある」は目的語を取らないので「を」は入らない。"}, "error_tags": {"と": "並列・相手", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39276, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が前はつながっていたのに、今は切れてしまったこと。", "primary_collocate": null, "pronunciation": "だんぜつ", "ipa": "dandzetsɯ", "syllable_count": 4, "sentences": [{"text": "兄とは十年前のけんか以来、断絶したままです。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "兄[あに]とは十年前[じゅうねんまえ]のけんか以来[いらい]、断絶[だんぜつ]したままです。", "sentence_source": "generated"}, {"text": "親子の断絶が続き、母は娘の連絡先も知りません。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "親子[おやこ]の断絶[だんぜつ]が続[つづ]き、母[はは]は娘[むすめ]の連絡先[れんらくさき]も知[し]りません。", "sentence_source": "generated"}, {"text": "父との断絶を、わたしはずっと後悔しています。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "父[ちち]との断絶[だんぜつ]を、わたしはずっと後悔[こうかい]しています。", "sentence_source": "generated"}, {"text": "大きなけんかのあと、二人の友情は断絶してしまいました。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "大[おお]きなけんかのあと、二人[ふたり]の友情[ゆうじょう]は断絶[だんぜつ]してしまいました。", "sentence_source": "generated"}, {"text": "長い断絶のあとで、姉妹は十年ぶりに会って話しました。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "長[なが]い断絶[だんぜつ]のあとで、姉妹[しまい]は十年[じゅうねん]ぶりに会[あ]って話[はな]しました。", "sentence_source": "generated"}, {"text": "親せきとの断絶は、お金のもんだいがきっかけでした。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "親[しん]せきとの断絶[だんぜつ]は、お金[かね]のもんだいがきっかけでした。", "sentence_source": "generated"}, {"text": "昔の友人との断絶を悲しく思い、手紙を書くことにしました。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "昔[むかし]の友人[ゆうじん]との断絶[だんぜつ]を悲[かな]しく思[おも]い、手紙[てがみ]を書[か]くことにしました。", "sentence_source": "generated"}, {"text": "世代の断絶がある家では、祖父母と孫が話をしません。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "世代[せだい]の断絶[だんぜつ]がある家[いえ]では、祖父母[そふぼ]と孫[まご]が話[はなし]をしません。", "sentence_source": "generated"}, {"text": "彼と断絶してから、わたしは一度も彼の顔を見ていません。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "彼[かれ]と断絶[だんぜつ]してから、わたしは一度[いちど]も彼[かれ]の顔[かお]を見[み]ていません。", "sentence_source": "generated"}, {"text": "家族の断絶をなくすために、毎週みんなで食事をしています。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "家族[かぞく]の断絶[だんぜつ]をなくすために、毎週[まいしゅう]みんなで食事[しょくじ]をしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "断絶する", "label": "基本形"}, {"form": "断絶した", "label": "過去形"}, {"form": "断絶して", "label": "て形"}, {"form": "断絶しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "家族や友人など、人と人とのつながりが切れて、会ったり話したりしなくなること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39276, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断絶", "is_correct": true, "explanation": "人とのつながりが切れた状態を表す。「〜したまま」で続き、文の内容に合う。"}, {"text": "友情", "is_correct": false, "explanation": "仲のよい気持ちを表す。「友情したまま」は文として成り立たない。"}, {"text": "距離", "is_correct": false, "explanation": "離れている程度を表す。「距離したまま」は不自然で、切れた関係の話には合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "年の数を表す。「年齢したまま」は意味が通らない。"}], "explanations": {"断絶": "人とのつながりが切れた状態を表す。「〜したまま」で続き、文の内容に合う。", "友情": "仲のよい気持ちを表す。「友情したまま」は文として成り立たない。", "距離": "離れている程度を表す。「距離したまま」は不自然で、切れた関係の話には合わない。", "年齢": "年の数を表す。「年齢したまま」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "断絶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "酒を断絶して、体の調子が良くなった。", "explanation": "ここは〈断つ〉（やめる）の意味。断絶は人や関係が切れることで、酒をやめる意味では使わないので合わない。"}, {"text": "夢を断絶して、もう一度挑戦することにした。", "explanation": "ここは〈断念〉の意味。断絶は人や関係が切れることで、夢をあきらめる意味では使わないので合わない。"}, {"text": "彼とは少し断絶を置いて、落ち着いて考えたい。", "explanation": "ここは〈距離を置く〉の意味。断絶は関係が完全に切れることで、少し離れる程度には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39276, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断絶", "is_correct": true, "explanation": "人とのつながりが切れたという意味。「との断絶を悲しく思い」と目的語で入る。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のこと。人との関係を表す文には入らない。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる入れ物。「友人との財布」は意味が通らない。"}, {"text": "教科書", "is_correct": false, "explanation": "授業で使う本。人間関係の文には合わない。"}], "explanations": {"断絶": "人とのつながりが切れたという意味。「との断絶を悲しく思い」と目的語で入る。", "天気": "空模様のこと。人との関係を表す文には入らない。", "財布": "お金を入れる入れ物。「友人との財布」は意味が通らない。", "教科書": "授業で使う本。人間関係の文には合わない。"}, "sentence_index": 6, "correct_answer": "断絶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "騒がしいので、外の音を断絶するために窓を閉めた。", "explanation": "ここは〈遮断〉（さえぎる）の意味。断絶は人や関係が切れることで、音をさえぎる意味では使わないので合わない。"}, {"text": "毎日、家族と断絶を取ろうとしています。", "explanation": "ここは〈連絡を取る〉の意味。断絶は連絡が切れることで、取るものではないので合わない。"}, {"text": "雨が強くなったので、作業を断絶して中に入った。", "explanation": "ここは〈中断〉の意味。断絶は続かなくなることで、一時的に止めて後で続ける意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39276, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母との断絶に、わたしはずっと悲しく思っています。", "corrected_sentence": "母との断絶を、わたしはずっと悲しく思っています。", "error_description": "「悲しく思う」は対象に「を」を付ける。「断絶に」と「に」を付けるのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39276, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父と断絶しまま、もう十年がたちました。", "corrected_sentence": "父と断絶したまま、もう十年がたちました。", "error_description": "「断絶」はサ変名詞なので「断絶した」とし、「まま」を続ける。「しまま」は活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
