INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39277, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今まで続いていた関係やつながりが、途中で切れてしまうこと。", "primary_collocate": null, "pronunciation": "だんぜつ", "ipa": "dandzetsɯ", "syllable_count": 4, "sentences": [{"text": "二つの国の国交が断絶し、船も飛行機も動かなくなりました。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]の国交[こっこう]が断絶[だんぜつ]し、船[ふね]も飛行機[ひこうき]も動[うご]かなくなりました。", "sentence_source": "generated"}, {"text": "長い戦争で、この地方の伝統が断絶してしまいました。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "長[なが]い戦争[せんそう]で、この地方[ちほう]の伝統[でんとう]が断絶[だんぜつ]してしまいました。", "sentence_source": "generated"}, {"text": "嵐のため、村と町をつなぐ連絡が断絶しました。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "嵐[あらし]のため、村[むら]と町[まち]をつなぐ連絡[れんらく]が断絶[だんぜつ]しました。", "sentence_source": "generated"}, {"text": "会社とその店との取引は、去年のうちに断絶しました。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "会社[かいしゃ]とその店[みせ]との取引[とりひき]は、去年[きょねん]のうちに断絶[だんぜつ]しました。", "sentence_source": "generated"}, {"text": "師匠が亡くなり、その技は弟子がいなかったので断絶しました。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "師匠[ししょう]が亡[な]くなり、その技[わざ]は弟子[でし]がいなかったので断絶[だんぜつ]しました。", "sentence_source": "generated"}, {"text": "国どうしの交流が断絶すると、人々の生活も苦しくなります。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "国[くに]どうしの交流[こうりゅう]が断絶[だんぜつ]すると、人々[ひとびと]の生活[せいかつ]も苦[くる]しくなります。", "sentence_source": "generated"}, {"text": "長いあいだ連絡が断絶していたため、島の様子は分かりませんでした。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "長[なが]いあいだ連絡[れんらく]が断絶[だんぜつ]していたため、島[しま]の様子[ようす]は分[わ]かりませんでした。", "sentence_source": "generated"}, {"text": "古い習慣が断絶しないよう、若い人に教えています。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "古[ふる]い習慣[しゅうかん]が断絶[だんぜつ]しないよう、若[わか]い人[ひと]に教[おし]えています。", "sentence_source": "generated"}, {"text": "電話線が切れて、町との通信が断絶しました。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "電話線[でんわせん]が切[き]れて、町[まち]との通信[つうしん]が断絶[だんぜつ]しました。", "sentence_source": "generated"}, {"text": "二つの会社の関係が断絶したのは、約束が守られなかったからです。", "target_word": "断絶", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]の関係[かんけい]が断絶[だんぜつ]したのは、約束[やくそく]が守[まも]られなかったからです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "断絶する", "label": "基本形"}, {"form": "断絶した", "label": "過去形"}, {"form": "断絶して", "label": "て形"}, {"form": "断絶しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "国・会社・伝統・連絡など、続いていた関係やつながりが途中で切れて、なくなること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39277, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断絶", "is_correct": true, "explanation": "国や関係のつながりが途中で切れること。「国交が断絶し」で文が成り立つ。"}, {"text": "季節", "is_correct": false, "explanation": "一年の時期の区分。国交の話には入らない。"}, {"text": "人数", "is_correct": false, "explanation": "人の数を表す。「国交が人数し」は意味が通らない。"}, {"text": "天候", "is_correct": false, "explanation": "空模様や気候の様子。国交が切れる文脈とは合わない。"}], "explanations": {"断絶": "国や関係のつながりが途中で切れること。「国交が断絶し」で文が成り立つ。", "季節": "一年の時期の区分。国交の話には入らない。", "人数": "人の数を表す。「国交が人数し」は意味が通らない。", "天候": "空模様や気候の様子。国交が切れる文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "断絶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨で試合が断絶して、翌日に続きが行われた。", "explanation": "ここは〈中断〉の意味。断絶は続かなくなることで、翌日に続きが行われる一時的な中止には合わない。"}, {"text": "工場は今は断絶しているが、来月から動き出す予定だ。", "explanation": "ここは〈休止〉の意味。断絶は切れたままになることで、いずれ再開する停止には合わない。"}, {"text": "誤解が断絶して、二人の仲は元に戻った。", "explanation": "ここは〈解消〉の意味。断絶は切れることで、誤解がなくなる意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39277, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断絶", "is_correct": true, "explanation": "連絡が途中で切れた状態。「〜していたため」と続く文に合う。"}, {"text": "地図", "is_correct": false, "explanation": "土地の様子を描いた図。連絡が切れる文脈には入らない。"}, {"text": "食材", "is_correct": false, "explanation": "料理に使う材料。連絡の話には合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "色の様子を表す。連絡が切れたという内容とは関係がない。"}], "explanations": {"断絶": "連絡が途中で切れた状態。「〜していたため」と続く文に合う。", "地図": "土地の様子を描いた図。連絡が切れる文脈には入らない。", "食材": "料理に使う材料。連絡の話には合わない。", "色彩": "色の様子を表す。連絡が切れたという内容とは関係がない。"}, "sentence_index": 6, "correct_answer": "断絶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公園では、ボール遊びを断絶することになった。", "explanation": "ここは〈禁止〉の意味。断絶は関係や流れが途中で切れることで、遊びを規則で止めさせる意味には使わないので合わない。"}, {"text": "二国は去年、新しい条約で断絶を結んだ。", "explanation": "ここは〈結ぶ〉の意味。断絶は関係が切れることで、結ぶ対象にはならない。"}, {"text": "人質を断絶して、無事に家へ帰した。", "explanation": "ここは〈解放〉の意味。断絶は関係やつながりが切れることで、人を自由にする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39277, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "取引が断絶しあと、会社は新しい店を探しました。", "corrected_sentence": "取引が断絶したあと、会社は新しい店を探しました。", "error_description": "「断絶」は「した」の形で「あと」に続ける。「しあと」は活用が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39277, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町との連絡が断絶しると、物資が届かなくなります。", "corrected_sentence": "町との連絡が断絶すると、物資が届かなくなります。", "error_description": "「断絶する」は「すると」と続ける。「しると」は活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39278, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「仲間から疎外された」の形。集団を起点とする「から」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「仲間を疎外された」は目的語の「を」を残した受身の誤り。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を表すが、「仲間と疎外された」とは言わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「仲間へ疎外された」は不自然で誤り。"}], "correct_answer": "から", "explanations": {"から": "「仲間から疎外された」の形。集団を起点とする「から」が正しい。", "を": "「仲間を疎外された」は目的語の「を」を残した受身の誤り。", "と": "「と」は相手を表すが、「仲間と疎外された」とは言わない。", "へ": "「へ」は方向を表し、「仲間へ疎外された」は不自然で誤り。"}, "error_tags": {"を": "目的語", "と": "相手・共同", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39278, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「仲間を疎外する」の目的語を示す「を」。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表し、「仲間より疎外する」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「仲間に疎外する」は不自然で、疎外する対象には「を」を使う。"}, {"text": "へ", "is_correct": false, "explanation": "「仲間へ疎外する」は方向の「へ」で、疎外する対象は「を」で示す。"}], "correct_answer": "を", "explanations": {"を": "「仲間を疎外する」の目的語を示す「を」。", "より": "「より」は比較の基準を表し、「仲間より疎外する」は成り立たない。", "に": "「仲間に疎外する」は不自然で、疎外する対象には「を」を使う。", "へ": "「仲間へ疎外する」は方向の「へ」で、疎外する対象は「を」で示す。"}, "error_tags": {"より": "比較", "に": "方向・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39278, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "仲間はずれにすること。", "primary_collocate": null, "pronunciation": "そがい", "ipa": "soɡai", "syllable_count": 3, "sentences": [{"text": "新しく来た子を疎外してはいけないと、先生は言いました。", "target_word": "疎外して", "complexity_tier": "T3", "furigana": "新[あたら]しく来[き]た子[こ]を疎外[そがい]してはいけないと、先生[せんせい]は言[い]いました。", "sentence_source": "generated"}, {"text": "彼は仲間から疎外され、昼休みはいつも一人でした。", "target_word": "疎外され", "complexity_tier": "T3", "furigana": "彼[かれ]は仲間[なかま]から疎外[そがい]され、昼休[ひるやす]みはいつも一人[ひとり]でした。", "sentence_source": "generated"}, {"text": "クラスで一人だけ疎外されて、花子は学校に行きたくなくなった。", "target_word": "疎外されて", "complexity_tier": "T3", "furigana": "クラスで一人[ひとり]だけ疎外[そがい]されて、花子[はなこ]は学校[がっこう]に行[い]きたくなくなった。", "sentence_source": "generated"}, {"text": "意見が違うからといって、誰かを疎外するのはやめよう。", "target_word": "疎外する", "complexity_tier": "T3", "furigana": "意見[いけん]が違[ちが]うからといって、誰[だれ]かを疎外[そがい]するのはやめよう。", "sentence_source": "generated"}, {"text": "転校生が疎外されないように、みんなで声をかけた。", "target_word": "疎外されない", "complexity_tier": "T3", "furigana": "転校生[てんこうせい]が疎外[そがい]されないように、みんなで声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "弟を疎外したことを、兄は後で謝った。", "target_word": "疎外した", "complexity_tier": "T3", "furigana": "弟[おとうと]を疎外[そがい]したことを、兄[あに]は後[あと]で謝[あやま]った。", "sentence_source": "generated"}, {"text": "疎外された少年は、一人で本を読んでいた。", "target_word": "疎外された", "complexity_tier": "T3", "furigana": "疎外[そがい]された少年[しょうねん]は、一人[ひとり]で本[ほん]を読[よ]んでいた。", "sentence_source": "generated"}, {"text": "仲間を疎外する遊びは、すぐにやめさせるべきだ。", "target_word": "疎外する", "complexity_tier": "T3", "furigana": "仲間[なかま]を疎外[そがい]する遊[あそ]びは、すぐにやめさせるべきだ。", "sentence_source": "generated"}, {"text": "彼女だけを疎外した理由を、リーダーは説明できなかった。", "target_word": "疎外した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]だけを疎外[そがい]した理由[りゆう]を、リーダーは説明[せつめい]できなかった。", "sentence_source": "generated"}, {"text": "みんなで花子を疎外していたことに気づいて、私は恥ずかしくなった。", "target_word": "疎外して", "complexity_tier": "T3", "furigana": "みんなで花子[はなこ]を疎外[そがい]していたことに気[き]づいて、私[わたし]は恥[は]ずかしくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "疎外する", "label": "終止形"}, {"form": "疎外した", "label": "過去形"}, {"form": "疎外して", "label": "て形"}, {"form": "疎外される", "label": "受身形"}, {"form": "疎外しない", "label": "否定形"}], "register": "中立（標準的な書き言葉・話し言葉）", "sense_fingerprint": "グループの中で特定の人を仲間に入れず、のけ者にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e3467d-5cea-4b54-9930-14d540bd33b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39278, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疎外して", "is_correct": true, "explanation": "「新しく来た子を仲間から外すこと」を禁じる文で、「疎外する」の意味に合う。"}, {"text": "歓迎して", "is_correct": false, "explanation": "「歓迎する」は仲間に迎えることで、禁止の文脈と意味が逆になる。"}, {"text": "紹介して", "is_correct": false, "explanation": "「紹介する」は人を引き合わせる意味で、「〜てはいけない」と禁じる理由になっていない。"}, {"text": "案内して", "is_correct": false, "explanation": "「案内する」は道や場所を教える意味で、仲間外れにしないという文の内容と関係しない。"}], "explanations": {"疎外して": "「新しく来た子を仲間から外すこと」を禁じる文で、「疎外する」の意味に合う。", "歓迎して": "「歓迎する」は仲間に迎えることで、禁止の文脈と意味が逆になる。", "紹介して": "「紹介する」は人を引き合わせる意味で、「〜てはいけない」と禁じる理由になっていない。", "案内して": "「案内する」は道や場所を教える意味で、仲間外れにしないという文の内容と関係しない。"}, "sentence_index": 0, "correct_answer": "疎外して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その規則は、選手の挑戦を疎外するものだ。", "explanation": "ここは〈妨げる〉（阻害）の意味。疎外は人を仲間から外す行為で、挑戦を妨げる意味では使わない。"}, {"text": "先生の質問を疎外して、彼は窓の外を見ていた。", "explanation": "ここは〈無視〉の意味。疎外は人を仲間から外す行為で、質問を対象にすると合わない。"}, {"text": "彼は離島に一人で疎外して暮らしている。", "explanation": "ここは〈孤立〉の意味。疎外は周囲が仲間から外す行為で、地理的に離れた状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39278, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疎外された", "is_correct": true, "explanation": "「疎外された少年」として、仲間外れの状態が「一人で本を読んでいた」と合う。"}, {"text": "祝福された", "is_correct": false, "explanation": "「祝福された」は喜ばれる意味で、一人で本を読む状況と合わない。"}, {"text": "招待された", "is_correct": false, "explanation": "「招待された」は仲間に迎えられた意味で、「一人で」と噛み合わない。"}, {"text": "尊敬された", "is_correct": false, "explanation": "「尊敬された」は敬われる意味で、この文の孤立した状況に合わない。"}], "explanations": {"疎外された": "「疎外された少年」として、仲間外れの状態が「一人で本を読んでいた」と合う。", "祝福された": "「祝福された」は喜ばれる意味で、一人で本を読む状況と合わない。", "招待された": "「招待された」は仲間に迎えられた意味で、「一人で」と噛み合わない。", "尊敬された": "「尊敬された」は敬われる意味で、この文の孤立した状況に合わない。"}, "sentence_index": 6, "correct_answer": "疎外された"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場は、安全基準を疎外して、点検を怠った。", "explanation": "ここは〈軽視〉の意味。疎外は人を仲間から外す行為で、基準のような物事には使わない。"}, {"text": "不良品をラインから疎外した。", "explanation": "ここは〈排除〉の意味。疎外は人の関係の中で外すことで、物を取り除く文には使わない。"}, {"text": "会社は古い計画を疎外して、新しい方針を選んだ。", "explanation": "ここは〈放棄〉の意味。疎外は人の集まりから外すことで、計画を対象にすると不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39278, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は班を疎外され、体育の時間はずっと一人だった。", "corrected_sentence": "彼は班から疎外され、体育の時間はずっと一人だった。", "error_description": "「疎外される」は「〜から疎外される」の形で使う。「を」は誤りで、正しくは「から」。集団（班）から外されるという起点を表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39278, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同じ班の友達から疎外しされて、彼はだんだん話さなくなった。", "corrected_sentence": "同じ班の友達から疎外されて、彼はだんだん話さなくなった。", "error_description": "正しい受身形は「疎外されて」。「疎外しされて」は「疎外し」と「される」が重なった誤りで、受身の形が崩れている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39279, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「意見が疎外される」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「意見を疎外される」は目的語の形として誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「意見へ疎外される」は方向を表し、疎外の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「意見と疎外された」は相手を表す形で、主語を示せず不自然。"}], "correct_answer": "が", "explanations": {"が": "「意見が疎外される」の主語を示す「が」。", "を": "「意見を疎外される」は目的語の形として誤り。", "へ": "「意見へ疎外される」は方向を表し、疎外の主語にならない。", "と": "「意見と疎外された」は相手を表す形で、主語を示せず不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39279, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「議論の場から疎外されない」の起点を示す「から」。"}, {"text": "へ", "is_correct": false, "explanation": "「議論の場へ疎外される」は方向を示す形で、疎外の表現として不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、「場より疎外される」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐだけで、「場の疎外される」では起点を示せない。"}], "correct_answer": "から", "explanations": {"から": "「議論の場から疎外されない」の起点を示す「から」。", "へ": "「議論の場へ疎外される」は方向を示す形で、疎外の表現として不自然。", "より": "「より」は比較を表し、「場より疎外される」は成り立たない。", "の": "「の」は名詞をつなぐだけで、「場の疎外される」では起点を示せない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39279, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会や集団の中で、ある人や物事を無視したり、排除したりすること。また、そのような状態。", "primary_collocate": null, "pronunciation": "そがい", "ipa": "soɡai", "syllable_count": 3, "sentences": [{"text": "移民を疎外する社会では、さまざまな問題が起こりやすい。", "target_word": "疎外する", "complexity_tier": "T3", "furigana": "移民[いみん]を疎外[そがい]する社会[しゃかい]では、さまざまな問題[もんだい]が起[お]こりやすい。", "sentence_source": "generated"}, {"text": "会議で若手の意見が疎外されていると、不満の声が上がった。", "target_word": "疎外されて", "complexity_tier": "T3", "furigana": "会議[かいぎ]で若手[わかて]の意見[いけん]が疎外[そがい]されていると、不満[ふまん]の声[こえ]が上[あ]がった。", "sentence_source": "generated"}, {"text": "地域から疎外された高齢者を支える活動が広がっている。", "target_word": "疎外された", "complexity_tier": "T3", "furigana": "地域[ちいき]から疎外[そがい]された高齢者[こうれいしゃ]を支[ささ]える活動[かつどう]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "少数派を疎外すれば、組織は活力を失う。", "target_word": "疎外すれば", "complexity_tier": "T3", "furigana": "少数派[しょうすうは]を疎外[そがい]すれば、組織[そしき]は活力[かつりょく]を失[うしな]う。", "sentence_source": "generated"}, {"text": "彼は職場で疎外され、次第に孤立していった。", "target_word": "疎外され", "complexity_tier": "T3", "furigana": "彼[かれ]は職場[しょくば]で疎外[そがい]され、次第[しだい]に孤立[こりつ]していった。", "sentence_source": "generated"}, {"text": "障害のある人を疎外しない社会を目指して、法律が改正された。", "target_word": "疎外しない", "complexity_tier": "T3", "furigana": "障害[しょうがい]のある人[ひと]を疎外[そがい]しない社会[しゃかい]を目指[めざ]して、法律[ほうりつ]が改正[かいせい]された。", "sentence_source": "generated"}, {"text": "経済の発展から疎外された地域では、人口が減り続けている。", "target_word": "疎外された", "complexity_tier": "T3", "furigana": "経済[けいざい]の発展[はってん]から疎外[そがい]された地域[ちいき]では、人口[じんこう]が減[へ]り続[つづ]けている。", "sentence_source": "generated"}, {"text": "新しい制度では、少数の意見を持つ人が議論の場から疎外されないよう配慮されている。", "target_word": "疎外", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]では、少数[しょうすう]の意見[いけん]を持[も]つ人[ひと]が議論[ぎろん]の場[ば]から疎外[そがい]されないよう配慮[はいりょ]されている。", "sentence_source": "generated"}, {"text": "貧しい家庭の子どもが教育から疎外される状況を、改善したい。", "target_word": "疎外される", "complexity_tier": "T3", "furigana": "貧[まず]しい家庭[かてい]の子[こ]どもが教育[きょういく]から疎外[そがい]される状況[じょうきょう]を、改善[かいぜん]したい。", "sentence_source": "generated"}, {"text": "疎外された状態が長く続くと、人は心を閉ざしてしまう。", "target_word": "疎外された", "complexity_tier": "T3", "furigana": "疎外[そがい]された状態[じょうたい]が長[なが]く続[つづ]くと、人[ひと]は心[こころ]を閉[と]ざしてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "疎外する", "label": "終止形"}, {"form": "疎外した", "label": "過去形"}, {"form": "疎外される", "label": "受身形"}, {"form": "疎外された", "label": "受身過去形"}, {"form": "疎外しない", "label": "否定形"}], "register": "やや硬い書き言葉（社会・報道・論説）", "sense_fingerprint": "社会や組織の中で、人や物事が無視・排除され、輪から外れた状態に置かれること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e3467d-5cea-4b54-9930-14d540bd33b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39279, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疎外する", "is_correct": true, "explanation": "「移民を疎外する社会」の形。社会が人を排除する問題を表し、文の論理に合う。"}, {"text": "支援する", "is_correct": false, "explanation": "「支援する社会」では問題が起こりやすいとは言えず、意味が合わない。"}, {"text": "歓迎する", "is_correct": false, "explanation": "「歓迎する社会」は問題の原因にならず、文の論理に合わない。"}, {"text": "撮影する", "is_correct": false, "explanation": "「撮影する社会」は問題の原因として文の内容と関係しない。"}], "explanations": {"疎外する": "「移民を疎外する社会」の形。社会が人を排除する問題を表し、文の論理に合う。", "支援する": "「支援する社会」では問題が起こりやすいとは言えず、意味が合わない。", "歓迎する": "「歓迎する社会」は問題の原因にならず、文の論理に合わない。", "撮影する": "「撮影する社会」は問題の原因として文の内容と関係しない。"}, "sentence_index": 0, "correct_answer": "疎外する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の日は、洗濯物を庭から疎外した。", "explanation": "ここは〈取り込む〉の意味。疎外は人や集団の関係で外すことで、物を取り込む文には使わない。"}, {"text": "古い設備を工場から疎外した。", "explanation": "ここは〈撤去〉（物を取り去る）の意味。疎外は人や集団の関係で外すことで、設備を取り去る文には使わない。"}, {"text": "強い雨は、作物の成長を疎外した。", "explanation": "ここは〈妨げる〉（阻害）の意味。疎外は人を仲間から外す行為で、成長を妨げる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39279, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疎外された", "is_correct": true, "explanation": "「経済の発展から疎外された地域」として、取り残された状態が人口減少と合う。"}, {"text": "歓迎された", "is_correct": false, "explanation": "「歓迎された地域」では人口が減り続けるとは言えず、意味が合わない。"}, {"text": "祝福された", "is_correct": false, "explanation": "「祝福された地域」は人口減少の文脈に合わない。"}, {"text": "注目された", "is_correct": false, "explanation": "「注目された地域」は人口が減り続ける文脈と噛み合わない。"}], "explanations": {"疎外された": "「経済の発展から疎外された地域」として、取り残された状態が人口減少と合う。", "歓迎された": "「歓迎された地域」では人口が減り続けるとは言えず、意味が合わない。", "祝福された": "「祝福された地域」は人口減少の文脈に合わない。", "注目された": "「注目された地域」は人口が減り続ける文脈と噛み合わない。"}, "sentence_index": 6, "correct_answer": "疎外された"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨で道が寸断され、村は疎外した。", "explanation": "ここは〈孤立〉の意味。道が絶たれて外部と切れた状態は孤立。疎外は周囲の人が仲間から外す行為で、地理的な状況には使わない。"}, {"text": "川の水は、堤防を疎外して流れた。", "explanation": "ここは〈突き破る〉の意味。疎外は無視・排除の意味で、水の勢いを表す文には使わない。"}, {"text": "彼は朝の空気を疎外して、故郷に戻った。", "explanation": "ここは〈気にしない〉の意味。疎外は人や物事を仲間から外す行為で、空気を対象にする文では不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39279, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高齢者が地域の行事から疎外しされないよう、市は送迎を始めた。", "corrected_sentence": "高齢者が地域の行事から疎外されないよう、市は送迎を始めた。", "error_description": "正しくは「疎外されない」。「疎外しされ」は「疎外し」と「される」を重ねた誤りで、受身の形が崩れている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39279, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家族へ疎外されていた彼は、転職を決めた。", "corrected_sentence": "家族から疎外されていた彼は、転職を決めた。", "error_description": "「疎外される」は「〜から疎外される」の形で使う。「へ」は方向を示すので「家族へ疎外される」は誤り。正しくは「から」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39282, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「愛情に根差している」の基盤を示す「に」。"}, {"text": "で", "is_correct": false, "explanation": "「愛情で根差している」は手段を表し、基盤の意味を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「愛情を根差している」は目的語を取る形ではなく、誤り。"}, {"text": "と", "is_correct": false, "explanation": "「愛情と根差している」は相手を表し、基盤の意味と合わない。"}], "correct_answer": "に", "explanations": {"に": "「愛情に根差している」の基盤を示す「に」。", "で": "「愛情で根差している」は手段を表し、基盤の意味を表せない。", "を": "「愛情を根差している」は目的語を取る形ではなく、誤り。", "と": "「愛情と根差している」は相手を表し、基盤の意味と合わない。"}, "error_tags": {"で": "手段・場所", "を": "目的語", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39282, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39282, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "何かの考えや気持ちが、深いところでしっかりとつながっていること。", "primary_collocate": null, "pronunciation": "ねざす", "ipa": "nezasɯ", "syllable_count": 3, "sentences": [{"text": "彼の優しさは、幼いころの経験に深く根差している。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "彼[かれ]の優[やさ]しさは、幼[おさな]いころの経験[けいけん]に深[ふか]く根差[ねざ]している。", "sentence_source": "generated"}, {"text": "彼女の信念は、家族への愛情に根差していると思う。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の信念[しんねん]は、家族[かぞく]への愛情[あいじょう]に根差[ねざ]していると思[おも]う。", "sentence_source": "generated"}, {"text": "この不安は、子どものころの記憶に根差しているようだ。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "この不安[ふあん]は、子[こ]どものころの記憶[きおく]に根差[ねざ]しているようだ。", "sentence_source": "generated"}, {"text": "自分の価値観に根差した選択だから、後悔はない。", "target_word": "根差した", "complexity_tier": "T3", "furigana": "自分[じぶん]の価値観[かちかん]に根差[ねざ]した選択[せんたく]だから、後悔[こうかい]はない。", "sentence_source": "generated"}, {"text": "生活に根差した言葉だから、人の心に響く。", "target_word": "根差した", "complexity_tier": "T3", "furigana": "生活[せいかつ]に根差[ねざ]した言葉[ことば]だから、人[ひと]の心[こころ]に響[ひび]く。", "sentence_source": "generated"}, {"text": "人々の気持ちに根差していない政策は、長続きしない。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "人々[ひとびと]の気持[きも]ちに根差[ねざ]していない政策[せいさく]は、長続[ながつづ]きしない。", "sentence_source": "generated"}, {"text": "故郷への思いに根差して、彼は詩を書き続けた。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "故郷[こきょう]への思[おも]いに根差[ねざ]して、彼[かれ]は詩[し]を書[か]き続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼の怒りは、不公平な扱いへの不満に根差している。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "彼[かれ]の怒[いか]りは、不公平[ふこうへい]な扱[あつか]いへの不満[ふまん]に根差[ねざ]している。", "sentence_source": "generated"}, {"text": "彼の強い責任感は、父の教えに根差している。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "彼[かれ]の強[つよ]い責任感[せきにんかん]は、父[ちち]の教[おし]えに根差[ねざ]している。", "sentence_source": "generated"}, {"text": "この詩の悲しみは、戦争で家族を失った経験に根差している。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "この詩[し]の悲[かな]しみは、戦争[せんそう]で家族[かぞく]を失[うしな]った経験[けいけん]に根差[ねざ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "根差す", "label": "終止形"}, {"form": "根差した", "label": "過去形"}, {"form": "根差して", "label": "て形"}, {"form": "根差している", "label": "継続形"}, {"form": "根差さない", "label": "否定形"}], "register": "やや硬い書き言葉", "sense_fingerprint": "考え・信念・感情などが、経験や愛情などの深い部分に結びついて生まれていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e3467d-5cea-4b54-9930-14d540bd33b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39282, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根差して", "is_correct": true, "explanation": "「経験に深く根差している」の形。考えや気持ちが経験という基盤に深く結びついていることを表す。"}, {"text": "忘れて", "is_correct": false, "explanation": "「経験に深く忘れている」は意味をなさず、基盤を示す文に合わない。"}, {"text": "比べて", "is_correct": false, "explanation": "「経験に深く比べている」は不自然で、基盤の意味に合わない。"}, {"text": "数えて", "is_correct": false, "explanation": "「経験に深く数えている」は意味が通らず、文の内容に合わない。"}], "explanations": {"根差して": "「経験に深く根差している」の形。考えや気持ちが経験という基盤に深く結びついていることを表す。", "忘れて": "「経験に深く忘れている」は意味をなさず、基盤を示す文に合わない。", "比べて": "「経験に深く比べている」は不自然で、基盤の意味に合わない。", "数えて": "「経験に深く数えている」は意味が通らず、文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "根差して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポスターは、壁に根差して一週間で剥がれた。", "explanation": "ここは〈貼りつく〉の意味。根差すは考えや気持ちが深く結びつく意味で、紙が表面にくっつく状態には使わない。"}, {"text": "川辺の柳は、湿った土に深く根差している。", "explanation": "ここは〈植物が土に根を張る〉の具体的な意味。考えや気持ちの結びつきを表す語義ではない。"}, {"text": "その電車は、一本の線路に根差している。", "explanation": "ここは〈つながっている〉の意味。根差すは考えや気持ちの結びつきを表すので、乗り物と線路の関係には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39282, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根差して", "is_correct": true, "explanation": "「故郷への思いに根差して」の形。思いを土台にして詩を書き続けたという意味。"}, {"text": "並べて", "is_correct": false, "explanation": "「故郷への思いに並べて」は意味が通らず、理由の文に合わない。"}, {"text": "縫って", "is_correct": false, "explanation": "「故郷への思いに縫って」は意味をなさず、文の内容と合わない。"}, {"text": "驚いて", "is_correct": false, "explanation": "「故郷への思いに驚いて」は感情の反応を表すが、詩を書き続けた理由としては不自然。"}], "explanations": {"根差して": "「故郷への思いに根差して」の形。思いを土台にして詩を書き続けたという意味。", "並べて": "「故郷への思いに並べて」は意味が通らず、理由の文に合わない。", "縫って": "「故郷への思いに縫って」は意味をなさず、文の内容と合わない。", "驚いて": "「故郷への思いに驚いて」は感情の反応を表すが、詩を書き続けた理由としては不自然。"}, "sentence_index": 6, "correct_answer": "根差して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "岸辺の草は、泥の中に根差している。", "explanation": "ここは〈植物が根を張る〉の具体的な意味。考えや気持ちの結びつきを表す語義ではない。"}, {"text": "その噂は、一本の鉛筆に根差している。", "explanation": "噂の基盤を一本の鉛筆とするのは、根差すの意味として不自然。"}, {"text": "その計画は、机の脚に根差していた。", "explanation": "ここは〈支えられる〉の意味。根差すは考えや気持ちの深い結びつきで、家具の脚には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39282, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その活動は、地域の人々の願いへ根差している。", "corrected_sentence": "その活動は、地域の人々の願いに根差している。", "error_description": "「根差す」は「〜に根差す」の形で使う。「へ」は方向を表し、「願いへ根差す」は誤り。正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39282, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店の味は、祖父の時代からの製法に根差されている。", "corrected_sentence": "この店の味は、祖父の時代からの製法に根差している。", "error_description": "「根差す」は自動詞で、受身の「根差される」は使わない。正しくは「根差している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39283, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「格差に根差した問題」の基盤を示す「に」。"}, {"text": "で", "is_correct": false, "explanation": "「格差で根差した」は手段を表し、基盤を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「格差と根差した」は相手を表し、基盤の意味にならない。"}, {"text": "が", "is_correct": false, "explanation": "「格差が根差した」は「根差す」の正しい助詞ではなく、不自然。"}], "correct_answer": "に", "explanations": {"に": "「格差に根差した問題」の基盤を示す「に」。", "で": "「格差で根差した」は手段を表し、基盤を示せない。", "と": "「格差と根差した」は相手を表し、基盤の意味にならない。", "が": "「格差が根差した」は「根差す」の正しい助詞ではなく、不自然。"}, "error_tags": {"で": "手段・場所", "と": "相手・共同", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39283, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「考え方に根差している」の基盤を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「考え方を根差している」は目的語を取る形で、誤り。"}, {"text": "の", "is_correct": false, "explanation": "「考え方の根差している」は連体修飾で、述語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「考え方へ根差している」は方向を表し、基盤の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「考え方に根差している」の基盤を示す「に」。", "を": "「考え方を根差している」は目的語を取る形で、誤り。", "の": "「考え方の根差している」は連体修飾で、述語にならない。", "へ": "「考え方へ根差している」は方向を表し、基盤の意味にならない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39283, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "ある事柄の基盤や原因として、深く結びついていること。", "primary_collocate": null, "pronunciation": "ねざす", "ipa": "nezasɯ", "syllable_count": 3, "sentences": [{"text": "今回の対立は、長年の歴史的な問題に根差している。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "今回[こんかい]の対立[たいりつ]は、長年[ながねん]の歴史的[れきしてき]な問題[もんだい]に根差[ねざ]している。", "sentence_source": "generated"}, {"text": "この事件は、社会の格差に根差した問題だ。", "target_word": "根差した", "complexity_tier": "T3", "furigana": "この事件[じけん]は、社会[しゃかい]の格差[かくさ]に根差[ねざ]した問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "土地の信仰に根差した祭りが、今も毎年開かれている。", "target_word": "根差した", "complexity_tier": "T3", "furigana": "土地[とち]の信仰[しんこう]に根差[ねざ]した祭[まつ]りが、今[いま]も毎年[まいとし]開[ひら]かれている。", "sentence_source": "generated"}, {"text": "地域の暮らしに根差した商店街は、住民に愛されている。", "target_word": "根差した", "complexity_tier": "T3", "furigana": "地域[ちいき]の暮[く]らしに根差[ねざ]した商店街[しょうてんがい]は、住民[じゅうみん]に愛[あい]されている。", "sentence_source": "generated"}, {"text": "差別は、無知や偏見に根差していることが多い。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "差別[さべつ]は、無知[むち]や偏見[へんけん]に根差[ねざ]していることが多[おお]い。", "sentence_source": "generated"}, {"text": "若者の不満は、将来への不安定な雇用に根差している。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "若者[わかもの]の不満[ふまん]は、将来[しょうらい]への不安定[ふあんてい]な雇用[こよう]に根差[ねざ]している。", "sentence_source": "generated"}, {"text": "その争いは、水の利用をめぐる古い対立に根差していた。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "その争[あらそ]いは、水[みず]の利用[りよう]をめぐる古[ふる]い対立[たいりつ]に根差[ねざ]していた。", "sentence_source": "generated"}, {"text": "日本の礼儀は、集団を大切にする考え方に根差している。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "日本[にほん]の礼儀[れいぎ]は、集団[しゅうだん]を大切[たいせつ]にする考[かんが]え方[かた]に根差[ねざ]している。", "sentence_source": "generated"}, {"text": "問題の原因が組織の体質に根差しているなら、簡単には解決しない。", "target_word": "根差して", "complexity_tier": "T3", "furigana": "問題[もんだい]の原因[げんいん]が組織[そしき]の体質[たいしつ]に根差[ねざ]しているなら、簡単[かんたん]には解決[かいけつ]しない。", "sentence_source": "generated"}, {"text": "地元の文化に根差した活動なら、長く続けられる。", "target_word": "根差した", "complexity_tier": "T3", "furigana": "地元[じもと]の文化[ぶんか]に根差[ねざ]した活動[かつどう]なら、長[なが]く続[つづ]けられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "根差す", "label": "終止形"}, {"form": "根差した", "label": "過去形"}, {"form": "根差して", "label": "て形"}, {"form": "根差している", "label": "継続形"}, {"form": "根差さない", "label": "否定形"}], "register": "やや硬い書き言葉", "sense_fingerprint": "問題・習慣・活動などが、歴史や土地や社会の仕組みといった基盤や原因に深く結びついていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e3467d-5cea-4b54-9930-14d540bd33b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39283, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根差して", "is_correct": true, "explanation": "「問題に根差している」の形。対立が長年の問題を基盤としていることを表す。"}, {"text": "解決して", "is_correct": false, "explanation": "「問題に解決している」は意味が通らず、対立の原因を示す文に合わない。"}, {"text": "通知して", "is_correct": false, "explanation": "「問題に通知している」は不自然で、原因を示す文と合わない。"}, {"text": "参加して", "is_correct": false, "explanation": "「問題に参加している」は不自然で、対立の原因という文脈に合わない。"}], "explanations": {"根差して": "「問題に根差している」の形。対立が長年の問題を基盤としていることを表す。", "解決して": "「問題に解決している」は意味が通らず、対立の原因を示す文に合わない。", "通知して": "「問題に通知している」は不自然で、原因を示す文と合わない。", "参加して": "「問題に参加している」は不自然で、対立の原因という文脈に合わない。"}, "sentence_index": 0, "correct_answer": "根差して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その古い石碑は、一度の大雨に根差している。", "explanation": "ここは〈きっかけで建つ〉の意味。根差すは長い歴史をもつ基盤を表すので、一度の天候には合わない。"}, {"text": "この苗は、痩せた土に根差している。", "explanation": "ここは〈植物が根を張る〉の文字どおりの意味。基盤や原因の抽象的な意味ではない。"}, {"text": "この曲の旋律は、一枚の写真に根差している。", "explanation": "ここは〈きっかけとなった〉の意味。根差すは土台となる深い結びつきを表すので、写真一枚には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39283, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根差して", "is_correct": true, "explanation": "「古い対立に根差していた」の形。争いが水をめぐる古い対立を基盤としていたことを表す。"}, {"text": "出発して", "is_correct": false, "explanation": "「古い対立に出発していた」は不自然で、原因を示す文に合わない。"}, {"text": "休憩して", "is_correct": false, "explanation": "「古い対立に休憩していた」は意味が通らず、争いの原因という文と合わない。"}, {"text": "勝利して", "is_correct": false, "explanation": "「古い対立に勝利していた」は不自然で、文の内容に合わない。"}], "explanations": {"根差して": "「古い対立に根差していた」の形。争いが水をめぐる古い対立を基盤としていたことを表す。", "出発して": "「古い対立に出発していた」は不自然で、原因を示す文に合わない。", "休憩して": "「古い対立に休憩していた」は意味が通らず、争いの原因という文と合わない。", "勝利して": "「古い対立に勝利していた」は不自然で、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "根差して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この大木は、深い岩盤に根差している。", "explanation": "ここは〈植物が根を張る〉の文字どおりの意味。基盤や原因の抽象的な意味ではない。"}, {"text": "そのつたは、古い塀の割れ目に根差していた。", "explanation": "ここは〈植物が根を張る〉の文字どおりの意味。基盤や原因の抽象的な意味ではない。"}, {"text": "そのハーブは、鉢の浅い土に根差していた。", "explanation": "ここは〈植物が根を張る〉の文字どおりの意味。基盤や原因の抽象的な意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
