INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39283, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その騒ぎは、地域の古い対立を根差していた。", "corrected_sentence": "その騒ぎは、地域の古い対立に根差していた。", "error_description": "「根差す」は「〜に根差す」の形で使う。「を」は目的語を示すので「対立を根差す」は誤り。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39284, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「主体に作る」は、内容の中心を家族向けにするという意味になり、文が通る。"}, {"text": "が", "is_correct": false, "explanation": "「主体が作られている」では主体が主語になり、文の意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "直前の「内容を」と目的語が重なり、「主体を作られている」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「主体と作られている」は並べる働きの助詞で、文として意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「主体に作る」は、内容の中心を家族向けにするという意味になり、文が通る。", "が": "「主体が作られている」では主体が主語になり、文の意味が通らない。", "を": "直前の「内容を」と目的語が重なり、「主体を作られている」は文として成り立たない。", "と": "「主体と作られている」は並べる働きの助詞で、文として意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語の重複", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39284, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「主体に編成する」は、若い選手を中心にしたチームの構成という意味になり、文が通る。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「主体へ編成」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や材料を表すが、「主体から編成」は組織の作り方として通じない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「主体より編成」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「主体に編成する」は、若い選手を中心にしたチームの構成という意味になり、文が通る。", "へ": "「へ」は方向を表すので、「主体へ編成」では文が成り立たない。", "から": "「から」は起点や材料を表すが、「主体から編成」は組織の作り方として通じない。", "より": "「より」は比較を表すので、「主体より編成」では意味が通らない。"}, "error_tags": {"へ": "方向", "から": "起点・材料", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39284, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなの中心になるもの。", "primary_collocate": null, "pronunciation": "しゅたい", "ipa": "ɕɯtai", "syllable_count": 3, "sentences": [{"text": "この祭りは、地域の住民が主体となって行われる。", "target_word": "主体", "complexity_tier": "T3", "furigana": "この祭[まつ]りは、地域[ちいき]の住民[じゅうみん]が主体[しゅたい]となって行[おこな]われる。", "sentence_source": "generated"}, {"text": "この番組は、家族で楽しめる内容を主体に作られている。", "target_word": "主体", "complexity_tier": "T3", "furigana": "この番組[ばんぐみ]は、家族[かぞく]で楽[たの]しめる内容[ないよう]を主体[しゅたい]に作[つく]られている。", "sentence_source": "generated"}, {"text": "学校行事では、生徒が主体になって計画を立てた。", "target_word": "主体", "complexity_tier": "T3", "furigana": "学校[がっこう]行事[ぎょうじ]では、生徒[せいと]が主体[しゅたい]になって計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "子どもが主体の活動だから、大人は手を出さないでください。", "target_word": "主体", "complexity_tier": "T3", "furigana": "子[こ]どもが主体[しゅたい]の活動[かつどう]だから、大人[おとな]は手[て]を出[だ]さないでください。", "sentence_source": "generated"}, {"text": "この会は、大学生を主体として作られた団体です。", "target_word": "主体", "complexity_tier": "T3", "furigana": "この会[かい]は、大学生[だいがくせい]を主体[しゅたい]として作[つく]られた団体[だんたい]です。", "sentence_source": "generated"}, {"text": "実行委員会が主体となり、駅前で募金を行った。", "target_word": "主体", "complexity_tier": "T3", "furigana": "実行[じっこう]委員会[いいんかい]が主体[しゅたい]となり、駅前[えきまえ]で募金[ぼきん]を行[おこな]った。", "sentence_source": "generated"}, {"text": "この店では、季節の野菜を主体にした料理を出している。", "target_word": "主体", "complexity_tier": "T3", "furigana": "この店[みせ]では、季節[きせつ]の野菜[やさい]を主体[しゅたい]にした料理[りょうり]を出[だ]している。", "sentence_source": "generated"}, {"text": "このチームは、若い選手を主体に編成されている。", "target_word": "主体", "complexity_tier": "T3", "furigana": "このチームは、若[わか]い選手[せんしゅ]を主体[しゅたい]に編成[へんせい]されている。", "sentence_source": "generated"}, {"text": "この地域は、農業を主体とした経済で成り立ってきた。", "target_word": "主体", "complexity_tier": "T3", "furigana": "この地域[ちいき]は、農業[のうぎょう]を主体[しゅたい]とした経済[けいざい]で成[な]り立[た]ってきた。", "sentence_source": "generated"}, {"text": "住民が主体の話し合いで、公園の使い方が決まった。", "target_word": "主体", "complexity_tier": "T3", "furigana": "住民[じゅうみん]が主体[しゅたい]の話[はな]し合[あ]いで、公園[こうえん]の使[つか]い方[かた]が決[き]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主体", "label": "基本形"}], "register": "中立（やや硬い書き言葉）", "sense_fingerprint": "活動や組織の中心となって、物事を進める人やグループ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e3467d-5cea-4b54-9930-14d540bd33b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39284, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主体", "is_correct": true, "explanation": "「主体となって」は、住民が中心になって祭りを進めるという意味になり、ここに入る。"}, {"text": "予算", "is_correct": false, "explanation": "予算は使う金額の計画のことで、住民が中心になるという文脈には入らない。"}, {"text": "期間", "is_correct": false, "explanation": "期間は時間の長さを表すので、人が中心となって行うという意味にはならない。"}, {"text": "形式", "is_correct": false, "explanation": "形式は行事の決まった型を指すので、住民が中心になるという意味にはならない。"}], "explanations": {"主体": "「主体となって」は、住民が中心になって祭りを進めるという意味になり、ここに入る。", "予算": "予算は使う金額の計画のことで、住民が中心になるという文脈には入らない。", "期間": "期間は時間の長さを表すので、人が中心となって行うという意味にはならない。", "形式": "形式は行事の決まった型を指すので、住民が中心になるという意味にはならない。"}, "sentence_index": 0, "correct_answer": "主体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その武将は、主体に最後まで仕えた。", "explanation": "ここは〈主君〉の意味。仕える相手は主君と言い、主体は仕える対象にならないので合わない。"}, {"text": "その映画では、祖母が主体を演じて、観客を笑わせた。", "explanation": "ここは〈主役〉の意味。映画の中心人物は主役と言い、主体は中心になって動く人や集団を指すので合わない。"}, {"text": "戦艦の主体が火を噴いた。", "explanation": "ここは〈主砲〉の意味。戦艦で火を噴く大砲は主砲と言い、主体は火を噴かないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39284, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主体", "is_correct": true, "explanation": "「主体にした料理」は、野菜を中心に使った料理という意味になり、文に合う。"}, {"text": "味付け", "is_correct": false, "explanation": "味付けは調味の仕方のことで、「野菜を味付けにした料理」では文が通らない。"}, {"text": "期限", "is_correct": false, "explanation": "期限は期日のことで、野菜を期限にするという文の流れには合わない。"}, {"text": "節約", "is_correct": false, "explanation": "節約は費用を抑えることで、野菜をそれにするという意味にならない。"}], "explanations": {"主体": "「主体にした料理」は、野菜を中心に使った料理という意味になり、文に合う。", "味付け": "味付けは調味の仕方のことで、「野菜を味付けにした料理」では文が通らない。", "期限": "期限は期日のことで、野菜を期限にするという文の流れには合わない。", "節約": "節約は費用を抑えることで、野菜をそれにするという意味にならない。"}, "sentence_index": 6, "correct_answer": "主体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は自分の主体を曲げず、最後まで反対し続けた。", "explanation": "ここは〈主張〉の意味。自分の意見を通すことは主張と言い、主体は人や集団が中心となって動くことなので合わない。"}, {"text": "強い風で、橋の主体が折れてしまった。", "explanation": "ここは〈主桁〉の意味。橋を支える太い梁を主桁と言い、主体は折れる部材の名前ではないので合わない。"}, {"text": "家臣は主体を裏切らないと、固く誓った。", "explanation": "ここは〈主君〉の意味。忠誠を誓う相手は主君と言い、主体は誓う対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39284, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会議は、若者が主体で進め方を決めた。", "corrected_sentence": "この会議は、若者が主体となって進め方を決めた。", "error_description": "「主体」は「主体となって」「主体として」の形で使う。「主体で」は不自然で、「で」は誤り。正しくは「主体となって」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39284, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい公園は、住民が主体へ計画された。", "corrected_sentence": "新しい公園は、住民が主体となって計画された。", "error_description": "「主体」は「主体となって」「主体として」の形で使う。「へ」は方向を示す助詞なので、ここでは誤り。正しくは「主体となって」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39287, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「山林を持つ」は山林を所有するという意味になり、文が通る。"}, {"text": "が", "is_correct": false, "explanation": "「山林が持っていて」では山林が持つ主語になり、文の意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「山林に持っていて」では、持つ対象を示せず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「山林で持っていて」では、持つ場所にはならず、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「山林を持つ」は山林を所有するという意味になり、文が通る。", "が": "「山林が持っていて」では山林が持つ主語になり、文の意味が通らない。", "に": "「山林に持っていて」では、持つ対象を示せず、文が成り立たない。", "で": "「山林で持っていて」では、持つ場所にはならず、文が通らない。"}, "error_tags": {"が": "主語", "に": "位置", "で": "場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39287, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「山林の中」は山林の内側という意味になり、文が通る。"}, {"text": "を", "is_correct": false, "explanation": "「山林を中は」では目的語になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「山林へ中は」は方向を示す語になり、文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「山林と中は」では並べる相手になり、文が通らない。"}], "correct_answer": "の", "explanations": {"の": "「山林の中」は山林の内側という意味になり、文が通る。", "を": "「山林を中は」では目的語になり、文が成り立たない。", "へ": "「山林へ中は」は方向を示す語になり、文の意味が通らない。", "と": "「山林と中は」では並べる相手になり、文が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39287, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "山や野にある、木がたくさん生えている場所。", "primary_collocate": null, "pronunciation": "さんりん", "ipa": "saɴɾiɴ", "syllable_count": 4, "sentences": [{"text": "この山林には、百年以上たった杉の木がたくさんあります。", "target_word": "山林", "complexity_tier": "T3", "furigana": "この山林(さんりん)には、百年(ひゃくねん)以上(いじょう)たった杉(すぎ)の木(き)がたくさんあります。", "sentence_source": "generated"}, {"text": "祖父は山林を持っていて、毎年木を切って売っています。", "target_word": "山林", "complexity_tier": "T3", "furigana": "祖父(そふ)は山林(さんりん)を持(も)っていて、毎年(まいとし)木(き)を切(き)って売(う)っています。", "sentence_source": "generated"}, {"text": "山林で道に迷ったので、救助隊が捜しに行きました。", "target_word": "山林", "complexity_tier": "T3", "furigana": "山林(さんりん)で道(みち)に迷(まよ)ったので、救助隊(きゅうじょたい)が捜(さが)しに行(い)きました。", "sentence_source": "generated"}, {"text": "大雨のあと、山林の土が崩れて道がふさがれた。", "target_word": "山林", "complexity_tier": "T3", "furigana": "大雨(おおあめ)のあと、山林(さんりん)の土(つち)が崩(くず)れて道(みち)がふさがれた。", "sentence_source": "generated"}, {"text": "山林を守るために、町の人たちは毎年木を植えています。", "target_word": "山林", "complexity_tier": "T3", "furigana": "山林(さんりん)を守(まも)るために、町(まち)の人(ひと)たちは毎年(まいとし)木(き)を植(う)えています。", "sentence_source": "generated"}, {"text": "火事が起きて、広い山林が焼けてしまった。", "target_word": "山林", "complexity_tier": "T3", "furigana": "火事(かじ)が起(お)きて、広(ひろ)い山林(さんりん)が焼(や)けてしまった。", "sentence_source": "generated"}, {"text": "この町は面積の八割が山林なので、畑が少ない。", "target_word": "山林", "complexity_tier": "T3", "furigana": "この町(まち)は面積(めんせき)の八割(はちわり)が山林(さんりん)なので、畑(はたけ)が少(すく)ない。", "sentence_source": "generated"}, {"text": "山林の中は空気がきれいで、夏でも涼しいです。", "target_word": "山林", "complexity_tier": "T3", "furigana": "山林(さんりん)の中(なか)は空気(くうき)がきれいで、夏(なつ)でも涼(すず)しいです。", "sentence_source": "generated"}, {"text": "父は山林の手入れをするため、朝早く山へ出かけた。", "target_word": "山林", "complexity_tier": "T3", "furigana": "父(ちち)は山林(さんりん)の手入(てい)れをするため、朝早(あさはや)く山(やま)へ出(で)かけた。", "sentence_source": "generated"}, {"text": "山林を買った会社が、木を切って道を作る計画を発表した。", "target_word": "山林", "complexity_tier": "T3", "furigana": "山林(さんりん)を買(か)った会社(かいしゃ)が、木(き)を切(き)って道(みち)を作(つく)る計画(けいかく)を発表(はっぴょう)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "山林", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "山や野で木が多く生えている場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e3467d-5cea-4b54-9930-14d540bd33b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39287, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山林", "is_correct": true, "explanation": "「この山林には」は、木がたくさん生えた場所という意味で、ここに入る。"}, {"text": "工具", "is_correct": false, "explanation": "工具は手で使う道具で、杉の木がたくさんある場所を指すことはできない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文書で、木が生えている場所の意味にはならない。"}, {"text": "給食", "is_correct": false, "explanation": "給食は学校の食事で、杉の木が生えている場所にはならない。"}], "explanations": {"山林": "「この山林には」は、木がたくさん生えた場所という意味で、ここに入る。", "工具": "工具は手で使う道具で、杉の木がたくさんある場所を指すことはできない。", "手紙": "手紙は文書で、木が生えている場所の意味にはならない。", "給食": "給食は学校の食事で、杉の木が生えている場所にはならない。"}, "sentence_index": 0, "correct_answer": "山林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨のあと、山林が起きて道がふさがれた。", "explanation": "ここは〈地滑り〉の意味。土地がずれ落ちる現象を指し、山林は起きる出来事ではないので合わない。"}, {"text": "この町では、山林を獲る人が多い。", "explanation": "ここは〈獲物〉の意味。狩りで捕まえるのは獲物で、山林は場所なので獲ることはできないので合わない。"}, {"text": "台風で山林が破裂して、町中が断水した。", "explanation": "ここは〈水道管〉の意味。破裂するのは水を通す管で、山林は土地を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39287, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山林", "is_correct": true, "explanation": "「面積の八割が山林」は、町の大部分が木の生えた土地という意味になり、ここに入る。"}, {"text": "畳", "is_correct": false, "explanation": "畳は床に敷く敷物で、面積の八割を占める土地の種類にはならない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は通信機器で、町の面積の八割を占める対象にはならない。"}, {"text": "定休日", "is_correct": false, "explanation": "定休日は店が休む日のことで、面積を表す語にはならない。"}], "explanations": {"山林": "「面積の八割が山林」は、町の大部分が木の生えた土地という意味になり、ここに入る。", "畳": "畳は床に敷く敷物で、面積の八割を占める土地の種類にはならない。", "電話": "電話は通信機器で、町の面積の八割を占める対象にはならない。", "定休日": "定休日は店が休む日のことで、面積を表す語にはならない。"}, "sentence_index": 6, "correct_answer": "山林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は朝早く川へ出て、大きな山林を釣り上げた。", "explanation": "ここは〈魚〉の意味。釣り上げる対象は魚などの生き物で、山林は土地を表すので合わない。"}, {"text": "春になり、池の山林がとけた。", "explanation": "ここは〈氷〉の意味。とけるのは氷や雪などで、山林は土地を指すのでとけないので合わない。"}, {"text": "夕方になり、海の山林が満ちてきた。", "explanation": "ここは〈潮〉の意味。満ちたり引いたりするのは潮で、山林は満ちることはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39287, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休みの日、父は山林が手入れをしている。", "corrected_sentence": "休みの日、父は山林の手入れをしている。", "error_description": "「手入れ」の前は「の」で結ぶ。「山林が」の「が」は誤り。正しくは「山林の手入れ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39287, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町は山林へ遠く、車がないと不便だ。", "corrected_sentence": "この町は山林から遠く、車がないと不便だ。", "error_description": "「遠い」は「から」で起点を示すので、「へ」は誤り。正しくは「山林から遠い」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39288, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「勉強に取り組んで」は取り組む対象を示す格助詞で、文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「勉強を取り組んで」は目的語の格にならず、取り組むとは結べない。"}, {"text": "が", "is_correct": false, "explanation": "「勉強が取り組んで」は勉強を主語にしてしまい、取り組む人の動作を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「勉強の取り組んでいる」は名詞の後に動詞を直接続けられず、文の形が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「勉強に取り組んで」は取り組む対象を示す格助詞で、文の意味に合う。", "を": "「勉強を取り組んで」は目的語の格にならず、取り組むとは結べない。", "が": "「勉強が取り組んで」は勉強を主語にしてしまい、取り組む人の動作を表せない。", "の": "「勉強の取り組んでいる」は名詞の後に動詞を直接続けられず、文の形が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39288, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「工作に取り組んでいる」は取り組む対象を示す格助詞で、文の意味に合う。"}, {"text": "の", "is_correct": false, "explanation": "「工作の取り組んでいる」は名詞につながらず、取り組む対象を示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「工作より取り組んでいる」は比較の意味になり、取り組む対象を示す形に合わないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「工作で取り組んでいる」は手段や場所を示し、取り組む対象を表せないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「工作に取り組んでいる」は取り組む対象を示す格助詞で、文の意味に合う。", "の": "「工作の取り組んでいる」は名詞につながらず、取り組む対象を示せないので合わない。", "より": "「工作より取り組んでいる」は比較の意味になり、取り組む対象を示す形に合わないので合わない。", "で": "「工作で取り組んでいる」は手段や場所を示し、取り組む対象を表せないので合わない。"}, "error_tags": {"の": "所属・修飾", "より": "比較", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39288, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを一生懸命にやってみること。", "primary_collocate": null, "pronunciation": "とりくむ", "ipa": "toɾikɯmɯ", "syllable_count": 4, "sentences": [{"text": "宿題に取り組む前に、お茶を飲んだ。", "target_word": "取り組む", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]に取[と]り組[く]む前[まえ]に、お茶[ちゃ]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "彼は毎日、漢字の勉強に取り組んでいる。", "target_word": "取り組んで", "complexity_tier": "T3", "furigana": "彼[かれ]は毎日[まいにち]、漢字[かんじ]の勉強[べんきょう]に取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "新しい仕事に取り組むのは、少し緊張する。", "target_word": "取り組む", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]に取[と]り組[く]むのは、少[すこ]し緊張[きんちょう]する。", "sentence_source": "generated"}, {"text": "みんなで掃除に取り組んだら、早く終わった。", "target_word": "取り組んだ", "complexity_tier": "T3", "furigana": "みんなで掃除[そうじ]に取[と]り組[く]んだら、早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "難しい問題でも、あきらめずに取り組もう。", "target_word": "取り組もう", "complexity_tier": "T3", "furigana": "難[むずか]しい問題[もんだい]でも、あきらめずに取[と]り組[く]もう。", "sentence_source": "generated"}, {"text": "姉は絵の練習に取り組んで、上手になった。", "target_word": "取り組んで", "complexity_tier": "T3", "furigana": "姉[あね]は絵[え]の練習[れんしゅう]に取[と]り組[く]んで、上手[じょうず]になった。", "sentence_source": "generated"}, {"text": "私は今年、ダイエットに取り組むことにした。", "target_word": "取り組む", "complexity_tier": "T3", "furigana": "私[わたし]は今年[ことし]、ダイエットに取[と]り組[く]むことにした。", "sentence_source": "generated"}, {"text": "子どもが楽しそうに工作に取り組んでいる。", "target_word": "取り組んで", "complexity_tier": "T3", "furigana": "子[こ]どもが楽[たの]しそうに工作[こうさく]に取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "まじめに取り組まなければ、試験には受からない。", "target_word": "取り組まなければ", "complexity_tier": "T3", "furigana": "まじめに取[と]り組[く]まなければ、試験[しけん]には受[う]からない。", "sentence_source": "generated"}, {"text": "初めて料理に取り組んだ日のことを覚えている。", "target_word": "取り組んだ", "complexity_tier": "T3", "furigana": "初[はじ]めて料理[りょうり]に取[と]り組[く]んだ日[ひ]のことを覚[おぼ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り組む", "label": "基本形"}, {"form": "取り組み", "label": "連用形"}, {"form": "取り組んで", "label": "て形"}, {"form": "取り組んだ", "label": "た形"}, {"form": "取り組まない", "label": "ない形"}], "register": "中立", "sense_fingerprint": "勉強や作業などを一生懸命にやる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39288, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り組む", "is_correct": true, "explanation": "「宿題に取り組む前に」は宿題を一生懸命にやる意味になり、お茶を飲んだという文に自然につながる。"}, {"text": "食べる", "is_correct": false, "explanation": "「宿題に食べる」は宿題を食べ物のように扱う意味になり、文として成り立たない。"}, {"text": "飲む", "is_correct": false, "explanation": "「宿題に飲む」は飲む対象として宿題が成り立たず、空欄に入ると意味が通らない。"}, {"text": "寝る", "is_correct": false, "explanation": "「宿題に寝る」は寝る対象として宿題を取れず、「前に」と続けても意味が成り立たない。"}], "explanations": {"取り組む": "「宿題に取り組む前に」は宿題を一生懸命にやる意味になり、お茶を飲んだという文に自然につながる。", "食べる": "「宿題に食べる」は宿題を食べ物のように扱う意味になり、文として成り立たない。", "飲む": "「宿題に飲む」は飲む対象として宿題が成り立たず、空欄に入ると意味が通らない。", "寝る": "「宿題に寝る」は寝る対象として宿題を取れず、「前に」と続けても意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "取り組む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "かばんから財布を取り組んだ。", "explanation": "ここは〈取り出す〉の意味。中にある物を引き出す行為は取り出すで表し、取り組むは使えないので合わない。"}, {"text": "予約を取り組んだ。", "explanation": "ここは〈取り消す〉の意味。決めていた予約をなくす行為は取り消すで表し、取り組むは合わない。"}, {"text": "電池を取り組んだ。", "explanation": "ここは〈取り替える〉の意味。古い物を新しい物に換える行為は取り替えるで表し、取り組むは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39288, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り組む", "is_correct": true, "explanation": "「ダイエットに取り組むことにした」は、ダイエットに努力して向き合う決意の文として成り立つ。"}, {"text": "食べる", "is_correct": false, "explanation": "「ダイエットに食べる」はダイエットを食べ物のように扱う意味になり、決意の文に合わない。"}, {"text": "休む", "is_correct": false, "explanation": "「ダイエットに休む」は休む対象としてダイエットが成り立たず、ことにした内容に合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "「ダイエットに眠る」は眠る対象として成り立たず、空欄に入ると意味が通らない。"}], "explanations": {"取り組む": "「ダイエットに取り組むことにした」は、ダイエットに努力して向き合う決意の文として成り立つ。", "食べる": "「ダイエットに食べる」はダイエットを食べ物のように扱う意味になり、決意の文に合わない。", "休む": "「ダイエットに休む」は休む対象としてダイエットが成り立たず、ことにした内容に合わない。", "眠る": "「ダイエットに眠る」は眠る対象として成り立たず、空欄に入ると意味が通らない。"}, "sentence_index": 6, "correct_answer": "取り組む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもからゲームを取り組んだ。", "explanation": "ここは〈取り上げる〉の意味。手にしている物を奪う行為は取り上げるで表し、取り組むは合わない。"}, {"text": "来客の電話を取り組んだ。", "explanation": "ここは〈取り次ぐ〉の意味。電話を別の人へつなぐ行為は取り次ぐで表し、取り組むは使わない。"}, {"text": "古いネジを取り組んだ。", "explanation": "ここは〈取り外す〉の意味。部品を外す行為は取り外すで表し、取り組むは使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39288, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は毎日、英語の勉強を取り組んでいる。", "corrected_sentence": "彼は毎日、英語の勉強に取り組んでいる。", "error_description": "「取り組む」は「〜に取り組む」の形をとり、取り組む対象を「に」で示す。「を」は誤りで、正しくは「勉強に取り組んでいる」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り組んで", "is_correct": true, "explanation": "「取り組んでいる」の「て形」で、「〜ている」に続く形として文中の形に合う。"}, {"text": "取り組み", "is_correct": false, "explanation": "連用形のままでは「いる」と続かず、「勉強に取り組みいる」は文として成り立たない。"}, {"text": "取り組んだ", "is_correct": false, "explanation": "「た形」は「いる」と続かず、「取り組んだいる」は文の形にならない。"}, {"text": "取り組まない", "is_correct": false, "explanation": "「ない形」は「いる」と続かず、否定の意味にもならないので空欄に入らない。"}], "correct_form": "取り組んで", "base_form": "取り組む", "form_label": "て形", "sentence_index": 1, "explanations": {"取り組んで": "「取り組んでいる」の「て形」で、「〜ている」に続く形として文中の形に合う。", "取り組み": "連用形のままでは「いる」と続かず、「勉強に取り組みいる」は文として成り立たない。", "取り組んだ": "「た形」は「いる」と続かず、「取り組んだいる」は文の形にならない。", "取り組まない": "「ない形」は「いる」と続かず、否定の意味にもならないので空欄に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39288, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎日、練習に取り組むなければ上達しない。", "corrected_sentence": "毎日、練習に取り組まなければ上達しない。", "error_description": "「〜なければ」は「ない形」に続けるので、正しくは「取り組まなければ」。「取り組むなければ」は動詞の形が誤っている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り組んで", "is_correct": true, "explanation": "「工作に取り組んでいる」の「て形」で、「〜ている」に続く形として文中の形に合う。"}, {"text": "取り組む", "is_correct": false, "explanation": "辞書形の「取り組む」は「いる」と続かず、「工作に取り組むいる」は文の形にならない。"}, {"text": "取り組もう", "is_correct": false, "explanation": "意志形の「取り組もう」は「いる」と続かず、「取り組もういる」は文の形にならない。"}, {"text": "取り組め", "is_correct": false, "explanation": "命令形の「取り組め」は「いる」と続かず、「取り組めいる」は成り立たない。"}], "correct_form": "取り組んで", "base_form": "取り組む", "form_label": "て形", "sentence_index": 7, "explanations": {"取り組んで": "「工作に取り組んでいる」の「て形」で、「〜ている」に続く形として文中の形に合う。", "取り組む": "辞書形の「取り組む」は「いる」と続かず、「工作に取り組むいる」は文の形にならない。", "取り組もう": "意志形の「取り組もう」は「いる」と続かず、「取り組もういる」は文の形にならない。", "取り組め": "命令形の「取り組め」は「いる」と続かず、「取り組めいる」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39289, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「課題に取り組んだ」は取り組む対象を示す格助詞で、文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「課題を取り組んだ」は目的語の格にならず、取り組むとは結べない。"}, {"text": "が", "is_correct": false, "explanation": "「課題が取り組んだ」は課題を主語にしてしまい、取り組む人の動作を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「課題の取り組んだ」は名詞の後に動詞を直接続けられず、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「課題に取り組んだ」は取り組む対象を示す格助詞で、文の意味に合う。", "を": "「課題を取り組んだ」は目的語の格にならず、取り組むとは結べない。", "が": "「課題が取り組んだ」は課題を主語にしてしまい、取り組む人の動作を表せない。", "の": "「課題の取り組んだ」は名詞の後に動詞を直接続けられず、文として成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39289, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「対策に取り組む方針」は取り組む対象を示す格助詞で、政府の方針の意味に合う。"}, {"text": "で", "is_correct": false, "explanation": "「対策で取り組む方針」は手段を表す「で」になり、取り組みの対象を示す形に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「対策と取り組む方針」は共同の「と」になり、取り組みの対象を示す形に合わず、文として不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "「対策より取り組む方針」は比較の意味になり、取り組みの対象を示す形に合わず、文の意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「対策に取り組む方針」は取り組む対象を示す格助詞で、政府の方針の意味に合う。", "で": "「対策で取り組む方針」は手段を表す「で」になり、取り組みの対象を示す形に合わない。", "と": "「対策と取り組む方針」は共同の「と」になり、取り組みの対象を示す形に合わず、文として不自然になる。", "より": "「対策より取り組む方針」は比較の意味になり、取り組みの対象を示す形に合わず、文の意味が通らない。"}, "error_tags": {"で": "手段", "と": "共同", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39289, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある目標や問題に対して、積極的にかかわって努力すること。", "primary_collocate": null, "pronunciation": "とりくむ", "ipa": "toɾikɯmɯ", "syllable_count": 4, "sentences": [{"text": "市は環境問題に取り組んでいる。", "target_word": "取り組んで", "complexity_tier": "T3", "furigana": "市[し]は環境問題[かんきょうもんだい]に取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "会社全体で、ミスを減らす課題に取り組んだ。", "target_word": "取り組んだ", "complexity_tier": "T3", "furigana": "会社全体[かいしゃぜんたい]で、ミスを減[へ]らす課題[かだい]に取[と]り組[く]んだ。", "sentence_source": "generated"}, {"text": "彼女は長年、病気の研究に取り組んできた。", "target_word": "取り組んで", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は長年[ながねん]、病気[びょうき]の研究[けんきゅう]に取[と]り組[く]んできた。", "sentence_source": "generated"}, {"text": "問題の解決に積極的に取り組む姿勢が大切だ。", "target_word": "取り組む", "complexity_tier": "T3", "furigana": "問題[もんだい]の解決[かいけつ]に積極的[せっきょくてき]に取[と]り組[く]む姿勢[しせい]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "チームは優勝という目標に向かって取り組んでいる。", "target_word": "取り組んで", "complexity_tier": "T3", "furigana": "チームは優勝[ゆうしょう]という目標[もくひょう]に向[む]かって取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "地域の人と協力して、ごみの問題に取り組みたい。", "target_word": "取り組みたい", "complexity_tier": "T3", "furigana": "地域[ちいき]の人[ひと]と協力[きょうりょく]して、ごみの問題[もんだい]に取[と]り組[く]みたい。", "sentence_source": "generated"}, {"text": "新しい課題に取り組むたびに、力がついた。", "target_word": "取り組む", "complexity_tier": "T3", "furigana": "新[あたら]しい課題[かだい]に取[と]り組[く]むたびに、力[ちから]がついた。", "sentence_source": "generated"}, {"text": "政府は人口減少の対策に取り組む方針だ。", "target_word": "取り組む", "complexity_tier": "T3", "furigana": "政府[せいふ]は人口減少[じんこうげんしょう]の対策[たいさく]に取[と]り組[く]む方針[ほうしん]だ。", "sentence_source": "generated"}, {"text": "彼は借金を返すために、仕事に取り組んだ。", "target_word": "取り組んだ", "complexity_tier": "T3", "furigana": "彼[かれ]は借金[しゃっきん]を返[かえ]すために、仕事[しごと]に取[と]り組[く]んだ。", "sentence_source": "generated"}, {"text": "学生たちは、町の防災の課題に取り組んでいる。", "target_word": "取り組んで", "complexity_tier": "T3", "furigana": "学生[がくせい]たちは、町[まち]の防災[ぼうさい]の課題[かだい]に取[と]り組[く]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り組む", "label": "基本形"}, {"form": "取り組み", "label": "連用形"}, {"form": "取り組んで", "label": "て形"}, {"form": "取り組んだ", "label": "た形"}, {"form": "取り組まない", "label": "ない形"}], "register": "中立", "sense_fingerprint": "目標や課題に積極的に向き合って努力する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39289, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り組んで", "is_correct": true, "explanation": "「環境問題に取り組んでいる」は環境問題に努力して向き合う様子を表し、文の意味に合う。"}, {"text": "食べて", "is_correct": false, "explanation": "「環境問題に食べている」は食べる対象として環境問題が成り立たず、空欄に入ると意味が通らない。"}, {"text": "眠って", "is_correct": false, "explanation": "「環境問題に眠っている」は眠る対象として成り立たず、文として意味が通らない。"}, {"text": "笑って", "is_correct": false, "explanation": "「環境問題に笑っている」は笑う対象として環境問題を取れず、市の取り組みを表せない。"}], "explanations": {"取り組んで": "「環境問題に取り組んでいる」は環境問題に努力して向き合う様子を表し、文の意味に合う。", "食べて": "「環境問題に食べている」は食べる対象として環境問題が成り立たず、空欄に入ると意味が通らない。", "眠って": "「環境問題に眠っている」は眠る対象として成り立たず、文として意味が通らない。", "笑って": "「環境問題に笑っている」は笑う対象として環境問題を取れず、市の取り組みを表せない。"}, "sentence_index": 0, "correct_answer": "取り組んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "申請を取り組んだ。", "explanation": "ここは〈取り下げる〉の意味。出した申請を引っ込める行為は取り下げるで表し、取り組むは使わないので合わない。"}, {"text": "カタログを取り組んだ。", "explanation": "ここは〈取り寄せる〉の意味。取り寄せて届けてもらう行為は取り寄せるで表し、取り組むは合わない。"}, {"text": "電球を取り組んだ。", "explanation": "ここは〈取り替える〉の意味。切れた電球を新しい物に換える行為は取り替えるで表し、取り組むは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39289, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り組む", "is_correct": true, "explanation": "「新しい課題に取り組むたびに」は課題に努力して向き合う意味になり、力がついたという文に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "「新しい課題に食べるたびに」は課題を食べ物のように扱う意味になり、文として成り立たない。"}, {"text": "眠る", "is_correct": false, "explanation": "「新しい課題に眠るたびに」は眠る対象として課題が成り立たず、空欄に入ると意味が通らない。"}, {"text": "笑う", "is_correct": false, "explanation": "「新しい課題に笑うたびに」は笑う対象として課題を取れず、力がついた理由にならない。"}], "explanations": {"取り組む": "「新しい課題に取り組むたびに」は課題に努力して向き合う意味になり、力がついたという文に合う。", "食べる": "「新しい課題に食べるたびに」は課題を食べ物のように扱う意味になり、文として成り立たない。", "眠る": "「新しい課題に眠るたびに」は眠る対象として課題が成り立たず、空欄に入ると意味が通らない。", "笑う": "「新しい課題に笑うたびに」は笑う対象として課題を取れず、力がついた理由にならない。"}, "sentence_index": 6, "correct_answer": "取り組む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもから危ないおもちゃを取り組んだ。", "explanation": "ここは〈取り上げる〉の意味。手にしている物を奪う行為は取り上げるで表し、取り組むは合わない。"}, {"text": "会社の受付で、電話を取り組んだ。", "explanation": "ここは〈取り次ぐ〉の意味。電話を別の人へつなぐ行為は取り次ぐで表し、取り組むは使わない。"}, {"text": "古い窓枠を取り組んだ。", "explanation": "ここは〈取り外す〉の意味。取り付けた物を外す行為は取り外すで表し、取り組むは使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39289, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地域の課題を取り組んでいる団体がある。", "corrected_sentence": "地域の課題に取り組んでいる団体がある。", "error_description": "「取り組む」は「〜に取り組む」の形をとり、対象を「に」で示す。「を」は誤りで、正しくは「課題に取り組んでいる」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り組んだ", "is_correct": true, "explanation": "「課題に取り組んだ」の「た形」で、過去の動作を表し文の形に合う。"}, {"text": "取り組み", "is_correct": false, "explanation": "連用形のままでは文が終わらず、「課題に取り組み。」は過去の文の形にならない。"}, {"text": "取り組んで", "is_correct": false, "explanation": "「て形」は「た」の形にならず、文が途中で止まってしまう。"}, {"text": "取り組まない", "is_correct": false, "explanation": "「ない形」は「た」と続かず、否定の意味にもならないので空欄に入らない。"}], "correct_form": "取り組んだ", "base_form": "取り組む", "form_label": "た形", "sentence_index": 1, "explanations": {"取り組んだ": "「課題に取り組んだ」の「た形」で、過去の動作を表し文の形に合う。", "取り組み": "連用形のままでは文が終わらず、「課題に取り組み。」は過去の文の形にならない。", "取り組んで": "「て形」は「た」の形にならず、文が途中で止まってしまう。", "取り組まない": "「ない形」は「た」と続かず、否定の意味にもならないので空欄に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39289, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域の安全の課題に取り組みことにした。", "corrected_sentence": "地域の安全の課題に取り組むことにした。", "error_description": "「〜ことにする」は動詞の辞書形に続けるので、正しくは「取り組むこと」。「取り組みこと」は動詞の形が誤っている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り組む", "is_correct": true, "explanation": "「取り組む方針」の基本形で、名詞の「方針」を直接修飾しており文の形に合う。"}, {"text": "取り組んで", "is_correct": false, "explanation": "「て形」は名詞を直接修飾できず、「取り組んで方針」は文として成り立たない。"}, {"text": "取り組め", "is_correct": false, "explanation": "命令形は名詞を直接修飾できず、「取り組め方針」は意味が通らない。"}, {"text": "取り組まれ", "is_correct": false, "explanation": "受け身の連用形のままでは「方針」を修飾できず、「取り組まれ方針」は文の形にならない。"}], "correct_form": "取り組む", "base_form": "取り組む", "form_label": "基本形", "sentence_index": 7, "explanations": {"取り組む": "「取り組む方針」の基本形で、名詞の「方針」を直接修飾しており文の形に合う。", "取り組んで": "「て形」は名詞を直接修飾できず、「取り組んで方針」は文として成り立たない。", "取り組め": "命令形は名詞を直接修飾できず、「取り組め方針」は意味が通らない。", "取り組まれ": "受け身の連用形のままでは「方針」を修飾できず、「取り組まれ方針」は文の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39291, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「移住するには」の「に」は、移住するための条件を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「移住するへは」は動詞の後に方向の助詞が続かず、成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「移住するをは」は不自然で、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「移住するがは」は主語の形にならず、文の構造が崩れる。"}], "correct_answer": "に", "explanations": {"に": "「移住するには」の「に」は、移住するための条件を示す。", "へ": "「移住するへは」は動詞の後に方向の助詞が続かず、成り立たない。", "を": "「移住するをは」は不自然で、文が成り立たない。", "が": "「移住するがは」は主語の形にならず、文の構造が崩れる。"}, "error_tags": {"へ": "方向", "を": "目的語", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39291, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39291, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "住む場所や生活の拠点を、別の地域や国に変えること。", "primary_collocate": null, "pronunciation": "いじゅう", "ipa": "id͡ʑɯː", "syllable_count": 3, "sentences": [{"text": "彼は定年後、田舎への移住を考えている。", "target_word": "移住", "complexity_tier": "T3", "furigana": "彼[かれ]は定年後[ていねんご]、田舎[いなか]への移住[いじゅう]を考[かんが]えている。", "sentence_source": "generated"}, {"text": "移住するには、ビザの申請が必要だ。", "target_word": "移住", "complexity_tier": "T3", "furigana": "移住[いじゅう]するには、ビザの申請[しんせい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "子どもの教育のため、一家はカナダへの移住を決めた。", "target_word": "移住", "complexity_tier": "T3", "furigana": "子[こ]どもの教育[きょういく]のため、一家[いっか]はカナダへの移住[いじゅう]を決[き]めた。", "sentence_source": "generated"}, {"text": "市は都会からの移住を勧めるために、家賃の補助を始めた。", "target_word": "移住", "complexity_tier": "T3", "furigana": "市[し]は都会[とかい]からの移住[いじゅう]を勧[すす]めるために、家賃[やちん]の補助[ほじょ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "移住して三年たつが、新しい町の暮らしにはまだ慣れない。", "target_word": "移住", "complexity_tier": "T3", "furigana": "移住[いじゅう]して三年[さんねん]たつが、新[あたら]しい町[まち]の暮[く]らしにはまだ慣[な]れない。", "sentence_source": "generated"}, {"text": "海外移住の前に、現地の言葉を勉強しておくとよい。", "target_word": "移住", "complexity_tier": "T3", "furigana": "海外[かいがい]移住[いじゅう]の前[まえ]に、現地[げんち]の言葉[ことば]を勉強[べんきょう]しておくとよい。", "sentence_source": "generated"}, {"text": "彼女は来月の移住に備えて、毎日求人を見て仕事を探している。", "target_word": "移住", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は来月[らいげつ]の移住[いじゅう]に備[そな]えて、毎日[まいにち]求人[きゅうじん]を見[み]て仕事[しごと]を探[さが]している。", "sentence_source": "generated"}, {"text": "村は移住してくる人を増やそうと、空き家を安く貸している。", "target_word": "移住", "complexity_tier": "T3", "furigana": "村[むら]は移住[いじゅう]してくる人[ひと]を増[ふ]やそうと、空[あ]き家[や]を安[やす]く貸[か]している。", "sentence_source": "generated"}, {"text": "夫の転勤をきっかけに、私たちは九州へ移住した。", "target_word": "移住", "complexity_tier": "T3", "furigana": "夫[おっと]の転勤[てんきん]をきっかけに、私[わたし]たちは九州[きゅうしゅう]へ移住[いじゅう]した。", "sentence_source": "generated"}, {"text": "移住の手続きは複雑で、半年以上かかった。", "target_word": "移住", "complexity_tier": "T3", "furigana": "移住[いじゅう]の手続[てつづ]きは複雑[ふくざつ]で、半年[はんとし]以上[いじょう]かかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移住する", "label": "辞書形"}, {"form": "移住した", "label": "過去形"}, {"form": "移住して", "label": "て形"}, {"form": "移住しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "暮らしの拠点を別の地域や外国に移し、そこで生活を始めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b545744d-41a4-491d-95fb-e6974ddf9eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39291, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移住", "is_correct": true, "explanation": "「田舎への移住を考えている」で、生活の拠点を移す計画に合う。"}, {"text": "出版", "is_correct": false, "explanation": "「田舎への出版を考えている」は生活の拠点の話と結びつかない。"}, {"text": "演奏", "is_correct": false, "explanation": "「田舎への演奏を考えている」は文意が通らない。"}, {"text": "注文", "is_correct": false, "explanation": "「田舎への注文を考えている」は定年後の計画として意味が合わない。"}], "explanations": {"移住": "「田舎への移住を考えている」で、生活の拠点を移す計画に合う。", "出版": "「田舎への出版を考えている」は生活の拠点の話と結びつかない。", "演奏": "「田舎への演奏を考えている」は文意が通らない。", "注文": "「田舎への注文を考えている」は定年後の計画として意味が合わない。"}, "sentence_index": 0, "correct_answer": "移住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お盆の間だけ、家族は田舎の祖父母の家へ移住した。", "explanation": "ここは〈帰省〉の意味。期間限定の里帰りで、住まいを別の地域に移すことではない。"}, {"text": "来月、同じ市内の別の部屋へ移住する。", "explanation": "ここは〈引っ越し〉の意味。同じ市内での住み替えは引っ越しで、移住は別の地域や国へ拠点を移すこと。"}, {"text": "毎朝七時に会社へ移住する。", "explanation": "ここは〈出勤〉の意味。会社へ通うだけで住まいは変わらないので、移住とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39291, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移住", "is_correct": true, "explanation": "「来月の移住に備えて」で、引っ越しの準備を指す文脈に合う。"}, {"text": "笑顔", "is_correct": false, "explanation": "「来月の笑顔に備えて」は文意が通らない。"}, {"text": "雨音", "is_correct": false, "explanation": "「来月の雨音に備えて」は求人を探す文脈と合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「来月の夕焼けに備えて」は不自然で、仕事探しの文脈と合わない。"}], "explanations": {"移住": "「来月の移住に備えて」で、引っ越しの準備を指す文脈に合う。", "笑顔": "「来月の笑顔に備えて」は文意が通らない。", "雨音": "「来月の雨音に備えて」は求人を探す文脈と合わない。", "夕焼け": "「来月の夕焼けに備えて」は不自然で、仕事探しの文脈と合わない。"}, "sentence_index": 6, "correct_answer": "移住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週から三日間、名古屋へ移住する予定だ。", "explanation": "ここは〈出張〉の意味。短期間の仕事で行くことで、住まいを移す移住とは合わない。"}, {"text": "大雨の日、住民は近くの高台へ移住した。", "explanation": "ここは〈避難〉の意味。危険を一時的に逃れる行動で、生活の拠点を移すことではない。"}, {"text": "休日は毎週、富士山へ移住している。", "explanation": "ここは〈登山〉の意味。山に登るのは一時的な行動で、そこに住むわけではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39291, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老後は海の見える町を移住したいと思っている。", "corrected_sentence": "老後は海の見える町へ移住したいと思っている。", "error_description": "移住先は「へ」で示す。「を」は移住の文に使えず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39291, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は長年の夢だった農業のため、山あいの村へ移住。", "corrected_sentence": "父は長年の夢だった農業のため、山あいの村へ移住した。", "error_description": "過去形の「移住した」が必要。「移住。」では文が終わっていない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2077fb-5805-427c-b931-fa45bdbd5b4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
