INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39292, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39292, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かに関係すること。例えば、グループの活動に自分も入って仲間と一緒にやること。", "primary_collocate": null, "pronunciation": "かんよ", "ipa": "kaɴjo", "syllable_count": 3, "sentences": [{"text": "私も町の祭りの準備に関与することになりました。", "target_word": "関与", "complexity_tier": "T3", "furigana": "私(わたし)も町(まち)の祭(まつ)りの準備(じゅんび)に関与(かんよ)することになりました。", "sentence_source": "generated"}, {"text": "田中さんは、クラブの活動に深く関与していて、毎日部室に来る。", "target_word": "関与", "complexity_tier": "T3", "furigana": "田中(たなか)さんは、クラブの活動(かつどう)に深(ふか)く関与(かんよ)していて、毎日(まいにち)部室(ぶしつ)に来(く)る。", "sentence_source": "generated"}, {"text": "新しい仲間が関与してくれたおかげで、チームの練習が楽しくなった。", "target_word": "関与", "complexity_tier": "T3", "furigana": "新(あたら)しい仲間(なかま)が関与(かんよ)してくれたおかげで、チームの練習(れんしゅう)が楽(たの)しくなった。", "sentence_source": "generated"}, {"text": "彼は忙しいので、グループの活動への関与は週に一度だけだ。", "target_word": "関与", "complexity_tier": "T3", "furigana": "彼(かれ)は忙(いそが)しいので、グループの活動(かつどう)への関与(かんよ)は週(しゅう)に一度(いちど)だけだ。", "sentence_source": "generated"}, {"text": "活動に関与する人が増えて、公園はとてもにぎやかになった。", "target_word": "関与", "complexity_tier": "T3", "furigana": "活動(かつどう)に関与(かんよ)する人(ひと)が増(ふ)えて、公園(こうえん)はとてもにぎやかになった。", "sentence_source": "generated"}, {"text": "先生はこの計画に関与していないので、くわしいことは知らない。", "target_word": "関与", "complexity_tier": "T3", "furigana": "先生(せんせい)はこの計画(けいかく)に関与(かんよ)していないので、くわしいことは知(し)らない。", "sentence_source": "generated"}, {"text": "同じ活動に関与した仲間とは、今でもよく会います。", "target_word": "関与", "complexity_tier": "T3", "furigana": "同(おな)じ活動(かつどう)に関与(かんよ)した仲間(なかま)とは、今(いま)でもよく会(あ)います。", "sentence_source": "generated"}, {"text": "学生が関与するイベントは、準備から片づけまで全部自分たちでやる。", "target_word": "関与", "complexity_tier": "T3", "furigana": "学生(がくせい)が関与(かんよ)するイベントは、準備(じゅんび)から片(かた)づけまで全部(ぜんぶ)自分(じぶん)たちでやる。", "sentence_source": "generated"}, {"text": "母は地域の読書会に長く関与していて、友だちも多い。", "target_word": "関与", "complexity_tier": "T3", "furigana": "母(はは)は地域(ちいき)の読書会(どくしょかい)に長(なが)く関与(かんよ)していて、友(とも)だちも多(おお)い。", "sentence_source": "generated"}, {"text": "みんなが関与したから、文化祭は大成功だった。", "target_word": "関与", "complexity_tier": "T3", "furigana": "みんなが関与(かんよ)したから、文化祭(ぶんかさい)は大成功(だいせいこう)だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "関与", "label": "基本形"}, {"form": "関与する", "label": "動詞形（辞書形）"}, {"form": "関与した", "label": "動詞形（過去）"}, {"form": "関与している", "label": "動詞形（進行・状態）"}], "register": "formal", "sense_fingerprint": "グループの活動に仲間として加わり関係すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e3467d-5cea-4b54-9930-14d540bd33b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39292, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "関与", "is_correct": true, "explanation": "祭りの準備に仲間として加わるという意味で、文の内容に合う正解。"}, {"text": "返却", "is_correct": false, "explanation": "借りた物を返す意味で、準備に加わるという文脈には合わない。"}, {"text": "満足", "is_correct": false, "explanation": "満ち足りた気持ちを表し、「準備に」と続いて作業に加わる意味にはならない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを終える意味で、準備に加わるという文の流れに合わない。"}], "explanations": {"関与": "祭りの準備に仲間として加わるという意味で、文の内容に合う正解。", "返却": "借りた物を返す意味で、準備に加わるという文脈には合わない。", "満足": "満ち足りた気持ちを表し、「準備に」と続いて作業に加わる意味にはならない。", "解散": "集まりを終える意味で、準備に加わるという文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "関与"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒かったので、ストーブに関与して手を温めた。", "explanation": "ここは〈触れる〉の意味。ストーブに直接触れる行為を指し、仲間として活動に加わる関与とは合わないので誤り。"}, {"text": "展望台から町の景色に関与した。", "explanation": "ここは〈眺める〉の意味。景色を見渡す行為を指すので、仲間として活動に加わる関与とは合わないので誤り。"}, {"text": "急な雨で、軒下に関与した。", "explanation": "ここは〈雨宿り〉の意味。雨を避けて軒下に入る行為を指すので、活動に加わる関与とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39292, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "関与", "is_correct": true, "explanation": "同じ活動に仲間として加わったという意味で、「同じ活動に」に続く唯一の語。"}, {"text": "脱出", "is_correct": false, "explanation": "その場から逃げ出す意味で、活動に加わった仲間を表す文には合わない。"}, {"text": "返金", "is_correct": false, "explanation": "払った代金を返す意味で、活動に加わるという文脈には合わない。"}, {"text": "仮眠", "is_correct": false, "explanation": "短い睡眠を指し、活動に加わった仲間の説明にはならないので合わない。"}], "explanations": {"関与": "同じ活動に仲間として加わったという意味で、「同じ活動に」に続く唯一の語。", "脱出": "その場から逃げ出す意味で、活動に加わった仲間を表す文には合わない。", "返金": "払った代金を返す意味で、活動に加わるという文脈には合わない。", "仮眠": "短い睡眠を指し、活動に加わった仲間の説明にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "関与"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昼に、うどんに関与した。", "explanation": "ここは〈食べる〉の意味。料理を口に入れる行為を指すので、仲間として活動に加わる関与とは合わない。"}, {"text": "休みに友だちと関与に行った。", "explanation": "ここは〈旅行〉の意味。出かけて楽しむ旅行と、活動に加わる関与は別で、「関与に行く」とは言わないので合わない。"}, {"text": "毎朝、犬と関与をしてから会社に行く。", "explanation": "ここは〈散歩〉の意味。犬と外を歩く行動を指すので、仲間として活動に加わる関与とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39292, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年の作品展の企画を関与することにした。", "corrected_sentence": "来年の作品展の企画に関与することにした。", "error_description": "「関与」に続く助詞が誤り。「関与する」は「〜に関与する」と使うので、「を」ではなく「に」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39292, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の大掃除を関与した仲間と、楽しく話した。", "corrected_sentence": "昨日の大掃除に関与した仲間と、楽しく話した。", "error_description": "「関与した」に続く助詞が誤り。「関与する」は「〜に関与する」と使うので、「を」ではなく「に」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
