INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39293, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある物事や活動に、自分から進んで関係したり、影響を与えたりすること。", "primary_collocate": null, "pronunciation": "かんよ", "ipa": "kaɴjo", "syllable_count": 3, "sentences": [{"text": "社長が自分から会議に関与して、計画の方向を変えた。", "target_word": "関与", "complexity_tier": "T3", "furigana": "社長(しゃちょう)が自分(じぶん)から会議(かいぎ)に関与(かんよ)して、計画(けいかく)の方向(ほうこう)を変(か)えた。", "sentence_source": "generated"}, {"text": "この事件に会社が関与していたことが、調べでわかった。", "target_word": "関与", "complexity_tier": "T3", "furigana": "この事件(じけん)に会社(かいしゃ)が関与(かんよ)していたことが、調(しら)べでわかった。", "sentence_source": "generated"}, {"text": "国の関与が大きすぎると、会社は自由に動けない。", "target_word": "関与", "complexity_tier": "T3", "furigana": "国(くに)の関与(かんよ)が大(おお)きすぎると、会社(かいしゃ)は自由(じゆう)に動(うご)けない。", "sentence_source": "generated"}, {"text": "彼は問題の解決に積極的に関与し、新しい案を出した。", "target_word": "関与", "complexity_tier": "T3", "furigana": "彼(かれ)は問題(もんだい)の解決(かいけつ)に積極的(せっきょくてき)に関与(かんよ)し、新(あたら)しい案(あん)を出(だ)した。", "sentence_source": "generated"}, {"text": "親が子どもの勉強に関与しすぎると、子どもが自分で考えなくなる。", "target_word": "関与", "complexity_tier": "T3", "furigana": "親(おや)が子(こ)どもの勉強(べんきょう)に関与(かんよ)しすぎると、子(こ)どもが自分(じぶん)で考(かんが)えなくなる。", "sentence_source": "generated"}, {"text": "政治家が工事の契約に関与したのではないかと、新聞が書いた。", "target_word": "関与", "complexity_tier": "T3", "furigana": "政治家(せいじか)が工事(こうじ)の契約(けいやく)に関与(かんよ)したのではないかと、新聞(しんぶん)が書(か)いた。", "sentence_source": "generated"}, {"text": "医者は治療方法の決定に患者が関与できるように説明した。", "target_word": "関与", "complexity_tier": "T3", "furigana": "医者(いしゃ)は治療(ちりょう)方法(ほうほう)の決定(けってい)に患者(かんじゃ)が関与(かんよ)できるように説明(せつめい)した。", "sentence_source": "generated"}, {"text": "その争いには関与したくないので、何も言わなかった。", "target_word": "関与", "complexity_tier": "T3", "furigana": "その争(あらそ)いには関与(かんよ)したくないので、何(なに)も言(い)わなかった。", "sentence_source": "generated"}, {"text": "市長の関与によって、古い駅の工事が早く始まった。", "target_word": "関与", "complexity_tier": "T3", "furigana": "市長(しちょう)の関与(かんよ)によって、古(ふる)い駅(えき)の工事(こうじ)が早(はや)く始(はじ)まった。", "sentence_source": "generated"}, {"text": "外国の会社が経営に関与するようになってから、店の売り方が変わった。", "target_word": "関与", "complexity_tier": "T3", "furigana": "外国(がいこく)の会社(かいしゃ)が経営(けいえい)に関与(かんよ)するようになってから、店(みせ)の売(う)り方(かた)が変(か)わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "関与", "label": "基本形"}, {"form": "関与する", "label": "動詞形（辞書形）"}, {"form": "関与した", "label": "動詞形（過去）"}, {"form": "関与しすぎる", "label": "動詞形（過度）"}], "register": "formal", "sense_fingerprint": "物事に自分から関わり影響を及ぼすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e3467d-5cea-4b54-9930-14d540bd33b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39293, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "関与", "is_correct": true, "explanation": "社長が会議に自分から関わって影響を与えたという意味で、文に合う正解。"}, {"text": "延期", "is_correct": false, "explanation": "予定を先に延ばす意味で、「会議に」と続けて影響を与える文脈には合わない。"}, {"text": "撤回", "is_correct": false, "explanation": "一度出した意見や決定を取り消す意味で、「会議に」と続く文には合わない。"}, {"text": "配布", "is_correct": false, "explanation": "資料などを配る意味で、会議に影響を与える文脈には合わない。"}], "explanations": {"関与": "社長が会議に自分から関わって影響を与えたという意味で、文に合う正解。", "延期": "予定を先に延ばす意味で、「会議に」と続けて影響を与える文脈には合わない。", "撤回": "一度出した意見や決定を取り消す意味で、「会議に」と続く文には合わない。", "配布": "資料などを配る意味で、会議に影響を与える文脈には合わない。"}, "sentence_index": 0, "correct_answer": "関与"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "喉が渇いたので、水に関与した。", "explanation": "ここは〈飲む〉の意味。水を口に入れる行為を指すので、ある物事に影響を与えるという関与とは合わない。"}, {"text": "子どもが機械のボタンに関与した。", "explanation": "ここは〈触る〉の意味。ボタンに手を触れる行為を指し、影響を与えるという意味では使わないので合わない。"}, {"text": "彼女は窓の外に関与していた。", "explanation": "ここは〈見つめる〉の意味。視線を向ける行為を指し、影響を及ぼす関与とは合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39293, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "関与", "is_correct": true, "explanation": "医者が患者に決定への影響を持たせるという意味で、「患者が〜できる」に合う正解。"}, {"text": "配達", "is_correct": false, "explanation": "物を届ける意味で、患者が決定に関わるという文脈には合わない。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べる意味で、患者が決定に影響を与える文には合わない。"}, {"text": "延長", "is_correct": false, "explanation": "長さや期間を伸ばす意味で、「決定に患者が〜できる」とは続かない。"}], "explanations": {"関与": "医者が患者に決定への影響を持たせるという意味で、「患者が〜できる」に合う正解。", "配達": "物を届ける意味で、患者が決定に関わるという文脈には合わない。", "点検": "状態を調べる意味で、患者が決定に影響を与える文には合わない。", "延長": "長さや期間を伸ばす意味で、「決定に患者が〜できる」とは続かない。"}, "sentence_index": 6, "correct_answer": "関与"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猫は一日中、窓辺に関与している。", "explanation": "ここは〈寝る〉の意味。眠って過ごす様子を指すので、影響を及ぼす関与とは合わないので誤り。"}, {"text": "庭の花が、朝から関与した。", "explanation": "ここは〈咲く〉の意味。花が開く自然な変化を指すので、影響を与える関与とは合わないので誤り。"}, {"text": "窓のカーテンが関与している。", "explanation": "ここは〈揺れる〉の意味。カーテンが風で動く様子を指すので、影響を与える関与とは合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39293, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地域の再開発計画を関与して、住民が意見を出した。", "corrected_sentence": "地域の再開発計画に関与して、住民が意見を出した。", "error_description": "「計画」に続く助詞が誤り。「関与する」は「〜に関与する」と使うので、「を」ではなく「に」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39293, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市民に関与によって、新しい公園の計画が決まった。", "corrected_sentence": "市民の関与によって、新しい公園の計画が決まった。", "error_description": "「市民」に続く助詞が誤り。「関与」の前には連体修飾の「の」が必要で、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39294, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体", "is_correct": true, "explanation": "「抽象」の対義語。形がはっきりしない意味の「抽象」と反対の意味を持つ。"}, {"text": "理論", "is_correct": false, "explanation": "筋道立てた考え方を表す語。抽象と関わるが対義語ではない。"}, {"text": "比喩", "is_correct": false, "explanation": "別の物事に例えて表す表現。抽象の対義語ではない。"}, {"text": "観念", "is_correct": false, "explanation": "頭の中の考えを表す語。抽象と近い意味で、対義語ではない。"}], "correct_answer": "具体", "explanations": {"具体": "「抽象」の対義語。形がはっきりしない意味の「抽象」と反対の意味を持つ。", "理論": "筋道立てた考え方を表す語。抽象と関わるが対義語ではない。", "比喩": "別の物事に例えて表す表現。抽象の対義語ではない。", "観念": "頭の中の考えを表す語。抽象と近い意味で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39294, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「抽象のまま」の「の」。「まま」は名詞に「の」で続く。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「抽象へまま」は成立せず、方向の意味にもならない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「抽象からまま」となり、「まま」の前に続けられない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用の「と」。「抽象とまま」は続かず、文の意味に合わない。"}], "correct_answer": "の", "explanations": {"の": "「抽象のまま」の「の」。「まま」は名詞に「の」で続く。", "へ": "方向の「へ」。「抽象へまま」は成立せず、方向の意味にもならない。", "から": "起点の「から」。「抽象からまま」となり、「まま」の前に続けられない。", "と": "並列や引用の「と」。「抽象とまま」は続かず、文の意味に合わない。"}, "error_tags": {"へ": "方向", "から": "起点", "と": "並列・引用"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体", "is_correct": true, "explanation": "「抽象」の対義語。「抽象」は具体の反対の意味を持つ。"}, {"text": "感覚", "is_correct": false, "explanation": "感じ取る働きを表す語。抽象の対義語ではない。"}, {"text": "印象", "is_correct": false, "explanation": "受ける感じを表す語。抽象の対義語ではない。"}, {"text": "事例", "is_correct": false, "explanation": "具体的な例を指す語。抽象の対義語として辞書に載る語ではない。"}], "correct_answer": "具体", "explanations": {"具体": "「抽象」の対義語。「抽象」は具体の反対の意味を持つ。", "感覚": "感じ取る働きを表す語。抽象の対義語ではない。", "印象": "受ける感じを表す語。抽象の対義語ではない。", "事例": "具体的な例を指す語。抽象の対義語として辞書に載る語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39294, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "形やようすがはっきりと見えたり、感じられたりしないこと。", "primary_collocate": null, "pronunciation": "ちゅうしょう", "ipa": "tɕɯːɕoː", "syllable_count": 4, "sentences": [{"text": "この詩は情景を抽象にとどめているので、読む人が自由に想像できる。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "この詩(し)は情景(じょうけい)を抽象(ちゅうしょう)にとどめているので、読(よ)む人(ひと)が自由(じゆう)に想像(そうぞう)できる。", "sentence_source": "generated"}, {"text": "彼女の説明は抽象の話ばかりで、どんな建物なのか少しも想像できなかった。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の説明[せつめい]は抽象[ちゅうしょう]の話[はなし]ばかりで、どんな建物[たてもの]なのか少[すこ]しも想像[そうぞう]できなかった。", "sentence_source": "generated"}, {"text": "抽象の度合いが高いほど、言葉の意味は人によって違って受け取られやすい。", "target_word": "抽象", "complexity_tier": "T4", "furigana": "抽象(ちゅうしょう)の度合(どあ)いが高(たか)いほど、言葉(ことば)の意味(いみ)は人(ひと)によって違(ちが)って受(う)け取(と)られやすい。", "sentence_source": "generated"}, {"text": "ここで抽象のまま話を進めると、聞き手が混乱するので、写真を見せよう。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "ここで抽象(ちゅうしょう)のまま話(はなし)を進(すす)めると、聞(き)き手(て)が混乱(こんらん)するので、写真(しゃしん)を見(み)せよう。", "sentence_source": "generated"}, {"text": "「時間」は触れることができない抽象なので、子どもには説明しにくい。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "「時間(じかん)」は触(ふ)れることができない抽象(ちゅうしょう)なので、子(こ)どもには説明(せつめい)しにくい。", "sentence_source": "generated"}, {"text": "音楽は形が見えない抽象だから、言葉で説明するのは難しい。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "音楽(おんがく)は形(かたち)が見(み)えない抽象(ちゅうしょう)だから、言葉(ことば)で説明(せつめい)するのは難(むずか)しい。", "sentence_source": "generated"}, {"text": "不安という抽象を数字で表すと、人に伝えやすくなる。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "不安(ふあん)という抽象(ちゅうしょう)を数字(すうじ)で表(あらわ)すと、人(ひと)に伝(つた)えやすくなる。", "sentence_source": "generated"}, {"text": "この文章は抽象のまま終わっていて、読み終わっても情景が頭に残らない。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "この文章[ぶんしょう]は抽象[ちゅうしょう]のまま終[お]わっていて、読[よ]み終[お]わっても情景[じょうけい]が頭[あたま]に残[のこ]らない。", "sentence_source": "generated"}, {"text": "この設計図は抽象のままで、寸法も材料も書かれていないので、職人は作ることができない。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "この設計図[せっけいず]は抽象[ちゅうしょう]のままで、寸法[すんぽう]も材料[ざいりょう]も書[か]かれていないので、職人[しょくにん]は作[つく]ることができない。", "sentence_source": "generated"}, {"text": "商品の説明が抽象だと、お客さんは大きさも色もわからず買えない。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "商品(しょうひん)の説明(せつめい)が抽象(ちゅうしょう)だと、お客(きゃく)さんは大(おお)きさも色(いろ)もわからず買(か)えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽象", "label": "基本形"}, {"form": "抽象的", "label": "派生形（形状詞）"}, {"form": "抽象の", "label": "連体形（の）"}, {"form": "抽象に", "label": "格助詞（に）"}], "register": "neutral", "sense_fingerprint": "形や様子が見えず、はっきり感じられないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39294, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽象", "is_correct": true, "explanation": "「情景を抽象にとどめる」の名詞。文の「抽象」がこの形に当たる。"}, {"text": "具体", "is_correct": false, "explanation": "「情景を具体にとどめている」は文として成り立つが、後半の「読む人が自由に想像できる」と矛盾し、文脈に合わない。"}, {"text": "理屈", "is_correct": false, "explanation": "筋道の意味の名詞。「情景を理屈にとどめる」は文脈の情景の描写と合わない。"}, {"text": "形式", "is_correct": false, "explanation": "かたちや決まりの意味の名詞。「情景を形式にとどめる」は文の意味に合わない。"}], "explanations": {"抽象": "「情景を抽象にとどめる」の名詞。文の「抽象」がこの形に当たる。", "具体": "「情景を具体にとどめている」は文として成り立つが、後半の「読む人が自由に想像できる」と矛盾し、文脈に合わない。", "理屈": "筋道の意味の名詞。「情景を理屈にとどめる」は文脈の情景の描写と合わない。", "形式": "かたちや決まりの意味の名詞。「情景を形式にとどめる」は文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "抽象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕焼けは抽象で、見ている人の心を明るくする。", "explanation": "ここは〈鮮やかな〉の意味。はっきり見える色には抽象を使わない。"}, {"text": "この店の看板は抽象で、遠くからでもはっきり読める。", "explanation": "ここは〈鮮明な〉の意味。はっきり見えることを抽象とは言わない。"}, {"text": "彼女の笑い声は抽象で、遠くにいても誰の声かすぐわかる。", "explanation": "ここは〈特徴的な〉の意味。はっきり聞き取れる音には抽象は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39294, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽象", "is_correct": true, "explanation": "「不安という抽象」の名詞。文中の形と一致し、数字で表す対象になる。"}, {"text": "抽象的", "is_correct": false, "explanation": "形容動詞。「不安という抽象的を数字で表す」となり、名詞として成立しない。"}, {"text": "抽象だ", "is_correct": false, "explanation": "終止形。「不安という抽象だを数字で表す」となり、名詞として成立しない。"}, {"text": "抽象に", "is_correct": false, "explanation": "連用形。「不安という抽象にを数字で表す」となり、目的語として成立しない。"}], "explanations": {"抽象": "「不安という抽象」の名詞。文中の形と一致し、数字で表す対象になる。", "抽象的": "形容動詞。「不安という抽象的を数字で表す」となり、名詞として成立しない。", "抽象だ": "終止形。「不安という抽象だを数字で表す」となり、名詞として成立しない。", "抽象に": "連用形。「不安という抽象にを数字で表す」となり、目的語として成立しない。"}, "sentence_index": 6, "correct_answer": "抽象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄は抽象に走るのが速く、リレーの選手に選ばれた。", "explanation": "ここは〈猛烈に〉の意味。走る速さの様子を表すのに抽象は副詞として使わない。"}, {"text": "彼の料理は抽象で、塩加減がちょうどよい。", "explanation": "ここは〈絶妙な〉の意味。味は感覚で確かめられるもので、抽象は合わない。"}, {"text": "バスの運賃は抽象に決まっていて、乗る人は迷わない。", "explanation": "ここは〈一定の〉の意味。金額の決まり方は抽象ではなく一定で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39294, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の話は抽象を多すぎて、聞いていると疲れてしまう。", "corrected_sentence": "彼の話は抽象が多すぎて、聞いていると疲れてしまう。", "error_description": "「多すぎる」の主語は「が」で示す。「抽象を多すぎて」は誤りで、「抽象が多すぎて」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39294, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この設計図は抽象だままで、寸法も材料も書かれていない。", "corrected_sentence": "この設計図は抽象のままで、寸法も材料も書かれていない。", "error_description": "「抽象」に「だ」が付いて「抽象だまま」となっている。「抽象のまま」の「の」で続けるのが正しい形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39295, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「抽象に偏る」の「に」。「偏る」が取る助詞で、文の意味にも合う。"}, {"text": "を", "is_correct": false, "explanation": "対象の「を」。「偏る」は目的語を取らないので「抽象を偏る」は成立しない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」。「抽象で偏る」は結びつかず、意味も通らない。"}, {"text": "の", "is_correct": false, "explanation": "「抽象の偏りすぎて」は「の」の後に動詞が続かず、文が崩れる。"}], "correct_answer": "に", "explanations": {"に": "「抽象に偏る」の「に」。「偏る」が取る助詞で、文の意味にも合う。", "を": "対象の「を」。「偏る」は目的語を取らないので「抽象を偏る」は成立しない。", "で": "手段や場所の「で」。「抽象で偏る」は結びつかず、意味も通らない。", "の": "「抽象の偏りすぎて」は「の」の後に動詞が続かず、文が崩れる。"}, "error_tags": {"を": "対象（目的語）", "で": "手段・場所", "の": "所属"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体", "is_correct": true, "explanation": "「抽象」の対義語。「抽象」は具体の反対の意味を持つ。"}, {"text": "観念", "is_correct": false, "explanation": "頭の中の考えを表す語で、抽象と近い意味。対義語ではない。"}, {"text": "理論", "is_correct": false, "explanation": "筋道立てた考え方を表す語。抽象と関わるが対義語ではない。"}, {"text": "比喩", "is_correct": false, "explanation": "別の物事に例えて表す表現。抽象の対義語ではない。"}], "correct_answer": "具体", "explanations": {"具体": "「抽象」の対義語。「抽象」は具体の反対の意味を持つ。", "観念": "頭の中の考えを表す語で、抽象と近い意味。対義語ではない。", "理論": "筋道立てた考え方を表す語。抽象と関わるが対義語ではない。", "比喩": "別の物事に例えて表す表現。抽象の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39295, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「抽象のまま」の「の」。「まま」は名詞に「の」で続く形で、文中の形と一致する。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」。「抽象がまま」となり、「まま」の前に続けられない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用の「と」。「抽象とまま」は続かず、文の意味にも合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「抽象からまま」は成立せず、文の構造に合わない。"}], "correct_answer": "の", "explanations": {"の": "「抽象のまま」の「の」。「まま」は名詞に「の」で続く形で、文中の形と一致する。", "が": "主格の「が」。「抽象がまま」となり、「まま」の前に続けられない。", "と": "並列や引用の「と」。「抽象とまま」は続かず、文の意味にも合わない。", "から": "起点の「から」。「抽象からまま」は成立せず、文の構造に合わない。"}, "error_tags": {"が": "主格", "と": "並列・引用", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体", "is_correct": true, "explanation": "「抽象」の対義語。「抽象」は具体の反対の意味を持つ。"}, {"text": "感覚", "is_correct": false, "explanation": "感じ取る働きを表す語。抽象の対義語ではない。"}, {"text": "印象", "is_correct": false, "explanation": "受ける感じを表す語。抽象の対義語ではない。"}, {"text": "事例", "is_correct": false, "explanation": "具体的な例を指す語。抽象の対義語として辞書に載る語ではない。"}], "correct_answer": "具体", "explanations": {"具体": "「抽象」の対義語。「抽象」は具体の反対の意味を持つ。", "感覚": "感じ取る働きを表す語。抽象の対義語ではない。", "印象": "受ける感じを表す語。抽象の対義語ではない。", "事例": "具体的な例を指す語。抽象の対義語として辞書に載る語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39295, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "形や内容がはっきりとしない、頭の中で考えただけのものごと。", "primary_collocate": null, "pronunciation": "ちゅうしょう", "ipa": "tɕɯːɕoː", "syllable_count": 4, "sentences": [{"text": "しかる後に、プログラミングという「神経系」を構築し、抽象的論理と物理的挙動を厳密に同期させるのだ。", "target_word": "抽象", "complexity_tier": "T4", "furigana": "しかる後(のち)に、プログラミングという「神経系(しんけいけい)」を構築(こうちく)し、抽象的(ちゅうしょうてき)論理(ろんり)と物理的(ぶつりてき)挙動(きょどう)を厳密(げんみつ)に同期(どうき)させるのだ。", "sentence_source": "mined"}, {"text": "この説明は抽象に偏りすぎていて、具体例がないので何を言いたいのかわからない。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "この説明(せつめい)は抽象(ちゅうしょう)に偏(かたよ)りすぎていて、具体例(ぐたいれい)がないので何(なに)を言(い)いたいのかわからない。", "sentence_source": "generated"}, {"text": "数学では、具体的な数から抽象へと考えを進めることが多い。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "数学(すうがく)では、具体的(ぐたいてき)な数(かず)から抽象(ちゅうしょう)へと考(かんが)えを進(すす)めることが多(おお)い。", "sentence_source": "generated"}, {"text": "哲学の授業では、現実の物から離れて抽象だけで議論することがある。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "哲学(てつがく)の授業(じゅぎょう)では、現実(げんじつ)の物(もの)から離(はな)れて抽象(ちゅうしょう)だけで議論(ぎろん)することがある。", "sentence_source": "generated"}, {"text": "抽象と具体を行き来して考えると、複雑な話も整理しやすくなる。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "抽象(ちゅうしょう)と具体(ぐたい)を行(い)き来(き)して考(かんが)えると、複雑(ふくざつ)な話(はなし)も整理(せいり)しやすくなる。", "sentence_source": "generated"}, {"text": "彼の話は抽象ばかりで、実際に何をするのかが見えてこない。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "彼(かれ)の話(はなし)は抽象(ちゅうしょう)ばかりで、実際(じっさい)に何(なに)をするのかが見(み)えてこない。", "sentence_source": "generated"}, {"text": "子どもに抽象を教えるときは、まず身近な例を見せるとよい。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "子(こ)どもに抽象(ちゅうしょう)を教(おし)えるときは、まず身近(みぢか)な例(れい)を見(み)せるとよい。", "sentence_source": "generated"}, {"text": "作文では、抽象のままで終わらせず、体験を具体的に書きなさい。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "作文(さくぶん)では、抽象(ちゅうしょう)のままで終(お)わらせず、体験(たいけん)を具体的(ぐたいてき)に書(か)きなさい。", "sentence_source": "generated"}, {"text": "理論は抽象の世界の話だが、実験をすれば現実とつながる。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "理論(りろん)は抽象(ちゅうしょう)の世界(せかい)の話(はなし)だが、実験(じっけん)をすれば現実(げんじつ)とつながる。", "sentence_source": "generated"}, {"text": "「幸福」のような抽象は、人によって思い浮かべるものが違う。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "「幸福(こうふく)」のような抽象(ちゅうしょう)は、人(ひと)によって思(おも)い浮(う)かべるものが違(ちが)う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽象", "label": "基本形"}, {"form": "抽象的", "label": "派生形（形状詞）"}, {"form": "抽象の", "label": "連体形（の）"}, {"form": "抽象に", "label": "格助詞（に）"}], "register": "neutral", "sense_fingerprint": "具体の反対。頭の中だけで考えた概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39295, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽象", "is_correct": true, "explanation": "文中の「抽象的論理」の語幹。「的論理」と続けるのに適した形。"}, {"text": "挙動", "is_correct": false, "explanation": "行動の意味の名詞。「挙動的論理」は意味が通らず、「的」で続かない。"}, {"text": "同期", "is_correct": false, "explanation": "時間を合わせる意味の名詞。「同期的論理」とは言わず、文の意味に合わない。"}, {"text": "構築", "is_correct": false, "explanation": "組み立てる意味の名詞。「構築的論理」は文脈の「厳密に同期させる」と合わない。"}], "explanations": {"抽象": "文中の「抽象的論理」の語幹。「的論理」と続けるのに適した形。", "挙動": "行動の意味の名詞。「挙動的論理」は意味が通らず、「的」で続かない。", "同期": "時間を合わせる意味の名詞。「同期的論理」とは言わず、文の意味に合わない。", "構築": "組み立てる意味の名詞。「構築的論理」は文脈の「厳密に同期させる」と合わない。"}, "sentence_index": 0, "correct_answer": "抽象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この布は抽象で、透けて向こうの景色がよく見える。", "explanation": "ここは〈薄い〉の意味。布の厚みを表すのに抽象は使わない。"}, {"text": "この箱は抽象で、子どもにも簡単に運べる。", "explanation": "ここは〈軽い〉の意味。重さを表すのに抽象は使わない。"}, {"text": "この部屋は抽象で、窓から気持ちのよい風が入る。", "explanation": "ここは〈広い〉の意味。部屋の大きさを表すのに抽象は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39295, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽象", "is_correct": true, "explanation": "「子どもに抽象を教える」の目的語。文中の形と一致する。"}, {"text": "抽象的", "is_correct": false, "explanation": "形容動詞。「子どもに抽象的を教える」となり、名詞の目的語にならない。"}, {"text": "抽象だ", "is_correct": false, "explanation": "終止形。「抽象だを教える」となり、目的語として成立しない。"}, {"text": "抽象の", "is_correct": false, "explanation": "連体形。「抽象のを教える」となり、目的語として成立しない。"}], "explanations": {"抽象": "「子どもに抽象を教える」の目的語。文中の形と一致する。", "抽象的": "形容動詞。「子どもに抽象的を教える」となり、名詞の目的語にならない。", "抽象だ": "終止形。「抽象だを教える」となり、目的語として成立しない。", "抽象の": "連体形。「抽象のを教える」となり、目的語として成立しない。"}, "sentence_index": 6, "correct_answer": "抽象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は背が抽象で、ドアの枠に頭をぶつけそうだ。", "explanation": "ここは〈高い〉の意味。背の高さは目に見えるもので、抽象の対象ではない。"}, {"text": "彼女の涙は抽象で、頬を伝って落ちていった。", "explanation": "ここは〈大粒の〉の意味。涙の粒の大きさを表すのに抽象は使わない。"}, {"text": "夜空の星は抽象で、ひとつひとつが見分けられる。", "explanation": "ここは〈くっきりとした〉の意味。見え方の鮮明さに抽象は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39295, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この授業は抽象を偏りすぎていて、生徒が内容をつかめない。", "corrected_sentence": "この授業は抽象に偏りすぎていて、生徒が内容をつかめない。", "error_description": "「偏る」は「に」を取る。「抽象を偏る」は誤りで、「抽象に偏る」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39295, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の考えは抽象な話で、現実の仕事には使いにくい。", "corrected_sentence": "彼の考えは抽象的な話で、現実の仕事には使いにくい。", "error_description": "形容動詞として名詞「話」を修飾する形は「抽象的な」。「抽象な」は誤りで、「的」が抜けている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
