INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39296, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『共感する』は『〜に共感する』で、共感の対象を『に』で示す。『私たちの理念に共感した』が正しい。"}, {"text": "が", "is_correct": false, "explanation": "『理念が共感した』だと理念が主語になり、『共感した人たち』と合わない。"}, {"text": "を", "is_correct": false, "explanation": "『共感する』は『に』を取るので、『理念を共感した』は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は向かう先を表すので、『共感する』の対象には使えない。"}], "correct_answer": "に", "explanations": {"に": "『共感する』は『〜に共感する』で、共感の対象を『に』で示す。『私たちの理念に共感した』が正しい。", "が": "『理念が共感した』だと理念が主語になり、『共感した人たち』と合わない。", "を": "『共感する』は『に』を取るので、『理念を共感した』は成り立たない。", "へ": "『へ』は向かう先を表すので、『共感する』の対象には使えない。"}, "error_tags": {"が": "主語化", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39296, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることについての、基本的な考え。", "primary_collocate": null, "pronunciation": "りねん", "ipa": "ɾiɲeɴ", "syllable_count": 3, "sentences": [{"text": "この会社の理念は、お客様の生活を支えることだ。", "target_word": "理念", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の理念[りねん]は、お客様[きゃくさま]の生活[せいかつ]を支[ささ]えることだ。", "sentence_source": "generated"}, {"text": "彼の理念は昔から変わらないので、周りの人も安心している。", "target_word": "理念", "complexity_tier": "T3", "furigana": "彼[かれ]の理念[りねん]は昔[むかし]から変[か]わらないので、周[まわ]りの人[ひと]も安心[あんしん]している。", "sentence_source": "generated"}, {"text": "新しい店長は、店の理念をみんなに丁寧に説明した。", "target_word": "理念", "complexity_tier": "T3", "furigana": "新[あたら]しい店長[てんちょう]は、店[みせ]の理念[りねん]をみんなに丁寧[ていねい]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "理念がはっきりしていない団体は、活動の方向を決めにくい。", "target_word": "理念", "complexity_tier": "T3", "furigana": "理念[りねん]がはっきりしていない団体[だんたい]は、活動[かつどう]の方向[ほうこう]を決[き]めにくい。", "sentence_source": "generated"}, {"text": "この病院は、患者を第一に考えるという理念を掲げている。", "target_word": "理念", "complexity_tier": "T3", "furigana": "この病院[びょういん]は、患者[かんじゃ]を第一[だいいち]に考[かんが]えるという理念[りねん]を掲[かか]げている。", "sentence_source": "generated"}, {"text": "理念は立派だが、実際の仕事ではなかなか守れない。", "target_word": "理念", "complexity_tier": "T3", "furigana": "理念[りねん]は立派[りっぱ]だが、実際[じっさい]の仕事[しごと]ではなかなか守[まも]れない。", "sentence_source": "generated"}, {"text": "創業者の理念を受け継いで、今も小さな店を続けている。", "target_word": "理念", "complexity_tier": "T3", "furigana": "創業者[そうぎょうしゃ]の理念[りねん]を受[う]け継[つ]いで、今[いま]も小[ちい]さな店[みせ]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "私たちの理念に共感した人たちが、少しずつ集まってきた。", "target_word": "理念", "complexity_tier": "T3", "furigana": "私[わたし]たちの理念[りねん]に共感[きょうかん]した人[ひと]たちが、少[すこ]しずつ集[あつ]まってきた。", "sentence_source": "generated"}, {"text": "理念だけで終わらないように、具体的な計画も作った。", "target_word": "理念", "complexity_tier": "T3", "furigana": "理念[りねん]だけで終[お]わらないように、具体的[ぐたいてき]な計画[けいかく]も作[つく]った。", "sentence_source": "generated"}, {"text": "町づくりの理念を決めるために、住民が何度も話し合った。", "target_word": "理念", "complexity_tier": "T3", "furigana": "町[まち]づくりの理念[りねん]を決[き]めるために、住民[じゅうみん]が何度[なんど]も話[はな]し合[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理念", "label": "基本形"}, {"form": "理念の", "label": "連体形（の）"}], "register": "formal", "sense_fingerprint": "ある事柄についての基本的な考え。会社・学校・団体などが掲げる方針の土台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39296, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理念", "is_correct": true, "explanation": "『この会社の理念は、お客様の生活を支える』の空欄に入り、会社の基本的な考えを表すので文意が通る。"}, {"text": "距離", "is_correct": false, "explanation": "『この会社の距離は』では意味が通らない。距離は場所や間の隔たりを指す語。"}, {"text": "時刻", "is_correct": false, "explanation": "『この会社の時刻は』は成り立たない。時刻は時の点を指す語。"}, {"text": "季節", "is_correct": false, "explanation": "『この会社の季節は』は文意に合わない。季節は一年の区分を指す語。"}], "explanations": {"理念": "『この会社の理念は、お客様の生活を支える』の空欄に入り、会社の基本的な考えを表すので文意が通る。", "距離": "『この会社の距離は』では意味が通らない。距離は場所や間の隔たりを指す語。", "時刻": "『この会社の時刻は』は成り立たない。時刻は時の点を指す語。", "季節": "『この会社の季節は』は文意に合わない。季節は一年の区分を指す語。"}, "sentence_index": 0, "correct_answer": "理念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年の理念は、毎月二冊本を読むことにした。", "explanation": "ここは〈目標〉の意味。理念は物事の根底にある考えで、毎月の具体的な数値を定める話には使わない。"}, {"text": "この説は、何度も実験を繰り返して確かめられた理念だ。", "explanation": "ここは〈理論〉の意味。理念は考え方や信念を指し、実験で検証される説明の体系には使わない。"}, {"text": "来週の理念は、社員旅行の準備を進めることだ。", "explanation": "ここは〈計画〉の意味。理念は根本の考えなので、来週の具体的な作業の予定には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39296, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理念", "is_correct": true, "explanation": "『創業者の理念を受け継いで』の目的語。創業者の基本的な考えを受け継ぐ意味で自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は受け継ぐものではない。『創業者の天気を受け継いで』は成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は人の重さを指し、受け継ぐ対象にならない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は受け継ぐものではなく、文意に合わない。"}], "explanations": {"理念": "『創業者の理念を受け継いで』の目的語。創業者の基本的な考えを受け継ぐ意味で自然。", "天気": "天気は受け継ぐものではない。『創業者の天気を受け継いで』は成り立たない。", "体重": "体重は人の重さを指し、受け継ぐ対象にならない。", "騒音": "騒音は受け継ぐものではなく、文意に合わない。"}, "sentence_index": 6, "correct_answer": "理念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週の試合の理念は、守備を固めることにした。", "explanation": "ここは〈方針〉の意味。理念は根本の考えで、試合での一時的な戦い方には使わない。"}, {"text": "子どもの頃の理念は、宇宙飛行士になることだった。", "explanation": "ここは〈夢〉の意味。理念は行動の土台になる考えで、将来なりたい姿には使わない。"}, {"text": "その話を聞いて、理念が少し軽くなった。", "explanation": "ここは〈気分〉の意味。理念は根本の考えを指すので、その時々の気持ちの状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39296, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私たちの店の理念を、お客様の笑顔を大切にすることだ。", "corrected_sentence": "私たちの店の理念は、お客様の笑顔を大切にすることだ。", "error_description": "『理念』は主題になる名詞なので『は』が正しい。『を』を付けると目的語になり、『〜ことだ』と文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39296, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その会社は、社員を大切にするという理念を掲げる、新しい制度を作った。", "corrected_sentence": "その会社は、社員を大切にするという理念を掲げて、新しい制度を作った。", "error_description": "『掲げる』は後ろに続く形なので連用形『掲げて』にする。『掲げる、』と終止形で切ると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39297, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『理念のもとに』の『の』。理念を名詞として続け、『もとに』で根拠を示す形になる。"}, {"text": "が", "is_correct": false, "explanation": "『理念が』だと理念が主語になり、『もとに活動』と続かない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や引用を示すので、『理念と＋もとに』は不自然。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すので、『理念からもとに』は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "『理念のもとに』の『の』。理念を名詞として続け、『もとに』で根拠を示す形になる。", "が": "『理念が』だと理念が主語になり、『もとに活動』と続かない。", "と": "『と』は並列や引用を示すので、『理念と＋もとに』は不自然。", "から": "『から』は起点を示すので、『理念からもとに』は成り立たない。"}, "error_tags": {"が": "主語化", "と": "並列・引用", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39297, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『反する』は『〜に反する』と『に』を取る。『自分の理念に反する仕事』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『反する』は『を』を取らないので、『理念を反する』は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すので、『理念で反する』は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、『理念へ反する』は不自然。"}], "correct_answer": "に", "explanations": {"に": "『反する』は『〜に反する』と『に』を取る。『自分の理念に反する仕事』が正しい。", "を": "『反する』は『を』を取らないので、『理念を反する』は成り立たない。", "で": "『で』は手段や場所を示すので、『理念で反する』は意味が通らない。", "へ": "『へ』は方向を示すので、『理念へ反する』は不自然。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39297, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の根底にある基本的な考え方や信念。", "primary_collocate": null, "pronunciation": "りねん", "ipa": "ɾiɲeɴ", "syllable_count": 3, "sentences": [{"text": "彼は「人を信じる」という理念を、どんな時も貫いている。", "target_word": "理念", "complexity_tier": "T3", "furigana": "彼[かれ]は「人[ひと]を信[しん]じる」という理念[りねん]を、どんな時[とき]も貫[つらぬ]いている。", "sentence_source": "generated"}, {"text": "この団体は、平和を守るという理念のもとに活動している。", "target_word": "理念", "complexity_tier": "T3", "furigana": "この団体[だんたい]は、平和[へいわ]を守[まも]るという理念[りねん]のもとに活動[かつどう]している。", "sentence_source": "generated"}, {"text": "理念を持たずに仕事をすると、困った時に迷ってしまう。", "target_word": "理念", "complexity_tier": "T3", "furigana": "理念[りねん]を持[も]たずに仕事[しごと]をすると、困[こま]った時[とき]に迷[まよ]ってしまう。", "sentence_source": "generated"}, {"text": "祖父の生き方には、はっきりした理念があった。", "target_word": "理念", "complexity_tier": "T3", "furigana": "祖父[そふ]の生[い]き方[かた]には、はっきりした理念[りねん]があった。", "sentence_source": "generated"}, {"text": "経営者が変わっても、会社の理念は変わらなかった。", "target_word": "理念", "complexity_tier": "T3", "furigana": "経営者[けいえいしゃ]が変[か]わっても、会社[かいしゃ]の理念[りねん]は変[か]わらなかった。", "sentence_source": "generated"}, {"text": "憲法の理念を、子どもたちにもわかりやすく伝えたい。", "target_word": "理念", "complexity_tier": "T3", "furigana": "憲法[けんぽう]の理念[りねん]を、子[こ]どもたちにもわかりやすく伝[つた]えたい。", "sentence_source": "generated"}, {"text": "理念の違いから、二人は別々の道を歩むことになった。", "target_word": "理念", "complexity_tier": "T3", "furigana": "理念[りねん]の違[ちが]いから、二人[ふたり]は別々[べつべつ]の道[みち]を歩[あゆ]むことになった。", "sentence_source": "generated"}, {"text": "彼女は自分の理念に反する仕事は引き受けない。", "target_word": "理念", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]の理念[りねん]に反[はん]する仕事[しごと]は引[ひ]き受[う]けない。", "sentence_source": "generated"}, {"text": "理念と現実の間で悩む教師は少なくない。", "target_word": "理念", "complexity_tier": "T3", "furigana": "理念[りねん]と現実[げんじつ]の間[あいだ]で悩[なや]む教師[きょうし]は少[すく]なくない。", "sentence_source": "generated"}, {"text": "その政党は、公平な社会という理念を訴えて選挙に臨んだ。", "target_word": "理念", "complexity_tier": "T3", "furigana": "その政党[せいとう]は、公平[こうへい]な社会[しゃかい]という理念[りねん]を訴[うった]えて選挙[せんきょ]に臨[のぞ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理念", "label": "基本形"}, {"form": "理念の", "label": "連体形（の）"}], "register": "formal", "sense_fingerprint": "物事の根底にある考え方や信念。人や組織が行動の拠り所にするもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39297, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理念", "is_correct": true, "explanation": "『という理念を貫いている』の目的語。考えや信念を貫く意味で自然につながる。"}, {"text": "距離", "is_correct": false, "explanation": "『距離を貫く』は意味が通らない。距離は間の長さを指す語。"}, {"text": "天気", "is_correct": false, "explanation": "天気は貫くものではない。ここでは考えや信念が入る。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は貫けるものではなく、命の長さを表す語。"}], "explanations": {"理念": "『という理念を貫いている』の目的語。考えや信念を貫く意味で自然につながる。", "距離": "『距離を貫く』は意味が通らない。距離は間の長さを指す語。", "天気": "天気は貫くものではない。ここでは考えや信念が入る。", "寿命": "寿命は貫けるものではなく、命の長さを表す語。"}, "sentence_index": 0, "correct_answer": "理念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末の理念は、家族で温泉に行くことだ。", "explanation": "ここは〈予定〉の意味。理念は物事の根底にある考えなので、週末の具体的な行き先の計画には使わない。"}, {"text": "料理の理念は、まず野菜を洗うことだ。", "explanation": "ここは〈手順〉の意味。理念は根本の考え方で、調理の順番には使わない。"}, {"text": "私の理念は、週末に山を歩くことだ。", "explanation": "ここは〈趣味〉の意味。理念は物事の根底の考えを指し、休日の過ごし方には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39297, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理念", "is_correct": true, "explanation": "『理念の違いから二人が別々の道を歩んだ』という文脈で、考え方の違いを指す語として正しい。"}, {"text": "季節", "is_correct": false, "explanation": "季節の違いで道が分かれたとは考えにくく、文意に合わない。季節は一年の区分を指す語。"}, {"text": "体重", "is_correct": false, "explanation": "体重の違いが別々の道を歩む理由になる文脈ではない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音の違いが道を分ける理由にはならず、文意に合わない。"}], "explanations": {"理念": "『理念の違いから二人が別々の道を歩んだ』という文脈で、考え方の違いを指す語として正しい。", "季節": "季節の違いで道が分かれたとは考えにくく、文意に合わない。季節は一年の区分を指す語。", "体重": "体重の違いが別々の道を歩む理由になる文脈ではない。", "騒音": "騒音の違いが道を分ける理由にはならず、文意に合わない。"}, "sentence_index": 6, "correct_answer": "理念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年の理念は、体重を五キロ減らすことだ。", "explanation": "ここは〈目標〉の意味。理念は根本の考えで、体重のような具体的な数値目標には使わない。"}, {"text": "来月の理念は、新しい店員を二人増やすことだ。", "explanation": "ここは〈方針〉の意味。理念は物事の根底の考えなので、来月に実行する人員の増加のような具体策には使わない。"}, {"text": "彼の理念は、穏やかで人当たりがよい。", "explanation": "ここは〈人柄〉の意味。理念は根本の考え方や信念を指すので、人の性格や人当たりの描写には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39297, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は家族を守るという理念に、いつも貫いている。", "corrected_sentence": "彼は家族を守るという理念を、いつも貫いている。", "error_description": "『貫く』は目的語に『を』を取る。『理念に』だと貫く対象が合わず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39297, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市長は、住民の声を聞くという理念を掲げは選挙に臨んだ。", "corrected_sentence": "市長は、住民の声を聞くという理念を掲げて選挙に臨んだ。", "error_description": "『掲げ』の後は『掲げて』と続けて『選挙に臨んだ』につなぐ。『掲げは』と助詞『は』を置くと文が途切れ、意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39298, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「隣人は」は話題を示し、私の隣人が犬の散歩をしているという文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「隣人を」は目的語を示すが、隣人を散歩の対象にする文ではないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「隣人へ散歩をする」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、隣人を出発点とする文にはならず不自然。"}], "correct_answer": "は", "explanations": {"は": "「隣人は」は話題を示し、私の隣人が犬の散歩をしているという文に合う。", "を": "「隣人を」は目的語を示すが、隣人を散歩の対象にする文ではないので合わない。", "へ": "「へ」は方向を示すが、「隣人へ散歩をする」は文として成り立たない。", "から": "起点の「から」は、隣人を出発点とする文にはならず不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39298, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「隣人が育てた」で、野菜を育てた主体を示す「が」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「隣人に育てた野菜」では、育てた主体を示せず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「隣人で育てた野菜」は場所や手段として解釈できず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "比べる相手がないので、「隣人より育てた野菜」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「隣人が育てた」で、野菜を育てた主体を示す「が」が正しい。", "に": "「隣人に育てた野菜」では、育てた主体を示せず文が成り立たない。", "で": "「隣人で育てた野菜」は場所や手段として解釈できず、不自然。", "より": "比べる相手がないので、「隣人より育てた野菜」は成り立たない。"}, "error_tags": {"に": "相手", "で": "場所・手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39298, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "となりに住んでいる人のこと。", "primary_collocate": null, "pronunciation": "りんじん", "ipa": "ɾindʑin", "syllable_count": 4, "sentences": [{"text": "隣人にあいさつをして、会社へ行きました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "隣人(りんじん)にあいさつをして、会社(かいしゃ)へ行(い)きました。", "sentence_source": "generated"}, {"text": "私の隣人は、いつも朝早く犬の散歩をしています。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "私(わたし)の隣人(りんじん)は、いつも朝早(あさはや)く犬(いぬ)の散歩(さんぽ)をしています。", "sentence_source": "generated"}, {"text": "引っ越しの日に、隣人がお菓子を持ってきてくれました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)しの日(ひ)に、隣人(りんじん)がお菓子(かし)を持(も)ってきてくれました。", "sentence_source": "generated"}, {"text": "夜に大きな音を出すと、隣人に迷惑がかかります。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "夜(よる)に大(おお)きな音(おと)を出(だ)すと、隣人(りんじん)に迷惑(めいわく)がかかります。", "sentence_source": "generated"}, {"text": "隣人とは仲がよく、旅行のおみやげを渡し合います。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "隣人(りんじん)とは仲(なか)がよく、旅行(りょこう)のおみやげを渡(わた)し合(あ)います。", "sentence_source": "generated"}, {"text": "新しい隣人は、やさしそうな家族でした。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "新(あたら)しい隣人(りんじん)は、やさしそうな家族(かぞく)でした。", "sentence_source": "generated"}, {"text": "留守のあいだ、隣人が荷物を受け取ってくれました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "留守(るす)のあいだ、隣人(りんじん)が荷物(にもつ)を受(う)け取(と)ってくれました。", "sentence_source": "generated"}, {"text": "隣人が育てた野菜を、おすそ分けしてもらいました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "隣人(りんじん)が育(そだ)てた野菜(やさい)を、おすそ分(わ)けしてもらいました。", "sentence_source": "generated"}, {"text": "台風の前に、隣人と一緒に庭の物を片づけました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "台風(たいふう)の前(まえ)に、隣人(りんじん)と一緒(いっしょ)に庭(にわ)の物(もの)を片(かた)づけました。", "sentence_source": "generated"}, {"text": "隣人の子どもが、うちの庭でよく遊んでいます。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "隣人(りんじん)の子(こ)どもが、うちの庭(にわ)でよく遊(あそ)んでいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "隣人", "label": "基本形"}, {"form": "隣人たち", "label": "複数形"}], "register": "中立（丁寧体）", "sense_fingerprint": "隣の家に住んでいる人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39298, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隣人", "is_correct": true, "explanation": "隣に住む人があいさつをする相手として成り立つ。"}, {"text": "天気", "is_correct": false, "explanation": "天気はあいさつの相手になれないので、「天気にあいさつをして」は意味が通らない。"}, {"text": "通勤", "is_correct": false, "explanation": "通勤は行為で、あいさつの相手にはならないので合わない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は物で、あいさつをする相手にはならない。"}], "explanations": {"隣人": "隣に住む人があいさつをする相手として成り立つ。", "天気": "天気はあいさつの相手になれないので、「天気にあいさつをして」は意味が通らない。", "通勤": "通勤は行為で、あいさつの相手にはならないので合わない。", "切符": "切符は物で、あいさつをする相手にはならない。"}, "sentence_index": 0, "correct_answer": "隣人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社の隣人と仕事を分担しました。", "explanation": "ここは〈同僚〉の意味。隣人は住まいが近い人を指すので、会社の仲間には合わない。"}, {"text": "町の隣人が集まり、祭りの準備をしました。", "explanation": "ここは〈住民〉の意味。隣人は隣に住む人を指すので、町全体の人には合わない。"}, {"text": "同じ家で暮らす隣人と、家事を分担しています。", "explanation": "ここは〈同居人〉の意味。隣人は別の家に住む人なので、一緒に暮らす人には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39298, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隣人", "is_correct": true, "explanation": "留守のあいだに荷物を受け取る人として成り立つ。"}, {"text": "電話", "is_correct": false, "explanation": "電話は荷物を受け取ることができないので、文が成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は物で、荷物を受け取る人の役割にはならない。"}, {"text": "花", "is_correct": false, "explanation": "花は物で、留守中に荷物を受け取ることはできないので不自然。"}], "explanations": {"隣人": "留守のあいだに荷物を受け取る人として成り立つ。", "電話": "電話は荷物を受け取ることができないので、文が成り立たない。", "窓": "窓は物で、荷物を受け取る人の役割にはならない。", "花": "花は物で、留守中に荷物を受け取ることはできないので不自然。"}, "sentence_index": 6, "correct_answer": "隣人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "観光に来た隣人が道を聞いてきました。", "explanation": "ここは〈旅行者〉の意味。隣人は近所に住む人なので、観光に来た人には合わない。"}, {"text": "遠くから来た隣人が、泊まっていきました。", "explanation": "ここは〈親戚〉の意味。隣人は近くに住む人を指すので、遠くから来る人には合わない。"}, {"text": "通りすがりの隣人に道を聞きました。", "explanation": "ここは〈通行人〉の意味。隣人は住まいが近い人を指すので、たまたま通りかかった人には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39298, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "うちの隣人を、旅行中に植木に水をやってくれました。", "corrected_sentence": "うちの隣人が、旅行中に植木に水をやってくれました。", "error_description": "助詞の誤り。動作の主体を示す「隣人が」が正しいが、「隣人を」になっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39298, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一人の隣人たちが、大雪の日に雪かきを手伝ってくれました。", "corrected_sentence": "一人の隣人が、大雪の日に雪かきを手伝ってくれました。", "error_description": "数と形の不一致。「一人の」には単数の「隣人」が合うが、複数形の「隣人たち」になっている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
