INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39299, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「隣人に頼んで」で、頼む相手を示す「に」が正しい。"}, {"text": "で", "is_correct": false, "explanation": "「隣人で頼んで」は場所や手段を示すように読め、人を相手にする文ではない。"}, {"text": "より", "is_correct": false, "explanation": "比べる相手がないので、「隣人より頼んで」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、頼む相手を示す文脈では不自然。"}], "correct_answer": "に", "explanations": {"に": "「隣人に頼んで」で、頼む相手を示す「に」が正しい。", "で": "「隣人で頼んで」は場所や手段を示すように読め、人を相手にする文ではない。", "より": "比べる相手がないので、「隣人より頼んで」は成り立たない。", "から": "起点の「から」は、頼む相手を示す文脈では不自然。"}, "error_tags": {"で": "場所・手段", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39299, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の家や土地のすぐ近くに住んでいる人のこと。", "primary_collocate": null, "pronunciation": "りんじん", "ipa": "ɾindʑin", "syllable_count": 4, "sentences": [{"text": "隣人とは、毎日顔を合わせます。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "隣人(りんじん)とは、毎日(まいにち)顔(かお)を合(あ)わせます。", "sentence_source": "generated"}, {"text": "畑の道具が足りなかったとき、隣人が貸してくれました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "畑(はたけ)の道具(どうぐ)が足(た)りなかったとき、隣人(りんじん)が貸(か)してくれました。", "sentence_source": "generated"}, {"text": "土地の境目のことで、隣人と話し合いました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "土地(とち)の境目(さかいめ)のことで、隣人(りんじん)と話(はな)し合(あ)いました。", "sentence_source": "generated"}, {"text": "田舎では、隣人との助け合いが大切にされています。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "田舎(いなか)では、隣人(りんじん)との助(たす)け合(あ)いが大切(たいせつ)にされています。", "sentence_source": "generated"}, {"text": "地震のとき、まず隣人の無事を確かめました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "地震(じしん)のとき、まず隣人(りんじん)の無事(ぶじ)を確(たし)かめました。", "sentence_source": "generated"}, {"text": "庭の木の枝が隣人の土地に入らないよう、切りました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "庭(にわ)の木(き)の枝(えだ)が隣人(りんじん)の土地(とち)に入(はい)らないよう、切(き)りました。", "sentence_source": "generated"}, {"text": "古くからの隣人が、町の祭りを手伝ってくれます。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "古(ふる)くからの隣人(りんじん)が、町(まち)の祭(まつ)りを手伝(てつだ)ってくれます。", "sentence_source": "generated"}, {"text": "隣人に頼んで、家の鍵を預かってもらいました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "隣人(りんじん)に頼(たの)んで、家(いえ)の鍵(かぎ)を預(あず)かってもらいました。", "sentence_source": "generated"}, {"text": "火事のとき、隣人が一番に知らせてくれました。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "火事(かじ)のとき、隣人(りんじん)が一番(いちばん)に知(し)らせてくれました。", "sentence_source": "generated"}, {"text": "同じ土地に長く住むと、隣人との付き合いも長くなります。", "target_word": "隣人", "complexity_tier": "T3", "furigana": "同(おな)じ土地(とち)に長(なが)く住(す)むと、隣人(りんじん)との付(つ)き合(あ)いも長(なが)くなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "隣人", "label": "基本形"}, {"form": "隣人たち", "label": "複数形"}], "register": "中立（丁寧体）", "sense_fingerprint": "自分の家や土地の近くに住む人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39299, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隣人", "is_correct": true, "explanation": "毎日顔を合わせる相手として、近くに住む人を表し文に合う。"}, {"text": "駅", "is_correct": false, "explanation": "駅は場所で、人と顔を合わせる対象にはならないので合わない。"}, {"text": "台所", "is_correct": false, "explanation": "台所は家の中の場所で、顔を合わせる相手にはならない。"}, {"text": "玄関", "is_correct": false, "explanation": "玄関は場所を指すので、「玄関と毎日顔を合わせます」は成り立たない。"}], "explanations": {"隣人": "毎日顔を合わせる相手として、近くに住む人を表し文に合う。", "駅": "駅は場所で、人と顔を合わせる対象にはならないので合わない。", "台所": "台所は家の中の場所で、顔を合わせる相手にはならない。", "玄関": "玄関は場所を指すので、「玄関と毎日顔を合わせます」は成り立たない。"}, "sentence_index": 0, "correct_answer": "隣人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同じ部活の隣人と練習しました。", "explanation": "ここは〈仲間〉の意味。隣人は住まいが近い人を指すので、部活の仲間には合わない。"}, {"text": "試合の隣人が大きな声援を送りました。", "explanation": "ここは〈観客〉の意味。隣人は近所の人を指すので、試合を見に来た人には合わない。"}, {"text": "隣人の政府と、貿易の協定を結びました。", "explanation": "ここは〈隣の国〉の意味。隣人は人を指すので、国や政府には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39299, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隣人", "is_correct": true, "explanation": "古くからの近所の人が町の祭りを手伝う、という文に合う。"}, {"text": "切符", "is_correct": false, "explanation": "切符は物で、祭りを手伝う主体にはならないので合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は建物の一部で、祭りを手伝うことはできない。"}, {"text": "看板", "is_correct": false, "explanation": "看板は物で、手伝う主体として成り立たない。"}], "explanations": {"隣人": "古くからの近所の人が町の祭りを手伝う、という文に合う。", "切符": "切符は物で、祭りを手伝う主体にはならないので合わない。", "天井": "天井は建物の一部で、祭りを手伝うことはできない。", "看板": "看板は物で、手伝う主体として成り立たない。"}, "sentence_index": 6, "correct_answer": "隣人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "交渉の隣人が、条件を変えてきました。", "explanation": "ここは〈相手〉の意味。隣人は近くに住む人を指すので、交渉の相手には合わない。"}, {"text": "家族の隣人が、毎朝お弁当を作ってくれます。", "explanation": "ここは〈家族〉の意味。隣人は別の家に住む人を指すので、一緒に暮らす家族には合わない。"}, {"text": "学校の隣人に質問しました。", "explanation": "ここは〈先生〉の意味。隣人は近所の人を指すので、教える立場の先生には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39299, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨の日に、隣人を車を移してくれました。", "corrected_sentence": "大雨の日に、隣人が車を移してくれました。", "error_description": "助詞の誤り。動作の主体を示す「隣人が」が正しいが、「隣人を」になっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39299, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一人の隣人たちが、大雪の日の朝に雪かきを手伝ってくれました。", "corrected_sentence": "一人の隣人が、大雪の日の朝に雪かきを手伝ってくれました。", "error_description": "数と形の不一致。「一人の」には単数の「隣人」が合うが、複数形の「隣人たち」になっている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39300, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を示す格助詞で、「汗をふいた」の「を」。ふく動作の対象は汗になる。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示すが、「汗にふいた」ではふく動作の対象にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「汗へふいた」は対象を表せず文に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「汗からふいた」では動作の対象を表せず意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "対象を示す格助詞で、「汗をふいた」の「を」。ふく動作の対象は汗になる。", "に": "位置や相手を示すが、「汗にふいた」ではふく動作の対象にならず不自然。", "へ": "方向を示すが、「汗へふいた」は対象を表せず文に合わない。", "から": "起点を示すが、「汗からふいた」では動作の対象を表せず意味が通らない。"}, "error_tags": {"に": "位置", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39300, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を示す格助詞で、「汗をかきやすい」の「を」。かく動作の対象は汗になる。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「汗でかきやすい」では動作の対象が示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、「汗とかきやすい」は動詞の対象として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示すが、「汗よりかきやすい」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "対象を示す格助詞で、「汗をかきやすい」の「を」。かく動作の対象は汗になる。", "で": "手段や場所を示すが、「汗でかきやすい」では動作の対象が示せず不自然。", "と": "並列や相手を示すが、「汗とかきやすい」は動詞の対象として成り立たない。", "より": "比較の基準を示すが、「汗よりかきやすい」では意味が通らない。"}, "error_tags": {"で": "手段", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39300, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体から出る水のようなもの。", "primary_collocate": null, "pronunciation": "あせ", "ipa": "ase", "syllable_count": 2, "sentences": [{"text": "夏は少し歩くだけで、汗が出る。", "target_word": "汗", "complexity_tier": "T2", "furigana": "夏[なつ]は少[すこ]し歩[ある]くだけで、汗[あせ]が出[で]る。", "sentence_source": "generated"}, {"text": "走ったあと、タオルで汗をふいた。", "target_word": "汗", "complexity_tier": "T2", "furigana": "走[はし]ったあと、タオルで汗[あせ]をふいた。", "sentence_source": "generated"}, {"text": "暑い部屋にいたので、背中に汗をかいた。", "target_word": "汗", "complexity_tier": "T2", "furigana": "暑[あつ]い部屋[へや]にいたので、背中[せなか]に汗[あせ]をかいた。", "sentence_source": "generated"}, {"text": "汗でシャツがぬれて、気持ちが悪い。", "target_word": "汗", "complexity_tier": "T3", "furigana": "汗[あせ]でシャツがぬれて、気持[きも]ちが悪[わる]い。", "sentence_source": "generated"}, {"text": "緊張で手のひらに汗が出た。", "target_word": "汗", "complexity_tier": "T3", "furigana": "緊張[きんちょう]で手[て]のひらに汗[あせ]が出[で]た。", "sentence_source": "generated"}, {"text": "運動のあとは汗をたくさんかくので、水を飲む。", "target_word": "汗", "complexity_tier": "T3", "furigana": "運動[うんどう]のあとは汗[あせ]をたくさんかくので、水[みず]を飲[の]む。", "sentence_source": "generated"}, {"text": "汗がひくまで、ベンチで休んだ。", "target_word": "汗", "complexity_tier": "T3", "furigana": "汗[あせ]がひくまで、ベンチで休[やす]んだ。", "sentence_source": "generated"}, {"text": "赤ちゃんは汗をかきやすいので、こまめに着替えさせる。", "target_word": "汗", "complexity_tier": "T4", "furigana": "赤[あか]ちゃんは汗[あせ]をかきやすいので、こまめに着替[きが]えさせる。", "sentence_source": "generated"}, {"text": "風呂に入って、一日の汗を流した。", "target_word": "汗", "complexity_tier": "T3", "furigana": "風呂[ふろ]に入[はい]って、一日[いちにち]の汗[あせ]を流[なが]した。", "sentence_source": "generated"}, {"text": "彼は額の汗をぬぐいながら、荷物を運んでいた。", "target_word": "汗", "complexity_tier": "T4", "furigana": "彼[かれ]は額[ひたい]の汗[あせ]をぬぐいながら、荷物[にもつ]を運[はこ]んでいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "汗", "label": "基本形"}], "register": "中立", "sense_fingerprint": "暑さや運動、緊張で皮膚から出る水分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39300, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汗", "is_correct": true, "explanation": "暑さや運動で皮膚から出る水分で、文の内容に合う。"}, {"text": "地図", "is_correct": false, "explanation": "紙や画面に描いた図で、体から出ることはない。"}, {"text": "砂利", "is_correct": false, "explanation": "細かい石の集まりで、体から出ることはない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便物に貼る小さな紙で、体から出ることはない。"}], "explanations": {"汗": "暑さや運動で皮膚から出る水分で、文の内容に合う。", "地図": "紙や画面に描いた図で、体から出ることはない。", "砂利": "細かい石の集まりで、体から出ることはない。", "切手": "郵便物に貼る小さな紙で、体から出ることはない。"}, "sentence_index": 0, "correct_answer": "汗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "けがをして、傷口から汗が流れた。", "explanation": "ここは〈血〉の意味。汗は皮膚から出る水分で、傷口から流れるものではない。"}, {"text": "フライパンに汗をひいた。", "explanation": "ここは〈油〉の意味。フライパンにひくのは油で、汗は体から出る水分なので合わない。"}, {"text": "空から汗が降ってきた。", "explanation": "ここは〈雨〉の意味。汗は体から出るもので、空から降ってくることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39300, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汗", "is_correct": true, "explanation": "「汗がひく」は汗が乾いて収まることで、文の内容に合う。"}, {"text": "靴下", "is_correct": false, "explanation": "身につける布製品で、「ひく」と組み合わない。"}, {"text": "大根", "is_correct": false, "explanation": "野菜の一種で、「ひく」と組み合わない。"}, {"text": "段ボール", "is_correct": false, "explanation": "箱に使う厚紙で、「ひく」と組み合わない。"}], "explanations": {"汗": "「汗がひく」は汗が乾いて収まることで、文の内容に合う。", "靴下": "身につける布製品で、「ひく」と組み合わない。", "大根": "野菜の一種で、「ひく」と組み合わない。", "段ボール": "箱に使う厚紙で、「ひく」と組み合わない。"}, "sentence_index": 6, "correct_answer": "汗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝の山は一面に汗が立ちこめていた。", "explanation": "ここは〈霧〉の意味。汗は体から出る水分で、山の一面に広がって漂うものではないので合わない。"}, {"text": "喉が渇いたので、冷蔵庫から汗を取り出して飲んだ。", "explanation": "ここは〈水〉の意味。汗は体から出るもので、冷蔵庫に保存して飲み物として取り出せるものではないので合わない。"}, {"text": "遠くで汗が鳴っている。", "explanation": "ここは〈雷〉の意味。汗は鳴るものではなく、音を立てない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39300, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "真夏の昼は、少し歩くだけで汗を出る。", "corrected_sentence": "真夏の昼は、少し歩くだけで汗が出る。", "error_description": "「出る」は主語に「が」を取る自動詞なので、「汗が出る」が正しい。「汗を出る」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39300, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暑い日は、外にいるだけで汗をたくさんかった。", "corrected_sentence": "暑い日は、外にいるだけで汗をたくさんかいた。", "error_description": "「かく」の過去形は「かいた」。「かった」は「かう」の過去形で、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39302, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『目指す』の目的語を示す『を』で、『包摂を目指して』と自然につながる。"}, {"text": "が", "is_correct": false, "explanation": "『目指す』は目的語を取る動詞なので、主語の『が』では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『目指す』は『に』で目標を取らず、『包摂に目指して』は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す『で』では、目指す対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "『目指す』の目的語を示す『を』で、『包摂を目指して』と自然につながる。", "が": "『目指す』は目的語を取る動詞なので、主語の『が』では文が成り立たない。", "に": "『目指す』は『に』で目標を取らず、『包摂に目指して』は不自然。", "で": "手段や場所を表す『で』では、目指す対象を示せない。"}, "error_tags": {"が": "主語", "に": "目標", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排除", "is_correct": true, "explanation": "社会から締め出す意味で、仲間に入れる包摂と対になる対義語。"}, {"text": "着色", "is_correct": false, "explanation": "色をつける意味で、仲間に入れることの対義語ではない。"}, {"text": "競争", "is_correct": false, "explanation": "勝ち負けを争う意味で、包摂の対義語ではない。"}, {"text": "読解", "is_correct": false, "explanation": "文章の意味を理解する意味で、包摂の対義語ではない。"}], "correct_answer": "排除", "explanations": {"排除": "社会から締め出す意味で、仲間に入れる包摂と対になる対義語。", "着色": "色をつける意味で、仲間に入れることの対義語ではない。", "競争": "勝ち負けを争う意味で、包摂の対義語ではない。", "読解": "文章の意味を理解する意味で、包摂の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39302, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排除", "is_correct": true, "explanation": "社会から締め出す意味で、仲間に入れる包摂と対になる対義語。"}, {"text": "減少", "is_correct": false, "explanation": "数や量が減る意味で、包摂の対義語ではない。"}, {"text": "放任", "is_correct": false, "explanation": "干渉しない意味で、仲間に入れないことを表す語ではない。"}, {"text": "停滞", "is_correct": false, "explanation": "進まない意味で、包摂の対義語ではない。"}], "correct_answer": "排除", "explanations": {"排除": "社会から締め出す意味で、仲間に入れる包摂と対になる対義語。", "減少": "数や量が減る意味で、包摂の対義語ではない。", "放任": "干渉しない意味で、仲間に入れないことを表す語ではない。", "停滞": "進まない意味で、包摂の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39302, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなを仲間に入れて、だれも取り残さないようにすること。", "primary_collocate": null, "pronunciation": "ほうせつ", "ipa": "hoːsetsɯ", "syllable_count": 4, "sentences": [{"text": "新しいメンバーも含めて皆を迎える包摂の姿勢が、このチームの強みだ。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "新[あたら]しいメンバーも含[ふく]めて皆[みな]を迎[むか]える包摂[ほうせつ]の姿勢[しせい]が、このチームの強[つよ]みだ。", "sentence_source": "generated"}, {"text": "一人も取り残さない包摂を目指して、クラスでルールを話し合った。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "一人[ひとり]も取[と]り残[のこ]さない包摂[ほうせつ]を目指[めざ]して、クラスでルールを話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "町内会は高齢者も子どもも包摂することで、活気のある集まりになった。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "町内会[ちょうないかい]は高齢者[こうれいしゃ]も子[こ]どもも包摂[ほうせつ]することで、活気[かっき]のある集[あつ]まりになった。", "sentence_source": "generated"}, {"text": "包摂を大切にする先生のおかげで、転校生もすぐに仲間になれた。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "包摂[ほうせつ]を大切[たいせつ]にする先生[せんせい]のおかげで、転校生[てんこうせい]もすぐに仲間[なかま]になれた。", "sentence_source": "generated"}, {"text": "言葉が違う人を仲間外れにしては、包摂とは言えない。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "言葉[ことば]が違[ちが]う人[ひと]を仲間外[なかまはず]れにしては、包摂[ほうせつ]とは言[い]えない。", "sentence_source": "generated"}, {"text": "誰も取り残さない包摂の考え方は、小さな部活動にも当てはまる。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "誰[だれ]も取[と]り残[のこ]さない包摂[ほうせつ]の考[かんが]え方[かた]は、小[ちい]さな部活動[ぶかつどう]にも当[あ]てはまる。", "sentence_source": "generated"}, {"text": "包摂がなければ、新しく入った人は居場所を見つけにくい。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "包摂[ほうせつ]がなければ、新[あたら]しく入[はい]った人[ひと]は居場所[いばしょ]を見[み]つけにくい。", "sentence_source": "generated"}, {"text": "彼は意見の違う人も包摂するリーダーとして信頼されている。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "彼[かれ]は意見[いけん]の違[ちが]う人[ひと]も包摂[ほうせつ]するリーダーとして信頼[しんらい]されている。", "sentence_source": "generated"}, {"text": "仲間を選ばず全員を受け入れる包摂が、この団体の約束である。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "仲間[なかま]を選[えら]ばず全員[ぜんいん]を受[う]け入[い]れる包摂[ほうせつ]が、この団体[だんたい]の約束[やくそく]である。", "sentence_source": "generated"}, {"text": "包摂を進めるため、会議では全員が一度は発言することになっている。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "包摂[ほうせつ]を進[すす]めるため、会議[かいぎ]では全員[ぜんいん]が一度[いちど]は発言[はつげん]することになっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "包摂", "label": "基本形"}, {"form": "包摂する", "label": "サ変動詞"}, {"form": "包摂した", "label": "過去形"}, {"form": "包摂される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "集団の中で全員を仲間に入れ、誰も取り残さないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39302, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包摂", "is_correct": true, "explanation": "文脈は『新しい人も含めて皆を迎える』姿勢を指し、包摂の意味と合う。"}, {"text": "包囲", "is_correct": false, "explanation": "囲んで閉じ込める意味で、迎える姿勢とは逆になり合わない。"}, {"text": "包装", "is_correct": false, "explanation": "物を包む意味で、人を迎える姿勢には使えない。"}, {"text": "検査", "is_correct": false, "explanation": "調べる意味で、迎える姿勢とは結びつかない。"}], "explanations": {"包摂": "文脈は『新しい人も含めて皆を迎える』姿勢を指し、包摂の意味と合う。", "包囲": "囲んで閉じ込める意味で、迎える姿勢とは逆になり合わない。", "包装": "物を包む意味で、人を迎える姿勢には使えない。", "検査": "調べる意味で、迎える姿勢とは結びつかない。"}, "sentence_index": 0, "correct_answer": "包摂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は失敗を包摂して、上司に報告しなかった。", "explanation": "ここは〈隠蔽〉の意味。包摂は仲間に入れることで、失敗を隠す意味はない。"}, {"text": "この菓子は、紙で丁寧に包摂されている。", "explanation": "ここは〈包装〉の意味。包摂には物を包む意味はない。"}, {"text": "祖父は古い手紙を包摂して、箱に大切にしまった。", "explanation": "ここは〈保管〉の意味。包摂は人を仲間に入れる意味で、物をしまう意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39302, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包摂", "is_correct": true, "explanation": "『包摂がなければ』は、仲間に入れる仕組みを指し、包摂と合う。"}, {"text": "漂白", "is_correct": false, "explanation": "物を白くする意味で、居場所の話とは合わない。"}, {"text": "伝票", "is_correct": false, "explanation": "書類の意味で、人を仲間に入れる話には合わない。"}, {"text": "屈折", "is_correct": false, "explanation": "光や言葉が曲がる意味で、居場所とは結びつかない。"}], "explanations": {"包摂": "『包摂がなければ』は、仲間に入れる仕組みを指し、包摂と合う。", "漂白": "物を白くする意味で、居場所の話とは合わない。", "伝票": "書類の意味で、人を仲間に入れる話には合わない。", "屈折": "光や言葉が曲がる意味で、居場所とは結びつかない。"}, "sentence_index": 6, "correct_answer": "包摂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "敵の軍勢が城を包摂して、三か月が過ぎた。", "explanation": "ここは〈包囲〉の意味。包摂は仲間に入れることで、軍勢が取り囲む様子は表さない。"}, {"text": "被災者に食料を包摂した。", "explanation": "ここは〈支給〉の意味。包摂は人を仲間に入れることで、物を配る意味はない。"}, {"text": "切手を包摂して、ノートにきれいに並べた。", "explanation": "ここは〈収集〉の意味。包摂は仲間に入れる意味で、物を集める意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39302, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "チームは、包摂で大切にしている。", "corrected_sentence": "チームは、包摂を大切にしている。", "error_description": "『大切にする』は目的語に『を』を取るので、『包摂で』は誤り。正しくは『包摂を』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39302, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "誰も包摂さない社会は問題だ。", "corrected_sentence": "誰も包摂されない社会は問題だ。", "error_description": "サ変動詞『包摂する』の受身は『包摂される』。『包摂さない』は『さ』の使い方が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39303, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排除", "is_correct": true, "explanation": "社会の外に置く意味で、社会への包摂と対になる対義語。"}, {"text": "管理", "is_correct": false, "explanation": "取り扱いを決める意味で、社会参加を広げる包摂の反対ではない。"}, {"text": "拡散", "is_correct": false, "explanation": "広がって散る意味で、対義語とは言えない。"}, {"text": "腐敗", "is_correct": false, "explanation": "物が傷む意味で、社会制度の文脈では対義語にならない。"}], "correct_answer": "排除", "explanations": {"排除": "社会の外に置く意味で、社会への包摂と対になる対義語。", "管理": "取り扱いを決める意味で、社会参加を広げる包摂の反対ではない。", "拡散": "広がって散る意味で、対義語とは言えない。", "腐敗": "物が傷む意味で、社会制度の文脈では対義語にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39303, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排除", "is_correct": true, "explanation": "社会の外に置く意味で、社会への包摂と対になる対義語。"}, {"text": "分配", "is_correct": false, "explanation": "分け与える意味で、仲間に入れるかどうかの対義語ではない。"}, {"text": "交換", "is_correct": false, "explanation": "取り替える意味で、包摂の反対を表す語ではない。"}, {"text": "沈黙", "is_correct": false, "explanation": "黙る意味で、社会制度の対義語にはならない。"}], "correct_answer": "排除", "explanations": {"排除": "社会の外に置く意味で、社会への包摂と対になる対義語。", "分配": "分け与える意味で、仲間に入れるかどうかの対義語ではない。", "交換": "取り替える意味で、包摂の反対を表す語ではない。", "沈黙": "黙る意味で、社会制度の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39303, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会の一員として、すべての人が平等に参加し、支援を受けられるようにすること。", "primary_collocate": null, "pronunciation": "ほうせつ", "ipa": "hoːsetsɯ", "syllable_count": 4, "sentences": [{"text": "障害のある人の包摂を進めるため、市は相談窓口を増やした。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "障害[しょうがい]のある人[ひと]の包摂[ほうせつ]を進[すす]めるため、市[し]は相談窓口[そうだんまどぐち]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "仕事に就きにくい若者を包摂する制度が、国で始まった。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "仕事[しごと]に就[つ]きにくい若者[わかもの]を包摂[ほうせつ]する制度[せいど]が、国[くに]で始[はじ]まった。", "sentence_source": "generated"}, {"text": "社会の包摂が進めば、誰もが支援を受けながら地域の活動に参加できる。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "社会[しゃかい]の包摂[ほうせつ]が進[すす]めば、誰[だれ]もが支援[しえん]を受[う]けながら地域[ちいき]の活動[かつどう]に参加[さんか]できる。", "sentence_source": "generated"}, {"text": "外国人住民の包摂には、日本語の学習支援が欠かせない。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]住民[じゅうみん]の包摂[ほうせつ]には、日本語[にほんご]の学習[がくしゅう]支援[しえん]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "貧しい家庭の子どもを包摂する政策が、学校で実施されている。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "貧[まず]しい家庭[かてい]の子[こ]どもを包摂[ほうせつ]する政策[せいさく]が、学校[がっこう]で実施[じっし]されている。", "sentence_source": "generated"}, {"text": "包摂が足りない社会では、支援を必要とする人が孤立しやすい。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "包摂[ほうせつ]が足[た]りない社会[しゃかい]では、支援[しえん]を必要[ひつよう]とする人[ひと]が孤立[こりつ]しやすい。", "sentence_source": "generated"}, {"text": "高齢者の包摂を目指し、町は無料の送迎バスを走らせている。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "高齢者[こうれいしゃ]の包摂[ほうせつ]を目指[めざ]し、町[まち]は無料[むりょう]の送迎[そうげい]バスを走[はし]らせている。", "sentence_source": "generated"}, {"text": "会社は障害のある社員を包摂して、平等に働ける環境を整えた。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は障害[しょうがい]のある社員[しゃいん]を包摂[ほうせつ]して、平等[びょうどう]に働[はたら]ける環境[かんきょう]を整[ととの]えた。", "sentence_source": "generated"}, {"text": "福祉の目的は、困っている人を社会に包摂することである。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "福祉[ふくし]の目的[もくてき]は、困[こま]っている人[ひと]を社会[しゃかい]に包摂[ほうせつ]することである。", "sentence_source": "generated"}, {"text": "包摂を実現するには、参加の機会と支援の両方が必要だ。", "target_word": "包摂", "complexity_tier": "T3", "furigana": "包摂[ほうせつ]を実現[じつげん]するには、参加[さんか]の機会[きかい]と支援[しえん]の両方[りょうほう]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "包摂", "label": "基本形"}, {"form": "包摂する", "label": "サ変動詞"}, {"form": "包摂した", "label": "過去形"}, {"form": "包摂される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "社会制度として、すべての人が平等に参加でき支援を受けられるようにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39303, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包摂", "is_correct": true, "explanation": "社会制度として支援を広げる文脈で、包摂が合う。"}, {"text": "清掃", "is_correct": false, "explanation": "掃除の意味で、障害のある人を対象にすると不自然。"}, {"text": "喫煙", "is_correct": false, "explanation": "たばこを吸う意味で、支援を進める文脈とは合わない。"}, {"text": "包囲", "is_correct": false, "explanation": "囲む意味で、支援の窓口を増やす文脈とは合わない。"}], "explanations": {"包摂": "社会制度として支援を広げる文脈で、包摂が合う。", "清掃": "掃除の意味で、障害のある人を対象にすると不自然。", "喫煙": "たばこを吸う意味で、支援を進める文脈とは合わない。", "包囲": "囲む意味で、支援の窓口を増やす文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "包摂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この茶葉は、和紙で一つずつ包摂してある。", "explanation": "ここは〈包装〉の意味。包摂は仲間に入れることで、物を包む意味はない。"}, {"text": "嵐の中で遭難者を包摂した。", "explanation": "ここは〈救助〉の意味。包摂は仲間に入れることで、遭難者を助け出す意味はない。"}, {"text": "機械を包摂して、故障を見つけた。", "explanation": "ここは〈点検〉の意味。包摂は仲間に入れる意味で、機械を調べる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39303, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包摂", "is_correct": true, "explanation": "高齢者が社会に参加できるよう支える文脈で、包摂が合う。"}, {"text": "離婚", "is_correct": false, "explanation": "夫婦の関係を終える意味で、高齢者を社会に迎える目標とは合わない。"}, {"text": "採寸", "is_correct": false, "explanation": "体の寸法を測る意味で、送迎バスの文脈とは結びつかない。"}, {"text": "泡立て", "is_correct": false, "explanation": "泡を立てる意味で、社会の支援とは関係しない。"}], "explanations": {"包摂": "高齢者が社会に参加できるよう支える文脈で、包摂が合う。", "離婚": "夫婦の関係を終える意味で、高齢者を社会に迎える目標とは合わない。", "採寸": "体の寸法を測る意味で、送迎バスの文脈とは結びつかない。", "泡立て": "泡を立てる意味で、社会の支援とは関係しない。"}, "sentence_index": 6, "correct_answer": "包摂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "敵の軍勢が村を包摂して、三日間続いた。", "explanation": "ここは〈包囲〉の意味。包摂は仲間に入れる意味で、軍勢が取り囲む様子は表さない。"}, {"text": "町はチラシを包摂して、全世帯に配った。", "explanation": "ここは〈配布〉の意味。包摂は仲間に入れる意味で、物を配る意味はない。"}, {"text": "荷物を包摂して、北海道まで運送した。", "explanation": "ここは〈運送〉の意味。包摂は人を仲間に入れることで、荷物を運ぶ意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39303, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "障害のある人に包摂する制度が増えた。", "corrected_sentence": "障害のある人を包摂する制度が増えた。", "error_description": "『包摂する』は対象に『を』を取る。『人に』は『人を』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39303, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "困っている人は社会に包摂れなかった。", "corrected_sentence": "困っている人は社会に包摂されなかった。", "error_description": "『包摂する』の受身は『包摂される』。『包摂れ』は『さ』が抜けていて誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39304, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「余所者の彼」の「の」。余所者を彼の前に続けて、彼を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "余所者を目的語にすると「余所者を彼は」となり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、余所者の後に続けると意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「余所者に彼は」は、迷った主語との関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「余所者の彼」の「の」。余所者を彼の前に続けて、彼を修飾する。", "を": "余所者を目的語にすると「余所者を彼は」となり、文が成り立たない。", "へ": "方向を表す「へ」は、余所者の後に続けると意味が通らない。", "に": "「余所者に彼は」は、迷った主語との関係が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "位置・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39304, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「クラスの余所者のように」の「の」。余所者を「ように」の前に続けて、比喩の対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「クラスに余所者」は相手・場所として続かず、「のように」の比喩が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「余所者が ように」は主語として続かず、比喩の文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「余所者と ように」は相手を示す形になり、比喩の文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「クラスの余所者のように」の「の」。余所者を「ように」の前に続けて、比喩の対象を示す。", "に": "「クラスに余所者」は相手・場所として続かず、「のように」の比喩が成り立たない。", "が": "「余所者が ように」は主語として続かず、比喩の文に合わない。", "と": "「余所者と ように」は相手を示す形になり、比喩の文として成り立たない。"}, "error_tags": {"に": "位置・相手", "が": "主語", "と": "相手・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39304, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の住んでいる場所とは違うところから来た人のことです。", "primary_collocate": null, "pronunciation": "よそもの", "ipa": "josomono", "syllable_count": 4, "sentences": [{"text": "この村では、私はまだ余所者だと思われている。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "この村[むら]では、私[わたし]はまだ余所者[よそもの]だと思[おも]われている。", "sentence_source": "generated"}, {"text": "余所者の彼は、道がわからなくて何度も迷った。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "余所者[よそもの]の彼[かれ]は、道[みち]がわからなくて何度[なんど]も迷[まよ]った。", "sentence_source": "generated"}, {"text": "町の人は最初、余所者の私に冷たかった。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]は最初[さいしょ]、余所者[よそもの]の私[わたし]に冷[つめ]たかった。", "sentence_source": "generated"}, {"text": "余所者でも、長く住めば仲間になれる。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "余所者[よそもの]でも、長[なが]く住[す]めば仲間[なかま]になれる。", "sentence_source": "generated"}, {"text": "祭りに余所者が来ると、すぐに分かる小さな町だ。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "祭[まつ]りに余所者[よそもの]が来[く]ると、すぐに分[わ]かる小[ちい]さな町[まち]だ。", "sentence_source": "generated"}, {"text": "彼女は都会から来た余所者として、村で暮らし始めた。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は都会[とかい]から来[き]た余所者[よそもの]として、村[むら]で暮[く]らし始[はじ]めた。", "sentence_source": "generated"}, {"text": "余所者の意見も、聞いてみる価値がある。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "余所者[よそもの]の意見[いけん]も、聞[き]いてみる価値[かち]がある。", "sentence_source": "generated"}, {"text": "転校してきた私は、クラスの余所者のように感じた。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "転校[てんこう]してきた私[わたし]は、クラスの余所者[よそもの]のように感[かん]じた。", "sentence_source": "generated"}, {"text": "店の主人は、余所者の客にも親切だった。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "店[みせ]の主人[しゅじん]は、余所者[よそもの]の客[きゃく]にも親切[しんせつ]だった。", "sentence_source": "generated"}, {"text": "余所者だからと言って、遠慮することはない。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "余所者[よそもの]だからと言[い]って、遠慮[えんりょ]することはない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "余所者", "label": "基本形"}], "register": "中立", "sense_fingerprint": "よその土地から来た人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39304, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "余所者", "is_correct": true, "explanation": "ここでは〈別の土地から来た人〉の意味。村の外から来た私に合う語。"}, {"text": "果物", "is_correct": false, "explanation": "人を指す語ではないので、「果物だと思われている」は意味が通らない。"}, {"text": "機械", "is_correct": false, "explanation": "人を指す語ではないので、「機械だと思われている」は不自然。"}, {"text": "看板", "is_correct": false, "explanation": "人間関係の文脈に合わず、「看板だと思われている」は成り立たない。"}], "explanations": {"余所者": "ここでは〈別の土地から来た人〉の意味。村の外から来た私に合う語。", "果物": "人を指す語ではないので、「果物だと思われている」は意味が通らない。", "機械": "人を指す語ではないので、「機械だと思われている」は不自然。", "看板": "人間関係の文脈に合わず、「看板だと思われている」は成り立たない。"}, "sentence_index": 0, "correct_answer": "余所者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古くからの余所者は、昔からの祭りをよく知っている。", "explanation": "ここは〈古くからの住人〉の意味。余所者は他所から来た人なので、昔から住む人には使えない。"}, {"text": "隣の家の余所者は、いつも回覧板を回してくれる。", "explanation": "ここは〈隣人〉の意味。余所者は他所から来た人なので、隣に住む人には使えない。"}, {"text": "運転中の余所者は、事故の原因になりやすい。", "explanation": "余所者は人を指す語なので、わき見の意味の文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39304, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余所者", "is_correct": true, "explanation": "ここでは〈よそから来た人〉の意味。「余所者の意見」として自然。"}, {"text": "石鹸", "is_correct": false, "explanation": "意見を持つ人を表さないので、「石鹸の意見」は成り立たない。"}, {"text": "窓口", "is_correct": false, "explanation": "人を指す語としても「窓口の意見」は不自然で、文の意味に合わない。"}, {"text": "時計", "is_correct": false, "explanation": "意見を述べる主体にならず、「時計の意見」は意味が通らない。"}], "explanations": {"余所者": "ここでは〈よそから来た人〉の意味。「余所者の意見」として自然。", "石鹸": "意見を持つ人を表さないので、「石鹸の意見」は成り立たない。", "窓口": "人を指す語としても「窓口の意見」は不自然で、文の意味に合わない。", "時計": "意見を述べる主体にならず、「時計の意見」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "余所者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町の景色は、この十年で余所者に変わった。", "explanation": "ここは〈様子〉の意味。余所者は人を指す語なので、町の様子が変わる意味には使えない。"}, {"text": "私は町で生まれ育ったので、余所者の道をよく知っている。", "explanation": "ここは〈土地の地理〉の意味。余所者は人を指す語なので、道の詳しさには使えない。"}, {"text": "祖母は、庭の鉢植えを余所者の場所に移した。", "explanation": "ここは〈置き場〉の意味。余所者は人を指す語なので、鉢植えの置き場には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39304, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "余所者を友人は、この町の道がわからず何度も迷った。", "corrected_sentence": "余所者の友人は、この町の道がわからず何度も迷った。", "error_description": "「余所者の友人」の「の」を「を」に変えると、余所者が目的語になり、文の主語が成り立たない。正しくは「余所者の友人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39304, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町に来たばかりの余所者が意見も、聞いてみる価値がある。", "corrected_sentence": "町に来たばかりの余所者の意見も、聞いてみる価値がある。", "error_description": "「余所者の意見」の「の」を「が」に変えると、余所者が意見の主体になり、「意見も」の続きが不自然になる。正しくは「余所者の意見」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39305, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「昔から住む人と余所者の間」の「の」。余所者を「間」の前に続けて、関係の一方を示す。"}, {"text": "を", "is_correct": false, "explanation": "「余所者を間に壁」は目的語としても、壁の文脈としても成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「余所者へ間」となり、関係を示す文に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は「余所者から間」となり、壁の関係を示せない。"}], "correct_answer": "の", "explanations": {"の": "「昔から住む人と余所者の間」の「の」。余所者を「間」の前に続けて、関係の一方を示す。", "を": "「余所者を間に壁」は目的語としても、壁の文脈としても成り立たない。", "へ": "方向を表す「へ」は「余所者へ間」となり、関係を示す文に合わない。", "から": "起点を表す「から」は「余所者から間」となり、壁の関係を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39305, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「余所者が畑に入る」の「が」。余所者が動作の主体であることを示す。"}, {"text": "で", "is_correct": false, "explanation": "「余所者で畑に入る」は手段や場所の意味になり、主語を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「余所者を畑に」は目的語が二つ続き、「入る」と結びつかない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「余所者より畑に入る」となり、主語を示す文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「余所者が畑に入る」の「が」。余所者が動作の主体であることを示す。", "で": "「余所者で畑に入る」は手段や場所の意味になり、主語を示せない。", "を": "「余所者を畑に」は目的語が二つ続き、「入る」と結びつかない。", "より": "比較の「より」は「余所者より畑に入る」となり、主語を示す文に合わない。"}, "error_tags": {"で": "手段・場所", "を": "目的語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39305, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "その地域に元々住んでいない人。よそから来た人。", "primary_collocate": null, "pronunciation": "よそもの", "ipa": "josomono", "syllable_count": 4, "sentences": [{"text": "余所者は土地のしきたりを知らないことが多い。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "余所者[よそもの]は土地[とち]のしきたりを知[し]らないことが多[おお]い。", "sentence_source": "generated"}, {"text": "この島では、昔から住む人と余所者の間に壁があった。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "この島[しま]では、昔[むかし]から住[す]む人[ひと]と余所者[よそもの]の間[あいだ]に壁[かべ]があった。", "sentence_source": "generated"}, {"text": "元々この町に住んでいない私は、余所者だ。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "元々[もともと]この町[まち]に住[す]んでいない私[わたし]は、余所者[よそもの]だ。", "sentence_source": "generated"}, {"text": "余所者を受け入れる町が増えている。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "余所者[よそもの]を受[う]け入[い]れる町[まち]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "余所者と言われて、集まりにも誘われなかった。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "余所者[よそもの]と言[い]われて、集[あつ]まりにも誘[さそ]われなかった。", "sentence_source": "generated"}, {"text": "余所者の目から見ると、この町の良さがよく分かる。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "余所者[よそもの]の目[め]から見[み]ると、この町[まち]の良[よ]さがよく分[わ]かる。", "sentence_source": "generated"}, {"text": "引っ越して五年になるが、まだ余所者だと感じる。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]して五年[ごねん]になるが、まだ余所者[よそもの]だと感[かん]じる。", "sentence_source": "generated"}, {"text": "地元の人は、余所者が畑に入るのを嫌がった。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "地元[じもと]の人[ひと]は、余所者[よそもの]が畑[はたけ]に入[はい]るのを嫌[いや]がった。", "sentence_source": "generated"}, {"text": "余所者の彼が町長になって、みんな驚いた。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "余所者[よそもの]の彼[かれ]が町長[ちょうちょう]になって、みんな驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "山の村では、余所者に家を貸さない家も多い。", "target_word": "余所者", "complexity_tier": "T3", "furigana": "山[やま]の村[むら]では、余所者[よそもの]に家[いえ]を貸[か]さない家[いえ]も多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "余所者", "label": "基本形"}], "register": "中立", "sense_fingerprint": "その地域に元から住んでいない、よそから来た人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39305, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "余所者", "is_correct": true, "explanation": "ここでは〈その地域に元々住んでいない人〉の意味。土地のしきたりを知らない人に合う。"}, {"text": "果物", "is_correct": false, "explanation": "人ではないので、「果物は土地のしきたりを知らない」は意味が通らない。"}, {"text": "機械", "is_correct": false, "explanation": "しきたりを知る主体にならず、「機械は土地のしきたりを知らない」は成り立たない。"}, {"text": "看板", "is_correct": false, "explanation": "物の名前なので、しきたりを知らないという主語にはならない。"}], "explanations": {"余所者": "ここでは〈その地域に元々住んでいない人〉の意味。土地のしきたりを知らない人に合う。", "果物": "人ではないので、「果物は土地のしきたりを知らない」は意味が通らない。", "機械": "しきたりを知る主体にならず、「機械は土地のしきたりを知らない」は成り立たない。", "看板": "物の名前なので、しきたりを知らないという主語にはならない。"}, "sentence_index": 0, "correct_answer": "余所者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古くなった鍋を、余所者に買い替えた。", "explanation": "ここは〈新品〉の意味。余所者は人を指す語なので、物の買い替えには使えない。"}, {"text": "地元の余所者は、祭りの準備を毎年手伝っている。", "explanation": "ここは〈古くからの住民〉の意味。余所者はよそから来た人なので、昔から住む人には使えない。"}, {"text": "同居人の余所者は、夜遅くまで音楽を聴いている。", "explanation": "ここは〈同じ家で暮らす人〉の意味。余所者は他所から来た人なので、同じ家で暮らす人には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39305, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余所者", "is_correct": true, "explanation": "ここでは〈よそから来た人〉の意味。まだ余所者だと感じる、という文脈に合う。"}, {"text": "石鹸", "is_correct": false, "explanation": "人を指さないので、「まだ石鹸だと感じる」は成り立たない。"}, {"text": "窓口", "is_correct": false, "explanation": "人の立場を表す語ではなく、「まだ窓口だと感じる」は意味が通らない。"}, {"text": "時計", "is_correct": false, "explanation": "感じる対象として不自然で、「まだ時計だと感じる」は成り立たない。"}], "explanations": {"余所者": "ここでは〈よそから来た人〉の意味。まだ余所者だと感じる、という文脈に合う。", "石鹸": "人を指さないので、「まだ石鹸だと感じる」は成り立たない。", "窓口": "人の立場を表す語ではなく、「まだ窓口だと感じる」は意味が通らない。", "時計": "感じる対象として不自然で、「まだ時計だと感じる」は成り立たない。"}, "sentence_index": 6, "correct_answer": "余所者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は、雨の降る日を余所者と呼んで、家で過ごした。", "explanation": "ここは〈休日〉の意味。余所者は人を指す語なので、日の呼び名には使えない。"}, {"text": "店の常連の彼は、毎日、余所者の指定席に通された。", "explanation": "ここは〈お気に入りの場所〉の意味。余所者は人を指す語なので、席の呼び名には使えない。"}, {"text": "式では、余所者の一張羅を着る人が多い。", "explanation": "ここは〈晴れ着〉の意味。余所者は人を指す語なので、服の呼び名には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39305, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の古い祭りには、余所者が参加も歓迎されるようになった。", "corrected_sentence": "町の古い祭りには、余所者の参加も歓迎されるようになった。", "error_description": "「余所者の参加」の「の」を「が」に変えると、余所者が参加の主体になり、文が成り立たない。正しくは「余所者の参加」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39305, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "引っ越して五年たつが、私はまだ余所者を見られている。", "corrected_sentence": "引っ越して五年たつが、私はまだ余所者として見られている。", "error_description": "「余所者として」の「として」を「を」に変えると、余所者が見る対象になり、「見られている」と合わなくなる。正しくは「余所者として」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
