INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39306, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ずっと前からそこにあったもので、新しく来たものではないこと。", "primary_collocate": null, "pronunciation": "ざいらい", "ipa": "dzaiɾai", "syllable_count": 4, "sentences": [{"text": "在来の方法では、この問題を解決するのは難しい。", "target_word": "在来", "complexity_tier": "T3", "furigana": "在来[ざいらい]の方法[ほうほう]では、この問題[もんだい]を解決[かいけつ]するのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "新しい機械は、在来のものより二倍も速く動く。", "target_word": "在来", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]は、在来[ざいらい]のものより二倍[にばい]も速[はや]く動[うご]く。", "sentence_source": "generated"}, {"text": "在来の品種は味が濃いが、育てるのに手間がかかる。", "target_word": "在来", "complexity_tier": "T3", "furigana": "在来[ざいらい]の品種[ひんしゅ]は味[あじ]が濃[こ]いが、育[そだ]てるのに手間[てま]がかかる。", "sentence_source": "generated"}, {"text": "工場は在来の技術を生かして、新しい製品を作った。", "target_word": "在来", "complexity_tier": "T3", "furigana": "工場[こうじょう]は在来[ざいらい]の技術[ぎじゅつ]を生[い]かして、新[あたら]しい製品[せいひん]を作[つく]った。", "sentence_source": "generated"}, {"text": "在来のやり方に慣れた職人は、新しい道具に戸惑った。", "target_word": "在来", "complexity_tier": "T3", "furigana": "在来[ざいらい]のやり方[かた]に慣[な]れた職人[しょくにん]は、新[あたら]しい道具[どうぐ]に戸惑[とまど]った。", "sentence_source": "generated"}, {"text": "この店は在来の味を守りながら、新しいメニューも増やした。", "target_word": "在来", "complexity_tier": "T3", "furigana": "この店[みせ]は在来[ざいらい]の味[あじ]を守[まも]りながら、新[あたら]しいメニューも増[ふ]やした。", "sentence_source": "generated"}, {"text": "在来の稲は寒さに強いので、今でも山の村で育てられている。", "target_word": "在来", "complexity_tier": "T3", "furigana": "在来[ざいらい]の稲[いね]は寒[さむ]さに強[つよ]いので、今[いま]でも山[やま]の村[むら]で育[そだ]てられている。", "sentence_source": "generated"}, {"text": "新型は在来の型より軽く、持ち運びが楽になった。", "target_word": "在来", "complexity_tier": "T3", "furigana": "新型[しんがた]は在来[ざいらい]の型[かた]より軽[かる]く、持[も]ち運[はこ]びが楽[らく]になった。", "sentence_source": "generated"}, {"text": "在来の考え方にとらわれては、新しい案は生まれない。", "target_word": "在来", "complexity_tier": "T3", "furigana": "在来[ざいらい]の考[かんが]え方[かた]にとらわれては、新[あたら]しい案[あん]は生[う]まれない。", "sentence_source": "generated"}, {"text": "在来のものをすべて捨てるのではなく、よい点は残すことにした。", "target_word": "在来", "complexity_tier": "T3", "furigana": "在来[ざいらい]のものをすべて捨[す]てるのではなく、よい点[てん]は残[のこ]すことにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "在来", "label": "基本形"}, {"form": "在来の", "label": "連体形（の）"}], "register": "formal", "sense_fingerprint": "以前からあって新しく登場したものではないこと。従来の方法・品種・型などに使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39306, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在来", "is_correct": true, "explanation": "『在来の方法』で、以前からある方法を指す。ここでは在来が正しい。"}, {"text": "失恋", "is_correct": false, "explanation": "『失恋の方法では』は意味が通らない。"}, {"text": "睡眠", "is_correct": false, "explanation": "『睡眠の方法では』は成り立たず、文意に合わない。"}, {"text": "夕方", "is_correct": false, "explanation": "『夕方の方法では』では問題解決の話にならず、文意に合わない。"}], "explanations": {"在来": "『在来の方法』で、以前からある方法を指す。ここでは在来が正しい。", "失恋": "『失恋の方法では』は意味が通らない。", "睡眠": "『睡眠の方法では』は成り立たず、文意に合わない。", "夕方": "『夕方の方法では』では問題解決の話にならず、文意に合わない。"}, "sentence_index": 0, "correct_answer": "在来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外国から入ってきた在来の植物が、川の周りで増えている。", "explanation": "ここは〈外来〉の意味。在来は以前からあったものを指すので、外国から入ってきたものには合わない。"}, {"text": "この工場では、在来の試作品を三つ作って比べた。", "explanation": "ここは〈試作品〉の意味。試作品は新しく作るものなので、以前からあったという在来とは矛盾する。"}, {"text": "この工場は、新しく開発された在来の機械を三台導入した。", "explanation": "ここは〈新型〉の意味。在来は新しく登場したものではないという意味なので、新開発の機械には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39306, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在来", "is_correct": true, "explanation": "『在来の稲』で、昔からある品種の稲を指す。ここでは在来が正しい。"}, {"text": "失業", "is_correct": false, "explanation": "『失業の稲』は意味が通らない。"}, {"text": "感動", "is_correct": false, "explanation": "『感動の稲』は稲を修飾せず、文意に合わない。"}, {"text": "寝不足", "is_correct": false, "explanation": "『寝不足の稲』は寒さに強い稲の話として不自然。"}], "explanations": {"在来": "『在来の稲』で、昔からある品種の稲を指す。ここでは在来が正しい。", "失業": "『失業の稲』は意味が通らない。", "感動": "『感動の稲』は稲を修飾せず、文意に合わない。", "寝不足": "『寝不足の稲』は寒さに強い稲の話として不自然。"}, "sentence_index": 6, "correct_answer": "在来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海外から輸入した在来のエビを、川に放してしまった。", "explanation": "ここは〈輸入〉の意味。在来は以前からあったものを指すので、海外から入れたものには合わない。"}, {"text": "この作家は、今まで誰も見たことのない在来の作品を次々と発表している。", "explanation": "ここは〈新作〉の意味。在来は以前からあったものを指すので、発表されたばかりの作品には使わない。"}, {"text": "この店は、新しく入った在来の商品を店頭に並べた。", "explanation": "ここは〈新しく入った〉の意味。在来は以前からあったものを指すので、新しく入った商品には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39306, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在来を技術は、もう時代に合わなくなってきた。", "corrected_sentence": "在来の技術は、もう時代に合わなくなってきた。", "error_description": "『在来』は後ろの名詞を修飾する『在来の』の形で使う。『在来を』と格助詞『を』を付けると名詞を修飾できず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39306, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在来な方法は、今でも多くの農家で守られている。", "corrected_sentence": "在来の方法は、今でも多くの農家で守られている。", "error_description": "『在来』は名詞なので、後ろに付くときは『在来の』とする。形容動詞の語尾『な』を付けると誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39307, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外来", "is_correct": true, "explanation": "外から入ってきたものを指し、在来の対義語になる。"}, {"text": "新規", "is_correct": false, "explanation": "新しく作る・始めるという意味で、在来の対義語ではない。"}, {"text": "国産", "is_correct": false, "explanation": "国内で作られたものを指す語で、在来の対義語にはならない。"}, {"text": "輸入", "is_correct": false, "explanation": "外国から買い入れる意味で、在来の対義語ではない。"}], "correct_answer": "外来", "explanations": {"外来": "外から入ってきたものを指し、在来の対義語になる。", "新規": "新しく作る・始めるという意味で、在来の対義語ではない。", "国産": "国内で作られたものを指す語で、在来の対義語にはならない。", "輸入": "外国から買い入れる意味で、在来の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39307, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外来", "is_correct": true, "explanation": "外から入ってきたものを指し、在来の対義語になる。"}, {"text": "国内", "is_correct": false, "explanation": "国の内側を指す語で、在来の対義語ではない。"}, {"text": "固有", "is_correct": false, "explanation": "その地域だけに見られる意味。在来と近い語だが、対義語ではない。"}, {"text": "新型", "is_correct": false, "explanation": "新しい型の意味で、在来の対義語とは言えない。"}], "correct_answer": "外来", "explanations": {"外来": "外から入ってきたものを指し、在来の対義語になる。", "国内": "国の内側を指す語で、在来の対義語ではない。", "固有": "その地域だけに見られる意味。在来と近い語だが、対義語ではない。", "新型": "新しい型の意味で、在来の対義語とは言えない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39307, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "その土地にもともとあって、新しく入ってきたものではないこと。", "primary_collocate": null, "pronunciation": "ざいらい", "ipa": "dzaiɾai", "syllable_count": 4, "sentences": [{"text": "池の在来の魚が、外から来た魚に食べられて減っている。", "target_word": "在来", "complexity_tier": "T3", "furigana": "池[いけ]の在来[ざいらい]の魚[さかな]が、外[そと]から来[き]た魚[さかな]に食[た]べられて減[へ]っている。", "sentence_source": "generated"}, {"text": "在来の植物を守るため、外国の草を取り除いている。", "target_word": "在来", "complexity_tier": "T3", "furigana": "在来[ざいらい]の植物[しょくぶつ]を守[まも]るため、外国[がいこく]の草[くさ]を取[と]り除[のぞ]いている。", "sentence_source": "generated"}, {"text": "この島には、在来のカエルだけが住んでいた。", "target_word": "在来", "complexity_tier": "T3", "furigana": "この島[しま]には、在来[ざいらい]のカエルだけが住[す]んでいた。", "sentence_source": "generated"}, {"text": "在来のメダカは、外から来たメダカに押されて数が減った。", "target_word": "在来", "complexity_tier": "T3", "furigana": "在来[ざいらい]のメダカは、外[そと]から来[き]たメダカに押[お]されて数[かず]が減[へ]った。", "sentence_source": "generated"}, {"text": "在来の野菜は、その土地の気候に合っていて病気に強い。", "target_word": "在来", "complexity_tier": "T3", "furigana": "在来[ざいらい]の野菜[やさい]は、その土地[とち]の気候[きこう]に合[あ]っていて病気[びょうき]に強[つよ]い。", "sentence_source": "generated"}, {"text": "山の在来の木を切って、外国の木を植えたことが問題になった。", "target_word": "在来", "complexity_tier": "T3", "furigana": "山[やま]の在来[ざいらい]の木[き]を切[き]って、外国[がいこく]の木[き]を植[う]えたことが問題[もんだい]になった。", "sentence_source": "generated"}, {"text": "在来の動物と外来の動物が、同じえさを取り合っている。", "target_word": "在来", "complexity_tier": "T3", "furigana": "在来[ざいらい]の動物[どうぶつ]と外来[がいらい]の動物[どうぶつ]が、同[おな]じえさを取[と]り合[あ]っている。", "sentence_source": "generated"}, {"text": "公園では、在来の草花を中心に植えている。", "target_word": "在来", "complexity_tier": "T3", "furigana": "公園[こうえん]では、在来[ざいらい]の草花[くさばな]を中心[ちゅうしん]に植[う]えている。", "sentence_source": "generated"}, {"text": "この地方では、在来のミツバチを大切に育てている。", "target_word": "在来", "complexity_tier": "T3", "furigana": "この地方[ちほう]では、在来[ざいらい]のミツバチを大切[たいせつ]に育[そだ]てている。", "sentence_source": "generated"}, {"text": "外国の貝が増えて、川に昔からいた在来の貝が見られなくなった。", "target_word": "在来", "complexity_tier": "T3", "furigana": "外国[がいこく]の貝[かい]が増[ふ]えて、川[かわ]に昔[むかし]からいた在来[ざいらい]の貝[かい]が見[み]られなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "在来", "label": "基本形"}, {"form": "在来の", "label": "連体形（の）"}], "register": "formal", "sense_fingerprint": "その土地にもとからいる・ある生き物や作物。外から入ってきたもの（外来）の対", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39307, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在来", "is_correct": true, "explanation": "『池の在来の魚』で、もともといた魚を指す。ここでは在来が正しい。"}, {"text": "寝具", "is_correct": false, "explanation": "『池の寝具の魚』は意味が通らない。"}, {"text": "熱意", "is_correct": false, "explanation": "熱意は魚を修飾せず、『池の熱意の魚』は文意に合わない。"}, {"text": "節約", "is_correct": false, "explanation": "『池の節約の魚』は成り立たず、文意に合わない。"}], "explanations": {"在来": "『池の在来の魚』で、もともといた魚を指す。ここでは在来が正しい。", "寝具": "『池の寝具の魚』は意味が通らない。", "熱意": "熱意は魚を修飾せず、『池の熱意の魚』は文意に合わない。", "節約": "『池の節約の魚』は成り立たず、文意に合わない。"}, "sentence_index": 0, "correct_answer": "在来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外国から来た在来のメダカが、池で増えて問題になった。", "explanation": "ここは〈外来〉の意味。在来は以前からその土地にいたものを指すので、外国から来た生き物には合わない。"}, {"text": "研究者が池で在来のメダカを見つけ、新種として発表した。", "explanation": "ここは〈新種〉の意味。在来は以前からいたものを指すので、新しく見つかった種には使わない。"}, {"text": "人が持ち込んだ在来の魚が、池の生態系を乱している。", "explanation": "ここは〈移入〉の意味。在来は以前からいた生き物を指すので、人が持ち込んだものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39307, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在来", "is_correct": true, "explanation": "『在来の動物』で、もともとその土地にいた動物を指す。ここでは在来が正しい。"}, {"text": "失業", "is_correct": false, "explanation": "『失業の動物と外来の動物』は意味が通らない。"}, {"text": "感動", "is_correct": false, "explanation": "『感動の動物』は文意に合わない。"}, {"text": "寝不足", "is_correct": false, "explanation": "『寝不足の動物』は文意に合わず、成り立たない。"}], "explanations": {"在来": "『在来の動物』で、もともとその土地にいた動物を指す。ここでは在来が正しい。", "失業": "『失業の動物と外来の動物』は意味が通らない。", "感動": "『感動の動物』は文意に合わない。", "寝不足": "『寝不足の動物』は文意に合わず、成り立たない。"}, "sentence_index": 6, "correct_answer": "在来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海外から輸入した在来のエビを、川に放してしまった。", "explanation": "ここは〈輸入〉の意味。在来は国内にもともといた生き物を指すので、海外から入れたものには合わない。"}, {"text": "新しく入ってきた在来の貝が、川の生態系を大きく変えた。", "explanation": "ここは〈新しく入ってきた〉の意味。在来は外から新しく入ってきたものではないことを表すので、矛盾する。"}, {"text": "この川では、外から持ち込まれた在来の魚が増えて問題になっている。", "explanation": "ここは〈外来〉の意味。在来は以前からその土地にいたものを指すので、外から持ち込まれたものには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39307, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在来を草花は、外から来た草に押されて減っている。", "corrected_sentence": "在来の草花は、外から来た草に押されて減っている。", "error_description": "『在来』は後ろの名詞に『の』でつなぐ。『を』を付けると名詞を修飾できず、文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39307, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、在来な草花を中心に公園を整えている。", "corrected_sentence": "市は、在来の草花を中心に公園を整えている。", "error_description": "『在来』は名詞を修飾するとき『の』を使う。『な』は形容動詞の語尾なので、名詞の『在来』には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39308, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「山の樹木が倒れた」と主語を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「倒れた」の主語にはならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着点を示す助詞で、倒れた主体を表せないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や原因を示す助詞で、倒れた主体を表せないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「山の樹木が倒れた」と主語を示す正しい助詞。", "を": "目的語を示す助詞で、「倒れた」の主語にはならないので合わない。", "に": "帰着点を示す助詞で、倒れた主体を表せないので合わない。", "で": "場所や原因を示す助詞で、倒れた主体を表せないので合わない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "で": "場所・原因"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39308, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "樹木を話題として示す助詞で、「冬の樹木は葉を落とし」という文の主題として正しい。"}, {"text": "と", "is_correct": false, "explanation": "「と」は「樹木と葉」を並べるだけで、主題の「は」が消えて文の骨組みが崩れ、「春を待っている」とも続かないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向や相手を示す助詞で、「冬の樹木へ葉を落とし」では主題にならず、意味も通らないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す助詞で、「冬の樹木より葉を落とし」では主題にならず、意味が通らないので合わない。"}], "correct_answer": "は", "explanations": {"は": "樹木を話題として示す助詞で、「冬の樹木は葉を落とし」という文の主題として正しい。", "と": "「と」は「樹木と葉」を並べるだけで、主題の「は」が消えて文の骨組みが崩れ、「春を待っている」とも続かないので合わない。", "へ": "方向や相手を示す助詞で、「冬の樹木へ葉を落とし」では主題にならず、意味も通らないので合わない。", "より": "比較の基準を示す助詞で、「冬の樹木より葉を落とし」では主題にならず、意味が通らないので合わない。"}, "error_tags": {"と": "並列（主語が立たない）", "へ": "方向・相手", "より": "比較の基準"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39308, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木。庭や山に生えている、大きな植物。", "primary_collocate": null, "pronunciation": "じゅもく", "ipa": "dʑɯmoku", "syllable_count": 3, "sentences": [{"text": "公園には、たくさんの樹木が植えられている。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "公園[こうえん]には、たくさんの樹木[じゅもく]が植[う]えられている。", "sentence_source": "generated"}, {"text": "台風で、山の樹木が何本も倒れた。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "台風[たいふう]で、山[やま]の樹木[じゅもく]が何本[なんぼん]も倒[たお]れた。", "sentence_source": "generated"}, {"text": "夏になると、樹木の葉が茂って、道に涼しい影ができる。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "夏[なつ]になると、樹木[じゅもく]の葉[は]が茂[しげ]って、道[みち]に涼[すず]しい影[かげ]ができる。", "sentence_source": "generated"}, {"text": "森の樹木は、空気をきれいにしてくれる。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "森[もり]の樹木[じゅもく]は、空気[くうき]をきれいにしてくれる。", "sentence_source": "generated"}, {"text": "この庭には、百年以上育っている樹木がある。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "この庭[にわ]には、百年[ひゃくねん]以上[いじょう]育[そだ]っている樹木[じゅもく]がある。", "sentence_source": "generated"}, {"text": "樹木の種類を調べるために、図鑑を持って山へ行った。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "樹木[じゅもく]の種類[しゅるい]を調[しら]べるために、図鑑[ずかん]を持[も]って山[やま]へ行[い]った。", "sentence_source": "generated"}, {"text": "町は、道の両側に樹木を植えて、景色を良くした。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "町[まち]は、道[みち]の両側[りょうがわ]に樹木[じゅもく]を植[う]えて、景色[けしき]を良[よ]くした。", "sentence_source": "generated"}, {"text": "冬の樹木は葉を落とし、静かに春を待っている。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "冬[ふゆ]の樹木[じゅもく]は葉[は]を落[お]とし、静[しず]かに春[はる]を待[ま]っている。", "sentence_source": "generated"}, {"text": "大きな樹木の根は、地面の深くまでのびている。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "大[おお]きな樹木[じゅもく]の根[ね]は、地面[じめん]の深[ふか]くまでのびている。", "sentence_source": "generated"}, {"text": "山の樹木を切りすぎると、大雨のときに山がくずれやすくなる。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "山[やま]の樹木[じゅもく]を切[き]りすぎると、大雨[おおあめ]のときに山[やま]がくずれやすくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "樹木", "label": "基本形"}], "register": "書き言葉（やや硬い）", "sense_fingerprint": "庭や山、森などに生えている木を、まとめて指す言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39308, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "樹木", "is_correct": true, "explanation": "植えられる植物を総称する語で、「たくさんの〜が植えられている」に入る。"}, {"text": "ベンチ", "is_correct": false, "explanation": "置くもので、植えることはできないので合わない。"}, {"text": "滑り台", "is_correct": false, "explanation": "設置する遊具で、植えられるものではないので合わない。"}, {"text": "噴水", "is_correct": false, "explanation": "設置される設備で、植えることはできないので合わない。"}], "explanations": {"樹木": "植えられる植物を総称する語で、「たくさんの〜が植えられている」に入る。", "ベンチ": "置くもので、植えることはできないので合わない。", "滑り台": "設置する遊具で、植えられるものではないので合わない。", "噴水": "設置される設備で、植えることはできないので合わない。"}, "sentence_index": 0, "correct_answer": "樹木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この接着剤は、乾くと樹木になって、ものを強くつなぐ。", "explanation": "〈樹脂〉の意味。固まって接着する素材を指す語で、生えている木を指す樹木とは合わない。"}, {"text": "秋に落ちた樹木を集めて、庭にまいた。", "explanation": "〈種〉の意味。集めてまくのは種で、生えている樹木をまくとは言わないので合わない。"}, {"text": "畑で樹木を収穫して、夕食に使った。", "explanation": "〈野菜〉の意味。収穫して食べるのは野菜で、樹木を収穫して食材にするとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39308, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "樹木", "is_correct": true, "explanation": "道の両側に植えて景色を良くする植物を指す語で、ここに入る。"}, {"text": "街灯", "is_correct": false, "explanation": "設置する照明器具で、植えることはできないので合わない。"}, {"text": "標識", "is_correct": false, "explanation": "立てて設置するもので、植えることはできないので合わない。"}, {"text": "石畳", "is_correct": false, "explanation": "道に敷く石で、植えることはできないので合わない。"}], "explanations": {"樹木": "道の両側に植えて景色を良くする植物を指す語で、ここに入る。", "街灯": "設置する照明器具で、植えることはできないので合わない。", "標識": "立てて設置するもので、植えることはできないので合わない。", "石畳": "道に敷く石で、植えることはできないので合わない。"}, "sentence_index": 6, "correct_answer": "樹木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の夜、グラスに樹木を入れて冷やした。", "explanation": "〈氷〉の意味。グラスに入れて飲み物を冷やすのは氷で、生えている樹木では合わない。"}, {"text": "庭の落ち葉を、樹木で掃いて集めた。", "explanation": "〈ほうき〉の意味。落ち葉を掃いて集める道具を指す語で、生えている樹木を道具として使うとは言わないので合わない。"}, {"text": "古い樹木の引き出しを、ゆっくり開けた。", "explanation": "〈たんす〉の意味。引き出しがある家具を指す語で、樹木には引き出しがないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39308, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強い風で、樹木を根ごと倒れた。", "corrected_sentence": "強い風で、樹木が根ごと倒れた。", "error_description": "「倒れる」は自動詞なので主語には「が」を使う。「樹木を」は目的語になり、「倒れた」と合わず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39308, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋が来て、樹木の葉を赤く色づいた。", "corrected_sentence": "秋が来て、樹木の葉が赤く色づいた。", "error_description": "「色づく」は自動詞なので主語には「が」を使う。「葉を」は目的語になり、文として成り立たないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39309, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "山の樹木を話題として示す助詞で、「山の樹木は、水を吸い上げます」の主題として正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「樹木を、水を吸い上げる」と続けると文が崩れるので合わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着点を示す助詞で、主題にはならないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す助詞で、この文の主題にはならないので合わない。"}], "correct_answer": "は", "explanations": {"は": "山の樹木を話題として示す助詞で、「山の樹木は、水を吸い上げます」の主題として正しい。", "を": "目的語を示す助詞で、「樹木を、水を吸い上げる」と続けると文が崩れるので合わない。", "に": "帰着点を示す助詞で、主題にはならないので合わない。", "で": "場所や手段を示す助詞で、この文の主題にはならないので合わない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39309, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "樹木を話題として示す助詞で、「樹木は二酸化炭素を吸って」という文の主題として正しい。"}, {"text": "の", "is_correct": false, "explanation": "「樹木の二酸化炭素を吸って」と続けても、樹木が吸う主体にならず、文が成り立たないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向や相手を示す助詞で、「樹木へ二酸化炭素を吸って」では吸う主体にならず合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す助詞で、「樹木より二酸化炭素を吸って」では主題にならず意味が通らないので合わない。"}], "correct_answer": "は", "explanations": {"は": "樹木を話題として示す助詞で、「樹木は二酸化炭素を吸って」という文の主題として正しい。", "の": "「樹木の二酸化炭素を吸って」と続けても、樹木が吸う主体にならず、文が成り立たないので合わない。", "へ": "方向や相手を示す助詞で、「樹木へ二酸化炭素を吸って」では吸う主体にならず合わない。", "より": "比較の基準を示す助詞で、「樹木より二酸化炭素を吸って」では主題にならず意味が通らないので合わない。"}, "error_tags": {"の": "所有・修飾（主語にならない）", "へ": "方向・相手", "より": "比較の基準"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39309, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面に根を張り、幹と枝、葉をもつ植物の総称。", "primary_collocate": null, "pronunciation": "じゅもく", "ipa": "dʑɯmokɯ", "syllable_count": 3, "sentences": [{"text": "公園には、高い樹木がたくさん並んでいます。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "公園[こうえん]には、高[たか]い樹木[じゅもく]がたくさん並[なら]んでいます。", "sentence_source": "generated"}, {"text": "山の樹木は、雨の水を根からゆっくり吸い上げます。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "山[やま]の樹木[じゅもく]は、雨[あめ]の水[みず]を根[ね]からゆっくり吸[す]い上[あ]げます。", "sentence_source": "generated"}, {"text": "大きな樹木の下は日かげになるので、夏でも涼しいです。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "大[おお]きな樹木[じゅもく]の下[した]は日[ひ]かげになるので、夏[なつ]でも涼[すず]しいです。", "sentence_source": "generated"}, {"text": "台風で多くの樹木が倒れ、道がふさがれてしまいました。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "台風[たいふう]で多[おお]くの樹木[じゅもく]が倒[たお]れ、道[みち]がふさがれてしまいました。", "sentence_source": "generated"}, {"text": "この森では、百年以上育った樹木を大切に守っています。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "この森[もり]では、百年[ひゃくねん]以上[いじょう]育[そだ]った樹木[じゅもく]を大切[たいせつ]に守[まも]っています。", "sentence_source": "generated"}, {"text": "春になると、樹木の枝に新しい葉が出てきます。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "春[はる]になると、樹木[じゅもく]の枝[えだ]に新[あたら]しい葉[は]が出[で]てきます。", "sentence_source": "generated"}, {"text": "町は、道の両側に樹木を植えて、緑の多い通りにしました。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "町[まち]は、道[みち]の両側[りょうがわ]に樹木[じゅもく]を植[う]えて、緑[みどり]の多[おお]い通[とお]りにしました。", "sentence_source": "generated"}, {"text": "樹木は二酸化炭素を吸って、酸素を出してくれます。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "樹木[じゅもく]は二酸化炭素[にさんかたんそ]を吸[す]って、酸素[さんそ]を出[だ]してくれます。", "sentence_source": "generated"}, {"text": "庭の樹木が大きくなりすぎたので、専門の人に枝を切ってもらいました。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "庭[にわ]の樹木[じゅもく]が大[おお]きくなりすぎたので、専門[せんもん]の人[ひと]に枝[えだ]を切[き]ってもらいました。", "sentence_source": "generated"}, {"text": "冬の間、樹木は葉を落として静かに春を待ちます。", "target_word": "樹木", "complexity_tier": "T3", "furigana": "冬[ふゆ]の間[あいだ]、樹木[じゅもく]は葉[は]を落[お]として静[しず]かに春[はる]を待[ま]ちます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "樹木", "label": "基本形"}], "register": "polite", "sense_fingerprint": "庭や山などに生え、幹・枝・葉をもつ植物を総称する語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39309, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "樹木", "is_correct": true, "explanation": "高く育って並ぶ植物を総称する語で、この文の主語として正しい。"}, {"text": "ベンチ", "is_correct": false, "explanation": "置かれる設備で、高く育って並ぶものではないので合わない。"}, {"text": "水飲み場", "is_correct": false, "explanation": "設置される設備で、高く育つものではないので合わない。"}, {"text": "ごみ箱", "is_correct": false, "explanation": "置かれる容器で、高く育って並ぶものではないので合わない。"}], "explanations": {"樹木": "高く育って並ぶ植物を総称する語で、この文の主語として正しい。", "ベンチ": "置かれる設備で、高く育って並ぶものではないので合わない。", "水飲み場": "設置される設備で、高く育つものではないので合わない。", "ごみ箱": "置かれる容器で、高く育って並ぶものではないので合わない。"}, "sentence_index": 0, "correct_answer": "樹木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋根に樹木を並べて、雨漏りを防いだ。", "explanation": "〈瓦〉の意味。屋根に並べて雨漏りを防ぐのは瓦で、生えている樹木では合わない。"}, {"text": "秋に樹木を拾って、袋に入れた。", "explanation": "〈木の実〉の意味。拾って袋に入れるのは木の実で、樹木を拾うとは言わないので合わない。"}, {"text": "川原で樹木を拾って、積み上げた。", "explanation": "〈石〉の意味。拾って積み上げるのは石で、樹木を拾って積むとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39309, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "樹木", "is_correct": true, "explanation": "道の両側に植えて緑を増やす植物を指す語で、ここに入る。"}, {"text": "ガードレール", "is_correct": false, "explanation": "道路に設置する柵で、植えることはできないので合わない。"}, {"text": "信号", "is_correct": false, "explanation": "道路に設置する装置で、植えることはできないので合わない。"}, {"text": "電柱", "is_correct": false, "explanation": "立てて設置するもので、植えることはできないので合わない。"}], "explanations": {"樹木": "道の両側に植えて緑を増やす植物を指す語で、ここに入る。", "ガードレール": "道路に設置する柵で、植えることはできないので合わない。", "信号": "道路に設置する装置で、植えることはできないので合わない。", "電柱": "立てて設置するもので、植えることはできないので合わない。"}, "sentence_index": 6, "correct_answer": "樹木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この樹木は、綿から糸を紡いで織った。", "explanation": "〈布〉の意味。糸を紡いで織って作るのは布で、生えている樹木には当てはまらないので合わない。"}, {"text": "古い樹木の引き出しを、ゆっくり開けた。", "explanation": "〈たんす〉の意味。引き出しを開ける家具で、樹木には引き出しがないので合わない。"}, {"text": "夏の夜、グラスに樹木を入れて冷やした。", "explanation": "〈氷〉の意味。グラスに入れて冷やすのは氷で、樹木を入れて冷やすとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39309, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の樹木で、毎年肥料をやっている。", "corrected_sentence": "庭の樹木に、毎年肥料をやっている。", "error_description": "「肥料をやる」の相手は「に」で示す。「で」は場所や手段を表すため、「樹木で」は不自然で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39309, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この森は、樹木を密集していて、昼でも暗い。", "corrected_sentence": "この森は、樹木が密集していて、昼でも暗い。", "error_description": "「密集する」は自動詞なので主語には「が」を使う。「樹木を」は目的語になり、文として成り立たないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39310, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「戻すのを忘れて」と動作を名詞化する正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「戻すが」と続けると文が崩れるので合わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着点を示す助詞で、「戻すに」と続けると文が成り立たないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す助詞で、「戻すで」と続けると文が成り立たないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「戻すのを忘れて」と動作を名詞化する正しい助詞。", "が": "主語を示す助詞で、「戻すが」と続けると文が崩れるので合わない。", "に": "帰着点を示す助詞で、「戻すに」と続けると文が成り立たないので合わない。", "で": "場所や手段を示す助詞で、「戻すで」と続けると文が成り立たないので合わない。"}, "error_tags": {"が": "主格（主語）", "に": "帰着点", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39310, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「戻すのが私の仕事」と動作を名詞化する正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "帰着点を示す助詞で、「戻すに」と続けると文が成り立たないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「戻すを」と続けると文が崩れるので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す助詞で、「戻すで」と続けると文が成り立たないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「戻すのが私の仕事」と動作を名詞化する正しい助詞。", "に": "帰着点を示す助詞で、「戻すに」と続けると文が成り立たないので合わない。", "を": "目的語を示す助詞で、「戻すを」と続けると文が崩れるので合わない。", "で": "場所や手段を示す助詞で、「戻すで」と続けると文が成り立たないので合わない。"}, "error_tags": {"に": "帰着点", "を": "目的語", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39310, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "前にあった場所や状態に、もう一度もどすこと。", "primary_collocate": null, "pronunciation": "もどす", "ipa": "modosɯ", "syllable_count": 3, "sentences": [{"text": "読み終わった本は、もとの棚に戻してください。", "target_word": "戻して", "complexity_tier": "T3", "furigana": "読[よ]み終[お]わった本[ほん]は、もとの棚[たな]に戻[もど]してください。", "sentence_source": "generated"}, {"text": "借りた道具を倉庫に戻すのを忘れて、先生に注意されました。", "target_word": "戻す", "complexity_tier": "T3", "furigana": "借[か]りた道具[どうぐ]を倉庫[そうこ]に戻[もど]すのを忘[わす]れて、先生[せんせい]に注意[ちゅうい]されました。", "sentence_source": "generated"}, {"text": "使ったはさみを引き出しに戻したので、すぐ見つかります。", "target_word": "戻した", "complexity_tier": "T3", "furigana": "使[つか]ったはさみを引[ひ]き出[だ]しに戻[もど]したので、すぐ見[み]つかります。", "sentence_source": "generated"}, {"text": "店で手に取った商品を、棚に戻して帰りました。", "target_word": "戻して", "complexity_tier": "T3", "furigana": "店[みせ]で手[て]に取[と]った商品[しょうひん]を、棚[たな]に戻[もど]して帰[かえ]りました。", "sentence_source": "generated"}, {"text": "動かしたいすを、もとの位置に戻してから教室を出ます。", "target_word": "戻して", "complexity_tier": "T3", "furigana": "動[うご]かしたいすを、もとの位置[いち]に戻[もど]してから教室[きょうしつ]を出[で]ます。", "sentence_source": "generated"}, {"text": "子どもが出したおもちゃを、箱に戻すように言いました。", "target_word": "戻す", "complexity_tier": "T3", "furigana": "子[こ]どもが出[だ]したおもちゃを、箱[はこ]に戻[もど]すように言[い]いました。", "sentence_source": "generated"}, {"text": "彼は取り出したカードを山に戻して、もう一度混ぜました。", "target_word": "戻して", "complexity_tier": "T3", "furigana": "彼[かれ]は取[と]り出[だ]したカードを山[やま]に戻[もど]して、もう一度[いちど]混[ま]ぜました。", "sentence_source": "generated"}, {"text": "洗ったお皿を食器棚に戻すのが、私の仕事です。", "target_word": "戻す", "complexity_tier": "T3", "furigana": "洗[あら]ったお皿[さら]を食器棚[しょっきだな]に戻[もど]すのが、私[わたし]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "地図を見終わったら、元の場所に戻しておいてください。", "target_word": "戻して", "complexity_tier": "T3", "furigana": "地図[ちず]を見終[みお]わったら、元[もと]の場所[ばしょ]に戻[もど]しておいてください。", "sentence_source": "generated"}, {"text": "魚が小さかったので、川に戻しました。", "target_word": "戻しました", "complexity_tier": "T3", "furigana": "魚[さかな]が小[ちい]さかったので、川[かわ]に戻[もど]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戻す", "label": "終止形"}, {"form": "戻した", "label": "過去形"}, {"form": "戻して", "label": "て形"}, {"form": "戻さない", "label": "否定形"}, {"form": "戻せば", "label": "仮定形"}, {"form": "戻そう", "label": "意向形"}, {"form": "戻せる", "label": "可能形"}, {"form": "戻される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "put a thing back in the place where it was before (return to its original location)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39310, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戻して", "is_correct": true, "explanation": "「もとの場所に戻す」の て形で、依頼の文として正しい。"}, {"text": "読んで", "is_correct": false, "explanation": "読む動作を表し、もとの棚に置くという意味には合わないので合わない。"}, {"text": "洗って", "is_correct": false, "explanation": "洗う動作を表し、本を棚に戻す意味には合わないので合わない。"}, {"text": "借りて", "is_correct": false, "explanation": "借りる動作を表し、本を元の場所へ返す意味には合わないので合わない。"}], "explanations": {"戻して": "「もとの場所に戻す」の て形で、依頼の文として正しい。", "読んで": "読む動作を表し、もとの棚に置くという意味には合わないので合わない。", "洗って": "洗う動作を表し、本を棚に戻す意味には合わないので合わない。", "借りて": "借りる動作を表し、本を元の場所へ返す意味には合わないので合わない。"}, "sentence_index": 0, "correct_answer": "戻して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "できたばかりの料理を、初めて冷蔵庫に戻した。", "explanation": "〈入れる〉の意味。初めて入れる場面なので、もとの場所へ返す意味の戻すとは合わない。"}, {"text": "新しく買った花瓶を、テーブルに戻した。", "explanation": "〈置く〉の意味。新しく置く場合に使い、もとあった場所へ返すという意味の戻すとは合わない。"}, {"text": "パンをオーブンで戻した。", "explanation": "〈焼く〉の意味。熱を加えて焼く調理に使い、元の場所へ返す意味の戻すとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39310, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戻して", "is_correct": true, "explanation": "「山に戻す」の て形で、もう一度混ぜるために元に返す意味で正しい。"}, {"text": "食べて", "is_correct": false, "explanation": "食べる動作を表し、カードを山に置く意味には合わないので合わない。"}, {"text": "歌って", "is_correct": false, "explanation": "歌う動作を表し、カードの扱いには合わないので合わない。"}, {"text": "折って", "is_correct": false, "explanation": "折る動作を表し、カードを山に戻す意味には合わないので合わない。"}], "explanations": {"戻して": "「山に戻す」の て形で、もう一度混ぜるために元に返す意味で正しい。", "食べて": "食べる動作を表し、カードを山に置く意味には合わないので合わない。", "歌って": "歌う動作を表し、カードの扱いには合わないので合わない。", "折って": "折る動作を表し、カードを山に戻す意味には合わないので合わない。"}, "sentence_index": 6, "correct_answer": "戻して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どものために、木の箱を戻した。", "explanation": "〈作る〉の意味。材料から新しく作る動作で、元の場所へ返す意味の戻すとは合わないので合わない。"}, {"text": "白い紙に、花の絵を戻した。", "explanation": "〈描く〉の意味。絵を新しく描く動作で、元の場所へ返す意味の戻すとは合わないので合わない。"}, {"text": "道で、落ちていた小石を、ごみ箱に戻した。", "explanation": "〈捨てる〉の意味。ごみとして捨てる動作で、もとの場所へ返す意味の戻すとは合わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39310, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "本は、棚に戻すないと、次の人が探せない。", "corrected_sentence": "本は、棚に戻さないと、次の人が探せない。", "error_description": "否定形は「戻さない」。「戻すない」は活用が誤りで、未然形に「ない」を続けるのが正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "戻す", "is_correct": true, "explanation": "辞書形で、「戻すのを忘れて」と名詞の「の」に続く文中の形と一致する。"}, {"text": "戻し", "is_correct": false, "explanation": "連用形で、「の」に続けることができないので合わない。"}, {"text": "戻して", "is_correct": false, "explanation": "て形で、「の」に続けることができないので合わない。"}, {"text": "戻せ", "is_correct": false, "explanation": "命令の形で、「の」に続けることができないので合わない。"}], "correct_form": "戻す", "base_form": "戻す", "form_label": "辞書形", "sentence_index": 1, "explanations": {"戻す": "辞書形で、「戻すのを忘れて」と名詞の「の」に続く文中の形と一致する。", "戻し": "連用形で、「の」に続けることができないので合わない。", "戻して": "て形で、「の」に続けることができないので合わない。", "戻せ": "命令の形で、「の」に続けることができないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39310, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍵は、もとの位置に戻すておきます。", "corrected_sentence": "鍵は、もとの位置に戻しておきます。", "error_description": "「ておく」に続けるときの連用形は「戻し」。「戻す」のままでは「て」に続かず、「戻すておきます」は活用が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "戻す", "is_correct": true, "explanation": "辞書形で、「戻すのが」と名詞の「の」に続く文中の形と一致する。"}, {"text": "戻します", "is_correct": false, "explanation": "丁寧形で、「の」に続けると文が成り立たないので合わない。"}, {"text": "戻さ", "is_correct": false, "explanation": "未然形で、「の」に続けることができないので合わない。"}, {"text": "戻そう", "is_correct": false, "explanation": "意志の形で、「の」に続けることができないので合わない。"}], "correct_form": "戻す", "base_form": "戻す", "form_label": "辞書形", "sentence_index": 7, "explanations": {"戻す": "辞書形で、「戻すのが」と名詞の「の」に続く文中の形と一致する。", "戻します": "丁寧形で、「の」に続けると文が成り立たないので合わない。", "戻さ": "未然形で、「の」に続けることができないので合わない。", "戻そう": "意志の形で、「の」に続けることができないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39311, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「戻してから」で、戻す動作の後に使うという時間的な順序を示す。"}, {"text": "に", "is_correct": false, "explanation": "「戻して」の後に「に」を置くと「戻してに使う」となり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「戻して」の後に「を」を置くと、目的語を示せず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「戻して」の後に「で」を置くと、「戻してで使う」となり文が成り立たない。"}], "correct_answer": "から", "explanations": {"から": "「戻してから」で、戻す動作の後に使うという時間的な順序を示す。", "に": "「戻して」の後に「に」を置くと「戻してに使う」となり、文が成り立たない。", "を": "「戻して」の後に「を」を置くと、目的語を示せず不自然。", "で": "「戻して」の後に「で」を置くと、「戻してで使う」となり文が成り立たない。"}, "error_tags": {"に": "方向・場所", "を": "目的語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
