INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39311, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や状態を、元の場所や元の形、元の状態に変えること。", "primary_collocate": null, "pronunciation": "もどす", "ipa": "modosɯ", "syllable_count": 3, "sentences": [{"text": "設定を最初の状態に戻したら、アプリが動くようになりました。", "target_word": "戻したら", "complexity_tier": "T3", "furigana": "設定[せってい]を最初[さいしょ]の状態[じょうたい]に戻[もど]したら、アプリが動[うご]くようになりました。", "sentence_source": "generated"}, {"text": "乾燥わかめは、水に入れて柔らかく戻してから使います。", "target_word": "戻して", "complexity_tier": "T3", "furigana": "乾燥[かんそう]わかめは、水[みず]に入[い]れて柔[やわ]らかく戻[もど]してから使[つか]います。", "sentence_source": "generated"}, {"text": "曲がった針金を、元の形に戻すのは難しいです。", "target_word": "戻す", "complexity_tier": "T3", "furigana": "曲[ま]がった針金[はりがね]を、元[もと]の形[かたち]に戻[もど]すのは難[むずか]しいです。", "sentence_source": "generated"}, {"text": "髪の色を黒に戻すため、美容院へ行きました。", "target_word": "戻す", "complexity_tier": "T3", "furigana": "髪[かみ]の色[いろ]を黒[くろ]に戻[もど]すため、美容院[びよういん]へ行[い]きました。", "sentence_source": "generated"}, {"text": "計画がうまくいかなかったので、話を白紙に戻すことになりました。", "target_word": "戻す", "complexity_tier": "T3", "furigana": "計画[けいかく]がうまくいかなかったので、話[はなし]を白紙[はくし]に戻[もど]すことになりました。", "sentence_source": "generated"}, {"text": "彼は、怒っていた顔を元の笑顔に戻して、客を迎えました。", "target_word": "戻して", "complexity_tier": "T3", "furigana": "かれは、おこっていたかおを もとのえがおに もどして、きゃくを むかえました。", "sentence_source": "generated"}, {"text": "間違えて消した文字を、元の状態に戻す方法を教えてください。", "target_word": "戻す", "complexity_tier": "T3", "furigana": "間違[まちが]えて消[け]した文字[もじ]を、元[もと]の状態[じょうたい]に戻[もど]す方法[ほうほう]を教[おし]えてください。", "sentence_source": "generated"}, {"text": "引っ越すときは、壁の色を元の白に戻す約束になっています。", "target_word": "戻す", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]すときは、壁[かべ]の色[いろ]を元[もと]の白[しろ]に戻[もど]す約束[やくそく]になっています。", "sentence_source": "generated"}, {"text": "冷凍した肉は、常温に戻してから焼きます。", "target_word": "戻してから", "complexity_tier": "T3", "furigana": "冷凍[れいとう]した肉[にく]は、常温[じょうおん]に戻[もど]してから焼[や]きます。", "sentence_source": "generated"}, {"text": "工事で変わった道を、元の姿に戻す工事が始まりました。", "target_word": "戻す", "complexity_tier": "T3", "furigana": "工事[こうじ]で変[か]わった道[みち]を、元[もと]の姿[すがた]に戻[もど]す工事[こうじ]が始[はじ]まりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戻す", "label": "終止形"}, {"form": "戻した", "label": "過去形"}, {"form": "戻して", "label": "て形"}, {"form": "戻さない", "label": "否定形"}, {"form": "戻せば", "label": "仮定形"}, {"form": "戻そう", "label": "意向形"}, {"form": "戻せる", "label": "可能形"}, {"form": "戻される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "restore a thing or condition to its original form or state (reset, revert, rehydrate)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39311, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戻したら", "is_correct": true, "explanation": "「戻す」の過去形に「ら」を付けたたら形（条件）。「元の状態に戻したら、動くようになった」と原因と結果がつながる。"}, {"text": "戻ったら", "is_correct": false, "explanation": "「戻る」は自動詞で「設定を」と続けられないため、「設定を戻る」は成り立たない。"}, {"text": "戻るなら", "is_correct": false, "explanation": "「戻る」は自動詞で「〜を」をとれないので、「設定を〜なら」の形にならない。"}, {"text": "戻っても", "is_correct": false, "explanation": "「戻る」は自動詞で「設定を」と続かず、文が成り立たない。"}], "explanations": {"戻したら": "「戻す」の過去形に「ら」を付けたたら形（条件）。「元の状態に戻したら、動くようになった」と原因と結果がつながる。", "戻ったら": "「戻る」は自動詞で「設定を」と続けられないため、「設定を戻る」は成り立たない。", "戻るなら": "「戻る」は自動詞で「〜を」をとれないので、「設定を〜なら」の形にならない。", "戻っても": "「戻る」は自動詞で「設定を」と続かず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "戻したら"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同じ失敗を戻さないように、反省しました。", "explanation": "ここは〈繰り返す〉の意味。戻すは元の状態へ返す語なので、同じことを再び起こす文脈には合わない。"}, {"text": "パソコンの不具合を戻すため、再起動しました。", "explanation": "ここは〈直す〉の意味。不具合は元の状態に返す対象ではなく、直して正常にする対象なので合わない。"}, {"text": "借りたお金を戻すため、銀行へ行きました。", "explanation": "ここは〈返す〉の意味。借りたお金は元の状態に戻すものではなく、相手へ渡すものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39311, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戻す", "is_correct": true, "explanation": "終止形で、「方法」を修飾して「元の状態に戻す方法」となる。"}, {"text": "戻して", "is_correct": false, "explanation": "て形は名詞を修飾できず、「戻して方法」は成り立たない。"}, {"text": "戻そう", "is_correct": false, "explanation": "意向形は名詞を修飾できず、「戻そう方法」は成り立たない。"}, {"text": "戻せば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「戻せば方法」は成り立たない。"}], "explanations": {"戻す": "終止形で、「方法」を修飾して「元の状態に戻す方法」となる。", "戻して": "て形は名詞を修飾できず、「戻して方法」は成り立たない。", "戻そう": "意向形は名詞を修飾できず、「戻そう方法」は成り立たない。", "戻せば": "仮定形は名詞を修飾できず、「戻せば方法」は成り立たない。"}, "sentence_index": 6, "correct_answer": "戻す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その工場は、新しい製品を戻す計画を立てた。", "explanation": "ここは〈作り出す〉の意味。戻すは元あった状態へ返す語なので、新しく生み出す文脈には合わない。"}, {"text": "店は新しいデザートを戻すことにした。", "explanation": "ここは〈追加する〉の意味。戻すは元の状態への回復を表すので、初めて加えるものには使わない。"}, {"text": "工場の壁に新しい棚を戻す工事が始まりました。", "explanation": "ここは〈取り付ける〉の意味。戻すは元あった場所へ返す語なので、新しく据える工事には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39311, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "使い終わった鍋を、元の棚に戻りました。", "corrected_sentence": "使い終わった鍋を、元の棚に戻しました。", "error_description": "誤りは「戻りました」（自動詞「戻る」）。正しくは「戻しました」（他動詞「戻す」）。「鍋を」の目的語をとれるのは他動詞の「戻す」だけである。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "戻して", "is_correct": true, "explanation": "て形。「柔らかく戻してから使う」で、戻す→使うという順序を表す。"}, {"text": "戻し", "is_correct": false, "explanation": "連用形で、「から」に直接続けると「戻しから」となり、文が成り立たないので合わない。"}, {"text": "戻せば", "is_correct": false, "explanation": "仮定形。「戻せばから」とは続かず、「〜てから」の位置に入らない。"}, {"text": "戻そう", "is_correct": false, "explanation": "意向形。「戻そうから」とは続かず、文が成り立たない。"}], "correct_form": "戻して", "base_form": "戻す", "form_label": "て形", "sentence_index": 1, "explanations": {"戻して": "て形。「柔らかく戻してから使う」で、戻す→使うという順序を表す。", "戻し": "連用形で、「から」に直接続けると「戻しから」となり、文が成り立たないので合わない。", "戻せば": "仮定形。「戻せばから」とは続かず、「〜てから」の位置に入らない。", "戻そう": "意向形。「戻そうから」とは続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39311, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ねじが緩んだので、ずれた部品を元の位置を戻しました。", "corrected_sentence": "ねじが緩んだので、ずれた部品を元の位置に戻しました。", "error_description": "誤りは「位置を」の「を」。「戻す」の到達点は「に」で示す。「を」を付けると「位置」が目的語になり、戻す先を正しく示せない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "戻す", "is_correct": true, "explanation": "終止形。「戻す約束」のように、約束の内容として「〜する約束」に続く。"}, {"text": "戻せ", "is_correct": false, "explanation": "命令形。「戻せ約束」とは続かず、約束の内容として不自然。"}, {"text": "戻し", "is_correct": false, "explanation": "連用形。「戻し約束」と直接つながらず、文が成り立たない。"}, {"text": "戻すな", "is_correct": false, "explanation": "禁止形。約束の内容を表す形にならず、「〜約束」の前に置けない。"}], "correct_form": "戻す", "base_form": "戻す", "form_label": "終止形", "sentence_index": 7, "explanations": {"戻す": "終止形。「戻す約束」のように、約束の内容として「〜する約束」に続く。", "戻せ": "命令形。「戻せ約束」とは続かず、約束の内容として不自然。", "戻し": "連用形。「戻し約束」と直接つながらず、文が成り立たない。", "戻すな": "禁止形。約束の内容を表す形にならず、「〜約束」の前に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
