INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39312, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ずっと続く間。", "primary_collocate": null, "pronunciation": "たえま", "ipa": "taema", "syllable_count": 3, "sentences": [{"text": "窓の外では、朝から絶え間なく雪が降っている。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]では、朝[あさ]から絶[た]え間[ま]なく雪[ゆき]が降[ふ]っている。", "sentence_source": "generated"}, {"text": "祭りの会場は、絶え間なく人が行き交い、歩くのも大変だった。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "祭[まつ]りの会場[かいじょう]は、絶[た]え間[ま]なく人[ひと]が行[ゆ]き交[か]い、歩[ある]くのも大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "母は絶え間なくしゃべり続け、私は口をはさめなかった。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "母[はは]は絶[た]え間[ま]なくしゃべり続[つづ]け、私[わたし]は口[くち]をはさめなかった。", "sentence_source": "generated"}, {"text": "駅前の道路は、絶え間なく車が通るので、横断するのが難しい。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の道路[どうろ]は、絶[た]え間[ま]なく車[くるま]が通[とお]るので、横断[おうだん]するのが難[むずか]しい。", "sentence_source": "generated"}, {"text": "絶え間ない拍手が会場に響き、歌手は何度も頭を下げた。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "絶[た]え間[ま]ない拍手[はくしゅ]が会場[かいじょう]に響[ひび]き、歌手[かしゅ]は何度[なんど]も頭[あたま]を下[さ]げた。", "sentence_source": "generated"}, {"text": "赤ちゃんが絶え間なく泣くので、父親は一晩中だっこしていた。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが絶[た]え間[ま]なく泣[な]くので、父親[ちちおや]は一晩中[ひとばんじゅう]だっこしていた。", "sentence_source": "generated"}, {"text": "滝の水は絶え間なく流れ落ち、岩を少しずつ削っている。", "target_word": "絶え間", "complexity_tier": "T4", "furigana": "滝[たき]の水[みず]は絶[た]え間[ま]なく流[なが]れ落[お]ち、岩[いわ]を少[すこ]しずつ削[けず]っている。", "sentence_source": "generated"}, {"text": "絶え間ない風の音で、山小屋の夜はほとんど眠れなかった。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "絶[た]え間[ま]ない風[かぜ]の音[おと]で、山小屋[やまごや]の夜[よる]はほとんど眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "工場の機械は絶え間なく動いていて、止まるのは点検の日だけだ。", "target_word": "絶え間", "complexity_tier": "T4", "furigana": "工場[こうじょう]の機械[きかい]は絶[た]え間[ま]なく動[うご]いていて、止[と]まるのは点検[てんけん]の日[ひ]だけだ。", "sentence_source": "generated"}, {"text": "電話が絶え間なく鳴り、受付の二人は昼ご飯を食べる暇もなかった。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "電話[でんわ]が絶[た]え間[ま]なく鳴[な]り、受付[うけつけ]の二人[ふたり]は昼[ひる]ご飯[はん]を食[た]べる暇[ひま]もなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絶え間", "label": "基本形"}, {"form": "絶え間なく", "label": "連用形（絶え間ない）"}], "register": "中立（書き言葉・常体）", "sense_fingerprint": "「絶え間なく」の形で、ある状態や動きがずっと続くさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T4: contains vocabulary far above tier T4: はさめ (Zipf 1.41)']::text[], '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39312, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絶え間", "is_correct": true, "explanation": "「絶え間なく」の形で、雪がずっと続く様子を表す。正解。"}, {"text": "寡黙", "is_correct": false, "explanation": "口数が少ないこと。「寡黙なく雪が降る」は意味が通らず、文に合わない。"}, {"text": "微笑", "is_correct": false, "explanation": "ほほえむこと。雪の様子を表す語として合わず、文が成り立たない。"}, {"text": "機嫌", "is_correct": false, "explanation": "その時の気分のこと。「機嫌なく雪が降る」は意味が通らず、ここでは合わない。"}], "explanations": {"絶え間": "「絶え間なく」の形で、雪がずっと続く様子を表す。正解。", "寡黙": "口数が少ないこと。「寡黙なく雪が降る」は意味が通らず、文に合わない。", "微笑": "ほほえむこと。雪の様子を表す語として合わず、文が成り立たない。", "機嫌": "その時の気分のこと。「機嫌なく雪が降る」は意味が通らず、ここでは合わない。"}, "sentence_index": 0, "correct_answer": "絶え間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の絶え間に、鍵が挟まっていた。", "explanation": "ここは〈隙間〉の意味。絶え間は時間の途切れずに続く性質を表し、机の隙間には使わない。"}, {"text": "親子の絶え間に、深い溝ができた。", "explanation": "ここは〈間柄〉の意味。絶え間は続く時間について使うので、人の間の隔たりには使えない。"}, {"text": "祖母は鍋の絶え間を見て、火を止めた。", "explanation": "ここは〈様子〉の意味。絶え間は続くことを表すので、鍋の状態を指す語としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39312, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絶え間", "is_correct": true, "explanation": "「絶え間なく」の形で、水が途切れず流れ落ちる様子を表す。正解。"}, {"text": "独白", "is_correct": false, "explanation": "ひとりで話すこと。「独白なく流れ落ち」は成り立たず、水の様子に合わない。"}, {"text": "足取り", "is_correct": false, "explanation": "歩くときの足の運び。水の流れを修飾する語としては合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っているときの息づかい。「寝息なく流れ落ち」は意味が通らない。"}], "explanations": {"絶え間": "「絶え間なく」の形で、水が途切れず流れ落ちる様子を表す。正解。", "独白": "ひとりで話すこと。「独白なく流れ落ち」は成り立たず、水の様子に合わない。", "足取り": "歩くときの足の運び。水の流れを修飾する語としては合わない。", "寝息": "眠っているときの息づかい。「寝息なく流れ落ち」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "絶え間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕焼けの空が、絶え間の色に染まった。", "explanation": "ここは〈鮮やか〉の意味。絶え間は続くことを表すので、色の鮮やかさを表す語としては合わない。"}, {"text": "彼は小説の絶え間に、栞を挟んだ。", "explanation": "ここは〈ページの隙間〉の意味。絶え間は途切れずに続く時間の性質を表すので、本の隙間は指せない。"}, {"text": "祖母は絶え間の手つきで、野菜を刻んだ。", "explanation": "ここは〈手際のよい〉の意味。絶え間は続くことを表すので、手つきの巧みさを表す語としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39312, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜通し絶え間に雨が降っていた。", "corrected_sentence": "夜通し絶え間なく雨が降っていた。", "error_description": "「絶え間」は「絶え間なく」の形で使う。「に」では形が合わないので、「なく」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39312, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜更けに絶え間ないに風の音が続いた。", "corrected_sentence": "夜更けに絶え間なく風の音が続いた。", "error_description": "「絶え間」を続く様子として使うときは「絶え間なく」の形になる。「ないに」は誤りで、「なく」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
