INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39313, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が途切れずに続くこと。間断がないこと。", "primary_collocate": null, "pronunciation": "たえま", "ipa": "taema", "syllable_count": 3, "sentences": [{"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "絶え間", "complexity_tier": "T5", "furigana": "仮想[かそう]空間[くうかん]上[じょう]で構築[こうちく]される3Dモデリングやアルゴリズムによる生成物[せいせいぶつ]は、かつての「仕立[した]て屋[や]」の矜持[きょうじ]をどう書[か]き換[か]えているのか。そこには、アナログな温[ぬく]もりとデジタルな冷徹[れいてつ]さの間[あいだ]の絶[た]え間[ま]ない緊張[きんちょう]関係[かんけい]が見[み]て取[と]れ、それは創造性[そうぞうせい]の本質[ほんしつ]を問[と]うている。", "sentence_source": "mined"}, {"text": "空港の近くに住んでいるので、飛行機の音が絶え間なく聞こえてくる。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "空港[くうこう]の近[ちか]くに住[す]んでいるので、飛行機[ひこうき]の音[おと]が絶[た]え間[ま]なく聞[き]こえてくる。", "sentence_source": "generated"}, {"text": "彼女は絶え間ない努力を続け、ついに大会で優勝した。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は絶[た]え間[ま]ない努力[どりょく]を続[つづ]け、ついに大会[たいかい]で優勝[ゆうしょう]した。", "sentence_source": "generated"}, {"text": "夜通し絶え間なく雨が降り、川の水かさが増した。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "夜通[よどお]し絶[た]え間[ま]なく雨[あめ]が降[ふ]り、川[かわ]の水[みず]かさが増[ま]した。", "sentence_source": "generated"}, {"text": "新しい店の前には、開店から絶え間なく客が訪れている。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]の前[まえ]には、開店[かいてん]から絶[た]え間[ま]なく客[きゃく]が訪[おとず]れている。", "sentence_source": "generated"}, {"text": "工事現場の絶え間ない騒音のせいで、近所の人が眠れずにいる。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "工事[こうじ]現場[げんば]の絶[た]え間[ま]ない騒音[そうおん]のせいで、近所[きんじょ]の人[ひと]が眠[ねむ]れずにいる。", "sentence_source": "generated"}, {"text": "絶え間ない痛みに耐えながら、彼は最後まで舞台に立った。", "target_word": "絶え間", "complexity_tier": "T4", "furigana": "絶[た]え間[ま]ない痛[いた]みに耐[た]えながら、彼[かれ]は最後[さいご]まで舞台[ぶたい]に立[た]った。", "sentence_source": "generated"}, {"text": "この海岸には、絶え間なく波が打ち寄せている。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "この海岸[かいがん]には、絶[た]え間[ま]なく波[なみ]が打[う]ち寄[よ]せている。", "sentence_source": "generated"}, {"text": "国境の町では、絶え間ない緊張が住民の生活に影を落としている。", "target_word": "絶え間", "complexity_tier": "T4", "furigana": "国境[こっきょう]の町[まち]では、絶[た]え間[ま]ない緊張[きんちょう]が住民[じゅうみん]の生活[せいかつ]に影[かげ]を落[お]としている。", "sentence_source": "generated"}, {"text": "通知が絶え間なく届くので、スマートフォンの電源を切った。", "target_word": "絶え間", "complexity_tier": "T3", "furigana": "通知[つうち]が絶[た]え間[ま]なく届[とど]くので、スマートフォンの電源[でんげん]を切[き]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絶え間", "label": "基本形"}, {"form": "絶え間なく", "label": "連用形（絶え間ない）"}], "register": "中立（書き言葉・常体）", "sense_fingerprint": "「絶え間ない」「絶え間なく」の形で、物事が途切れず続くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39313, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絶え間", "is_correct": true, "explanation": "「絶え間ない」の形で、途切れず続く緊張関係を表す。正解。"}, {"text": "気まぐれ", "is_correct": false, "explanation": "気分でころころ変わること。「気まぐれない緊張関係」は意味が通らず、文の内容に合わない。"}, {"text": "皮肉", "is_correct": false, "explanation": "遠回しな批判を指す。「皮肉ない緊張関係」は成り立たず、ここでは合わない。"}, {"text": "手際", "is_correct": false, "explanation": "物事を処理する手順の良さを指す。緊張関係を修飾する語としては不自然。"}], "explanations": {"絶え間": "「絶え間ない」の形で、途切れず続く緊張関係を表す。正解。", "気まぐれ": "気分でころころ変わること。「気まぐれない緊張関係」は意味が通らず、文の内容に合わない。", "皮肉": "遠回しな批判を指す。「皮肉ない緊張関係」は成り立たず、ここでは合わない。", "手際": "物事を処理する手順の良さを指す。緊張関係を修飾する語としては不自然。"}, "sentence_index": 0, "correct_answer": "絶え間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁の絶え間に、小さな穴があいていた。", "explanation": "ここは〈隙間〉の意味。絶え間は途切れずに続く時間の性質を表すので、壁の隙間のような空間には使わない。"}, {"text": "二人の絶え間に、冷たい風が吹いた。", "explanation": "ここは〈間柄〉の意味。絶え間は続く時間について使うので、人と人の隔たりには使えない。"}, {"text": "彼は質問に絶え間を入れず答えた。", "explanation": "ここは〈間髪を入れず〉の慣用句の意味。絶え間はこの形では使わず、間を置かない意味は「間髪」が担う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39313, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絶え間", "is_correct": true, "explanation": "「絶え間ない痛み」の形で、途切れずに続く痛みを表す。正解。"}, {"text": "好奇心", "is_correct": false, "explanation": "知りたいと思う気持ち。「好奇心ない痛み」は成り立たず、痛みの説明にならない。"}, {"text": "安堵", "is_correct": false, "explanation": "ほっとして安心すること。痛みを修飾する形にならず、文の内容に合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "お腹がすいている状態。「空腹ない痛み」は意味が通らず、ここでは合わない。"}], "explanations": {"絶え間": "「絶え間ない痛み」の形で、途切れずに続く痛みを表す。正解。", "好奇心": "知りたいと思う気持ち。「好奇心ない痛み」は成り立たず、痛みの説明にならない。", "安堵": "ほっとして安心すること。痛みを修飾する形にならず、文の内容に合わない。", "空腹": "お腹がすいている状態。「空腹ない痛み」は意味が通らず、ここでは合わない。"}, "sentence_index": 6, "correct_answer": "絶え間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は絶え間で、答えを思いついた。", "explanation": "ここは〈一瞬〉の意味。絶え間は途切れず続くことで、短い瞬間を表す語ではないので合わない。"}, {"text": "答えが絶え間なく合った。", "explanation": "ここは〈ぴったり〉の意味。絶え間は続く性質を表し、一致の度合いを表さないので合わない。"}, {"text": "その店は絶え間の味で評判だ。", "explanation": "ここは〈絶品〉の意味。絶え間は続くことを表す語で、味のすばらしさは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39313, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜明けまで絶え間に雨音が続いた。", "corrected_sentence": "夜明けまで絶え間なく雨音が続いた。", "error_description": "「絶え間」は「絶え間なく」の形で副詞的に使う。「に」を付けると形が合わないので、「なく」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39313, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い日は絶え間ないに風が吹き続けた。", "corrected_sentence": "寒い日は絶え間なく風が吹き続けた。", "error_description": "「絶え間」を続く状態として使うときは「絶え間なく」の形になる。「ないに」は誤りで、「なく」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39314, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「大好き」は「〜が大好き」の形で対象を示すので、「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「大好き」は「を」をとらないので、「昆虫を大好き」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向・相手を表し、「大好き」の対象には付かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段を表し、対象を示す「大好き」の文脈には合わない。"}], "correct_answer": "が", "explanations": {"が": "「大好き」は「〜が大好き」の形で対象を示すので、「が」が正しい。", "を": "「大好き」は「を」をとらないので、「昆虫を大好き」は不自然。", "に": "「に」は方向・相手を表し、「大好き」の対象には付かない。", "で": "「で」は場所・手段を表し、対象を示す「大好き」の文脈には合わない。"}, "error_tags": {"を": "対象の格", "に": "方向・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39314, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「昆虫の姿」の「の」で、名詞を連体修飾する。「姿」の持ち主を示す。"}, {"text": "を", "is_correct": false, "explanation": "「昆虫を姿は」と目的語を置くと、見える対象が立たず文が崩れるので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「昆虫へ姿」では所有の関係にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示すので、名詞を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "「昆虫の姿」の「の」で、名詞を連体修飾する。「姿」の持ち主を示す。", "を": "「昆虫を姿は」と目的語を置くと、見える対象が立たず文が崩れるので合わない。", "へ": "「へ」は方向を示すので、「昆虫へ姿」では所有の関係にならない。", "から": "「から」は起点や理由を示すので、名詞を修飾する形にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点・理由"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39314, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "虫のことです。小さな生き物です。", "primary_collocate": null, "pronunciation": "こんちゅう", "ipa": "kont͡ɕɯː", "syllable_count": 4, "sentences": [{"text": "夏の森には、いろいろな昆虫がいます。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "夏[なつ]の森[もり]には、いろいろな昆虫[こんちゅう]がいます。", "sentence_source": "generated"}, {"text": "弟は昆虫が大好きで、毎日図鑑を見ています。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "弟[おとうと]は昆虫[こんちゅう]が大好[だいす]きで、毎日[まいにち]図鑑[ずかん]を見[み]ています。", "sentence_source": "generated"}, {"text": "昆虫は体が小さいので、鳥に食べられやすいです。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "昆虫[こんちゅう]は体[からだ]が小[ちい]さいので、鳥[とり]に食[た]べられやすいです。", "sentence_source": "generated"}, {"text": "公園で、見たことのない昆虫を見つけました。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "公園[こうえん]で、見[み]たことのない昆虫[こんちゅう]を見[み]つけました。", "sentence_source": "generated"}, {"text": "昆虫の体は、頭と胸とおなかの三つに分かれています。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "昆虫[こんちゅう]の体[からだ]は、頭[あたま]と胸[むね]とおなかの三[みっ]つに分[わ]かれています。", "sentence_source": "generated"}, {"text": "夜になると、明かりのまわりに昆虫が集まってきます。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "夜[よる]になると、明[あ]かりのまわりに昆虫[こんちゅう]が集[あつ]まってきます。", "sentence_source": "generated"}, {"text": "カブトムシやチョウは、よく知られた昆虫です。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "カブトムシやチョウは、よく知[し]られた昆虫[こんちゅう]です。", "sentence_source": "generated"}, {"text": "寒い冬には、昆虫の姿はほとんど見えません。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "寒[さむ]い冬[ふゆ]には、昆虫[こんちゅう]の姿[すがた]はほとんど見[み]えません。", "sentence_source": "generated"}, {"text": "昆虫の足は六本あるので、クモとは違います。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "昆虫[こんちゅう]の足[あし]は六本[ろっぽん]あるので、クモとは違[ちが]います。", "sentence_source": "generated"}, {"text": "小さな昆虫を手にのせて、子どもが笑っています。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "小[ちい]さな昆虫[こんちゅう]を手[て]にのせて、子[こ]どもが笑[わら]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "昆虫", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "insect as a small creature (basic, child-level explanation: bugs, six legs, small body)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39314, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昆虫", "is_correct": true, "explanation": "「がいます」に続き、虫の仲間の小さな生き物を指す。森の生き物として自然。"}, {"text": "植物", "is_correct": false, "explanation": "植物は「生えている」で示すもので、「がいます」では不自然。"}, {"text": "鉱物", "is_correct": false, "explanation": "鉱物は生き物ではないので、「がいます」と続かない。"}, {"text": "家具", "is_correct": false, "explanation": "家具は生き物ではないので、森の文脈には合わない。"}], "explanations": {"昆虫": "「がいます」に続き、虫の仲間の小さな生き物を指す。森の生き物として自然。", "植物": "植物は「生えている」で示すもので、「がいます」では不自然。", "鉱物": "鉱物は生き物ではないので、「がいます」と続かない。", "家具": "家具は生き物ではないので、森の文脈には合わない。"}, "sentence_index": 0, "correct_answer": "昆虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パンに目に見えない昆虫がついて、カビが生えました。", "explanation": "ここは〈菌〉の意味。昆虫は目に見えない大きさの生き物ではないので、この文脈には合わない。"}, {"text": "インフルエンザの昆虫が、冬に流行しました。", "explanation": "ここは〈ウイルス〉の意味。病気を広げる病原体は昆虫ではないので、流行の主語にはならない。"}, {"text": "おなかの中の昆虫を、薬で退治しました。", "explanation": "ここは〈寄生虫〉の意味。体内に住む寄生虫は昆虫とは別の生き物なので、この文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39314, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昆虫", "is_correct": true, "explanation": "「よく知られた」に続き、カブトムシやチョウを指す。文脈に合う。"}, {"text": "家畜", "is_correct": false, "explanation": "家畜は人が飼う動物で、カブトムシやチョウには当てはまらない。"}, {"text": "果物", "is_correct": false, "explanation": "果物は食べ物で、カブトムシやチョウとは別の物なので合わない。"}, {"text": "布", "is_correct": false, "explanation": "布は生き物ではなく物なので、文脈に合わない。"}], "explanations": {"昆虫": "「よく知られた」に続き、カブトムシやチョウを指す。文脈に合う。", "家畜": "家畜は人が飼う動物で、カブトムシやチョウには当てはまらない。", "果物": "果物は食べ物で、カブトムシやチョウとは別の物なので合わない。", "布": "布は生き物ではなく物なので、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "昆虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プログラムの昆虫を直したら、アプリが動くようになった。", "explanation": "ここは〈バグ（ソフトの不具合）〉の意味。昆虫は生き物の一種で、ソフトの欠陥を指す語ではないので合わない。"}, {"text": "庭の隅に昆虫が生えて、草取りが大変だ。", "explanation": "ここは〈雑草〉の意味。昆虫は生えてくる植物ではないので、庭に生えるという文脈には合わない。"}, {"text": "机の上に昆虫が積もっていた。", "explanation": "ここは〈ほこり〉の意味。昆虫は積もって溜まる汚れではないので、この文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39314, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "花の蜜を吸う昆虫が、庭で見つけました。", "corrected_sentence": "花の蜜を吸う昆虫を、庭で見つけました。", "error_description": "誤りは「昆虫が」の「が」。「見つける」の対象は「を」で示す。「が」では「昆虫が見つけた」の意味になり、見つけられた対象が示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39314, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公園の草むらで、小さな昆虫に探しました。", "corrected_sentence": "公園の草むらで、小さな昆虫を探しました。", "error_description": "誤りは「昆虫に」の「に」。「探す」の対象は「を」で示す。「に」では対象を示せず、不自然な文になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39315, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ふせぐ」の対象を示す「を」。「入ってくる昆虫を」で目的語になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段を示すので、防ぐ対象には付かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、防ぐ対象を示す文脈には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、防ぐ対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「ふせぐ」の対象を示す「を」。「入ってくる昆虫を」で目的語になる。", "で": "「で」は場所・手段を示すので、防ぐ対象には付かない。", "へ": "「へ」は方向を示すので、防ぐ対象を示す文脈には合わない。", "と": "「と」は相手や並列を示すので、防ぐ対象を示せない。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39315, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「減らす」の対象を示す「を」。「昆虫を減らす」で目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「減らす」の目的語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すので、「減らす」の対象には付かない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞の連体修飾なので、動詞「減らす」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「減らす」の対象を示す「を」。「昆虫を減らす」で目的語になる。", "が": "「が」は主語を示すので、「減らす」の目的語にはならない。", "に": "「に」は場所や相手を示すので、「減らす」の対象には付かない。", "の": "「の」は名詞の連体修飾なので、動詞「減らす」の目的語にならない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39315, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "動物の一種で、体が小さく、多くの種類があります。人の生活の周りにもよくいます。", "primary_collocate": null, "pronunciation": "こんちゅう", "ipa": "kont͡ɕɯː", "syllable_count": 4, "sentences": [{"text": "畑には、野菜を食べる昆虫がよく来ます。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "畑[はたけ]には、野菜[やさい]を食[た]べる昆虫[こんちゅう]がよく来[き]ます。", "sentence_source": "generated"}, {"text": "家の中に入ってくる昆虫を、網戸でふせいでいます。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "家[いえ]の中[なか]に入[はい]ってくる昆虫[こんちゅう]を、網戸[あみど]でふせいでいます。", "sentence_source": "generated"}, {"text": "都会の公園にも、たくさんの昆虫がすんでいます。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "都会[とかい]の公園[こうえん]にも、たくさんの昆虫[こんちゅう]がすんでいます。", "sentence_source": "generated"}, {"text": "ミツバチのような昆虫は、花の受粉を助けてくれます。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "ミツバチのような昆虫[こんちゅう]は、花[はな]の受粉[じゅふん]を助[たす]けてくれます。", "sentence_source": "generated"}, {"text": "昆虫は種類が多く、世界に百万種以上いるといわれます。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "昆虫[こんちゅう]は種類[しゅるい]が多[おお]く、世界[せかい]に百万種[ひゃくまんしゅ]以上[いじょう]いるといわれます。", "sentence_source": "generated"}, {"text": "蚊は人の血を吸う昆虫なので、夏は対策が必要です。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "蚊[か]は人[ひと]の血[ち]を吸[す]う昆虫[こんちゅう]なので、夏[なつ]は対策[たいさく]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "庭に花を植えたら、いろいろな昆虫が飛んでくるようになりました。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "庭[にわ]に花[はな]を植[う]えたら、いろいろな昆虫[こんちゅう]が飛[と]んでくるようになりました。", "sentence_source": "generated"}, {"text": "台所に来る昆虫を減らすために、毎日ゴミを捨てています。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "台所[だいどころ]に来[く]る昆虫[こんちゅう]を減[へ]らすために、毎日[まいにち]ゴミを捨[す]てています。", "sentence_source": "generated"}, {"text": "学校の理科では、身近な昆虫の育ち方を調べます。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "学校[がっこう]の理科[りか]では、身近[みぢか]な昆虫[こんちゅう]の育[そだ]ち方[かた]を調[しら]べます。", "sentence_source": "generated"}, {"text": "暑い季節になると、家の周りでも昆虫が増えます。", "target_word": "昆虫", "complexity_tier": "T3", "furigana": "暑[あつ]い季節[きせつ]になると、家[いえ]の周[まわ]りでも昆虫[こんちゅう]が増[ふ]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "昆虫", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "insect as an animal group with many species, commonly found around human life (gardens, homes, fields)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: ふせい (Zipf 1.29)']::text[], '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39315, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昆虫", "is_correct": true, "explanation": "「野菜を食べる」「畑に来る」に合う生き物で、畑の周りにもよくいる。"}, {"text": "岩", "is_correct": false, "explanation": "岩は生き物ではないので、「野菜を食べて畑に来る」とは成り立たない。"}, {"text": "機械", "is_correct": false, "explanation": "機械は野菜を食べないので、文脈に合わない。"}, {"text": "家具", "is_correct": false, "explanation": "家具は生き物ではないので、畑に来るという文脈に合わない。"}], "explanations": {"昆虫": "「野菜を食べる」「畑に来る」に合う生き物で、畑の周りにもよくいる。", "岩": "岩は生き物ではないので、「野菜を食べて畑に来る」とは成り立たない。", "機械": "機械は野菜を食べないので、文脈に合わない。", "家具": "家具は生き物ではないので、畑に来るという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "昆虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台所の流しに、目に見えない昆虫が増えました。", "explanation": "ここは〈細菌〉の意味。昆虫は目に見えない大きさの生き物ではないので、この文脈には合わない。"}, {"text": "深い海にすむ昆虫を、船で調べました。", "explanation": "ここは〈魚〉の意味。昆虫は人の生活の周りにいる生き物で、深い海にすむという文脈には合わない。"}, {"text": "夏の空に昆虫が広がって、夕立を降らせました。", "explanation": "ここは〈雲〉の意味。雨を降らせるのは雲の働きで、昆虫には当てはまらないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39315, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昆虫", "is_correct": true, "explanation": "「花を植えたら飛んでくる」生き物として自然。庭の周りでよく見られる。"}, {"text": "電車", "is_correct": false, "explanation": "電車は生き物ではなく、飛んでくるという文脈に合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は飛んでこないので、文脈に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は生き物ではなく、庭に飛んでくるという文脈に合わない。"}], "explanations": {"昆虫": "「花を植えたら飛んでくる」生き物として自然。庭の周りでよく見られる。", "電車": "電車は生き物ではなく、飛んでくるという文脈に合わない。", "冷蔵庫": "冷蔵庫は飛んでこないので、文脈に合わない。", "教科書": "教科書は生き物ではなく、庭に飛んでくるという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "昆虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プログラムの昆虫が原因で、アプリが止まった。", "explanation": "ここは〈バグ（ソフトの不具合）〉の意味。昆虫は生き物の一種で、ソフトの欠陥を指す語ではないので合わない。"}, {"text": "庭の隅に昆虫が生えてきて、草取りが大変だ。", "explanation": "ここは〈雑草〉の意味。昆虫は生えてくる植物ではないので、庭に生えるという文脈には合わない。"}, {"text": "部屋の隅に昆虫が積もっていた。", "explanation": "ここは〈ほこり〉の意味。昆虫は積もって溜まる汚れではないので、この文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39315, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の花のまわりで、昆虫が観察しました。", "corrected_sentence": "庭の花のまわりで、昆虫を観察しました。", "error_description": "誤りは「昆虫が」の「が」。「観察する」の対象は「を」で示す。「が」では昆虫が観察する側になり、観察の対象が示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39315, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭で捕まえた昆虫を、虫かごに入りました。", "corrected_sentence": "庭で捕まえた昆虫を、虫かごに入れました。", "error_description": "誤りは「入りました」（自動詞「入る」）。正しくは「入れました」（他動詞「入れる」）。「昆虫を」と続けるには他動詞の「入れる」が必要である。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39316, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「サルだけが生息する」で、生息する生き物の主語を示す「が」が入り、文が自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "生息は自動詞なので、目的語の「を」は取らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、ここでは生息の動作に方向は合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、生息する主語の後には続かない。"}], "correct_answer": "が", "explanations": {"が": "「サルだけが生息する」で、生息する生き物の主語を示す「が」が入り、文が自然に成り立つ。", "を": "生息は自動詞なので、目的語の「を」は取らない。", "へ": "「へ」は方向を表すが、ここでは生息の動作に方向は合わない。", "から": "「から」は起点を表すので、生息する主語の後には続かない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39316, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「生き物が生息している」で、生息する主体を示す主語の「が」が入り、文が自然に成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所を示すが、生き物を場所として「生息している」とは言えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、生き物を手段として「生息している」とは言えない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する形なので、「生き物の生息している」では文が終わらない。"}], "correct_answer": "が", "explanations": {"が": "「生き物が生息している」で、生息する主体を示す主語の「が」が入り、文が自然に成り立つ。", "に": "「に」は場所を示すが、生き物を場所として「生息している」とは言えない。", "で": "「で」は手段や場所を示すが、生き物を手段として「生息している」とは言えない。", "の": "「の」は名詞を修飾する形なので、「生き物の生息している」では文が終わらない。"}, "error_tags": {"に": "場所", "で": "手段", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39316, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生き物が住んでいること。", "primary_collocate": null, "pronunciation": "せいそく", "ipa": "seːsokɯ", "syllable_count": 4, "sentences": [{"text": "この川にはめずらしい魚が生息している。", "target_word": "生息", "complexity_tier": "T3", "furigana": "この川[かわ]にはめずらしい魚[さかな]が生息[せいそく]している。", "sentence_source": "generated"}, {"text": "森の奥には、小さなサルだけが生息する。", "target_word": "生息", "complexity_tier": "T3", "furigana": "森[もり]の奥[おく]には、小[ちい]さなサルだけが生息[せいそく]する。", "sentence_source": "generated"}, {"text": "北極には、ホッキョクグマが生息している。", "target_word": "生息", "complexity_tier": "T3", "furigana": "北極[ほっきょく]には、ホッキョクグマが生息[せいそく]している。", "sentence_source": "generated"}, {"text": "湖の水がよごれて、魚の生息が難しくなった。", "target_word": "生息", "complexity_tier": "T3", "furigana": "湖[みずうみ]の水[みず]がよごれて、魚[さかな]の生息[せいそく]が難[むずか]しくなった。", "sentence_source": "generated"}, {"text": "この島では、百種類以上の鳥の生息が確認された。", "target_word": "生息", "complexity_tier": "T3", "furigana": "この島[しま]では、百[ひゃく]種類[しゅるい]以上[いじょう]の鳥[とり]の生息[せいそく]が確認[かくにん]された。", "sentence_source": "generated"}, {"text": "ペンギンは南の寒い海の近くに生息する。", "target_word": "生息", "complexity_tier": "T3", "furigana": "ペンギンは南[みなみ]の寒[さむ]い海[うみ]の近[ちか]くに生息[せいそく]する。", "sentence_source": "generated"}, {"text": "水がきれいなので、ホタルが生息できる。", "target_word": "生息", "complexity_tier": "T3", "furigana": "水[みず]がきれいなので、ホタルが生息[せいそく]できる。", "sentence_source": "generated"}, {"text": "砂漠にも、たくさんの生き物が生息している。", "target_word": "生息", "complexity_tier": "T3", "furigana": "砂漠[さばく]にも、たくさんの生[い]き物[もの]が生息[せいそく]している。", "sentence_source": "generated"}, {"text": "山の上に生息する鳥を見に行った。", "target_word": "生息", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]に生息[せいそく]する鳥[とり]を見[み]に行[い]った。", "sentence_source": "generated"}, {"text": "昔は、この池にカエルが生息していたが、今は見られない。", "target_word": "生息", "complexity_tier": "T3", "furigana": "昔[むかし]は、この池[いけ]にカエルが生息[せいそく]していたが、今[いま]は見[み]られない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生息する", "label": "dictionary form"}, {"form": "生息している", "label": "progressive"}, {"form": "生息した", "label": "past"}, {"form": "生息しない", "label": "negative"}], "register": "neutral written (plain form)", "sense_fingerprint": "animals living in a place (simple ''inhabit'')", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39316, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生息", "is_correct": true, "explanation": "「この川にはめずらしい魚が生息している」で、生き物がその場所に住んでいることを表し、文が自然に成り立つ。"}, {"text": "養殖", "is_correct": false, "explanation": "養殖は人が魚を育てて増やすことなので、魚を主語にすると意味が通らない。"}, {"text": "漁獲", "is_correct": false, "explanation": "漁獲は人が魚を捕ることなので、魚が主語の「している」では成り立たない。"}, {"text": "放流", "is_correct": false, "explanation": "放流は人が魚を川に放すことなので、魚が主語の文には合わない。"}], "explanations": {"生息": "「この川にはめずらしい魚が生息している」で、生き物がその場所に住んでいることを表し、文が自然に成り立つ。", "養殖": "養殖は人が魚を育てて増やすことなので、魚を主語にすると意味が通らない。", "漁獲": "漁獲は人が魚を捕ることなので、魚が主語の「している」では成り立たない。", "放流": "放流は人が魚を川に放すことなので、魚が主語の文には合わない。"}, "sentence_index": 0, "correct_answer": "生息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝六時に起きて、規則正しい生息を送っている。", "explanation": "ここは〈生活〉の意味。生活は人が暮らしぶりを送ることに使うが、生息は生き物が自然の中で住むことなので、人の暮らしぶりには使えない。"}, {"text": "その店は去年、駅前に生息した。", "explanation": "ここは〈開店〉の意味。開店は店が営業を始めることで、生息は生き物が住むことなので、店には使えない。"}, {"text": "この村には古い神社が生息している。", "explanation": "ここは〈存在〉の意味。存在はものがあることを言うが、生息は生き物が住むことなので、神社には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39316, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生息", "is_correct": true, "explanation": "「ホタルが生息できる」で、住み続けられる環境を表し、文が自然に成り立つ。"}, {"text": "製造", "is_correct": false, "explanation": "製造は人が物を作ることで、ホタルを主語にすると意味が通らない。"}, {"text": "発電", "is_correct": false, "explanation": "発電はエネルギーを生み出すことで、ホタルを主語にすると成り立たない。"}, {"text": "点灯", "is_correct": false, "explanation": "点灯は明かりをつけることで、ホタルが自分で明かりを点けるという文脈には合わない。"}], "explanations": {"生息": "「ホタルが生息できる」で、住み続けられる環境を表し、文が自然に成り立つ。", "製造": "製造は人が物を作ることで、ホタルを主語にすると意味が通らない。", "発電": "発電はエネルギーを生み出すことで、ホタルを主語にすると成り立たない。", "点灯": "点灯は明かりをつけることで、ホタルが自分で明かりを点けるという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "生息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は来月、大阪へ生息する。", "explanation": "ここは〈転勤〉の意味。転勤は会社の命令で勤務地を変えることで、生息は生き物が自然の中で暮らすことなので、人の異動には使えない。"}, {"text": "友人は今、ホテルに生息している。", "explanation": "ここは〈滞在〉の意味。滞在は一時的に人が宿に泊まることで、生息は生き物が自然の場所に住むことを表すので、ホテルには合わない。"}, {"text": "古い船が海底に生息している。", "explanation": "ここは〈沈む〉の意味。沈むは物が水の底へ下がることで、生息は生き物が住むことなので、船には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39316, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この池には、小さなカメを生息している。", "corrected_sentence": "この池には、小さなカメが生息している。", "error_description": "「生息」は自動詞なので目的語の「を」は取れない。主語を示す「が」にして「カメが生息している」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39316, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この森には、小さな虫が生息された。", "corrected_sentence": "この森には、小さな虫が生息していた。", "error_description": "「生息」は自動詞なので、受け身の「された」は作れない。過去の状態を表す「生息していた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39317, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「自然の中で生息する」で、生息する場所を示す「で」が入り、文が自然に成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「中が生息する」と主語にすると、場所の「中」が住む主体になり意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "生息は自動詞なので、目的語の「を」は取らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、ここで場所を表す「で」の代わりにはならない。"}], "correct_answer": "で", "explanations": {"で": "「自然の中で生息する」で、生息する場所を示す「で」が入り、文が自然に成り立つ。", "が": "「中が生息する」と主語にすると、場所の「中」が住む主体になり意味が通らない。", "を": "生息は自動詞なので、目的語の「を」は取らない。", "から": "「から」は起点を示すので、ここで場所を表す「で」の代わりにはならない。"}, "error_tags": {"が": "主語", "を": "目的語", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
