INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39317, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生物が自然の状態で生活し、繁殖すること。また、その場所。", "primary_collocate": null, "pronunciation": "せいそく", "ipa": "seːsokɯ", "syllable_count": 4, "sentences": [{"text": "この鳥は、湿地で生息し、春に卵を産む。", "target_word": "生息", "complexity_tier": "T3", "furigana": "この鳥[とり]は、湿地[しっち]で生息[せいそく]し、春[はる]に卵[たまご]を産[う]む。", "sentence_source": "generated"}, {"text": "自然の中で生息するトキは、数が少ない。", "target_word": "生息", "complexity_tier": "T3", "furigana": "自然[しぜん]の中[なか]で生息[せいそく]するトキは、数[かず]が少[すく]ない。", "sentence_source": "generated"}, {"text": "森が切られたので、動物が生息する場所が減った。", "target_word": "生息", "complexity_tier": "T3", "furigana": "森[もり]が切[き]られたので、動物[どうぶつ]が生息[せいそく]する場所[ばしょ]が減[へ]った。", "sentence_source": "generated"}, {"text": "川の上流には、きれいな水を好む魚が生息し、繁殖している。", "target_word": "生息", "complexity_tier": "T3", "furigana": "川[かわ]の上流[じょうりゅう]には、きれいな水[みず]を好[この]む魚[さかな]が生息[せいそく]し、繁殖[はんしょく]している。", "sentence_source": "generated"}, {"text": "干潟は、多くの貝が生息する大切な場所だ。", "target_word": "生息", "complexity_tier": "T3", "furigana": "干潟[ひがた]は、多[おお]くの貝[かい]が生息[せいそく]する大切[たいせつ]な場所[ばしょ]だ。", "sentence_source": "generated"}, {"text": "動物園では、野生で生息する姿を見ることができない。", "target_word": "生息", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では、野生[やせい]で生息[せいそく]する姿[すがた]を見[み]ることができない。", "sentence_source": "generated"}, {"text": "この洞窟には、光のない所で生息するコウモリがいる。", "target_word": "生息", "complexity_tier": "T3", "furigana": "この洞窟[どうくつ]には、光[ひかり]のない所[ところ]で生息[せいそく]するコウモリがいる。", "sentence_source": "generated"}, {"text": "海の温度が上がり、サンゴが生息できる場所がせまくなった。", "target_word": "生息", "complexity_tier": "T3", "furigana": "海[うみ]の温度[おんど]が上[あ]がり、サンゴが生息[せいそく]できる場所[ばしょ]がせまくなった。", "sentence_source": "generated"}, {"text": "川に生息するカワウソを守る活動が始まった。", "target_word": "生息", "complexity_tier": "T3", "furigana": "川[かわ]に生息[せいそく]するカワウソを守[まも]る活動[かつどう]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "調査で、この山には新しい種類のカエルが生息することがわかった。", "target_word": "生息", "complexity_tier": "T3", "furigana": "調査[ちょうさ]で、この山[やま]には新[あたら]しい種類[しゅるい]のカエルが生息[せいそく]することがわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生息する", "label": "dictionary form"}, {"form": "生息している", "label": "progressive"}, {"form": "生息した", "label": "past"}, {"form": "生息できる", "label": "potential"}], "register": "formal written (plain form)", "sense_fingerprint": "organisms living and breeding in the wild, and the place where they do", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39317, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生息", "is_correct": true, "explanation": "「湿地で生息し」で、鳥がその場所に住むことを表し、文が自然に成り立つ。"}, {"text": "狩猟", "is_correct": false, "explanation": "狩猟は人が鳥を捕ることを指すので、鳥が主語の文には合わない。"}, {"text": "放鳥", "is_correct": false, "explanation": "放鳥は人が鳥を野に放つことなので、鳥が自分で行う動作としては成り立たない。"}, {"text": "観察", "is_correct": false, "explanation": "観察は人が対象を見て調べることで、鳥を主語にすると意味が通らない。"}], "explanations": {"生息": "「湿地で生息し」で、鳥がその場所に住むことを表し、文が自然に成り立つ。", "狩猟": "狩猟は人が鳥を捕ることを指すので、鳥が主語の文には合わない。", "放鳥": "放鳥は人が鳥を野に放つことなので、鳥が自分で行う動作としては成り立たない。", "観察": "観察は人が対象を見て調べることで、鳥を主語にすると意味が通らない。"}, "sentence_index": 0, "correct_answer": "生息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は昨日、駅まで生息した。", "explanation": "ここは〈移動〉の意味。移動は人や物が場所を変えることで、生息は生き物が特定の場所で暮らすことなので、人の行き先には使えない。"}, {"text": "その町は昔から商業で生息してきた。", "explanation": "ここは〈繁栄〉の意味。繁栄は町や店などが栄えることで、生息は生き物が住むことを表すので、町の栄え方には使えない。"}, {"text": "赤ちゃんがベビーベッドで生息している。", "explanation": "ここは〈寝る〉の意味。寝るは人が眠ることで、生息は生き物が自然の中で住むことなので、眠っている赤ちゃんには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39317, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生息", "is_correct": true, "explanation": "「光のない所で生息するコウモリ」で、コウモリが住む様子を表し、文が自然に成り立つ。"}, {"text": "製造", "is_correct": false, "explanation": "製造は人が物を作ることで、コウモリを主語にすると意味が通らない。"}, {"text": "販売", "is_correct": false, "explanation": "販売は物を売ることで、コウモリを主語にすると成り立たない。"}, {"text": "採掘", "is_correct": false, "explanation": "採掘は地下の資源を掘り出すことで、コウモリが主語では意味が合わない。"}], "explanations": {"生息": "「光のない所で生息するコウモリ」で、コウモリが住む様子を表し、文が自然に成り立つ。", "製造": "製造は人が物を作ることで、コウモリを主語にすると意味が通らない。", "販売": "販売は物を売ることで、コウモリを主語にすると成り立たない。", "採掘": "採掘は地下の資源を掘り出すことで、コウモリが主語では意味が合わない。"}, "sentence_index": 6, "correct_answer": "生息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町に新しい公園が生息した。", "explanation": "ここは〈誕生〉の意味。誕生は新しいものが生まれることで、生息は生き物が住むことなので、公園には使えない。"}, {"text": "犯人は国外へ生息した。", "explanation": "ここは〈逃亡〉の意味。逃亡は人が逃げることで、生息は生き物が住み続けることを表すので、人の逃げ方には使えない。"}, {"text": "電車が駅に生息している。", "explanation": "ここは〈停車〉の意味。停車は乗り物が止まることで、生息は生き物が住むことなので、電車には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39317, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この浅瀬には、きれいな水を好む魚を生息している。", "corrected_sentence": "この浅瀬には、きれいな水を好む魚が生息している。", "error_description": "「生息」は自動詞なので、「を」ではなく主語の「が」が正しい。「魚が生息している」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39317, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この谷には、冬の間も生息を作るコウモリがいる。", "corrected_sentence": "この谷には、冬の間も生息するコウモリがいる。", "error_description": "「生息」は「する」と結びつくサ変動詞で、「作る」とは組み合わせられない。「生息するコウモリ」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39318, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「囀りが聞こえる」で、聞こえるものの主語を示す「が」が入り、文が自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「聞こえる」は目的語の「を」を取らないので、「囀りを聞こえる」は誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、聞こえるものの後には続かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同を示すので、「囀りと聞こえる」では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「囀りが聞こえる」で、聞こえるものの主語を示す「が」が入り、文が自然に成り立つ。", "を": "「聞こえる」は目的語の「を」を取らないので、「囀りを聞こえる」は誤り。", "へ": "「へ」は方向を示すので、聞こえるものの後には続かない。", "と": "「と」は共同を示すので、「囀りと聞こえる」では文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39318, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「囀りを聞きながら」で、聞く動作の対象を示す「を」が入り、文が自然に成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すが、聞く動作の対象には「を」が入る。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、聞くという動作には続かない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するので、「囀りの聞きながら」では動詞につながらない。"}], "correct_answer": "を", "explanations": {"を": "「囀りを聞きながら」で、聞く動作の対象を示す「を」が入り、文が自然に成り立つ。", "に": "「に」は相手や場所を示すが、聞く動作の対象には「を」が入る。", "へ": "「へ」は方向を示すので、聞くという動作には続かない。", "の": "「の」は名詞を修飾するので、「囀りの聞きながら」では動詞につながらない。"}, "error_tags": {"に": "相手", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39318, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "小鳥が楽しく歌うこと。", "primary_collocate": null, "pronunciation": "さえずり", "ipa": "saedzɯɾi", "syllable_count": 4, "sentences": [{"text": "朝、窓の外から小鳥の囀りが聞こえてきた。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "朝[あさ]、窓[まど]の外[そと]から小鳥[ことり]の囀[さえず]りが聞[き]こえてきた。", "sentence_source": "generated"}, {"text": "森を歩くと、あちこちから囀りが聞こえる。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "森[もり]を歩[ある]くと、あちこちから囀[さえず]りが聞[き]こえる。", "sentence_source": "generated"}, {"text": "春になると、庭に鳥の囀りがにぎやかに広がる。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "春[はる]になると、庭[にわ]に鳥[とり]の囀[さえず]りがにぎやかに広[ひろ]がる。", "sentence_source": "generated"}, {"text": "小鳥の囀りで、ぼくは目が覚めた。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "小鳥[ことり]の囀[さえず]りで、ぼくは目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "囀りが急にやんで、森が静かになった。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "囀[さえず]りが急[きゅう]にやんで、森[もり]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "木の上で、小鳥が楽しそうな囀りを聞かせてくれた。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "木[き]の上[うえ]で、小鳥[ことり]が楽[たの]しそうな囀[さえず]りを聞[き]かせてくれた。", "sentence_source": "generated"}, {"text": "雨があがると、鳥たちの囀りがまた始まった。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "雨[あめ]があがると、鳥[とり]たちの囀[さえず]りがまた始[はじ]まった。", "sentence_source": "generated"}, {"text": "母は、朝の囀りを聞きながらお茶を飲むのが好きだ。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "母[はは]は、朝[あさ]の囀[さえず]りを聞[き]きながらお茶[ちゃ]を飲[の]むのが好[す]きだ。", "sentence_source": "generated"}, {"text": "公園のベンチで、小鳥の囀りに耳をすませた。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "公園[こうえん]のベンチで、小鳥[ことり]の囀[さえず]りに耳[みみ]をすませた。", "sentence_source": "generated"}, {"text": "窓を開けると、すがすがしい空気と囀りが入ってきた。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、すがすがしい空気[くうき]と囀[さえず]りが入[はい]ってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "囀り", "label": "noun"}, {"form": "囀る", "label": "related verb dictionary form"}], "register": "neutral (plain form)", "sense_fingerprint": "small birds singing cheerfully; the sound heard in daily life", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39318, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "囀り", "is_correct": true, "explanation": "「小鳥の囀りが聞こえてきた」で、小鳥の歌声が聞こえる意味になり、文が自然に成り立つ。"}, {"text": "羽毛", "is_correct": false, "explanation": "羽毛は鳥の体を覆う羽のことで、聞こえてくるものではないので文が成り立たない。"}, {"text": "餌", "is_correct": false, "explanation": "餌は鳥が食べるもので、音として聞こえてくるとは言えない。"}, {"text": "卵", "is_correct": false, "explanation": "卵は産むものであり、聞こえてくるものではないので意味が通らない。"}], "explanations": {"囀り": "「小鳥の囀りが聞こえてきた」で、小鳥の歌声が聞こえる意味になり、文が自然に成り立つ。", "羽毛": "羽毛は鳥の体を覆う羽のことで、聞こえてくるものではないので文が成り立たない。", "餌": "餌は鳥が食べるもので、音として聞こえてくるとは言えない。", "卵": "卵は産むものであり、聞こえてくるものではないので意味が通らない。"}, "sentence_index": 0, "correct_answer": "囀り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猫の囀りで、ぼくは目が覚めた。", "explanation": "ここは〈鳴き声〉の意味。鳴き声は猫や犬も出すが、囀りは小鳥が楽しく歌うことを指すので、猫には使わない。"}, {"text": "父の囀りで、ぼくは目が覚めた。", "explanation": "ここは〈咳〉の意味。咳は人が喉から出す音で、囀りは小鳥が歌うことなので、人の咳には使えない。"}, {"text": "隣の部屋から、金づちの囀りが聞こえてきた。", "explanation": "ここは〈打つ音〉の意味。打つ音は金づちが物を叩いて出す音で、囀りは小鳥の楽しい歌を指すので、道具の音には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39318, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "囀り", "is_correct": true, "explanation": "「鳥たちの囀りがまた始まった」で、鳥が鳴き始めた意味になり、文が自然に成り立つ。"}, {"text": "翼", "is_correct": false, "explanation": "翼は鳥の体の一部で、始まるものではないので「翼がまた始まった」は成り立たない。"}, {"text": "足跡", "is_correct": false, "explanation": "足跡は地面に残るもので、始まるものではないので文が成り立たない。"}, {"text": "巣", "is_correct": false, "explanation": "巣は鳥が作る住まいで、始まるものではないので「巣がまた始まった」は意味が通らない。"}], "explanations": {"囀り": "「鳥たちの囀りがまた始まった」で、鳥が鳴き始めた意味になり、文が自然に成り立つ。", "翼": "翼は鳥の体の一部で、始まるものではないので「翼がまた始まった」は成り立たない。", "足跡": "足跡は地面に残るもので、始まるものではないので文が成り立たない。", "巣": "巣は鳥が作る住まいで、始まるものではないので「巣がまた始まった」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "囀り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台所から香ばしい囀りがしてきた。", "explanation": "ここは〈匂い〉の意味。香ばしい匂いは食べ物から漂うもので、囀りは小鳥の歌声を指すので、食べ物の香りには使えない。"}, {"text": "夕焼けの囀りがきれいだった。", "explanation": "ここは〈色〉の意味。色は目で見るもので、囀りは小鳥が歌う声を指すので、夕焼けの色には使えない。"}, {"text": "玄関でドアの囀りがした。", "explanation": "ここは〈開く音〉の意味。ドアの音は物が出す音で、囀りは小鳥の鳴き声なので、ドアには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39318, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方、窓の外から小鳥の囀りを聞こえてきた。", "corrected_sentence": "夕方、窓の外から小鳥の囀りが聞こえてきた。", "error_description": "「聞こえる」は主語に「が」を取る動詞。「囀りを」と目的語にしたのが誤り。主語の「が」にして「囀りが聞こえてきた」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39318, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨がやむと、鳥たちの囀りがまた始めた。", "corrected_sentence": "雨がやむと、鳥たちの囀りがまた始まった。", "error_description": "「始める」は他動詞で目的語が必要。主語の「囀りが」には自動詞の「始まる」を使い、「始まった」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39319, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39319, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「囀りの上手な」で、囀りに関する上手さを示す「の」が入り、文が自然に成り立つ。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すので、囀りで上手というのは成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や対象を示すので、「囀りに上手な」とは続かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「囀りから上手な」とは言えない。"}], "correct_answer": "の", "explanations": {"の": "「囀りの上手な」で、囀りに関する上手さを示す「の」が入り、文が自然に成り立つ。", "で": "「で」は手段を示すので、囀りで上手というのは成り立たない。", "に": "「に」は方向や対象を示すので、「囀りに上手な」とは続かない。", "から": "「から」は起点を示すので、「囀りから上手な」とは言えない。"}, "error_tags": {"で": "手段", "に": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39319, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "鳥がさえずること。美しい声で鳴くこと。", "primary_collocate": null, "pronunciation": "さえずり", "ipa": "saedzɯɾi", "syllable_count": 4, "sentences": [{"text": "ウグイスの美しい囀りは、春の訪れを知らせる。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "ウグイスの美[うつく]しい囀[さえず]りは、春[はる]の訪[おとず]れを知[し]らせる。", "sentence_source": "generated"}, {"text": "彼女の話し声は、まるで小鳥の囀りのようにかわいらしい。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の話[はな]し声[ごえ]は、まるで小鳥[ことり]の囀[さえず]りのようにかわいらしい。", "sentence_source": "generated"}, {"text": "繁殖期のオスは、メスをよぶために囀りを続ける。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "繁殖期[はんしょくき]のオスは、メスをよぶために囀[さえず]りを続[つづ]ける。", "sentence_source": "generated"}, {"text": "録音した囀りを聞いて、鳥の種類を調べた。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "録音[ろくおん]した囀[さえず]りを聞[き]いて、鳥[とり]の種類[しゅるい]を調[しら]べた。", "sentence_source": "generated"}, {"text": "この鳥は、澄んだ囀りで有名だ。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "この鳥[とり]は、澄[す]んだ囀[さえず]りで有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "夜明けとともに、森じゅうに囀りが響きわたる。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "夜明[よあ]けとともに、森[もり]じゅうに囀[さえず]りが響[ひび]きわたる。", "sentence_source": "generated"}, {"text": "鳥かごの中のカナリアが、高い囀りを聞かせてくれた。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "鳥[とり]かごの中[なか]のカナリアが、高[たか]い囀[さえず]りを聞[き]かせてくれた。", "sentence_source": "generated"}, {"text": "囀りの上手なヒバリは、昔から人々に愛されてきた。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "囀[さえず]りの上手[じょうず]なヒバリは、昔[むかし]から人々[ひとびと]に愛[あい]されてきた。", "sentence_source": "generated"}, {"text": "山小屋の朝は、鳥たちの囀りで始まる。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "山小屋[やまごや]の朝[あさ]は、鳥[とり]たちの囀[さえず]りで始[はじ]まる。", "sentence_source": "generated"}, {"text": "野鳥観察では、姿よりも先に囀りで鳥に気づくことが多い。", "target_word": "囀り", "complexity_tier": "T3", "furigana": "野鳥[やちょう]観察[かんさつ]では、姿[すがた]よりも先[さき]に囀[さえず]りで鳥[とり]に気[き]づくことが多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "囀り", "label": "noun"}, {"form": "囀る", "label": "related verb dictionary form"}], "register": "neutral to literary (plain form)", "sense_fingerprint": "a bird''s beautiful song, also used as a simile for a lovely voice", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39319, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "囀り", "is_correct": true, "explanation": "「ウグイスの美しい囀り」で、ウグイスの美しい鳴き声を指し、文が自然に成り立つ。"}, {"text": "脚", "is_correct": false, "explanation": "脚は体の部位で、春の訪れを知らせるものではないので、主語として意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さのことで、春の訪れを知らせるものではないので文が成り立たない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の熱さのことで、春の訪れを知らせるものではないので文が成り立たない。"}], "explanations": {"囀り": "「ウグイスの美しい囀り」で、ウグイスの美しい鳴き声を指し、文が自然に成り立つ。", "脚": "脚は体の部位で、春の訪れを知らせるものではないので、主語として意味が通らない。", "体重": "体重は体の重さのことで、春の訪れを知らせるものではないので文が成り立たない。", "体温": "体温は体の熱さのことで、春の訪れを知らせるものではないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "囀り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "車の囀りが響いた。", "explanation": "ここは〈エンジン音〉の意味。エンジン音は機械が出す音で、囀りは鳥が美しく鳴く声なので、車の音には合わない。"}, {"text": "台所の蛇口から、水の囀りが止まらない。", "explanation": "ここは〈水音〉の意味。水音は水が流れて出る音で、囀りは鳥の美しい声を指すので、水の流れには使えない。"}, {"text": "ドアの囀りが耳に残る。", "explanation": "ここは〈きしむ音〉の意味。きしむ音はドアなどがこすれて出す音で、囀りは鳥の美しい鳴き声を指すので、ドアには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39319, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "囀り", "is_correct": true, "explanation": "「高い囀りを聞かせてくれた」で、カナリアが高く美しい鳴き声を聞かせた意味になり、文が自然に成り立つ。"}, {"text": "標高", "is_correct": false, "explanation": "標高は土地の高さを表すので、聞かせるものとしては成り立たない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は物の価格のことで、聞かせることはできず意味が通らない。"}, {"text": "身長", "is_correct": false, "explanation": "身長は人の背の高さで、聞かせるものではないので文が成り立たない。"}], "explanations": {"囀り": "「高い囀りを聞かせてくれた」で、カナリアが高く美しい鳴き声を聞かせた意味になり、文が自然に成り立つ。", "標高": "標高は土地の高さを表すので、聞かせるものとしては成り立たない。", "値段": "値段は物の価格のことで、聞かせることはできず意味が通らない。", "身長": "身長は人の背の高さで、聞かせるものではないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "囀り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓から見える囀りが美しい。", "explanation": "ここは〈風景〉の意味。風景は目で見るもので、囀りは耳で聞くものなので、見えるものとしては使えない。"}, {"text": "旬の囀りで季節に気づく。", "explanation": "ここは〈味〉の意味。旬の味は舌で感じるもので、囀りは鳥の鳴き声を指すので、食べ物には使えない。"}, {"text": "地震の囀りで目が覚めた。", "explanation": "ここは〈揺れ〉の意味。揺れは地面が動くことで、囀りは鳥の鳴き声なので、地震には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39319, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ヒバリの澄んだ囀りを、春の訪れを知らせる。", "corrected_sentence": "ヒバリの澄んだ囀りは、春の訪れを知らせる。", "error_description": "主語の「は」を「を」にすると、「囀りを」が目的語になり、「知らせる」の目的語「春の訪れ」と重なって誤り。主題の「は」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39319, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ウグイスの囀るは、春の訪れを知らせる。", "corrected_sentence": "ウグイスの囀りは、春の訪れを知らせる。", "error_description": "「囀る」は動詞なので、主語になる名詞「囀り」の位置には置けない。名詞の「囀り」にして「ウグイスの囀りは」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39320, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「遊んだ」の場所を表す「で」で、里山での遊びという意味になり文が自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「遊ぶ」は「を」を目的語にとらず、「里山を遊んだ」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点や時点を表すため、遊ぶ場所を示すには合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すため、その場での遊びには合わない。"}], "correct_answer": "で", "explanations": {"で": "「遊んだ」の場所を表す「で」で、里山での遊びという意味になり文が自然になる。", "を": "「遊ぶ」は「を」を目的語にとらず、「里山を遊んだ」は不自然。", "に": "「に」は到着点や時点を表すため、遊ぶ場所を示すには合わない。", "へ": "「へ」は移動の方向を表すため、その場での遊びには合わない。"}, "error_tags": {"を": "目的語（動作の対象）", "に": "到着点・時点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39320, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「歩いた」の対象として道や山の区域を示し、「近くの里山を歩いた」と成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「里山が歩いた」では主語として不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するため、動詞「歩いた」の直前には置けない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すため、「里山と歩いた」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「歩いた」の対象として道や山の区域を示し、「近くの里山を歩いた」と成り立つ。", "が": "「が」は主語を示すため、「里山が歩いた」では主語として不自然。", "の": "「の」は名詞を修飾するため、動詞「歩いた」の直前には置けない。", "と": "「と」は相手や並列を表すため、「里山と歩いた」は不自然。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39320, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人々が住む近くにある、山や林のことです。", "primary_collocate": null, "pronunciation": "さとやま", "ipa": "satojama", "syllable_count": 4, "sentences": [{"text": "私の家の裏には、小さな里山がある。", "target_word": "里山", "complexity_tier": "T3", "furigana": "私[わたし]の家[いえ]の裏[うら]には、小[ちい]さな里山[さとやま]がある。", "sentence_source": "generated"}, {"text": "子どものころ、毎日のように里山で遊んだ。", "target_word": "里山", "complexity_tier": "T3", "furigana": "子[こ]どものころ、毎日[まいにち]のように里山[さとやま]で遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "里山には、村の人が使う細い道が続いている。", "target_word": "里山", "complexity_tier": "T3", "furigana": "里山[さとやま]には、村[むら]の人[ひと]が使[つか]う細[ほそ]い道[みち]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "秋になると、里山へきのこを採りに行く。", "target_word": "里山", "complexity_tier": "T3", "furigana": "秋[あき]になると、里山[さとやま]へきのこを採[と]りに行[い]く。", "sentence_source": "generated"}, {"text": "この町は海にも里山にも近くて、住みやすい。", "target_word": "里山", "complexity_tier": "T3", "furigana": "この町[まち]は海[うみ]にも里山[さとやま]にも近[ちか]くて、住[す]みやすい。", "sentence_source": "generated"}, {"text": "里山で、祖父は薪を集めていた。", "target_word": "里山", "complexity_tier": "T3", "furigana": "里山[さとやま]で、祖父[そふ]は薪[たきぎ]を集[あつ]めていた。", "sentence_source": "generated"}, {"text": "里山の木を切る人が減って、林が荒れてしまった。", "target_word": "里山", "complexity_tier": "T3", "furigana": "里山[さとやま]の木[き]を切[き]る人[ひと]が減[へ]って、林[はやし]が荒[あ]れてしまった。", "sentence_source": "generated"}, {"text": "学校の遠足で、近くの里山を歩いた。", "target_word": "里山", "complexity_tier": "T3", "furigana": "学校[がっこう]の遠足[えんそく]で、近[ちか]くの里山[さとやま]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "里山には、カブトムシやクワガタがたくさんいる。", "target_word": "里山", "complexity_tier": "T3", "furigana": "里山[さとやま]には、カブトムシやクワガタがたくさんいる。", "sentence_source": "generated"}, {"text": "村のはずれの里山から、夕方になると煙が上がっていた。", "target_word": "里山", "complexity_tier": "T3", "furigana": "村[むら]のはずれの里山[さとやま]から、夕方[ゆうがた]になると煙[けむり]が上[あ]がっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "里山", "label": "noun"}], "register": "plain", "sense_fingerprint": "the hills and woods right next to where people live; used for everyday life", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39320, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "里山", "is_correct": true, "explanation": "「小さな」の後に名詞が入り、家の裏にある山や林を指すので文が成り立つ。"}, {"text": "走って", "is_correct": false, "explanation": "「小さな」は名詞の前にしか置けないため、動詞の「走って」は入らず文が成り立たない。"}, {"text": "静かに", "is_correct": false, "explanation": "副詞の「静かに」は「小さな」の後に続かず、名詞の位置に入れない。"}, {"text": "眠い", "is_correct": false, "explanation": "形容詞の「眠い」は「小さな」の後に続けられず、「小さな眠いがある」は文にならない。"}], "explanations": {"里山": "「小さな」の後に名詞が入り、家の裏にある山や林を指すので文が成り立つ。", "走って": "「小さな」は名詞の前にしか置けないため、動詞の「走って」は入らず文が成り立たない。", "静かに": "副詞の「静かに」は「小さな」の後に続かず、名詞の位置に入れない。", "眠い": "形容詞の「眠い」は「小さな」の後に続けられず、「小さな眠いがある」は文にならない。"}, "sentence_index": 0, "correct_answer": "里山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人里を遠く離れた里山で、炭焼きの小屋を建てた。", "explanation": "〈里山〉は人里の近くにある山や林なので、「人里を遠く離れた」とは合わない。ここは〈奥山〉の意味で、取り違えている。"}, {"text": "ヒマラヤの里山では、空気が薄くて息が苦しくなる。", "explanation": "〈里山〉は人の暮らしに近い低めの山や林を指し、標高の高い山岳地帯には使わない。ここは〈高山〉の意味を取り違えている。"}, {"text": "夏の里山では、子どもたちが砂浜で貝を拾っていた。", "explanation": "〈里山〉は山や林のことで、砂浜や海辺の意味では使わない。ここは〈海岸〉の意味を取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39320, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "里山", "is_correct": true, "explanation": "「里山の木」は人の暮らしの近くにある山や林の木を指し、文脈に合う。"}, {"text": "急いで", "is_correct": false, "explanation": "副詞の「急いで」は名詞の「木」を修飾できず、「急いでの木」は成り立たない。"}, {"text": "美しく", "is_correct": false, "explanation": "副詞の「美しく」は名詞に直接かからず、「美しくの木」とは続かない。"}, {"text": "踊って", "is_correct": false, "explanation": "動詞の「踊って」は名詞の前に来られず、文が成り立たない。"}], "explanations": {"里山": "「里山の木」は人の暮らしの近くにある山や林の木を指し、文脈に合う。", "急いで": "副詞の「急いで」は名詞の「木」を修飾できず、「急いでの木」は成り立たない。", "美しく": "副詞の「美しく」は名詞に直接かからず、「美しくの木」とは続かない。", "踊って": "動詞の「踊って」は名詞の前に来られず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "里山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の隅に、樹齢百年の里山が一本立っている。", "explanation": "〈里山〉は山や林のまとまりを指し、一本の木には使わない。ここは〈大木〉の意味を取り違えている。"}, {"text": "村の中心の里山に、役場やお店が並んでいる。", "explanation": "〈里山〉は自然の山林を指し、役場や店が並ぶ市街地の意味では使わない。ここは〈市街地〉の意味を取り違えている。"}, {"text": "寺の里山の屋根が、台風で吹き飛ばされた。", "explanation": "〈里山〉は山や林を指し、屋根のある建物の意味では使わない。ここは〈お堂〉の意味を取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39320, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちは放課後、里山に遊んだ。", "corrected_sentence": "子どもたちは放課後、里山で遊んだ。", "error_description": "「遊ぶ」の場所は「で」で示す。「に」は到着点を表すため、ここでは誤り。正しくは「里山で遊んだ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39320, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どものころから、私は里山を好きだった。", "corrected_sentence": "子どものころから、私は里山が好きだった。", "error_description": "「好きだ」は対象を「が」で示す。「を」は誤りで、正しくは「里山が好きだった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
