INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39321, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39321, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人の生活に近い場所にある、自然の豊かな山や林。昔ながらの日本の風景。", "primary_collocate": null, "pronunciation": "さとやま", "ipa": "satojama", "syllable_count": 4, "sentences": [{"text": "里山の風景を見ると、昔の日本を思い出す。", "target_word": "里山", "complexity_tier": "T3", "furigana": "里山[さとやま]の風景[ふうけい]を見[み]ると、昔[むかし]の日本[にほん]を思[おも]い出[だ]す。", "sentence_source": "generated"}, {"text": "田んぼと里山が広がる景色は、日本らしくて美しい。", "target_word": "里山", "complexity_tier": "T3", "furigana": "田[た]んぼと里山[さとやま]が広[ひろ]がる景色[けしき]は、日本[にほん]らしくて美[うつく]しい。", "sentence_source": "generated"}, {"text": "里山は人が手を入れてきたので、多くの生き物が暮らしている。", "target_word": "里山", "complexity_tier": "T3", "furigana": "里山[さとやま]は人[ひと]が手[て]を入[い]れてきたので、多[おお]くの生[い]き物[もの]が暮[く]らしている。", "sentence_source": "generated"}, {"text": "都会から来た観光客が、里山の静かな景色に感動した。", "target_word": "里山", "complexity_tier": "T3", "furigana": "都会[とかい]から来[き]た観光客[かんこうきゃく]が、里山[さとやま]の静[しず]かな景色[けしき]に感動[かんどう]した。", "sentence_source": "generated"}, {"text": "この地域では、里山を守る活動が続けられている。", "target_word": "里山", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、里山[さとやま]を守[まも]る活動[かつどう]が続[つづ]けられている。", "sentence_source": "generated"}, {"text": "里山の春は、桜や山菜など自然の恵みでいっぱいだ。", "target_word": "里山", "complexity_tier": "T3", "furigana": "里山[さとやま]の春[はる]は、桜[さくら]や山菜[さんさい]など自然[しぜん]の恵[めぐ]みでいっぱいだ。", "sentence_source": "generated"}, {"text": "写真家は、里山の四季をずっと撮り続けている。", "target_word": "里山", "complexity_tier": "T3", "furigana": "写真家[しゃしんか]は、里山[さとやま]の四季[しき]をずっと撮[と]り続[つづ]けている。", "sentence_source": "generated"}, {"text": "茅葺き屋根の家と里山が、昔ながらの風景をつくっている。", "target_word": "里山", "complexity_tier": "T3", "furigana": "茅葺[かやぶ]き屋根[やね]の家[いえ]と里山[さとやま]が、昔[むかし]ながらの風景[ふうけい]をつくっている。", "sentence_source": "generated"}, {"text": "里山の豊かな自然を、次の世代に残したい。", "target_word": "里山", "complexity_tier": "T3", "furigana": "里山[さとやま]の豊[ゆた]かな自然[しぜん]を、次[つぎ]の世代[せだい]に残[のこ]したい。", "sentence_source": "generated"}, {"text": "民宿に泊まって、里山の暮らしを体験した。", "target_word": "里山", "complexity_tier": "T3", "furigana": "民宿[みんしゅく]に泊[と]まって、里山[さとやま]の暮[く]らしを体験[たいけん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "里山", "label": "noun"}], "register": "plain", "sense_fingerprint": "nature-rich woods and hills tended by people, seen as a traditional Japanese landscape", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39321, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "里山", "is_correct": true, "explanation": "「里山の風景」は自然豊かな山林の景色を指し、「昔の日本を思い出す」と文が合う。"}, {"text": "見て", "is_correct": false, "explanation": "動詞の「見て」は名詞「風景」の前に置けず、「見ての風景」は成り立たない。"}, {"text": "静かに", "is_correct": false, "explanation": "副詞の「静かに」は名詞を直接修飾できず、「静かにの風景」は不自然。"}, {"text": "急いで", "is_correct": false, "explanation": "副詞の「急いで」は名詞の前に入らず、「急いでの風景」は成り立たない。"}], "explanations": {"里山": "「里山の風景」は自然豊かな山林の景色を指し、「昔の日本を思い出す」と文が合う。", "見て": "動詞の「見て」は名詞「風景」の前に置けず、「見ての風景」は成り立たない。", "静かに": "副詞の「静かに」は名詞を直接修飾できず、「静かにの風景」は不自然。", "急いで": "副詞の「急いで」は名詞の前に入らず、「急いでの風景」は成り立たない。"}, "sentence_index": 0, "correct_answer": "里山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人の手が一度も入ったことのない里山を、ガイドと歩いた。", "explanation": "〈里山〉は人が手を入れて守ってきた山林なので、人の手が入っていない場所には合わない。ここは〈原生林〉の意味を取り違えている。"}, {"text": "都心の里山が、夜空を明るく照らしている。", "explanation": "〈里山〉は自然豊かな山林で、ビルが並ぶ都心の景観には使わない。ここは〈高層ビル群〉の意味を取り違えている。"}, {"text": "茅葺き屋根の古い里山が、村の一角に残っている。", "explanation": "〈里山〉は家ではなく山や林の風景を指す。ここは〈古民家〉の意味を取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39321, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "里山", "is_correct": true, "explanation": "「里山の四季」は自然豊かな山林の移ろいを指し、写真の対象として文が成り立つ。"}, {"text": "撮って", "is_correct": false, "explanation": "動詞の「撮って」は名詞の前に入れず、「撮っての四季」は成り立たない。"}, {"text": "ずっと", "is_correct": false, "explanation": "副詞の「ずっと」は名詞を直接修飾できず、「ずっとの四季」は不自然。"}, {"text": "美しく", "is_correct": false, "explanation": "副詞の「美しく」は名詞の前に直接入らず、「美しくの四季」は成り立たない。"}], "explanations": {"里山": "「里山の四季」は自然豊かな山林の移ろいを指し、写真の対象として文が成り立つ。", "撮って": "動詞の「撮って」は名詞の前に入れず、「撮っての四季」は成り立たない。", "ずっと": "副詞の「ずっと」は名詞を直接修飾できず、「ずっとの四季」は不自然。", "美しく": "副詞の「美しく」は名詞の前に直接入らず、「美しくの四季」は成り立たない。"}, "sentence_index": 6, "correct_answer": "里山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "見渡すかぎり里山が広がり、強い風が砂を巻き上げていた。", "explanation": "〈里山〉は緑豊かな山林を指し、砂ばかりの砂漠の意味では使わない。ここは〈砂漠〉の意味を取り違えている。"}, {"text": "田植えを終えた里山が、朝日に光っている。", "explanation": "〈里山〉は山や林の風景で、田植えをする水田の意味では使わない。ここは〈水田〉の意味を取り違えている。"}, {"text": "夏の里山で、子どもたちが波に乗っていた。", "explanation": "〈里山〉は山や林のことで、波の立つ海の意味では使わない。ここは〈海〉の意味を取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39321, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この村では、里山を人の手で守られている。", "corrected_sentence": "この村では、里山が人の手で守られている。", "error_description": "受け身の文で動作を受ける「里山」は主語になるので「が」で示す。「を」は誤り。正しくは「里山が人の手で守られている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39321, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末、家族で里山が散歩した。", "corrected_sentence": "週末、家族で里山を散歩した。", "error_description": "「散歩する」で歩く場所は「を」で示す。「が」は主語を示すため、里山は歩く主体になれず誤り。正しくは「里山を散歩した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39322, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「返ってきた」の主語として、声がこちらへ戻ってくる文になり自然。"}, {"text": "を", "is_correct": false, "explanation": "「返ってきた」は自動詞なので、「声を」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点を表すため、主語の位置には入らず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するため、動詞の前では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「返ってきた」の主語として、声がこちらへ戻ってくる文になり自然。", "を": "「返ってきた」は自動詞なので、「声を」は不自然。", "に": "「に」は到着点を表すため、主語の位置には入らず文が成り立たない。", "の": "「の」は名詞を修飾するため、動詞の前では文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "到着点", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39322, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「手もとに返ってきた」の到着点を表し、ブーメランが手もとへ戻る文になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「手もとが返ってきた」は到着点として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すため、「手もとと返ってきた」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表すため、「手もとより返ってきた」は到着点として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「手もとに返ってきた」の到着点を表し、ブーメランが手もとへ戻る文になる。", "が": "「が」は主語を示すため、「手もとが返ってきた」は到着点として成り立たない。", "と": "「と」は相手や並列を表すため、「手もとと返ってきた」は意味が通らない。", "より": "「より」は比較や起点を表すため、「手もとより返ってきた」は到着点として成り立たない。"}, "error_tags": {"が": "主語", "と": "並列・相手", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39322, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "うしろやもとのほうへもどる。", "primary_collocate": null, "pronunciation": "かえる", "ipa": "kaeɾɯ", "syllable_count": 3, "sentences": [{"text": "貸した本が一週間後に返ってきた。", "target_word": "返って", "complexity_tier": "T3", "furigana": "貸[か]した本[ほん]が一週間後[いっしゅうかんご]に返[かえ]ってきた。", "sentence_source": "generated"}, {"text": "山の上で叫ぶと、向かいの谷から声が返ってきた。", "target_word": "返って", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]で叫[さけ]ぶと、向[む]かいの谷[たに]から声[こえ]が返[かえ]ってきた。", "sentence_source": "generated"}, {"text": "壁に当たったボールが、すぐにこちらへ返ってきた。", "target_word": "返ってきた", "complexity_tier": "T3", "furigana": "壁[かべ]に当[あ]たったボールが、すぐにこちらへ返[かえ]ってきた。", "sentence_source": "generated"}, {"text": "道を間違えたので、少し前の交差点へ返って歩き直した。", "target_word": "返って", "complexity_tier": "T3", "furigana": "道[みち]を間違[まちが]えたので、少[すこ]し前[まえ]の交差点[こうさてん]へ返[かえ]って歩[ある]き直[なお]した。", "sentence_source": "generated"}, {"text": "迷子になった犬が、ようやく飼い主のもとへ返ってきた。", "target_word": "返ってきた", "complexity_tier": "T3", "furigana": "迷子[まいご]になった犬[いぬ]が、ようやく飼[か]い主[ぬし]のもとへ返[かえ]ってきた。", "sentence_source": "generated"}, {"text": "行き止まりだったので、車は来た道へ返るしかなかった。", "target_word": "返る", "complexity_tier": "T3", "furigana": "行[い]き止[ど]まりだったので、車[くるま]は来[き]た道[みち]へ返[かえ]るしかなかった。", "sentence_source": "generated"}, {"text": "岸を離れた船が、夕方には港へ返った。", "target_word": "返った", "complexity_tier": "T3", "furigana": "岸[きし]を離[はな]れた船[ふね]が、夕方[ゆうがた]には港[みなと]へ返[かえ]った。", "sentence_source": "generated"}, {"text": "投げたブーメランが手もとに返ってきた。", "target_word": "返って", "complexity_tier": "T3", "furigana": "投[な]げたブーメランが手[て]もとに返[かえ]ってきた。", "sentence_source": "generated"}, {"text": "波は岸にぶつかって、また沖へ返っていく。", "target_word": "返って", "complexity_tier": "T3", "furigana": "波[なみ]は岸[きし]にぶつかって、また沖[おき]へ返[かえ]っていく。", "sentence_source": "generated"}, {"text": "貸したお金が三年たっても返ってこない。", "target_word": "返って", "complexity_tier": "T3", "furigana": "貸[か]したお金[かね]が三年[さんねん]たっても返[かえ]ってこない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "返る", "label": "辞書形"}, {"form": "返らない", "label": "否定形"}, {"form": "返ります", "label": "丁寧形"}, {"form": "返って", "label": "て形"}, {"form": "返った", "label": "過去形"}, {"form": "返れば", "label": "仮定形"}, {"form": "返ろう", "label": "意向形"}], "register": "plain", "sense_fingerprint": "貸した物や声、気持ちなどが、もとの持ち主や出どころ、もとの状態のほうへもどる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39322, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "返って", "is_correct": true, "explanation": "て形で「てきた」を作り、貸した本がもとの持ち主のもとへ戻ってきた意味になる。"}, {"text": "返らず", "is_correct": false, "explanation": "ず形は「きた」に続けられず、「返らずきた」は文が成り立たない。"}, {"text": "返そう", "is_correct": false, "explanation": "意向形は「きた」に直接続かず、「返そうきた」は成り立たない。"}, {"text": "返れ", "is_correct": false, "explanation": "命令形は「きた」の前に置けず、「返れきた」は文にならない。"}], "explanations": {"返って": "て形で「てきた」を作り、貸した本がもとの持ち主のもとへ戻ってきた意味になる。", "返らず": "ず形は「きた」に続けられず、「返らずきた」は文が成り立たない。", "返そう": "意向形は「きた」に直接続かず、「返そうきた」は成り立たない。", "返れ": "命令形は「きた」の前に置けず、「返れきた」は文にならない。"}, "sentence_index": 0, "correct_answer": "返って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しく作った庭に、春の花が返った。", "explanation": "〈返る〉はもとの状態へもどる意味で、初めて生まれたものには使わない。ここは〈咲く〉の意味を取り違えている。"}, {"text": "大学を出て、新しい町へ返った。", "explanation": "〈返る〉はもとの場所や状態へもどる意味。初めて行く町には使わない。ここは〈移る〉の意味を取り違えている。"}, {"text": "夏の終わりに、子どもたちは初めての海外へ返った。", "explanation": "〈返る〉はもとの場所へもどる意味で、初めて行く場所には使わない。ここは〈行く〉の意味を取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39322, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "返った", "is_correct": true, "explanation": "過去形で文を締め、船が夕方に港へもどった出来事を表す。"}, {"text": "返れば", "is_correct": false, "explanation": "仮定形は文末にできず、「港へ返れば。」は文が未完成になる。"}, {"text": "返りながら", "is_correct": false, "explanation": "「〜ながら」は文末に置けず、「港へ返りながら。」は文が完結しない。"}, {"text": "返りつつ", "is_correct": false, "explanation": "「〜つつ」は文末に置けず、「港へ返りつつ。」は文が成り立たない。"}], "explanations": {"返った": "過去形で文を締め、船が夕方に港へもどった出来事を表す。", "返れば": "仮定形は文末にできず、「港へ返れば。」は文が未完成になる。", "返りながら": "「〜ながら」は文末に置けず、「港へ返りながら。」は文が完結しない。", "返りつつ": "「〜つつ」は文末に置けず、「港へ返りつつ。」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "返った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大人になって、性格が大きく返った。", "explanation": "〈返る〉はもとの状態へもどる意味で、新しく変化する意味では使わない。ここは〈変わる〉の意味を取り違えている。"}, {"text": "強い風で、帆が大きく返った。", "explanation": "〈返る〉はもとの場所や状態へもどる意味で、ここでは裏返る意味に使っている。義項とは別の用法を取り違えている。"}, {"text": "不安が日に日に返っていった。", "explanation": "〈返る〉はもとの状態へもどる意味で、程度が増していく意味では使わない。ここは〈増す〉の意味を取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39322, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "貸したお金を三か月後に返ってきた。", "corrected_sentence": "貸したお金が三か月後に返ってきた。", "error_description": "「返ってくる」の主語（もどってくるもの）は「が」で示す。「を」は誤りで、正しくは「貸したお金が返ってきた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "返って", "is_correct": true, "explanation": "て形で「てきた」に続き、声がもとの方向へ戻ってきた意味になる。"}, {"text": "返らない", "is_correct": false, "explanation": "否定形では「返らないきた」となり、「きた」に続かず文が成り立たない。"}, {"text": "返ろう", "is_correct": false, "explanation": "意向形では「返ろうきた」となり、「きた」に続かず文が成り立たない。"}, {"text": "返り", "is_correct": false, "explanation": "連用形では「返りきた」となり、「きた」に続かず文が成り立たない。"}], "correct_form": "返って", "base_form": "返る", "form_label": "て形", "sentence_index": 1, "explanations": {"返って": "て形で「てきた」に続き、声がもとの方向へ戻ってきた意味になる。", "返らない": "否定形では「返らないきた」となり、「きた」に続かず文が成り立たない。", "返ろう": "意向形では「返ろうきた」となり、「きた」に続かず文が成り立たない。", "返り": "連用形では「返りきた」となり、「きた」に続かず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39322, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "漁を終えた船は、夕方には港で返った。", "corrected_sentence": "漁を終えた船は、夕方には港へ返った。", "error_description": "「返る」はもどる先を「へ」で示す。「で」は動作の場所を表すため誤り。正しくは「港へ返った」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "返って", "is_correct": true, "explanation": "て形で「てきた」を作り、ブーメランが手もとへもどってきた意味になる。"}, {"text": "返った", "is_correct": false, "explanation": "過去形では「返ったきた」となり、「きた」に続かず文が成り立たない。"}, {"text": "返ります", "is_correct": false, "explanation": "丁寧形は「きた」に続かず、「返りますきた」は成り立たない。"}, {"text": "返る", "is_correct": false, "explanation": "辞書形では「返るきた」となり、「きた」に続かず文が成り立たない。"}], "correct_form": "返って", "base_form": "返る", "form_label": "て形", "sentence_index": 7, "explanations": {"返って": "て形で「てきた」を作り、ブーメランが手もとへもどってきた意味になる。", "返った": "過去形では「返ったきた」となり、「きた」に続かず文が成り立たない。", "返ります": "丁寧形は「きた」に続かず、「返りますきた」は成り立たない。", "返る": "辞書形では「返るきた」となり、「きた」に続かず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39323, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「中心に返る」の到着点を表し、振り子が中心へ戻る意味で文が自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「返る」は自動詞なので、「中心を返る」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するため、動詞の直前では文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「中心が返る」では振り子が戻る先を表せない。"}], "correct_answer": "に", "explanations": {"に": "「中心に返る」の到着点を表し、振り子が中心へ戻る意味で文が自然になる。", "を": "「返る」は自動詞なので、「中心を返る」は不自然。", "の": "「の」は名詞を修飾するため、動詞の直前では文が成り立たない。", "が": "「が」は主語を示すため、「中心が返る」では振り子が戻る先を表せない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39323, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「本来の状態に返った」の到着点を表し、体調がもとの状態へ戻った意味で自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すため、「状態と返った」は文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「返る」は自動詞で目的語をとらず、「状態を返った」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表すため、「状態より返った」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「本来の状態に返った」の到着点を表し、体調がもとの状態へ戻った意味で自然になる。", "と": "「と」は相手や並列を表すため、「状態と返った」は文が成り立たない。", "を": "「返る」は自動詞で目的語をとらず、「状態を返った」は成り立たない。", "より": "「より」は比較や起点を表すため、「状態より返った」は意味が通らない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39323, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物の位置や状態が、基準となる場所や方向へもどること。特に、物事が以前の状態や方向に戻ることを表す。", "primary_collocate": null, "pronunciation": "かえる", "ipa": "kaeɾɯ", "syllable_count": 3, "sentences": [{"text": "ゴムは引っ張っても、手を放すと元の長さに返る。", "target_word": "返る", "complexity_tier": "T3", "furigana": "ゴムは引[ひ]っ張[ぱ]っても、手[て]を放[はな]すと元[もと]の長[なが]さに返[かえ]る。", "sentence_source": "generated"}, {"text": "振り子は端まで行くと、また中心に返る。", "target_word": "返る", "complexity_tier": "T3", "furigana": "振[ふ]り子[こ]は端[はし]まで行[い]くと、また中心[ちゅうしん]に返[かえ]る。", "sentence_source": "generated"}, {"text": "道に迷ったら、原点に返って考え直そう。", "target_word": "返って", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]ったら、原点[げんてん]に返[かえ]って考[かんが]え直[なお]そう。", "sentence_source": "generated"}, {"text": "基本に返って、毎日同じ練習を続けた。", "target_word": "返って", "complexity_tier": "T3", "furigana": "基本[きほん]に返[かえ]って、毎日[まいにち]同[おな]じ練習[れんしゅう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼の話は、いつも最後には最初の話題に返る。", "target_word": "返る", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は、いつも最後[さいご]には最初[さいしょ]の話題[わだい]に返[かえ]る。", "sentence_source": "generated"}, {"text": "話が脱線したら、元の話題に返って続けよう。", "target_word": "返って", "complexity_tier": "T3", "furigana": "話[はなし]が脱線[だっせん]したら、元[もと]の話題[わだい]に返[かえ]って続[つづ]けよう。", "sentence_source": "generated"}, {"text": "大会が終わって、選手たちは普段の生活に返った。", "target_word": "返った", "complexity_tier": "T3", "furigana": "大会[たいかい]が終[お]わって、選手[せんしゅ]たちは普段[ふだん]の生活[せいかつ]に返[かえ]った。", "sentence_source": "generated"}, {"text": "休養を取ったので、体調も本来の状態に返った。", "target_word": "返った", "complexity_tier": "T3", "furigana": "休養[きゅうよう]を取[と]ったので、体調[たいちょう]も本来[ほんらい]の状態[じょうたい]に返[かえ]った。", "sentence_source": "generated"}, {"text": "議論が元の点に返ったところで、会議は終わった。", "target_word": "返った", "complexity_tier": "T3", "furigana": "議論[ぎろん]が元[もと]の点[てん]に返[かえ]ったところで、会議[かいぎ]は終[お]わった。", "sentence_source": "generated"}, {"text": "地震のあと、町は少しずつ元の暮らしに返りつつある。", "target_word": "返り", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、町[まち]は少[すこ]しずつ元[もと]の暮[く]らしに返[かえ]りつつある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "返る", "label": "辞書形"}, {"form": "返らない", "label": "否定形"}, {"form": "返ります", "label": "丁寧形"}, {"form": "返って", "label": "て形"}, {"form": "返った", "label": "過去形"}, {"form": "返れば", "label": "仮定形"}, {"form": "返ろう", "label": "意向形"}], "register": "plain", "sense_fingerprint": "物の位置や物事の状態が、基準・原点・以前の状態へもどる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39323, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "返る", "is_correct": true, "explanation": "辞書形で文を締め、ゴムが手を放すと元の長さへもどる意味になる。"}, {"text": "返れば", "is_correct": false, "explanation": "仮定形は文末にできず、「元の長さに返れば。」は文が途中で切れる。"}, {"text": "返りつつ", "is_correct": false, "explanation": "「〜つつ」は文末に置けず、「元の長さに返りつつ。」は文が完結しない。"}, {"text": "返って", "is_correct": false, "explanation": "て形は文末に置けず、「元の長さに返って。」は文が途切れる。"}], "explanations": {"返る": "辞書形で文を締め、ゴムが手を放すと元の長さへもどる意味になる。", "返れば": "仮定形は文末にできず、「元の長さに返れば。」は文が途中で切れる。", "返りつつ": "「〜つつ」は文末に置けず、「元の長さに返りつつ。」は文が完結しない。", "返って": "て形は文末に置けず、「元の長さに返って。」は文が途切れる。"}, "sentence_index": 0, "correct_answer": "返る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "基本を終えて、次の段階へ返った。", "explanation": "〈返る〉はもとの基準や以前の状態へもどる意味で、前へ進む意味では使わない。ここは〈進む〉の意味を取り違えている。"}, {"text": "今年は、新しい分野へ返った。", "explanation": "〈返る〉は以前の状態や基準へもどる意味で、初めての分野へ向かう意味では使わない。ここは〈挑戦〉の意味を取り違えている。"}, {"text": "噂は、あっという間に町中へ返った。", "explanation": "〈返る〉はもとの場所や状態へもどる意味で、広がる意味では使わない。ここは〈広がる〉の意味を取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39323, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "返った", "is_correct": true, "explanation": "過去形で文を締め、選手たちが大会後に普段の生活へもどった出来事を表す。"}, {"text": "返り", "is_correct": false, "explanation": "連用形では述語にならず、「普段の生活に返り。」は文が途切れる。"}, {"text": "返らず", "is_correct": false, "explanation": "ず形は述語として完結せず、「普段の生活に返らず。」は文が成り立たない。"}, {"text": "返りながら", "is_correct": false, "explanation": "「〜ながら」は文末に置けず、「普段の生活に返りながら。」は文が完結しない。"}], "explanations": {"返った": "過去形で文を締め、選手たちが大会後に普段の生活へもどった出来事を表す。", "返り": "連用形では述語にならず、「普段の生活に返り。」は文が途切れる。", "返らず": "ず形は述語として完結せず、「普段の生活に返らず。」は文が成り立たない。", "返りながら": "「〜ながら」は文末に置けず、「普段の生活に返りながら。」は文が完結しない。"}, "sentence_index": 6, "correct_answer": "返った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい技術が返って、町は活気づいた。", "explanation": "〈返る〉はもとの状態や持ち主へもどる意味で、新しく生まれる意味では使わない。ここは〈生まれる〉の意味を取り違えている。"}, {"text": "新しい年度が四月に返った。", "explanation": "〈返る〉は以前の状態へもどる意味で、新しく始まる意味では使わない。ここは〈始まる〉の意味を取り違えている。"}, {"text": "新しいビルが、ようやく返った。", "explanation": "〈返る〉は以前の状態へもどる意味で、完成する意味では使わない。ここは〈完成する〉の意味を取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39323, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ばねは力を抜くと、もとの形を返る。", "corrected_sentence": "ばねは力を抜くと、もとの形に返る。", "error_description": "「返る」はもどる先を「に」で示す。「を」は自動詞の「返る」には合わないため誤り。正しくは「もとの形に返る」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "返る", "is_correct": true, "explanation": "辞書形で文を締め、振り子が中心へもどる意味になる。"}, {"text": "返れば", "is_correct": false, "explanation": "仮定形は文末にできず、「中心に返れば。」は文が途切れる。"}, {"text": "返って", "is_correct": false, "explanation": "て形は文末に置けず、「中心に返って。」は文が途切れる。"}, {"text": "返りつつ", "is_correct": false, "explanation": "「〜つつ」は文末に置けず、「中心に返りつつ。」は文が完結しない。"}], "correct_form": "返る", "base_form": "返る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"返る": "辞書形で文を締め、振り子が中心へもどる意味になる。", "返れば": "仮定形は文末にできず、「中心に返れば。」は文が途切れる。", "返って": "て形は文末に置けず、「中心に返って。」は文が途切れる。", "返りつつ": "「〜つつ」は文末に置けず、「中心に返りつつ。」は文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39323, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "休暇が終わって、社員は普段の仕事に返らた。", "corrected_sentence": "休暇が終わって、社員は普段の仕事に返った。", "error_description": "「返る」の過去形は「返った」。「返らた」は活用を誤った形で、正しくは「返った」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "返った", "is_correct": true, "explanation": "過去形で、体調が本来の状態へもどった出来事を表す。"}, {"text": "返らず", "is_correct": false, "explanation": "ず形は文末で完結せず、「本来の状態に返らず。」は文が成り立たない。"}, {"text": "返りつつ", "is_correct": false, "explanation": "「〜つつ」は文末に置けず、「本来の状態に返りつつ。」は文が完結しない。"}, {"text": "返れ", "is_correct": false, "explanation": "命令形は「返れ」と命じる形で、体調の回復を述べる文には合わない。"}], "correct_form": "返った", "base_form": "返る", "form_label": "過去形", "sentence_index": 7, "explanations": {"返った": "過去形で、体調が本来の状態へもどった出来事を表す。", "返らず": "ず形は文末で完結せず、「本来の状態に返らず。」は文が成り立たない。", "返りつつ": "「〜つつ」は文末に置けず、「本来の状態に返りつつ。」は文が完結しない。", "返れ": "命令形は「返れ」と命じる形で、体調の回復を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
