INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39324, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「頼んだ」の目的語を示し、「修復を頼んだ」が自然。"}, {"text": "に", "is_correct": false, "explanation": "相手を示すが、修復は人ではないので「修復に頼んだ」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「修復が頼んだ」では誰が頼んだか成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「修復で頼んだ」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「頼んだ」の目的語を示し、「修復を頼んだ」が自然。", "に": "相手を示すが、修復は人ではないので「修復に頼んだ」は不自然。", "が": "主語を示すが、「修復が頼んだ」では誰が頼んだか成り立たない。", "で": "手段や場所を示すが、「修復で頼んだ」は意味が通らない。"}, "error_tags": {"に": "相手マーカー", "が": "主語マーカー", "で": "手段・場所マーカー"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39324, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "こわれたものを、もとどおりにすること。", "primary_collocate": null, "pronunciation": "しゅうふく", "ipa": "ɕɯːɸɯkɯ", "syllable_count": 4, "sentences": [{"text": "父は壊れた時計の修復を頼んだ。", "target_word": "修復", "complexity_tier": "T2", "furigana": "父[ちち]は壊[こわ]れた時計[とけい]の修復[しゅうふく]を頼[たの]んだ。", "sentence_source": "generated"}, {"text": "割れた皿は、修復すれば、また使える。", "target_word": "修復", "complexity_tier": "T2", "furigana": "割[わ]れた皿[さら]は、修復[しゅうふく]すれば、また使[つか]える。", "sentence_source": "generated"}, {"text": "この絵は古いので、修復が必要だ。", "target_word": "修復", "complexity_tier": "T2", "furigana": "この絵[え]は古[ふる]いので、修復[しゅうふく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "台風で壊れた塀の修復は、来週から始まる。", "target_word": "修復", "complexity_tier": "T3", "furigana": "台風[たいふう]で壊[こわ]れた塀[へい]の修復[しゅうふく]は、来週[らいしゅう]から始[はじ]まる。", "sentence_source": "generated"}, {"text": "職人が古い人形を修復して、元の姿に戻した。", "target_word": "修復", "complexity_tier": "T3", "furigana": "職人[しょくにん]が古[ふる]い人形[にんぎょう]を修復[しゅうふく]して、元[もと]の姿[すがた]に戻[もど]した。", "sentence_source": "generated"}, {"text": "道路の修復が終わり、車がまた通れるようになった。", "target_word": "修復", "complexity_tier": "T3", "furigana": "道路[どうろ]の修復[しゅうふく]が終[お]わり、車[くるま]がまた通[とお]れるようになった。", "sentence_source": "generated"}, {"text": "壊れた自転車は、修復に二日かかると言われた。", "target_word": "修復", "complexity_tier": "T3", "furigana": "壊[こわ]れた自転車[じてんしゃ]は、修復[しゅうふく]に二日[ふつか]かかると言[い]われた。", "sentence_source": "generated"}, {"text": "小さな傷なら、自分で修復できる。", "target_word": "修復", "complexity_tier": "T2", "furigana": "小[ちい]さな傷[きず]なら、自分[じぶん]で修復[しゅうふく]できる。", "sentence_source": "generated"}, {"text": "古い写真を修復してもらい、母は喜んだ。", "target_word": "修復", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]を修復[しゅうふく]してもらい、母[はは]は喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "城の壁は、昔のとおりに修復された。", "target_word": "修復", "complexity_tier": "T3", "furigana": "城[しろ]の壁[かべ]は、昔[むかし]のとおりに修復[しゅうふく]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "修復する", "label": "動詞形"}, {"form": "修復した", "label": "過去形"}, {"form": "修復された", "label": "受身過去形"}], "register": "中立（やや硬い）", "sense_fingerprint": "壊れた物を直して元どおりの状態にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39324, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修復", "is_correct": true, "explanation": "壊れた時計を直すことを頼む、という文脈に合い、修復が入る。"}, {"text": "変色", "is_correct": false, "explanation": "色が変わることで、時計を直す依頼とは合わない。"}, {"text": "暴落", "is_correct": false, "explanation": "価格が急に下がることで、時計の依頼には当てはまらない。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出すことで、時計には当てはまらない。"}], "explanations": {"修復": "壊れた時計を直すことを頼む、という文脈に合い、修復が入る。", "変色": "色が変わることで、時計を直す依頼とは合わない。", "暴落": "価格が急に下がることで、時計の依頼には当てはまらない。", "採掘": "地下の資源を掘り出すことで、時計には当てはまらない。"}, "sentence_index": 0, "correct_answer": "修復"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人口が修復して、町に活気が戻った。", "explanation": "ここは〈増加〉の意味。修復は壊れた物を直すことで、人口が増えることには使わない。"}, {"text": "鍋のお湯が修復して、ぐらぐら煮立った。", "explanation": "ここは〈沸騰〉の意味。修復は壊れた物を直すことで、お湯が沸くことには使わない。"}, {"text": "このワインは十年寝かせて修復し、香りが深まった。", "explanation": "ここは〈熟成〉の意味。修復は壊れた物を直すことで、時間をかけて味や香りが深まることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39324, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修復", "is_correct": true, "explanation": "壊れた自転車を直すのに二日かかる、という意味で修復が入る。"}, {"text": "増築", "is_correct": false, "explanation": "建物の床面積を増やすことで、自転車には当てはまらない。"}, {"text": "脱色", "is_correct": false, "explanation": "色を抜くことで、自転車を直す時間の話にはならない。"}, {"text": "冷凍", "is_correct": false, "explanation": "食品などを凍らせることで、壊れた自転車の文脈には合わない。"}], "explanations": {"修復": "壊れた自転車を直すのに二日かかる、という意味で修復が入る。", "増築": "建物の床面積を増やすことで、自転車には当てはまらない。", "脱色": "色を抜くことで、自転車を直す時間の話にはならない。", "冷凍": "食品などを凍らせることで、壊れた自転車の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "修復"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "定刻どおりに列車が駅に修復した。", "explanation": "ここは〈到着〉の意味。修復は壊れた物を直すことで、ある場所に着くことには使わない。"}, {"text": "待ちわびた赤ちゃんが、修復した。", "explanation": "ここは〈誕生〉の意味。修復は既にある物の損傷を直すことで、新しく生まれることには使わない。"}, {"text": "畑のトマトを、修復して集めた。", "explanation": "ここは〈収穫〉の意味。修復は壊れた物を直すことで、作物を取り入れることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39324, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いドアの修復に、大工に頼んだ。", "corrected_sentence": "古いドアの修復を、大工に頼んだ。", "error_description": "誤り: 修復に（正しくは修復を）。頼むの目的語となるため「を」が必要で、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39324, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "壊れた時計は、修復られて、また動くようになった。", "corrected_sentence": "壊れた時計は、修復されて、また動くようになった。", "error_description": "誤り: 修復られて（正しくは修復されて）。サ変動詞「修復する」の受身は「される」で、「られ」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39325, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「修復には、数年かかる」と続き、「〜には」の形で自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。直後の「は」と重なり「修復がには」となり不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。ここでは修復を目的語にする動詞がなく成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する。「修復のは」となり文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "「修復には、数年かかる」と続き、「〜には」の形で自然。", "が": "主語を示す。直後の「は」と重なり「修復がには」となり不自然。", "を": "目的語を示す。ここでは修復を目的語にする動詞がなく成り立たない。", "の": "名詞を修飾する。「修復のは」となり文が成立しない。"}, "error_tags": {"が": "主語マーカー", "を": "目的語マーカー", "の": "連体修飾マーカー"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
