INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39325, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "壊れたり、傷んだりしたものを、元の良い状態に戻すこと。", "primary_collocate": null, "pronunciation": "しゅうふく", "ipa": "ɕɯːɸɯkɯ", "syllable_count": 4, "sentences": [{"text": "かつては安定していた生態系のサイクルが、現代文明の経済活動によって歪められ、その修復は極めて困難な局面を迎えている。", "target_word": "修復", "complexity_tier": "T5", "furigana": "かつては安定[あんてい]していた生態系[せいたいけい]のサイクルが、現代文明[げんだいぶんめい]の経済活動[けいざいかつどう]によって歪[ゆが]められ、その修復[しゅうふく]は極[きわ]めて困難[こんなん]な局面[きょくめん]を迎[むか]えている。", "sentence_source": "mined"}, {"text": "古い壁画の修復には、数年かかる見込みだ。", "target_word": "修復", "complexity_tier": "T3", "furigana": "古[ふる]い壁画[へきが]の修復[しゅうふく]には、数年[すうねん]かかる見込[みこ]みだ。", "sentence_source": "generated"}, {"text": "地震で壊れた橋の修復が、ようやく終わった。", "target_word": "修復", "complexity_tier": "T3", "furigana": "地震[じしん]で壊[こわ]れた橋[はし]の修復[しゅうふく]が、ようやく終[お]わった。", "sentence_source": "generated"}, {"text": "二人の関係の修復は、簡単ではない。", "target_word": "修復", "complexity_tier": "T3", "furigana": "二人[ふたり]の関係[かんけい]の修復[しゅうふく]は、簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "傷んだ屋根を修復するために、業者を呼んだ。", "target_word": "修復", "complexity_tier": "T3", "furigana": "傷[いた]んだ屋根[やね]を修復[しゅうふく]するために、業者[ぎょうしゃ]を呼[よ]んだ。", "sentence_source": "generated"}, {"text": "破損したデータの修復に成功したので、仕事を続けられる。", "target_word": "修復", "complexity_tier": "T4", "furigana": "破損[はそん]したデータの修復[しゅうふく]に成功[せいこう]したので、仕事[しごと]を続[つづ]けられる。", "sentence_source": "generated"}, {"text": "森の生態系を修復するには、長い時間が必要だ。", "target_word": "修復", "complexity_tier": "T4", "furigana": "森[もり]の生態系[せいたいけい]を修復[しゅうふく]するには、長[なが]い時間[じかん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "信頼の修復には、誠実な対応が欠かせない。", "target_word": "修復", "complexity_tier": "T4", "furigana": "信頼[しんらい]の修復[しゅうふく]には、誠実[せいじつ]な対応[たいおう]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "寺の本堂は、大規模な修復を経て、昔の姿を取り戻した。", "target_word": "修復", "complexity_tier": "T4", "furigana": "寺[てら]の本堂[ほんどう]は、大規模[だいきぼ]な修復[しゅうふく]を経[へ]て、昔[むかし]の姿[すがた]を取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "傷ついた肌の修復を助ける薬だ。", "target_word": "修復", "complexity_tier": "T3", "furigana": "傷[きず]ついた肌[はだ]の修復[しゅうふく]を助[たす]ける薬[くすり]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "修復する", "label": "動詞形"}, {"form": "修復した", "label": "過去形"}, {"form": "修復される", "label": "受身形"}], "register": "中立（やや硬い）", "sense_fingerprint": "壊れたり傷んだりした物や関係、環境を元の良い状態に戻すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39325, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修復", "is_correct": true, "explanation": "文脈は「元の良い状態に戻す」ことを求めており、修復が入る。"}, {"text": "変色", "is_correct": false, "explanation": "色が変わることで、元に戻すという意味とは合わない。"}, {"text": "暴落", "is_correct": false, "explanation": "価格などが急に下がることで、生態系の文脈には当てはまらない。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出すことで、生態系のサイクルには当てはまらない。"}], "explanations": {"修復": "文脈は「元の良い状態に戻す」ことを求めており、修復が入る。", "変色": "色が変わることで、元に戻すという意味とは合わない。", "暴落": "価格などが急に下がることで、生態系の文脈には当てはまらない。", "採掘": "地下の資源を掘り出すことで、生態系のサイクルには当てはまらない。"}, "sentence_index": 0, "correct_answer": "修復"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪で寝込んでいたが、体力が修復して、もう元気だ。", "explanation": "ここは〈回復〉の意味。修復は壊れた物や関係を直すことで、体力が戻ることには使わない。"}, {"text": "渋滞が修復して、やっと車が流れ始めた。", "explanation": "ここは〈解消〉の意味。修復は壊れた物を直すことで、渋滞がなくなることには使わない。"}, {"text": "怒りが修復して、やっと落ち着いた。", "explanation": "ここは〈鎮静〉の意味。修復は壊れた物や関係を直すことで、怒りが収まることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39325, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修復", "is_correct": true, "explanation": "「〜するには、長い時間が必要だ」で、元に戻す作業の難しさを述べており修復が入る。"}, {"text": "増築", "is_correct": false, "explanation": "建物の床面積を増やすことで、森の生態系には使えない。"}, {"text": "脱色", "is_correct": false, "explanation": "色を抜くことで、森の生態系を対象にすると意味が通らない。"}, {"text": "配線", "is_correct": false, "explanation": "電線や回路をつなぐことで、生態系には当てはまらない。"}], "explanations": {"修復": "「〜するには、長い時間が必要だ」で、元に戻す作業の難しさを述べており修復が入る。", "増築": "建物の床面積を増やすことで、森の生態系には使えない。", "脱色": "色を抜くことで、森の生態系を対象にすると意味が通らない。", "配線": "電線や回路をつなぐことで、生態系には当てはまらない。"}, "sentence_index": 6, "correct_answer": "修復"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "絶滅したと思われた植物が、修復して再び花を咲かせた。", "explanation": "ここは〈復活〉の意味。修復は壊れた物を直すことで、生き物が生き返ることには使わない。"}, {"text": "古いソフトを、最新版に修復した。", "explanation": "ここは〈更新〉の意味。修復は壊れた物を直すことで、新しい版に切り替えることには使わない。"}, {"text": "中断していた工事が、修復した。", "explanation": "ここは〈再開〉の意味。修復は壊れた物を直すことで、止まっていた作業を再び進めることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39325, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "壊れた屋根の修復に、業者に頼んだ。", "corrected_sentence": "壊れた屋根の修復を、業者に頼んだ。", "error_description": "誤り: 修復に（正しくは修復を）。頼むの目的語は修復なので、直接目的を示す「を」が必要で、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39325, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い橋は、修復させて安全になった。", "corrected_sentence": "古い橋は、修復されて安全になった。", "error_description": "誤り: 修復させて（使役形）。橋は他者に直されるので、受身の「修復されて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39326, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39326, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「拡大へと転回した」の「と」。転回の直前に付き、変化の結果を示す。"}, {"text": "が", "is_correct": false, "explanation": "「拡大へが転回した」となり、格助詞が重なって不自然。"}, {"text": "で", "is_correct": false, "explanation": "「拡大へで転回した」となり、手段にも場所にもならず成立しない。"}, {"text": "を", "is_correct": false, "explanation": "「拡大へを転回した」となり、転回の目的語にならない。"}], "correct_answer": "と", "explanations": {"と": "「拡大へと転回した」の「と」。転回の直前に付き、変化の結果を示す。", "が": "「拡大へが転回した」となり、格助詞が重なって不自然。", "で": "「拡大へで転回した」となり、手段にも場所にもならず成立しない。", "を": "「拡大へを転回した」となり、転回の目的語にならない。"}, "error_tags": {"が": "格の重なり", "で": "手段・場所", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39326, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の向きが変わったり、考え方が変わったりすること。", "primary_collocate": null, "pronunciation": "てんかい", "ipa": "teŋkai", "syllable_count": 4, "sentences": [{"text": "あの一言を境に、交渉の流れは大きく転回した。", "target_word": "転回", "complexity_tier": "T3", "furigana": "あの一言[ひとこと]を境[さかい]に、交渉[こうしょう]の流[なが]れは大[おお]きく転回[てんかい]した。", "sentence_source": "generated"}, {"text": "新しい社長が来てから、会社の方針は大きく転回した。", "target_word": "転回した", "complexity_tier": "T3", "furigana": "新[あたら]しい社長[しゃちょう]が来[き]てから、会社[かいしゃ]の方針[ほうしん]は大[おお]きく転回[てんかい]した。", "sentence_source": "generated"}, {"text": "長い議論の末、反対派の意見は賛成へと転回した。", "target_word": "転回した", "complexity_tier": "T3", "furigana": "長[なが]い議論[ぎろん]の末[すえ]、反対派[はんたいは]の意見[いけん]は賛成[さんせい]へと転回[てんかい]した。", "sentence_source": "generated"}, {"text": "物の見方が転回すると、問題は意外と簡単に解ける。", "target_word": "転回", "complexity_tier": "T3", "furigana": "物[もの]の見方[みかた]が転回[てんかい]すると、問題[もんだい]は意外[いがい]と簡単[かんたん]に解[と]ける。", "sentence_source": "generated"}, {"text": "その経験は、彼の人生観に大きな転回をもたらした。", "target_word": "転回", "complexity_tier": "T3", "furigana": "その経験[けいけん]は、彼[かれ]の人生観[じんせいかん]に大[おお]きな転回[てんかい]をもたらした。", "sentence_source": "generated"}, {"text": "考え方の転回は、小さなきっかけから始まることが多い。", "target_word": "転回", "complexity_tier": "T3", "furigana": "考[かんが]え方[かた]の転回[てんかい]は、小[ちい]さなきっかけから始[はじ]まることが多[おお]い。", "sentence_source": "generated"}, {"text": "政府の外交方針は、昨年から対話重視へと転回している。", "target_word": "転回している", "complexity_tier": "T3", "furigana": "政府[せいふ]の外交[がいこう]方針[ほうしん]は、昨年[さくねん]から対話[たいわ]重視[じゅうし]へと転回[てんかい]している。", "sentence_source": "generated"}, {"text": "不況のなか、会社の戦略は縮小から拡大へと転回した。", "target_word": "転回", "complexity_tier": "T3", "furigana": "不況[ふきょう]のなか、会社[かいしゃ]の戦略[せんりゃく]は縮小[しゅくしょう]から拡大[かくだい]へと転回[てんかい]した。", "sentence_source": "generated"}, {"text": "この小説は、主人公の心の転回を丁寧に描いている。", "target_word": "転回", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、主人公[しゅじんこう]の心[こころ]の転回[てんかい]を丁寧[ていねい]に描[えが]いている。", "sentence_source": "generated"}, {"text": "彼は失敗をきっかけに、考え方が守りから攻めへと転回した。", "target_word": "転回", "complexity_tier": "T3", "furigana": "彼[かれ]は失敗[しっぱい]をきっかけに、考[かんが]え方[かた]が守[まも]りから攻[せ]めへと転回[てんかい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "転回", "label": "名詞形"}, {"form": "転回する", "label": "辞書形"}, {"form": "転回しない", "label": "否定形"}, {"form": "転回して", "label": "て形"}, {"form": "転回した", "label": "過去形"}, {"form": "転回される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "考え方・方針・意見などの向きががらりと変わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39326, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "転回", "is_correct": true, "explanation": "「大きく転回した」となり、名詞の転回に「した」が続いて文が成立する。"}, {"text": "転回して", "is_correct": false, "explanation": "て形で切れるため、「大きく転回してした」となり文が成立しない。"}, {"text": "転回させ", "is_correct": false, "explanation": "使役の途中で切れ、「大きく転回させした」は成り立たない。"}, {"text": "転回でき", "is_correct": false, "explanation": "可能形の連用形で、「大きく転回できした」と「した」が続かない。"}], "explanations": {"転回": "「大きく転回した」となり、名詞の転回に「した」が続いて文が成立する。", "転回して": "て形で切れるため、「大きく転回してした」となり文が成立しない。", "転回させ": "使役の途中で切れ、「大きく転回させした」は成り立たない。", "転回でき": "可能形の連用形で、「大きく転回できした」と「した」が続かない。"}, "sentence_index": 0, "correct_answer": "転回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の好みは、子どものころから少しずつ転回した。", "explanation": "ここは〈変化〉（少しずつ移り変わる）の意味。〈転回〉は向きが大きく切り替わることなので、少しずつの変化には合わない。"}, {"text": "社長は不正がばれて、地位から転回した。", "explanation": "ここは〈転落〉（地位や立場から落ちる）の意味。〈転回〉は向きが変わることで、地位が下がる意味では使わない。"}, {"text": "ヨットは強風の中、岬の手前で大きく転回して港へ戻った。", "explanation": "ここは船の進行方向を変える物理的な〈転回〉で、考え方や方針の変化を表すこの義項とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39326, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "転回している", "is_correct": true, "explanation": "「へと転回している」で、昨年から続く変化として文が成立する。"}, {"text": "転回しつつ", "is_correct": false, "explanation": "「つつ」は後に続く動作を要する形で、「対話重視へと転回しつつ。」と文末にならず、文が完成しない。"}, {"text": "転回しながら", "is_correct": false, "explanation": "「ながら」は後に別の動作が続く形で、文末では成り立たず、文が完成しない。"}, {"text": "転回しなけれ", "is_correct": false, "explanation": "条件の途中で切れ、文が完成しない。"}], "explanations": {"転回している": "「へと転回している」で、昨年から続く変化として文が成立する。", "転回しつつ": "「つつ」は後に続く動作を要する形で、「対話重視へと転回しつつ。」と文末にならず、文が完成しない。", "転回しながら": "「ながら」は後に別の動作が続く形で、文末では成り立たず、文が完成しない。", "転回しなけれ": "条件の途中で切れ、文が完成しない。"}, "sentence_index": 6, "correct_answer": "転回している"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この記事は来月、別の雑誌へ転回される予定だ。", "explanation": "ここは〈転載〉（記事を別の媒体に写して載せる）の意味。〈転回〉は向きが変わることで、記事を載せ直す意味では使わない。"}, {"text": "雨でぬれた道で、彼は足を滑らせて転回した。", "explanation": "ここは〈転倒〉（つまずいて倒れる）の意味。〈転回〉は向きを変える動きで、倒れることには使わない。"}, {"text": "家族は来月、郊外へ転回することになった。", "explanation": "ここは〈転居〉（住まいを移す）の意味。〈転回〉は向きや方針が変わることで、引っ越しには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39326, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社長が代わり、会社の方針は保守から革新へに転回した。", "corrected_sentence": "社長が代わり、会社の方針は保守から革新へと転回した。", "error_description": "正しくは「革新へと転回した」。「へ」は方向を示し、「と」を重ねて「へと」とするのが自然。「へに」は助詞が二つ重なった誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39326, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その発見は、研究の方向を大きく転回さた。", "corrected_sentence": "その発見は、研究の方向を大きく転回させた。", "error_description": "正しくは「転回させた」（転回＋使役「させる」の過去形）。「転回さた」は「させ」の形が抜けている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39327, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39327, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「境に転回し」の「に」。転回の直前に付き、区切りを示す。"}, {"text": "が", "is_correct": false, "explanation": "「境が転回し」となり、境は転回の主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「境の転回し」となり、文が続かない。"}, {"text": "を", "is_correct": false, "explanation": "「境を転回し」となり、境を動かす意味にならず不自然。"}], "correct_answer": "に", "explanations": {"に": "「境に転回し」の「に」。転回の直前に付き、区切りを示す。", "が": "「境が転回し」となり、境は転回の主語にならない。", "の": "「境の転回し」となり、文が続かない。", "を": "「境を転回し」となり、境を動かす意味にならず不自然。"}, "error_tags": {"が": "主語", "の": "連体修飾", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39327, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある方向から別の方向へ向きを変えること。また、考え方や状況が大きく変化すること。", "primary_collocate": null, "pronunciation": "てんかい", "ipa": "teŋkai", "syllable_count": 4, "sentences": [{"text": "この道路では、車の転回が禁止されている。", "target_word": "転回", "complexity_tier": "T3", "furigana": "この道路[どうろ]では、車[くるま]の転回[てんかい]が禁止[きんし]されている。", "sentence_source": "generated"}, {"text": "前の車が突然転回したので、危うくぶつかるところだった。", "target_word": "転回した", "complexity_tier": "T3", "furigana": "前[まえ]の車[くるま]が突然[とつぜん]転回[てんかい]したので、危[あや]うくぶつかるところだった。", "sentence_source": "generated"}, {"text": "飛行機は雲の手前で大きく転回し、空港へ引き返した。", "target_word": "転回し", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は雲[くも]の手前[てまえ]で大[おお]きく転回[てんかい]し、空港[くうこう]へ引[ひ]き返[かえ]した。", "sentence_source": "generated"}, {"text": "船は港の外で転回して、島のほうへ進んだ。", "target_word": "転回して", "complexity_tier": "T3", "furigana": "船[ふね]は港[みなと]の外[そと]で転回[てんかい]して、島[しま]のほうへ進[すす]んだ。", "sentence_source": "generated"}, {"text": "ここは道幅が広いので、安全に転回できる。", "target_word": "転回できる", "complexity_tier": "T3", "furigana": "ここは道幅[みちはば]が広[ひろ]いので、安全[あんぜん]に転回[てんかい]できる。", "sentence_source": "generated"}, {"text": "狭い路地で、運転手は何度も転回を試みた。", "target_word": "転回", "complexity_tier": "T3", "furigana": "狭[せま]い路地[ろじ]で、運転手[うんてんしゅ]は何度[なんど]も転回[てんかい]を試[こころ]みた。", "sentence_source": "generated"}, {"text": "戦況は一夜にして転回し、守る側が攻める側になった。", "target_word": "転回し", "complexity_tier": "T3", "furigana": "戦況[せんきょう]は一夜[いちや]にして転回[てんかい]し、守[まも]る側[がわ]が攻[せ]める側[がわ]になった。", "sentence_source": "generated"}, {"text": "景気は去年の夏を境に転回し、少しずつ回復し始めた。", "target_word": "転回し", "complexity_tier": "T3", "furigana": "景気[けいき]は去年[きょねん]の夏[なつ]を境[さかい]に転回[てんかい]し、少[すこ]しずつ回復[かいふく]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼女の人生は、その出会いをきっかけに大きく転回した。", "target_word": "転回した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の人生[じんせい]は、その出会[であ]いをきっかけに大[おお]きく転回[てんかい]した。", "sentence_source": "generated"}, {"text": "物語は、主人公が真実を知った瞬間に大きく転回する。", "target_word": "転回する", "complexity_tier": "T3", "furigana": "物語[ものがたり]は、主人公[しゅじんこう]が真実[しんじつ]を知[し]った瞬間[しゅんかん]に大[おお]きく転回[てんかい]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "転回", "label": "名詞形"}, {"form": "転回する", "label": "辞書形"}, {"form": "転回しない", "label": "否定形"}, {"form": "転回して", "label": "て形"}, {"form": "転回した", "label": "過去形"}, {"form": "転回できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "車・船・飛行機などが向きを変えること、また状況ががらりと変わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39327, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "転回", "is_correct": true, "explanation": "「車の転回が禁止されている」の名詞として成立する。"}, {"text": "転回して", "is_correct": false, "explanation": "て形では名詞の位置に入らず、「車の転回して禁止」となる。"}, {"text": "転回させ", "is_correct": false, "explanation": "使役の連用形で、「車の転回させ禁止」は成立しない。"}, {"text": "転回でき", "is_correct": false, "explanation": "可能形の連用形で、名詞の位置に入らず不自然。"}], "explanations": {"転回": "「車の転回が禁止されている」の名詞として成立する。", "転回して": "て形では名詞の位置に入らず、「車の転回して禁止」となる。", "転回させ": "使役の連用形で、「車の転回させ禁止」は成立しない。", "転回でき": "可能形の連用形で、名詞の位置に入らず不自然。"}, "sentence_index": 0, "correct_answer": "転回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は失敗の責任を部下に転回した。", "explanation": "ここは〈転嫁〉（責任や負担を他人に押しつける）の意味。〈転回〉は向きを変えることで、責任を押しつける意味では使わない。"}, {"text": "高速で回るドリルは、軸を中心に転回し続けた。", "explanation": "機械が軸を中心に回る意味は〈回転〉。〈転回〉は進む向きを変えることなので、回り続ける機械には使わない。"}, {"text": "届いたメールを、そのまま友人へ転回した。", "explanation": "ここは〈転送〉（受け取ったものを別の相手へ送る）の意味。〈転回〉は向きや状況が変わることで、メールを送り直す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39327, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "転回し", "is_correct": true, "explanation": "「一夜にして転回し、」の連用形で、後ろの文に続いて意味が通る。"}, {"text": "転回させ", "is_correct": false, "explanation": "使役の連用形で、「戦況を転回させ」となり主語の戦況と合わない。"}, {"text": "転回しよう", "is_correct": false, "explanation": "意志の形で、戦況が意志を持つ文になり不自然。"}, {"text": "転回しろ", "is_correct": false, "explanation": "命令形で、文の途中に入らず成立しない。"}], "explanations": {"転回し": "「一夜にして転回し、」の連用形で、後ろの文に続いて意味が通る。", "転回させ": "使役の連用形で、「戦況を転回させ」となり主語の戦況と合わない。", "転回しよう": "意志の形で、戦況が意志を持つ文になり不自然。", "転回しろ": "命令形で、文の途中に入らず成立しない。"}, "sentence_index": 6, "correct_answer": "転回し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は去年、会社を転回した。", "explanation": "ここは〈転職〉（勤め先を変える）の意味。〈転回〉は向きを変えることで、勤め先を変える意味では使わない。"}, {"text": "会議で決まったことを、帳簿へ転回した。", "explanation": "ここは〈転記〉（書き写す）の意味。〈転回〉は向きを変えることで、書き写しには使わない。"}, {"text": "雨上がりの坂で、子どもが転回してひざを打った。", "explanation": "ここは〈転倒〉（倒れること）の意味。〈転回〉は向きを変える動きで、倒れて体を打つ場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39327, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "狭い道で、トラックは転回できないず、バックで戻った。", "corrected_sentence": "狭い道で、トラックは転回できず、バックで戻った。", "error_description": "正しくは「転回できず」。「できない」の否定の連用形は「できず」で、「できないず」とは言えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39327, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その会社は、経営を赤字から黒字へと転回させいた。", "corrected_sentence": "その会社は、経営を赤字から黒字へと転回させた。", "error_description": "正しくは「転回させた」。「させいた」は活用の誤りで、「させ＋た」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39328, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "素人", "is_correct": true, "explanation": "専門家の対義語。専門の人と対になる語。"}, {"text": "機械", "is_correct": false, "explanation": "機械は物で、人の対義語にはならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は物で、人との対義関係はない。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は物で、人との対義関係はない。"}], "correct_answer": "素人", "explanations": {"素人": "専門家の対義語。専門の人と対になる語。", "機械": "機械は物で、人の対義語にはならない。", "教科書": "教科書は物で、人との対義関係はない。", "辞書": "辞書は物で、人との対義関係はない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39328, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「専門の人」の「の」は、専門と人をつなぐ連体の助詞。"}, {"text": "に", "is_correct": false, "explanation": "「専門に人」とは続かない。「に」は専門の後の直接の助詞として不自然。"}, {"text": "を", "is_correct": false, "explanation": "「専門を人」は対象として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「専門で人」と続くと名詞を修飾できず誤り。"}], "correct_answer": "の", "explanations": {"の": "「専門の人」の「の」は、専門と人をつなぐ連体の助詞。", "に": "「専門に人」とは続かない。「に」は専門の後の直接の助詞として不自然。", "を": "「専門を人」は対象として成り立たない。", "で": "「専門で人」と続くと名詞を修飾できず誤り。"}, "error_tags": {"の": "連体修飾", "に": "方向・相手", "を": "対象", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39328, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることに特に詳しい人。", "primary_collocate": null, "pronunciation": "せんもん", "ipa": "seɴmoɴ", "syllable_count": 4, "sentences": [{"text": "パソコンのことは、専門の人に聞いたほうが早い。", "target_word": "専門", "complexity_tier": "T3", "furigana": "パソコンのことは、専門[せんもん]の人[ひと]に聞[き]いたほうが早[はや]い。", "sentence_source": "generated"}, {"text": "彼は魚の専門だから、どんな魚でも名前を言い当てる。", "target_word": "専門", "complexity_tier": "T3", "furigana": "彼[かれ]は魚[さかな]の専門[せんもん]だから、どんな魚[さかな]でも名前[なまえ]を言[い]い当[あ]てる。", "sentence_source": "generated"}, {"text": "体の調子が悪いときは、専門の医者に診てもらおう。", "target_word": "専門", "complexity_tier": "T3", "furigana": "体[からだ]の調子[ちょうし]が悪[わる]いときは、専門[せんもん]の医者[いしゃ]に診[み]てもらおう。", "sentence_source": "generated"}, {"text": "専門の人に任せれば、素人がやるよりずっと安全だ。", "target_word": "専門", "complexity_tier": "T3", "furigana": "専門[せんもん]の人[ひと]に任[まか]せれば、素人[しろうと]がやるよりずっと安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "この古い絵の価値は、専門の目で見ないとわからない。", "target_word": "専門", "complexity_tier": "T3", "furigana": "この古[ふる]い絵[え]の価値[かち]は、専門[せんもん]の目[め]で見[み]ないとわからない。", "sentence_source": "generated"}, {"text": "車の修理は難しいので、専門の人を呼んで直してもらった。", "target_word": "専門", "complexity_tier": "T3", "furigana": "車[くるま]の修理[しゅうり]は難[むずか]しいので、専門[せんもん]の人[ひと]を呼[よ]んで直[なお]してもらった。", "sentence_source": "generated"}, {"text": "税金のことは難しいので、専門の人に代わりに調べてもらった。", "target_word": "専門", "complexity_tier": "T3", "furigana": "税金[ぜいきん]のことは難[むずか]しいので、専門[せんもん]の人[ひと]に代[か]わりに調[しら]べてもらった。", "sentence_source": "generated"}, {"text": "電気工事は専門の人に頼まないと、火事の危険がある。", "target_word": "専門", "complexity_tier": "T3", "furigana": "電気[でんき]工事[こうじ]は専門[せんもん]の人[ひと]に頼[たの]まないと、火事[かじ]の危険[きけん]がある。", "sentence_source": "generated"}, {"text": "あの先生は鳥の専門で、鳴き声だけで種類がわかる。", "target_word": "専門", "complexity_tier": "T3", "furigana": "あの先生[せんせい]は鳥[とり]の専門[せんもん]で、鳴[な]き声[ごえ]だけで種類[しゅるい]がわかる。", "sentence_source": "generated"}, {"text": "専門の人が見れば、本物かどうかはすぐにわかる。", "target_word": "専門", "complexity_tier": "T3", "furigana": "専門[せんもん]の人[ひと]が見[み]れば、本物[ほんもの]かどうかはすぐにわかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "専門", "label": "基本形"}, {"form": "専門の", "label": "連体形（の）"}, {"form": "専門で", "label": "で形"}], "register": "neutral", "sense_fingerprint": "ある分野に特に詳しい人。その道に通じた人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: 言い当てる (Zipf 2.22)']::text[], '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39328, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "専門", "is_correct": true, "explanation": "「専門の人」は、パソコンに詳しい人を指す。文の意味に合う。"}, {"text": "説明書", "is_correct": false, "explanation": "説明書は物なので、「〜の人に聞く」の空欄には入らない。"}, {"text": "掲示板", "is_correct": false, "explanation": "掲示板は人ではないため、「〜の人に聞いたほうが早い」と続かない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は人を指さないので、「〜の人に聞く」とは言えない。"}], "explanations": {"専門": "「専門の人」は、パソコンに詳しい人を指す。文の意味に合う。", "説明書": "説明書は物なので、「〜の人に聞く」の空欄には入らない。", "掲示板": "掲示板は人ではないため、「〜の人に聞いたほうが早い」と続かない。", "教科書": "教科書は人を指さないので、「〜の人に聞く」とは言えない。"}, "sentence_index": 0, "correct_answer": "専門"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このうどんは専門の味で、ダシの香りが格別だ。", "explanation": "ここは〈玄人の味〉（職人の腕前が出た味）の意味。〈専門〉は分野や専門家の意味で、味の出来ばえを表す「玄人」の代わりには合わない。"}, {"text": "この記者は新聞社の専門で、他社の記事は書けない。", "explanation": "ここは〈専属〉（一つの組織だけに所属する）の意味。〈専門〉は分野や専門家の意味なので、所属を限る「専属」の代わりには合わない。"}, {"text": "この担当は専門で、ほかの仕事は受け持たない。", "explanation": "ここは〈専任〉（その仕事だけを受け持つ）の意味。〈専門〉は分野の意味で、仕事の受け持ち方は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39328, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "専門", "is_correct": true, "explanation": "「専門の人に代わりに調べてもらう」は、税金に詳しい人に頼む意味で自然。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は物なので、「〜の人に調べてもらう」とは続かない。"}, {"text": "段ボール", "is_correct": false, "explanation": "段ボールは材料で、人を修飾できない。"}, {"text": "自動車", "is_correct": false, "explanation": "自動車は物で、「〜の人」と言えない。"}], "explanations": {"専門": "「専門の人に代わりに調べてもらう」は、税金に詳しい人に頼む意味で自然。", "辞書": "辞書は物なので、「〜の人に調べてもらう」とは続かない。", "段ボール": "段ボールは材料で、人を修飾できない。", "自動車": "自動車は物で、「〜の人」と言えない。"}, "sentence_index": 6, "correct_answer": "専門"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は会社の専門で、毎朝いちばん早く出勤する。", "explanation": "ここは〈古参〉（長く勤めている人）の意味。〈専門〉は分野や専門家の意味で、勤続年数の意味では使えない。"}, {"text": "この部屋は社長の専門で、ほかの社員は使えない。", "explanation": "ここは〈専用〉（ひとりだけが使う）の意味。〈専門〉は分野の意味で、部屋の占有は表さない。"}, {"text": "この新製品は専門として、この店だけで売っている。", "explanation": "ここは〈専売〉（その店だけで売る）の意味。〈専門〉は分野や専門家の意味で、販売の独占は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39328, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は木の専門に、材料を見ただけで年数がわかる。", "corrected_sentence": "祖父は木の専門で、材料を見ただけで年数がわかる。", "error_description": "「専門」の後は「で」（〜である）で述語を作る。「専門に」は続く述語がなく、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39328, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この件は専門で先生に相談してください。", "corrected_sentence": "この件は専門の先生に相談してください。", "error_description": "「専門」と「先生」をつなぐのは「の」（〜の先生）。「で」は名詞を修飾できず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39330, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「介入する」は「〜に介入する」の形で、対象を「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「けんかを介入して」は対象の格が合わず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」は、介入する相手を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「けんかと介入して」は相手を並べる意味になり、文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "「介入する」は「〜に介入する」の形で、対象を「に」で示す。", "を": "「けんかを介入して」は対象の格が合わず、不自然。", "で": "場所や手段を示す「で」は、介入する相手を表せない。", "と": "「けんかと介入して」は相手を並べる意味になり、文脈に合わない。"}, "error_tags": {"を": "対象の格", "で": "場所・手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
