INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39330, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "誰かが他の人のことに入って、手伝ったり、変えたりすること。", "primary_collocate": null, "pronunciation": "かいにゅう", "ipa": "kainʲɯː", "syllable_count": 4, "sentences": [{"text": "親が子どもの友達関係に介入しすぎるのはよくない。", "target_word": "介入", "complexity_tier": "T3", "furigana": "親[おや]が子[こ]どもの友達[ともだち]関係[かんけい]に介入[かいにゅう]しすぎるのはよくない。", "sentence_source": "generated"}, {"text": "先生が二人のけんかに介入して、話し合いの場を作った。", "target_word": "介入", "complexity_tier": "T3", "furigana": "先生[せんせい]が二人[ふたり]のけんかに介入[かいにゅう]して、話[はな]し合[あ]いの場[ば]を作[つく]った。", "sentence_source": "generated"}, {"text": "夫婦の問題に他人が介入するのは難しい。", "target_word": "介入", "complexity_tier": "T3", "furigana": "夫婦[ふうふ]の問題[もんだい]に他人[たにん]が介入[かいにゅう]するのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "母はいつも私の進路に介入してくるので、少し困っている。", "target_word": "介入", "complexity_tier": "T3", "furigana": "母[はは]はいつも私[わたし]の進路[しんろ]に介入[かいにゅう]してくるので、少[すこ]し困[こま]っている。", "sentence_source": "generated"}, {"text": "兄弟げんかに親が介入すると、かえって長引くことがある。", "target_word": "介入", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]げんかに親[おや]が介入[かいにゅう]すると、かえって長引[ながび]くことがある。", "sentence_source": "generated"}, {"text": "祖母は、孫夫婦の生活に介入しないように気をつけている。", "target_word": "介入", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、孫夫婦[まごふうふ]の生活[せいかつ]に介入[かいにゅう]しないように気[き]をつけている。", "sentence_source": "generated"}, {"text": "隣の人が家の事情に介入してきて、不愉快だった。", "target_word": "介入", "complexity_tier": "T3", "furigana": "隣[となり]の人[ひと]が家[いえ]の事情[じじょう]に介入[かいにゅう]してきて、不愉快[ふゆかい]だった。", "sentence_source": "generated"}, {"text": "友達が悩んでいたが、どこまで介入していいかわからなかった。", "target_word": "介入", "complexity_tier": "T3", "furigana": "友達[ともだち]が悩[なや]んでいたが、どこまで介入[かいにゅう]していいかわからなかった。", "sentence_source": "generated"}, {"text": "上司が部下の仕事に細かく介入すると、部下は自分で考えなくなる。", "target_word": "介入", "complexity_tier": "T3", "furigana": "上司[じょうし]が部下[ぶか]の仕事[しごと]に細[こま]かく介入[かいにゅう]すると、部下[ぶか]は自分[じぶん]で考[かんが]えなくなる。", "sentence_source": "generated"}, {"text": "必要以上の介入は、相手の成長をじゃますることがある。", "target_word": "介入", "complexity_tier": "T3", "furigana": "必要[ひつよう]以上[いじょう]の介入[かいにゅう]は、相手[あいて]の成長[せいちょう]をじゃますることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "介入する", "label": "辞書形"}, {"form": "介入して", "label": "て形"}, {"form": "介入した", "label": "過去形"}, {"form": "介入しない", "label": "否定形"}, {"form": "介入を", "label": "名詞＋を"}], "register": "neutral", "sense_fingerprint": "人が他の人の問題や生活に入り込み、手助けしたり変えようとしたりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39330, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "介入", "is_correct": true, "explanation": "「介入しすぎる」は、他人の問題に手を出しすぎるという意味になり、文に合う。"}, {"text": "解散", "is_correct": false, "explanation": "解散は組織や集まりを終わらせること。「友達関係に解散しすぎる」は意味が通らない。"}, {"text": "収穫", "is_correct": false, "explanation": "収穫は作物を取り入れること。人間関係には使わない。"}, {"text": "配達", "is_correct": false, "explanation": "配達は品物を届けること。友達関係の話には合わない。"}], "explanations": {"介入": "「介入しすぎる」は、他人の問題に手を出しすぎるという意味になり、文に合う。", "解散": "解散は組織や集まりを終わらせること。「友達関係に解散しすぎる」は意味が通らない。", "収穫": "収穫は作物を取り入れること。人間関係には使わない。", "配達": "配達は品物を届けること。友達関係の話には合わない。"}, "sentence_index": 0, "correct_answer": "介入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月から、私は新しいサークルに介入することになった。", "explanation": "ここは〈参加〉の意味。介入は他人のことに無理に入り込んで手を出すことで、サークルに加わる意味では使わない。"}, {"text": "二枚の板のあいだに、薄い紙が介入している。", "explanation": "ここは〈介在〉の意味。介入は人や組織が意図して手を出すことで、物が間にはさまっている状態には使わない。"}, {"text": "私は友達を結婚式に介入した。", "explanation": "ここは〈招待〉の意味。介入は手を出して事態に影響を与えることで、人を誘って呼ぶ意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39330, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "介入", "is_correct": true, "explanation": "「介入してきて」は、他人が事情に手を出してくるという意味になり、文に合う。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案などに点数をつけること。家の事情には合わない。"}, {"text": "出版", "is_correct": false, "explanation": "出版は本などを世に出すこと。家の事情とは結びつかない。"}, {"text": "延期", "is_correct": false, "explanation": "延期は予定を後ろにずらすこと。「家の事情に延期してきて」は意味が通らない。"}], "explanations": {"介入": "「介入してきて」は、他人が事情に手を出してくるという意味になり、文に合う。", "採点": "採点は答案などに点数をつけること。家の事情には合わない。", "出版": "出版は本などを世に出すこと。家の事情とは結びつかない。", "延期": "延期は予定を後ろにずらすこと。「家の事情に延期してきて」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "介入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は吹奏楽部に介入している。", "explanation": "ここは〈所属〉の意味。介入は他人の事柄に手を出すことで、組織に属している意味では使わない。"}, {"text": "来年、私は大学に介入する予定だ。", "explanation": "ここは〈進学〉の意味。介入は事柄に手を出して影響を与えることで、学校に入る意味では使わない。"}, {"text": "新人は来月から営業部に介入することになった。", "explanation": "ここは〈配属〉の意味。介入は手を出して影響を与えることで、担当部署に割り当てる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39330, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "隣の家の問題を親が介入して、話し合いの場を作った。", "corrected_sentence": "隣の家の問題に親が介入して、話し合いの場を作った。", "error_description": "助詞の誤り。「介入する」は「〜に介入する」の形をとるので、「を」ではなく「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39330, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社の経営に、上司が介入をかけた。", "corrected_sentence": "会社の経営に、上司が介入を行った。", "error_description": "動詞の誤り。「介入」と結びつく動詞は「行う」で、「かける」は組み合わない。「介入を行った」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
