INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39331, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "外部から入り込んで、事態や活動に影響を与えること。", "primary_collocate": null, "pronunciation": "かいにゅう", "ipa": "kainʲɯː", "syllable_count": 4, "sentences": [{"text": "政府が市場に介入して、急な値上がりを抑えた。", "target_word": "介入", "complexity_tier": "T3", "furigana": "政府[せいふ]が市場[しじょう]に介入[かいにゅう]して、急[きゅう]な値上[ねあ]がりを抑[おさ]えた。", "sentence_source": "generated"}, {"text": "警察の介入で、広場の争いはすぐにおさまった。", "target_word": "介入", "complexity_tier": "T3", "furigana": "警察[けいさつ]の介入[かいにゅう]で、広場[ひろば]の争[あらそ]いはすぐにおさまった。", "sentence_source": "generated"}, {"text": "他の国が戦争に介入したため、事態はさらに複雑になった。", "target_word": "介入", "complexity_tier": "T3", "furigana": "他[ほか]の国[くに]が戦争[せんそう]に介入[かいにゅう]したため、事態[じたい]はさらに複雑[ふくざつ]になった。", "sentence_source": "generated"}, {"text": "外部からの介入がなければ、この問題は解決できなかっただろう。", "target_word": "介入", "complexity_tier": "T3", "furigana": "外部[がいぶ]からの介入[かいにゅう]がなければ、この問題[もんだい]は解決[かいけつ]できなかっただろう。", "sentence_source": "generated"}, {"text": "国の介入によって、バス会社の運行が続けられることになった。", "target_word": "介入", "complexity_tier": "T3", "furigana": "国[くに]の介入[かいにゅう]によって、バス会社[かいしゃ]の運行[うんこう]が続[つづ]けられることになった。", "sentence_source": "generated"}, {"text": "医者の早い介入のおかげで、病気は重くならなかった。", "target_word": "介入", "complexity_tier": "T3", "furigana": "医者[いしゃ]の早[はや]い介入[かいにゅう]のおかげで、病気[びょうき]は重[おも]くならなかった。", "sentence_source": "generated"}, {"text": "為替市場への介入は、円の急な変動を防ぐために行われた。", "target_word": "介入", "complexity_tier": "T3", "furigana": "為替[かわせ]市場[しじょう]への介入[かいにゅう]は、円[えん]の急[きゅう]な変動[へんどう]を防[ふせ]ぐために行[おこな]われた。", "sentence_source": "generated"}, {"text": "国連は紛争地域への介入について、長い議論を続けている。", "target_word": "介入", "complexity_tier": "T3", "furigana": "国連[こくれん]は紛争[ふんそう]地域[ちいき]への介入[かいにゅう]について、長[なが]い議論[ぎろん]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "外国の介入を嫌って、住民たちは自分たちで話し合うことにした。", "target_word": "介入", "complexity_tier": "T3", "furigana": "外国[がいこく]の介入[かいにゅう]を嫌[きら]って、住民[じゅうみん]たちは自分[じぶん]たちで話[はな]し合[あ]うことにした。", "sentence_source": "generated"}, {"text": "会社の合併に政府が介入するかどうかが、注目されている。", "target_word": "介入", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の合併[がっぺい]に政府[せいふ]が介入[かいにゅう]するかどうかが、注目[ちゅうもく]されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "介入する", "label": "辞書形"}, {"form": "介入して", "label": "て形"}, {"form": "介入した", "label": "過去形"}, {"form": "介入しない", "label": "否定形"}, {"form": "介入を", "label": "名詞＋を"}], "register": "neutral", "sense_fingerprint": "政府・警察・外国など外部の力が、事件や市場や活動に入り込んで影響を与える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39331, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "介入", "is_correct": true, "explanation": "「市場に介入して」は、政府が外から市場に手を出して値上がりを抑えたという意味になり、文に合う。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案などに点数をつけること。「市場に採点して」は意味が通らない。"}, {"text": "解約", "is_correct": false, "explanation": "解約は契約を終わらせること。市場には使わない。"}, {"text": "延期", "is_correct": false, "explanation": "延期は予定を後ろにずらすこと。市場に対しては意味が通らない。"}], "explanations": {"介入": "「市場に介入して」は、政府が外から市場に手を出して値上がりを抑えたという意味になり、文に合う。", "採点": "採点は答案などに点数をつけること。「市場に採点して」は意味が通らない。", "解約": "解約は契約を終わらせること。市場には使わない。", "延期": "延期は予定を後ろにずらすこと。市場に対しては意味が通らない。"}, "sentence_index": 0, "correct_answer": "介入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は自分の作品を展覧会に介入した。", "explanation": "ここは〈出品〉の意味。介入は外から事態に影響を与えることで、作品を並べて出す意味では使わない。"}, {"text": "私は友達の誕生日に、花束を介入した。", "explanation": "ここは〈贈呈〉の意味。介入は事態に手を出して影響を与えることで、物を人に渡す意味では使わない。"}, {"text": "その会社は新しい技術に資金を介入した。", "explanation": "ここは〈投資〉の意味。介入は外から事態に手を出すことで、資金を出して見込みに賭ける意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39331, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "介入", "is_correct": true, "explanation": "「為替市場への介入」は、外から市場に手を出す行為を指し、文に合う。"}, {"text": "採取", "is_correct": false, "explanation": "採取は自然の物を取り集めること。「為替市場への採取」は意味が通らない。"}, {"text": "解散", "is_correct": false, "explanation": "解散は組織や集まりを終わらせること。市場には使わない。"}, {"text": "開催", "is_correct": false, "explanation": "開催は会や催しを開くこと。市場への開催という表現は文に合わない。"}], "explanations": {"介入": "「為替市場への介入」は、外から市場に手を出す行為を指し、文に合う。", "採取": "採取は自然の物を取り集めること。「為替市場への採取」は意味が通らない。", "解散": "解散は組織や集まりを終わらせること。市場には使わない。", "開催": "開催は会や催しを開くこと。市場への開催という表現は文に合わない。"}, "sentence_index": 6, "correct_answer": "介入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "郵便局が荷物を玄関に介入した。", "explanation": "ここは〈配達〉の意味。介入は手を出して事態に影響を与えることで、品物を届ける意味では使わない。"}, {"text": "私は駅前の書店で、その本を介入した。", "explanation": "ここは〈購入〉の意味。介入は事態に手を出すことで、お金を払って手に入れる意味では使わない。"}, {"text": "私はバスに介入した。", "explanation": "ここは〈乗車〉の意味。介入は外から事態に手を出すことで、乗り物に乗る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39331, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府が為替市場を介入して、円の価値を守った。", "corrected_sentence": "政府が為替市場に介入して、円の価値を守った。", "error_description": "助詞の誤り。「介入する」は「〜に介入する」の形で、対象は「に」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39331, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国は通信市場への介入を取った。", "corrected_sentence": "国は通信市場への介入を行った。", "error_description": "動詞の誤り。「介入」と結びつく動詞は「行う」で、「取る」は組み合わない。「介入を行った」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39332, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始まる", "is_correct": true, "explanation": "「終わる」の対義語。物事の終わりに対して始まりを表す。"}, {"text": "届く", "is_correct": false, "explanation": "物が目的地に着く意味で、対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "睡眠の意味で、終わるとは対になっていない。"}, {"text": "壊れる", "is_correct": false, "explanation": "壊れる状態を表し、終わるの対義語ではない。"}], "correct_answer": "始まる", "explanations": {"始まる": "「終わる」の対義語。物事の終わりに対して始まりを表す。", "届く": "物が目的地に着く意味で、対義語ではない。", "眠る": "睡眠の意味で、終わるとは対になっていない。", "壊れる": "壊れる状態を表し、終わるの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39332, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始まる", "is_correct": true, "explanation": "「終わる」の対義語。長い冬の終わりに対して春の始まりを表す。"}, {"text": "集まる", "is_correct": false, "explanation": "人や物が一か所に寄る意味で、対義語ではない。"}, {"text": "戻る", "is_correct": false, "explanation": "元の場所や状態へ帰る意味で、終わるの対義語ではない。"}, {"text": "引く", "is_correct": false, "explanation": "引っ張る、差し引くなどの意味で、対義語ではない。"}], "correct_answer": "始まる", "explanations": {"始まる": "「終わる」の対義語。長い冬の終わりに対して春の始まりを表す。", "集まる": "人や物が一か所に寄る意味で、対義語ではない。", "戻る": "元の場所や状態へ帰る意味で、終わるの対義語ではない。", "引く": "引っ張る、差し引くなどの意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39332, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "続いていた物事や動作が、そこで済んで、それ以上続かなくなること。", "primary_collocate": null, "pronunciation": "おわる", "ipa": "owaɾɯ", "syllable_count": 3, "sentences": [{"text": "夏休みが終わる前に、宿題を全部出したい。", "target_word": "終わる", "complexity_tier": "T3", "furigana": "夏休[なつやす]みが終[お]わる前[まえ]に、宿題[しゅくだい]を全部[ぜんぶ]出[だ]したい。", "sentence_source": "generated"}, {"text": "授業が終わったら、図書館で会おう。", "target_word": "終わったら", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が終[お]わったら、図書館[としょかん]で会[あ]おう。", "sentence_source": "generated"}, {"text": "会議が長引いて、終わったのは夜の九時だった。", "target_word": "終わった", "complexity_tier": "T3", "furigana": "会議[かいぎ]が長引[ながび]いて、終[お]わったのは夜[よる]の九時[くじ]だった。", "sentence_source": "generated"}, {"text": "この仕事は今日中に終わらないので、明日も来る。", "target_word": "終わらない", "complexity_tier": "T3", "furigana": "この仕事[しごと]は今日中[きょうじゅう]に終[お]わらないので、明日[あした]も来[く]る。", "sentence_source": "generated"}, {"text": "映画が終わると、観客は静かに席を立った。", "target_word": "終わる", "complexity_tier": "T3", "furigana": "映画[えいが]が終[お]わると、観客[かんきゃく]は静[しず]かに席[せき]を立[た]った。", "sentence_source": "generated"}, {"text": "仕事が終われば、同僚と食事に行く予定だ。", "target_word": "終われば", "complexity_tier": "T3", "furigana": "仕事[しごと]が終[お]われば、同僚[どうりょう]と食事[しょくじ]に行[い]く予定[よてい]だ。", "sentence_source": "generated"}, {"text": "試合は一対零で終わった。", "target_word": "終わった", "complexity_tier": "T3", "furigana": "試合[しあい]は一対零[いちたいぜろ]で終[お]わった。", "sentence_source": "generated"}, {"text": "話し合いは何も決まらないまま終わってしまった。", "target_word": "終わって", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いは何[なに]も決[き]まらないまま終[お]わってしまった。", "sentence_source": "generated"}, {"text": "工事は来月の末に終わる予定だ。", "target_word": "終わる", "complexity_tier": "T3", "furigana": "工事[こうじ]は来月[らいげつ]の末[すえ]に終[お]わる予定[よてい]だ。", "sentence_source": "generated"}, {"text": "長い冬が終わって、町に春が来た。", "target_word": "終わって", "complexity_tier": "T3", "furigana": "長[なが]い冬[ふゆ]が終[お]わって、町[まち]に春[はる]が来[き]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "終わる", "label": "辞書形"}, {"form": "終わらない", "label": "否定形"}, {"form": "終わります", "label": "丁寧形"}, {"form": "終わって", "label": "て形"}, {"form": "終わった", "label": "過去形"}, {"form": "終われば", "label": "仮定形"}, {"form": "終わろう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "続いていた物事がそこで済み、それ以上続かなくなる（自動詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39332, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "終わる", "is_correct": true, "explanation": "辞書形で「前に」と続き、夏休みが終わる時点を表す。"}, {"text": "終わらせる", "is_correct": false, "explanation": "他動詞で「夏休みが〜」と主語に取れない。文に合わない。"}, {"text": "届く", "is_correct": false, "explanation": "「夏休みが届く」は意味が通らない。"}, {"text": "決める", "is_correct": false, "explanation": "他動詞で、「夏休みが決める」とは続かない。"}], "explanations": {"終わる": "辞書形で「前に」と続き、夏休みが終わる時点を表す。", "終わらせる": "他動詞で「夏休みが〜」と主語に取れない。文に合わない。", "届く": "「夏休みが届く」は意味が通らない。", "決める": "他動詞で、「夏休みが決める」とは続かない。"}, "sentence_index": 0, "correct_answer": "終わる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先月の貯金が終わってしまい、生活が苦しくなった。", "explanation": "ここは〈尽きる〉（なくなる）の意味。〈終わる〉は物事の区切りを表し、お金が減ってなくなる意味では使わない。"}, {"text": "停電で、部屋の灯りが終わった。", "explanation": "ここは〈消える〉の意味。〈終わる〉は物事の区切りで、光が消えるとは言わない。"}, {"text": "洗濯物が雨で終わってしまった。", "explanation": "ここは〈だめになる〉（台無しになる）の意味。〈終わる〉は物事の区切りを表し、雨で台無しになる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39332, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "終わった", "is_correct": true, "explanation": "た形で結果を表し、試合が終了したことを示す。"}, {"text": "届いた", "is_correct": false, "explanation": "「試合は届いた」は意味が通らない。"}, {"text": "使った", "is_correct": false, "explanation": "「試合は使った」は不自然で、文の意味に合わない。"}, {"text": "眠った", "is_correct": false, "explanation": "「試合は眠った」は意味が通らない。"}], "explanations": {"終わった": "た形で結果を表し、試合が終了したことを示す。", "届いた": "「試合は届いた」は意味が通らない。", "使った": "「試合は使った」は不自然で、文の意味に合わない。", "眠った": "「試合は眠った」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "終わった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋になると木の葉が一斉に終わって、庭が静かになった。", "explanation": "ここは〈落ちる〉（葉が離れる）の意味。〈終わる〉は物事の区切りで、葉が落ちる様子には使わない。"}, {"text": "時計の針が終わって、部屋が急に静かになった。", "explanation": "ここは〈止まる〉（動かなくなる）の意味。時計が「終わる」とは言わない。"}, {"text": "客が次々と終わって、店が静かになった。", "explanation": "ここは〈去る〉（その場を離れる）の意味。人が「終わる」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39332, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議が終わらったあと、資料を配ります。", "corrected_sentence": "会議が終わったあと、資料を配ります。", "error_description": "「〜あと」の前は「終わった」（た形）が正しい。「終わらった」は活用が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "終わったら", "is_correct": true, "explanation": "た形＋「ら」で条件を表す。文の条件の意味に合う。"}, {"text": "終わらない", "is_correct": false, "explanation": "否定形で、「終わらないら」の条件にならない。"}, {"text": "終わります", "is_correct": false, "explanation": "丁寧形で、「授業が終わりますら」とは続かない。"}, {"text": "終わろう", "is_correct": false, "explanation": "意向形で、条件を表す文脈に合わない。"}], "correct_form": "終わったら", "base_form": "終わる", "form_label": "たら形", "sentence_index": 1, "explanations": {"終わったら": "た形＋「ら」で条件を表す。文の条件の意味に合う。", "終わらない": "否定形で、「終わらないら」の条件にならない。", "終わります": "丁寧形で、「授業が終わりますら」とは続かない。", "終わろう": "意向形で、条件を表す文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39332, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試合が終わったまで、ここで待ちます。", "corrected_sentence": "試合が終わるまで、ここで待ちます。", "error_description": "「〜まで」の前は辞書形（終わる）が正しい。「終わったまで」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "終わって", "is_correct": true, "explanation": "て形で、「まま〜してしまった」の結果を表す。文に合う。"}, {"text": "終わらず", "is_correct": false, "explanation": "ず形で、「まま」と続く形としては文の流れに合わない。"}, {"text": "終わっている", "is_correct": false, "explanation": "状態の表現で、「まま〜してしまった」の動作の流れに合わない。"}, {"text": "終わり", "is_correct": false, "explanation": "名詞形で、「まま〜」の文法に合わない。"}], "correct_form": "終わって", "base_form": "終わる", "form_label": "て形", "sentence_index": 7, "explanations": {"終わって": "て形で、「まま〜してしまった」の結果を表す。文に合う。", "終わらず": "ず形で、「まま」と続く形としては文の流れに合わない。", "終わっている": "状態の表現で、「まま〜してしまった」の動作の流れに合わない。", "終わり": "名詞形で、「まま〜」の文法に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39333, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始まる", "is_correct": true, "explanation": "「終わる」の対義語。雨がまだ終わっていないことに対して、始まりを表す。"}, {"text": "戻る", "is_correct": false, "explanation": "元の場所や状態へ帰る意味で、対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "睡眠の意味で、対義語ではない。"}, {"text": "壊れる", "is_correct": false, "explanation": "壊れる状態を表し、対義語ではない。"}], "correct_answer": "始まる", "explanations": {"始まる": "「終わる」の対義語。雨がまだ終わっていないことに対して、始まりを表す。", "戻る": "元の場所や状態へ帰る意味で、対義語ではない。", "眠る": "睡眠の意味で、対義語ではない。", "壊れる": "壊れる状態を表し、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39333, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始まる", "is_correct": true, "explanation": "「終わる」の対義語。食事の終わりの後に、皿を洗う動作が始まることを表す。"}, {"text": "集まる", "is_correct": false, "explanation": "人や物が寄る意味で、対義語ではない。"}, {"text": "引く", "is_correct": false, "explanation": "引っ張る、差し引くなどの意味で、対義語ではない。"}, {"text": "並ぶ", "is_correct": false, "explanation": "順に一列に並ぶ意味で、対義語ではない。"}], "correct_answer": "始まる", "explanations": {"始まる": "「終わる」の対義語。食事の終わりの後に、皿を洗う動作が始まることを表す。", "集まる": "人や物が寄る意味で、対義語ではない。", "引く": "引っ張る、差し引くなどの意味で、対義語ではない。", "並ぶ": "順に一列に並ぶ意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39333, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事や動作が、最後の状態になること。続いていたことが、もう続かなくなること。", "primary_collocate": null, "pronunciation": "おわる", "ipa": "owaɾɯ", "syllable_count": 3, "sentences": [{"text": "宿題が終わるまで、ゲームはしないと決めました。", "target_word": "終わる", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が終[お]わるまで、ゲームはしないと決[き]めました。", "sentence_source": "generated"}, {"text": "会議は予定より早く終わったので、みんな昼ごはんに行きました。", "target_word": "終わった", "complexity_tier": "T3", "furigana": "会議[かいぎ]は予定[よてい]より早[はや]く終[お]わったので、みんな昼[ひる]ごはんに行[い]きました。", "sentence_source": "generated"}, {"text": "夏休みが終わると、学校でまた友達に会えます。", "target_word": "終わる", "complexity_tier": "T3", "furigana": "夏休[なつやす]みが終[お]わると、学校[がっこう]でまた友達[ともだち]に会[あ]えます。", "sentence_source": "generated"}, {"text": "雨はまだ終わっていないから、傘を持って出かけてください。", "target_word": "終わって", "complexity_tier": "T3", "furigana": "雨[あめ]はまだ終[お]わっていないから、傘[かさ]を持[も]って出[で]かけてください。", "sentence_source": "generated"}, {"text": "映画が終わった後、私たちは近くの店で感想を話しました。", "target_word": "終わった", "complexity_tier": "T3", "furigana": "映画[えいが]が終[お]わった後[あと]、私[わたし]たちは近[ちか]くの店[みせ]で感想[かんそう]を話[はな]しました。", "sentence_source": "generated"}, {"text": "仕事が終わらなくて、昨日は夜遅くまで会社に残りました。", "target_word": "終わらなくて", "complexity_tier": "T3", "furigana": "仕事[しごと]が終[お]わらなくて、昨日[きのう]は夜遅[よるおそ]くまで会社[かいしゃ]に残[のこ]りました。", "sentence_source": "generated"}, {"text": "試合は二対二の引き分けで終わりました。", "target_word": "終わりました", "complexity_tier": "T3", "furigana": "試合[しあい]は二対二[にたいに]の引[ひ]き分[わ]けで終[お]わりました。", "sentence_source": "generated"}, {"text": "授業が終わるチャイムが鳴ると、生徒たちは教室を飛び出しました。", "target_word": "終わる", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が終[お]わるチャイムが鳴[な]ると、生徒[せいと]たちは教室[きょうしつ]を飛[と]び出[だ]しました。", "sentence_source": "generated"}, {"text": "この長い工事は来月の末に終わる予定です。", "target_word": "終わる", "complexity_tier": "T3", "furigana": "この長[なが]い工事[こうじ]は来月[らいげつ]の末[すえ]に終[お]わる予定[よてい]です。", "sentence_source": "generated"}, {"text": "食事が終わってから、母は皿を洗い始めました。", "target_word": "終わって", "complexity_tier": "T3", "furigana": "食事[しょくじ]が終[お]わってから、母[はは]は皿[さら]を洗[あら]い始[はじ]めました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "終わる", "label": "辞書形"}, {"form": "終わります", "label": "ます形"}, {"form": "終わった", "label": "た形"}, {"form": "終わって", "label": "て形"}, {"form": "終わらない", "label": "ない形"}, {"form": "終われば", "label": "ば形"}], "register": "neutral", "sense_fingerprint": "続いていた物事や動作が最後まで進んで止まること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39333, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "終わる", "is_correct": true, "explanation": "辞書形で「〜まで」と続き、宿題が完了するまでを表す。"}, {"text": "眠る", "is_correct": false, "explanation": "「宿題が眠るまで」は意味が通らない。"}, {"text": "包む", "is_correct": false, "explanation": "「宿題が包むまで」は意味が通らない。"}, {"text": "届ける", "is_correct": false, "explanation": "他動詞で、「宿題が届けるまで」とは続かない。"}], "explanations": {"終わる": "辞書形で「〜まで」と続き、宿題が完了するまでを表す。", "眠る": "「宿題が眠るまで」は意味が通らない。", "包む": "「宿題が包むまで」は意味が通らない。", "届ける": "他動詞で、「宿題が届けるまで」とは続かない。"}, "sentence_index": 0, "correct_answer": "終わる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "荷物が終わって、玄関に置いておいた。", "explanation": "ここは〈届く〉（目的地に着く）の意味。〈終わる〉は作業や期間の区切りで、荷物には使わない。"}, {"text": "お茶がすっかり終わってしまった。", "explanation": "ここは〈なくなる〉（残りがなくなる）の意味。〈終わる〉は物事の区切りで、飲み物の残りには使わない。"}, {"text": "ケガが終わって、また走れるようになった。", "explanation": "ここは〈治る〉（ケガが癒える）の意味。ケガが「終わる」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39333, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "終わりました", "is_correct": true, "explanation": "丁寧形で結果を表し、試合が引き分けで終了したことを示す。"}, {"text": "食べました", "is_correct": false, "explanation": "「試合は引き分けで食べました」は意味が通らない。"}, {"text": "磨きました", "is_correct": false, "explanation": "「試合は引き分けで磨きました」は意味が通らない。"}, {"text": "開けました", "is_correct": false, "explanation": "「試合は引き分けで開けました」は意味が通らない。"}], "explanations": {"終わりました": "丁寧形で結果を表し、試合が引き分けで終了したことを示す。", "食べました": "「試合は引き分けで食べました」は意味が通らない。", "磨きました": "「試合は引き分けで磨きました」は意味が通らない。", "開けました": "「試合は引き分けで開けました」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "終わりました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お風呂のお湯が終わってしまったので、もう一度沸かした。", "explanation": "ここは〈冷める〉（温度が下がる）の意味。お湯が「終わる」とは言わない。"}, {"text": "コップが終わってしまったので、新しいのを買った。", "explanation": "ここは〈割れる〉の意味。〈終わる〉は物事の区切りで、物が壊れる状態には使わない。"}, {"text": "赤ちゃんがやっと終わって、部屋が静かになった。", "explanation": "ここは〈眠る〉の意味。人が寝入る状態を「終わる」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39333, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仕事が終わるを待っています。", "corrected_sentence": "仕事が終わるのを待っています。", "error_description": "「終わる」の後は「の」で名詞化して「のを待つ」とする。「を」だけでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "終わった", "is_correct": true, "explanation": "た形で、「ので」の前の過去の結果を表す。文に合う。"}, {"text": "終わらない", "is_correct": false, "explanation": "否定形で、「早く終わらないので」は文の意味と逆になる。"}, {"text": "終わります", "is_correct": false, "explanation": "丁寧形で、「終わりますので」は文の流れに合わない。"}, {"text": "終われば", "is_correct": false, "explanation": "仮定形で、「早く終われば」は仮定の意味になり、実際に終わった事実に合わない。"}], "correct_form": "終わった", "base_form": "終わる", "form_label": "た形", "sentence_index": 1, "explanations": {"終わった": "た形で、「ので」の前の過去の結果を表す。文に合う。", "終わらない": "否定形で、「早く終わらないので」は文の意味と逆になる。", "終わります": "丁寧形で、「終わりますので」は文の流れに合わない。", "終われば": "仮定形で、「早く終われば」は仮定の意味になり、実際に終わった事実に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39333, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試合が終わりたら、みんなで写真を撮りましょう。", "corrected_sentence": "試合が終わったら、みんなで写真を撮りましょう。", "error_description": "「終わったら」（た形＋ら）が正しい。「終わりたら」は活用が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "終わる", "is_correct": true, "explanation": "辞書形で、「チャイムが〜」を修飾し、授業の終了を表す。"}, {"text": "終わらず", "is_correct": false, "explanation": "「終わらず」は否定の意味になり、文の意味と逆になる。"}, {"text": "終わろう", "is_correct": false, "explanation": "意向形で、名詞を修飾する文脈に合わない。"}, {"text": "終われ", "is_correct": false, "explanation": "命令形で、文の描写に合わない。"}], "correct_form": "終わる", "base_form": "終わる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"終わる": "辞書形で、「チャイムが〜」を修飾し、授業の終了を表す。", "終わらず": "「終わらず」は否定の意味になり、文の意味と逆になる。", "終わろう": "意向形で、名詞を修飾する文脈に合わない。", "終われ": "命令形で、文の描写に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39334, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「巡検の日」の「の」は、巡検と日をつなぐ連体の助詞。"}, {"text": "に", "is_correct": false, "explanation": "「巡検に日」とは続かない。"}, {"text": "を", "is_correct": false, "explanation": "「巡検を日」は対象として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「巡検で日」は名詞を修飾できず誤り。"}], "correct_answer": "の", "explanations": {"の": "「巡検の日」の「の」は、巡検と日をつなぐ連体の助詞。", "に": "「巡検に日」とは続かない。", "を": "「巡検を日」は対象として成り立たない。", "で": "「巡検で日」は名詞を修飾できず誤り。"}, "error_tags": {"の": "連体修飾", "に": "方向・相手", "を": "対象", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39334, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「巡検が終わった」の「が」は、巡検を主語にする格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「巡検を終わった」は他動詞のように扱うことになり、終わるは自動詞なので誤り。"}, {"text": "に", "is_correct": false, "explanation": "「巡検に終わった」は文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「巡検と終わった」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「巡検が終わった」の「が」は、巡検を主語にする格助詞。", "を": "「巡検を終わった」は他動詞のように扱うことになり、終わるは自動詞なので誤り。", "に": "「巡検に終わった」は文の意味が通らない。", "と": "「巡検と終わった」は意味が通らない。"}, "error_tags": {"が": "主語", "を": "対象", "に": "方向・相手", "と": "共同・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39334, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自然の中を歩いて、いろいろなものを見て回ることです。", "primary_collocate": null, "pronunciation": "じゅんけん", "ipa": "dʑɯŋkeɴ", "syllable_count": 4, "sentences": [{"text": "日曜日に、先生と一緒に森を歩く巡検に参加しました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に、先生[せんせい]と一緒[いっしょ]に森[もり]を歩[ある]く巡検[じゅんけん]に参加[さんか]しました。", "sentence_source": "generated"}, {"text": "巡検の日は朝から晴れていて、川の水がとてもきれいに見えました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "巡検[じゅんけん]の日[ひ]は朝[あさ]から晴[は]れていて、川[かわ]の水[みず]がとてもきれいに見[み]えました。", "sentence_source": "generated"}, {"text": "私たちは山の中を歩く巡検で、めずらしい花を三種類見つけました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "私[わたし]たちは山[やま]の中[なか]を歩[ある]く巡検[じゅんけん]で、めずらしい花[はな]を三種類[さんしゅるい]見[み]つけました。", "sentence_source": "generated"}, {"text": "雨が強くなったので、今日の巡検は途中でやめることになりました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]くなったので、今日[きょう]の巡検[じゅんけん]は途中[とちゅう]でやめることになりました。", "sentence_source": "generated"}, {"text": "巡検では、歩きながら木や鳥の名前を教えてもらいました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "巡検[じゅんけん]では、歩[ある]きながら木[き]や鳥[とり]の名前[なまえ]を教[おし]えてもらいました。", "sentence_source": "generated"}, {"text": "春の巡検に行くときは、歩きやすいくつをはいてください。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "春[はる]の巡検[じゅんけん]に行[い]くときは、歩[ある]きやすいくつをはいてください。", "sentence_source": "generated"}, {"text": "海岸を回る巡検の間、子どもたちは貝を集めて楽しんでいました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "海岸[かいがん]を回[まわ]る巡検[じゅんけん]の間[あいだ]、子[こ]どもたちは貝[かい]を集[あつ]めて楽[たの]しんでいました。", "sentence_source": "generated"}, {"text": "巡検が終わったあと、見たものをノートにまとめました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "巡検[じゅんけん]が終[お]わったあと、見[み]たものをノートにまとめました。", "sentence_source": "generated"}, {"text": "町の近くの湖をぐるっと回る巡検は、約二時間かかります。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "町[まち]の近[ちか]くの湖[みずうみ]をぐるっと回[まわ]る巡検[じゅんけん]は、約二時間[やくにじかん]かかります。", "sentence_source": "generated"}, {"text": "昨日の巡検で歩きすぎて、足がまだ痛いです。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "昨日[きのう]の巡検[じゅんけん]で歩[ある]きすぎて、足[あし]がまだ痛[いた]いです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "巡検", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "自然の中を歩きながら、動植物や景色を見て回ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39334, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巡検", "is_correct": true, "explanation": "自然の中を歩いて見て回る催しとして、森を歩く内容に合う。"}, {"text": "名簿", "is_correct": false, "explanation": "名簿は書類で、「森を歩く名簿に参加」とは続かない。"}, {"text": "辞典", "is_correct": false, "explanation": "辞典は本で、「森を歩く辞典」は意味が通らない。"}, {"text": "倉庫", "is_correct": false, "explanation": "倉庫は建物で、「森を歩く倉庫」は成り立たない。"}], "explanations": {"巡検": "自然の中を歩いて見て回る催しとして、森を歩く内容に合う。", "名簿": "名簿は書類で、「森を歩く名簿に参加」とは続かない。", "辞典": "辞典は本で、「森を歩く辞典」は意味が通らない。", "倉庫": "倉庫は建物で、「森を歩く倉庫」は成り立たない。"}, "sentence_index": 0, "correct_answer": "巡検"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警備員が夜の町を巡検している。", "explanation": "ここは〈巡回〉（見回る）の意味。巡検は自然の中を見て回る催しで、町の警備には使わない。"}, {"text": "毎朝、機械を巡検してから仕事を始める。", "explanation": "ここは〈点検〉の意味。巡検は自然観察の行事なので、機械の点検には使わない。"}, {"text": "工場では、製品の巡検を毎日行う。", "explanation": "ここは〈検査〉の意味。巡検は野外で見て回る活動で、製品の検査には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39334, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巡検", "is_correct": true, "explanation": "自然の中を歩いて見て回る催しとして、海岸を回る内容に合う。"}, {"text": "地図", "is_correct": false, "explanation": "地図は物で、「海岸を回る地図の間」とは続かない。"}, {"text": "食器", "is_correct": false, "explanation": "食器は物で、「海岸を回る食器」は意味が通らない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は物で、「海岸を回る花瓶」は成り立たない。"}], "explanations": {"巡検": "自然の中を歩いて見て回る催しとして、海岸を回る内容に合う。", "地図": "地図は物で、「海岸を回る地図の間」とは続かない。", "食器": "食器は物で、「海岸を回る食器」は意味が通らない。", "花瓶": "花瓶は物で、「海岸を回る花瓶」は成り立たない。"}, "sentence_index": 6, "correct_answer": "巡検"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この旅は、寺を一つずつ巡検する。", "explanation": "ここは〈巡礼〉（信仰の場を回る）の意味。巡検は自然の中を見て回る活動なので、寺には使わない。"}, {"text": "朝、先生が生徒の巡検を取る。", "explanation": "ここは〈点呼〉（名前を確かめる）の意味。巡検は点呼ではなく、「取る」とも言わない。"}, {"text": "郵便配達員が毎朝、家々を巡検して回る。", "explanation": "ここは〈配達〉（物を届ける）の意味。巡検は届け物の仕事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39334, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "巡検を参加するには、申し込みが必要です。", "corrected_sentence": "巡検に参加するには、申し込みが必要です。", "error_description": "「参加する」は「〜に参加する」が正しい。「巡検を」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39334, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎年、春に巡検を行いです。", "corrected_sentence": "毎年、春に巡検を行います。", "error_description": "「行う」の丁寧形は「行います」が正しい。「行いです」は活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39335, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「巡検の前に」で、巡検を前に結ぶ連体修飾の「の」。"}, {"text": "で", "is_correct": false, "explanation": "「巡検で前に」は成り立たない。「で」は場所や手段を表す。"}, {"text": "に", "is_correct": false, "explanation": "「巡検に前に」は、「前」が名詞として続かず文にならない。"}, {"text": "から", "is_correct": false, "explanation": "「巡検から前に」は起点の「から」が「前」と続かず、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「巡検の前に」で、巡検を前に結ぶ連体修飾の「の」。", "で": "「巡検で前に」は成り立たない。「で」は場所や手段を表す。", "に": "「巡検に前に」は、「前」が名詞として続かず文にならない。", "から": "「巡検から前に」は起点の「から」が「前」と続かず、意味が通らない。"}, "error_tags": {"で": "場所・手段を表し、名詞の連結にならない", "に": "「前」と続かず文が成り立たない", "から": "起点を表し、「前」と続かない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39335, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「巡検があります」で、存在するものを示す主語の「が」。"}, {"text": "を", "is_correct": false, "explanation": "「巡検をあります」は目的語の「を」が「ある」と続かず、文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「巡検へあります」は方向の「へ」が「ある」と続かず、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「巡検とあります」は並列や相手の「と」で、「ある」の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「巡検があります」で、存在するものを示す主語の「が」。", "を": "「巡検をあります」は目的語の「を」が「ある」と続かず、文にならない。", "へ": "「巡検へあります」は方向の「へ」が「ある」と続かず、意味が通らない。", "と": "「巡検とあります」は並列や相手の「と」で、「ある」の主語にならない。"}, "error_tags": {"を": "目的語で、「ある」の主語にならない", "へ": "方向を表し、存在の主語にならない", "と": "並列・相手を表し、存在の主語にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39335, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "野外に出て、実地に調査や見学をするために、あちこちを回って見ること。", "primary_collocate": null, "pronunciation": "じゅんけん", "ipa": "dʑɯŋkeɴ", "syllable_count": 4, "sentences": [{"text": "地質の授業で、川の石を調べるために巡検に出かけました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "地質[ちしつ]の授業[じゅぎょう]で、川[かわ]の石[いし]を調[しら]べるために巡検[じゅんけん]に出[で]かけました。", "sentence_source": "generated"}, {"text": "巡検の前に、先生が調べる場所と集まる時間を説明しました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "巡検[じゅんけん]の前[まえ]に、先生[せんせい]が調[しら]べる場所[ばしょ]と集[あつ]まる時間[じかん]を説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "大学の巡検では、地図を持って工場や農家を回り、話を聞きました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "大学[だいがく]の巡検[じゅんけん]では、地図[ちず]を持[も]って工場[こうじょう]や農家[のうか]を回[まわ]り、話[はなし]を聞[き]きました。", "sentence_source": "generated"}, {"text": "巡検の記録は、レポートにまとめて来週までに出さなければなりません。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "巡検[じゅんけん]の記録[きろく]は、レポートにまとめて来週[らいしゅう]までに出[だ]さなければなりません。", "sentence_source": "generated"}, {"text": "雨の日は道が危ないので、巡検は来月に延ばされました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は道[みち]が危[あぶ]ないので、巡検[じゅんけん]は来月[らいげつ]に延[の]ばされました。", "sentence_source": "generated"}, {"text": "学生たちは巡検で見た地層の写真を、一人ずつ発表しました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "学生[がくせい]たちは巡検[じゅんけん]で見[み]た地層[ちそう]の写真[しゃしん]を、一人[ひとり]ずつ発表[はっぴょう]しました。", "sentence_source": "generated"}, {"text": "この巡検は見学だけでなく、自分で調査をするところが特徴です。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "この巡検[じゅんけん]は見学[けんがく]だけでなく、自分[じぶん]で調査[ちょうさ]をするところが特徴[とくちょう]です。", "sentence_source": "generated"}, {"text": "地理のゼミでは、毎年秋に二日間の巡検があります。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "地理[ちり]のゼミでは、毎年[まいとし]秋[あき]に二日間[ふつかかん]の巡検[じゅんけん]があります。", "sentence_source": "generated"}, {"text": "町の水の問題を知るため、私たちは巡検でダムと浄水場を見ました。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "町[まち]の水[みず]の問題[もんだい]を知[し]るため、私[わたし]たちは巡検[じゅんけん]でダムと浄水場[じょうすいじょう]を見[み]ました。", "sentence_source": "generated"}, {"text": "巡検に参加する人は、ノートとカメラを必ず持ってきてください。", "target_word": "巡検", "complexity_tier": "T3", "furigana": "巡検[じゅんけん]に参加[さんか]する人[ひと]は、ノートとカメラを必[かなら]ず持[も]ってきてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "巡検", "label": "基本形"}], "register": "formal", "sense_fingerprint": "授業や研究のために野外へ出て、実地に調査・見学しながら回ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39335, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巡検", "is_correct": true, "explanation": "川の石を調べるために野外へ出かける、実地の調査・見学の行事を指す語で、文に合う。"}, {"text": "標本", "is_correct": false, "explanation": "標本は採集して保存した実物のことで、「出かける」先にはならない。"}, {"text": "論文", "is_correct": false, "explanation": "論文は研究成果をまとめた文書で、「調べるために出かける」対象ではない。"}, {"text": "分析", "is_correct": false, "explanation": "分析は成分などを調べる作業の名前で、場所へ「出かける」ことにはならない。"}], "explanations": {"巡検": "川の石を調べるために野外へ出かける、実地の調査・見学の行事を指す語で、文に合う。", "標本": "標本は採集して保存した実物のことで、「出かける」先にはならない。", "論文": "論文は研究成果をまとめた文書で、「調べるために出かける」対象ではない。", "分析": "分析は成分などを調べる作業の名前で、場所へ「出かける」ことにはならない。"}, "sentence_index": 0, "correct_answer": "巡検"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お遍路さんは四国の寺を巡検して回り、家族の無事を祈ります。", "explanation": "ここは〈巡礼〉の意味。信仰のために寺社を回る行為で、学術的な実地見学の巡検とは違うので合わない。"}, {"text": "毎年、専門の業者がエアコンを巡検してくれます。", "explanation": "ここは〈点検〉の意味。機器の状態を調べる作業で、野外の見学・調査である巡検は合わない。"}, {"text": "ジャングルを巡検して、まだ知られていない植物を見つけました。", "explanation": "ここは〈探検〉の意味。未知の場所を切り開いて進むことで、計画された実地見学である巡検とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39335, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巡検", "is_correct": true, "explanation": "見学だけでなく自分で調査をする、と対比される実地の学習行事を指す語で、文に合う。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案に点数をつける作業で、見学や調査の内容を表す語ではない。"}, {"text": "在庫", "is_correct": false, "explanation": "在庫は店などにある品物のことで、「この〜は特徴です」の主語にはならない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は他の言語へ置き換える作業で、見学や調査の特徴を表す語ではない。"}], "explanations": {"巡検": "見学だけでなく自分で調査をする、と対比される実地の学習行事を指す語で、文に合う。", "採点": "採点は答案に点数をつける作業で、見学や調査の内容を表す語ではない。", "在庫": "在庫は店などにある品物のことで、「この〜は特徴です」の主語にはならない。", "翻訳": "翻訳は他の言語へ置き換える作業で、見学や調査の特徴を表す語ではない。"}, "sentence_index": 6, "correct_answer": "巡検"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "力士たちは地方を巡検して回り、土地の人に相撲を見せます。", "explanation": "ここは〈巡業〉の意味。巡業は興行として各地を回ることで、学習・研究の実地見学である巡検とは合わない。"}, {"text": "美術館の絵画を巡検して、色づかいの美しさを味わいました。", "explanation": "ここは〈鑑賞〉の意味。作品の美しさを味わう行為で、野外を実地に回って調べる巡検とは違うので合わない。"}, {"text": "会社の経理を巡検して、帳簿の不正を見つけました。", "explanation": "ここは〈監査〉の意味。帳簿を調べて不正を確かめる仕事で、野外を実地に回る巡検とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39335, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週、巡検を出かけます。", "corrected_sentence": "来週、巡検に出かけます。", "error_description": "「出かける」は行き先を「に」で示す。対象語の後の「を」が誤りで、「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39335, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週、巡検が行わなければなりません。", "corrected_sentence": "来週、巡検を行わなければなりません。", "error_description": "「行う」は他動詞で、目的語「巡検」は「を」で示す。対象語の後の「が」が誤りで、「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39336, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「林業では」で、分野や範囲を示して主題になる「で」。"}, {"text": "が", "is_correct": false, "explanation": "「林業がは」は主語の「が」が「は」と続かず、文にならない。"}, {"text": "を", "is_correct": false, "explanation": "「林業をは」は目的語の「を」が「は」と続かず、文にならない。"}, {"text": "の", "is_correct": false, "explanation": "「林業のは」は連体修飾の「の」が「は」と続かず、文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「林業では」で、分野や範囲を示して主題になる「で」。", "が": "「林業がは」は主語の「が」が「は」と続かず、文にならない。", "を": "「林業をは」は目的語の「を」が「は」と続かず、文にならない。", "の": "「林業のは」は連体修飾の「の」が「は」と続かず、文が成り立たない。"}, "error_tags": {"が": "主語の格助詞だが「は」と続かない", "を": "目的語で、主題の位置に来ない", "の": "連体修飾で、「は」と続かない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39336, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「林業の人たち」で、林業に関わる人を修飾する連体修飾の「の」。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、「人たち」を修飾できない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」で、名詞と名詞を修飾の形でつなげない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」で、「人たち」を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "「林業の人たち」で、林業に関わる人を修飾する連体修飾の「の」。", "へ": "方向を表す「へ」で、「人たち」を修飾できない。", "より": "比較を表す「より」で、名詞と名詞を修飾の形でつなげない。", "から": "起点を表す「から」で、「人たち」を修飾する形にならない。"}, "error_tags": {"へ": "方向を表すため、人を修飾できない", "より": "比較を表すため、修飾の形にならない", "から": "起点を表すため、修飾の形にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39336, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "山で木を育てたり、切ったりする仕事のことです。", "primary_collocate": null, "pronunciation": "りんぎょう", "ipa": "ɾiŋɡʲoː", "syllable_count": 4, "sentences": [{"text": "祖父は若いころから山で林業をして、家族を育てました。", "target_word": "林業", "complexity_tier": "T3", "furigana": "祖父[そふ]は若[わか]いころから山[やま]で林業[りんぎょう]をして、家族[かぞく]を育[そだ]てました。", "sentence_source": "generated"}, {"text": "林業では、木を切るだけでなく、新しい木を植えることも大切です。", "target_word": "林業", "complexity_tier": "T3", "furigana": "林業[りんぎょう]では、木[き]を切[き]るだけでなく、新[あたら]しい木[き]を植[う]えることも大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "林業をしている叔父は、毎朝早く山へ出かけます。", "target_word": "林業", "complexity_tier": "T3", "furigana": "林業[りんぎょう]をしている叔父[おじ]は、毎朝[まいあさ]早[はや]く山[やま]へ出[で]かけます。", "sentence_source": "generated"}, {"text": "雪が多い冬は、林業の人たちが山で作業するのが難しくなります。", "target_word": "林業", "complexity_tier": "T3", "furigana": "雪[ゆき]が多[おお]い冬[ふゆ]は、林業[りんぎょう]の人[ひと]たちが山[やま]で作業[さぎょう]するのが難[むずか]しくなります。", "sentence_source": "generated"}, {"text": "私の町では、林業で働く人が少しずつ減っています。", "target_word": "林業", "complexity_tier": "T3", "furigana": "私[わたし]の町[まち]では、林業[りんぎょう]で働[はたら]く人[ひと]が少[すこ]しずつ減[へ]っています。", "sentence_source": "generated"}, {"text": "林業には、高い木に登ったり、重い機械を使ったりする危ない作業があります。", "target_word": "林業", "complexity_tier": "T3", "furigana": "林業[りんぎょう]には、高[たか]い木[き]に登[のぼ]ったり、重[おも]い機械[きかい]を使[つか]ったりする危[あぶ]ない作業[さぎょう]があります。", "sentence_source": "generated"}, {"text": "父は会社をやめて、故郷で林業を始めることにしました。", "target_word": "林業", "complexity_tier": "T3", "furigana": "父[ちち]は会社[かいしゃ]をやめて、故郷[こきょう]で林業[りんぎょう]を始[はじ]めることにしました。", "sentence_source": "generated"}, {"text": "林業の人たちは、木が大きくなるまで何十年も山の世話をします。", "target_word": "林業", "complexity_tier": "T3", "furigana": "林業[りんぎょう]の人[ひと]たちは、木[き]が大[おお]きくなるまで何十年[なんじゅうねん]も山[やま]の世話[せわ]をします。", "sentence_source": "generated"}, {"text": "山の仕事に興味があるので、将来は林業で働きたいです。", "target_word": "林業", "complexity_tier": "T3", "furigana": "山[やま]の仕事[しごと]に興味[きょうみ]があるので、将来[しょうらい]は林業[りんぎょう]で働[はたら]きたいです。", "sentence_source": "generated"}, {"text": "林業を体験するイベントで、子どもたちは小さな木を植えました。", "target_word": "林業", "complexity_tier": "T3", "furigana": "林業[りんぎょう]を体験[たいけん]するイベントで、子[こ]どもたちは小[ちい]さな木[き]を植[う]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "林業", "label": "基本形"}], "register": "polite", "sense_fingerprint": "山で木を植え、育て、切り出す人々の仕事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39336, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "林業", "is_correct": true, "explanation": "山で木を育てたり切ったりする仕事を表し、「をして」の目的語として文に合う。"}, {"text": "木材", "is_correct": false, "explanation": "木材は切り出した木そのもので、「をする」と続けて仕事を表すことはできない。"}, {"text": "森林", "is_correct": false, "explanation": "森林は木の集まる場所で、「をする」の対象にはならない。"}, {"text": "樹木", "is_correct": false, "explanation": "樹木は木そのものを指し、「をして」の動作の対象として文が成り立たない。"}], "explanations": {"林業": "山で木を育てたり切ったりする仕事を表し、「をして」の目的語として文に合う。", "木材": "木材は切り出した木そのもので、「をする」と続けて仕事を表すことはできない。", "森林": "森林は木の集まる場所で、「をする」の対象にはならない。", "樹木": "樹木は木そのものを指し、「をして」の動作の対象として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "林業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は林業で米と野菜を育て、毎朝田んぼを見回ります。", "explanation": "ここは〈農業〉の意味。米や野菜を育てる仕事で、山で木を育てて切る林業とは対象が違うので合わない。"}, {"text": "あの職人は林業の仕事で、公園の池や庭石を美しく整えています。", "explanation": "ここは〈造園〉の意味。庭や公園を設計・整備する仕事で、森林で木を育てて切る林業とは合わない。"}, {"text": "この港では林業が盛んで、毎朝たくさんの魚が水揚げされます。", "explanation": "ここは〈漁業〉の意味。魚を捕って売る産業で、山の木を扱う林業とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39336, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林業", "is_correct": true, "explanation": "故郷で始める仕事の名前として、山で木を育てて切る産業を表し、文に合う。"}, {"text": "山林", "is_correct": false, "explanation": "山林は山全体の森を指し、「始める」対象にはならない。"}, {"text": "材木", "is_correct": false, "explanation": "材木は加工した木材で、「始める」という行為の対象にはならない。"}, {"text": "杉", "is_correct": false, "explanation": "杉は木の種類で、「始める」とは続かず仕事の名前にならない。"}], "explanations": {"林業": "故郷で始める仕事の名前として、山で木を育てて切る産業を表し、文に合う。", "山林": "山林は山全体の森を指し、「始める」対象にはならない。", "材木": "材木は加工した木材で、「始める」という行為の対象にはならない。", "杉": "杉は木の種類で、「始める」とは続かず仕事の名前にならない。"}, "sentence_index": 6, "correct_answer": "林業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母はベランダで花を育てる林業を楽しんでいます。", "explanation": "ここは〈園芸〉の意味。草花を育てる趣味で、山で木を育てて切る林業とは場所も対象も違うので合わない。"}, {"text": "林業では、巣箱のミツバチを毎日見まわります。", "explanation": "ここは〈養蜂〉の意味。ミツバチを飼って蜂蜜を採る仕事で、森林の木を扱う林業とは合わない。"}, {"text": "林業は、山から鉄や石炭を掘り出す産業です。", "explanation": "ここは〈鉱業〉の意味。山の鉱物を掘る産業で、木を育てて切る林業とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39336, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "叔父は林業に働いていて、毎日山へ行きます。", "corrected_sentence": "叔父は林業で働いていて、毎日山へ行きます。", "error_description": "「働く」は分野を表す「で」を取る（〜で働く）。ここの「に」が誤りで、「で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39336, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は、林業を続けるなければならないと考えています。", "corrected_sentence": "父は、林業を続けなければならないと考えています。", "error_description": "「続ける」の未然形は「続け」。「続けるなければ」は活用が誤りで、「続けなければ」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39337, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「林業は」で、林業を文の主題として示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、主題の位置に立つ文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、主題を表す位置に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は「林業の」で止まり、主題にならない。"}], "correct_answer": "は", "explanations": {"は": "「林業は」で、林業を文の主題として示す「は」。", "を": "目的語の「を」は、主題の位置に立つ文として成り立たない。", "へ": "方向の「へ」は、主題を表す位置に合わない。", "の": "連体修飾の「の」は「林業の」で止まり、主題にならない。"}, "error_tags": {"を": "目的語で、主題の位置に来ない", "へ": "方向を表し、主題にならない", "の": "連体修飾で、主題にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39337, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「林業が衰えると」で、衰える動作の主語を示す「が」。"}, {"text": "に", "is_correct": false, "explanation": "「林業に衰えると」は「衰える」の主語にならず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す「で」で、衰える主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表す「と」で、衰える動作の主語の格にならない。"}], "correct_answer": "が", "explanations": {"が": "「林業が衰えると」で、衰える動作の主語を示す「が」。", "に": "「林業に衰えると」は「衰える」の主語にならず、文が成り立たない。", "で": "場所や手段を表す「で」で、衰える主語にはならない。", "と": "並列や相手を表す「と」で、衰える動作の主語の格にならない。"}, "error_tags": {"に": "「衰える」の主語にならない", "で": "場所・手段を表し、主語にならない", "と": "並列・相手を表し、主語にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39337, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "森林を管理し、木材を生産する産業や技術のこと。", "primary_collocate": null, "pronunciation": "りんぎょう", "ipa": "ɾiŋɡʲoː", "syllable_count": 4, "sentences": [{"text": "この地方では林業が盛んで、きれいな杉の木材を全国に送っています。", "target_word": "林業", "complexity_tier": "T3", "furigana": "この地方[ちほう]では林業[りんぎょう]が盛[さか]んで、きれいな杉[すぎ]の木材[もくざい]を全国[ぜんこく]に送[おく]っています。", "sentence_source": "generated"}, {"text": "林業は、森林を守りながら木材を作る産業です。", "target_word": "林業", "complexity_tier": "T3", "furigana": "林業[りんぎょう]は、森林[しんりん]を守[まも]りながら木材[もくざい]を作[つく]る産業[さんぎょう]です。", "sentence_source": "generated"}, {"text": "新しい機械が入って、林業の技術が大きく進みました。", "target_word": "林業", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]が入[はい]って、林業[りんぎょう]の技術[ぎじゅつ]が大[おお]きく進[すす]みました。", "sentence_source": "generated"}, {"text": "輸入木材が安くなり、国内の林業は厳しい状況が続いています。", "target_word": "林業", "complexity_tier": "T3", "furigana": "輸入木材[ゆにゅうもくざい]が安[やす]くなり、国内[こくない]の林業[りんぎょう]は厳[きび]しい状況[じょうきょう]が続[つづ]いています。", "sentence_source": "generated"}, {"text": "林業の会社は、森を管理して、必要な量の木材だけを切っています。", "target_word": "林業", "complexity_tier": "T3", "furigana": "林業[りんぎょう]の会社[かいしゃ]は、森[もり]を管理[かんり]して、必要[ひつよう]な量[りょう]の木材[もくざい]だけを切[き]っています。", "sentence_source": "generated"}, {"text": "大学では、環境と林業の関係について研究しています。", "target_word": "林業", "complexity_tier": "T3", "furigana": "大学[だいがく]では、環境[かんきょう]と林業[りんぎょう]の関係[かんけい]について研究[けんきゅう]しています。", "sentence_source": "generated"}, {"text": "政府は林業を支えるために、若い働き手を増やす計画を発表しました。", "target_word": "林業", "complexity_tier": "T3", "furigana": "政府[せいふ]は林業[りんぎょう]を支[ささ]えるために、若[わか]い働[はたら]き手[て]を増[ふ]やす計画[けいかく]を発表[はっぴょう]しました。", "sentence_source": "generated"}, {"text": "林業が衰えると、手入れされない森が増えて災害の危険が高まります。", "target_word": "林業", "complexity_tier": "T3", "furigana": "林業[りんぎょう]が衰[おとろ]えると、手入れ[ていれ]されない森[もり]が増[ふ]えて災害[さいがい]の危険[きけん]が高[たか]まります。", "sentence_source": "generated"}, {"text": "木材の生産だけでなく、森林の保全も林業の大切な役割です。", "target_word": "林業", "complexity_tier": "T3", "furigana": "木材[もくざい]の生産[せいさん]だけでなく、森林[しんりん]の保全[ほぜん]も林業[りんぎょう]の大切[たいせつ]な役割[やくわり]です。", "sentence_source": "generated"}, {"text": "国内の林業を守るため、地元の木を使った家が増えています。", "target_word": "林業", "complexity_tier": "T3", "furigana": "国内[こくない]の林業[りんぎょう]を守[まも]るため、地元[じもと]の木[き]を使[つか]った家[いえ]が増[ふ]えています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "林業", "label": "基本形"}], "register": "formal", "sense_fingerprint": "森林を管理して木材を生産する産業や、その技術", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6073267a-d390-4f44-87f3-cfa7dc62ec2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
